{
  "timeline": [
    {
      "headline": "Invention of the First Refrigeration Machine",
      "text": "In 1834, Jacob Perkins built the first practical refrigeration machine. It operated on the vapor-compression cycle, which is still used in most refrigerators today.",
      "date": "1834"
    },
    {
      "headline": "Development of the Ice-Making Machine",
      "text": "In 1854, James Harrison, an Australian, developed the first practical ice-making machine and demonstrated it by producing 3,000 kilograms of ice per day.",
      "date": "1854"
    },
    {
      "headline": "Introduction of the Domestic Refrigerator",
      "text": "In 1913, refrigerators for home use were invented. Fred W. Wolf invented a unit that was mounted on top of an icebox.",
      "date": "1913"
    },
    {
      "headline": "First Self-Contained Refrigerator",
      "text": "In 1923, Frigidaire introduced the first self-contained refrigerator, which was a significant advancement as it combined the compressor and the cold box into a single unit.",
      "date": "1923"
    },
    {
      "headline": "Introduction of Freon",
      "text": "In 1928, Thomas Midgley, Jr. developed Freon, a safer refrigerant that became widely used in refrigerators.",
      "date": "1928"
    },
    {
      "headline": "Introduction of the Two-Door Refrigerator",
      "text": "In 1939, the first two-door refrigerator was introduced, featuring a separate freezer compartment.",
      "date": "1939"
    },
    {
      "headline": "Introduction of the Frost-Free Refrigerator",
      "text": "In 1950, the first frost-free refrigerators were introduced, eliminating the need for manual defrosting.",
      "date": "1950"
    },
    {
      "headline": "Energy Efficiency Improvements",
      "text": "In the 1970s and 1980s, energy efficiency became a focus, leading to the development of more energy-efficient refrigerator models.",
      "date": "1970"
    },
    {
      "headline": "Phase-Out of CFCs",
      "text": "In the 1990s, due to environmental concerns, chlorofluorocarbons (CFCs) were phased out in favor of more environmentally friendly refrigerants.",
      "date": "1990"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Brewed",
      "text": "Stella Artois was first brewed in 1926 by Brouwerij Artois in Leuven, Belgium. It was originally brewed as a Christmas beer and named 'Stella', meaning 'star' in Latin.",
      "date": "1926"
    },
    {
      "headline": "International Expansion",
      "text": "Over the years, Stella Artois expanded its market beyond Belgium, becoming available in countries such as the UK, Ireland, Canada, and Australia.",
      "date": "1950s"
    },
    {
      "headline": "Acquisition by Interbrew",
      "text": "Stella Artois became part of Interbrew International B.V., which later merged to form the world's largest brewer, Anheuser-Busch InBev SA/NV.",
      "date": "1987"
    },
    {
      "headline": "Reduced ABV in Certain Markets",
      "text": "In some countries, including the UK, Ireland, Canada, and Australia, Stella Artois is sold with a reduced alcohol by volume (ABV) compared to its original form.",
      "date": "2012"
    }
  ]
}

