{
  "timeline": [
    {
      "headline": "Birth of Erich Honecker",
      "text": "Erich Honecker was born on August 25, 1912, in Neunkirchen, German Empire.",
      "date": "1912-08-25"
    },
    {
      "headline": "Joined the Communist Youth Movement",
      "text": "In 1926, Erich Honecker joined the Communist Youth Movement, marking the beginning of his political career.",
      "date": "1926"
    },
    {
      "headline": "Joined the Communist Party of Germany",
      "text": "In 1929, Honecker became a member of the Communist Party of Germany.",
      "date": "1929"
    },
    {
      "headline": "Imprisonment by the Nazis",
      "text": "In 1935, Honecker was arrested by the Nazis and sentenced to ten years in prison for his political activities.",
      "date": "1935"
    },
    {
      "headline": "Release from Prison",
      "text": "Honecker was released from prison in 1945 after the end of World War II.",
      "date": "1945"
    },
    {
      "headline": "Founding Member of the Free German Youth",
      "text": "In 1946, Honecker became a founding member of the Free German Youth (FDJ), the official youth movement of East Germany.",
      "date": "1946"
    },
    {
      "headline": "Elected to the Central Committee of the SED",
      "text": "In 1950, Honecker was elected to the Central Committee of the Socialist Unity Party of Germany (SED).",
      "date": "1950"
    },
    {
      "headline": "Became Secretary for Security Matters",
      "text": "In 1958, Honecker became the Secretary for Security Matters in the SED, overseeing the construction of the Berlin Wall.",
      "date": "1958"
    },
    {
      "headline": "General Secretary of the SED",
      "text": "On May 3, 1971, Erich Honecker became the General Secretary of the Socialist Unity Party of Germany (SED), the de facto leader of East Germany.",
      "date": "1971-05-03"
    },
    {
      "headline": "Chairman of the State Council",
      "text": "In 1976, Honecker became the Chairman of the State Council, the official head of state of East Germany.",
      "date": "1976"
    },
    {
      "headline": "Fall from Power",
      "text": "On October 18, 1989, Erich Honecker was forced to resign from all his positions due to the political changes and protests in East Germany.",
      "date": "1989-10-18"
    },
    {
      "headline": "Exile in the Soviet Union",
      "text": "After his resignation, Honecker went into exile in the Soviet Union in 1991.",
      "date": "1991"
    },
    {
      "headline": "Return to Germany and Trial",
      "text": "In 1992, Honecker returned to Germany to face trial for his role in the deaths of people attempting to escape East Germany.",
      "date": "1992"
    },
    {
      "headline": "Death of Erich Honecker",
      "text": "Erich Honecker died on May 29, 1994, in Santiago, Chile.",
      "date": "1994-05-29"
    }
  ]
}

