{
  "timeline": [
    {
      "headline": "Start of the Triassic Period",
      "text": "The Triassic Period began approximately 251.902 million years ago, following the Permian-Triassic extinction event, which was the most severe extinction event in Earth's history.",
      "date": "-251902000"
    },
    {
      "headline": "Early Triassic Epoch",
      "text": "The Early Triassic Epoch spanned from approximately 251.902 million years ago to around 247.2 million years ago. This epoch saw the recovery of life after the Permian-Triassic extinction event.",
      "date": "-251902000"
    },
    {
      "headline": "Middle Triassic Epoch",
      "text": "The Middle Triassic Epoch lasted from about 247.2 million years ago to approximately 237 million years ago. During this time, ecosystems began to stabilize, and new groups of animals, such as the first dinosaurs, started to appear.",
      "date": "-247200000"
    },
    {
      "headline": "Late Triassic Epoch",
      "text": "The Late Triassic Epoch extended from around 237 million years ago to 201.4 million years ago. This epoch saw the diversification of dinosaurs and the appearance of the first true mammals.",
      "date": "-237000000"
    },
    {
      "headline": "End of the Triassic Period",
      "text": "The Triassic Period ended approximately 201.4 million years ago, marked by the Triassic-Jurassic extinction event, which led to the extinction of many species and paved the way for the dominance of dinosaurs in the Jurassic Period.",
      "date": "-201400000"
    }
  ]
}

