{
  "timeline": [
    {
      "headline": "Ancient Egyptian Use",
      "text": "Ancient Egyptians were the first to make marshmallows, using the sap of the marsh-mallow plant (Althaea officinalis) mixed with nuts and honey. This was a delicacy reserved for gods and royalty.",
      "date": "-2000"
    },
    {
      "headline": "19th Century French Confection",
      "text": "In the early 19th century, French confectioners began whipping marshmallow sap with egg whites and sugar to create a confection similar to the modern marshmallow.",
      "date": "1800"
    },
    {
      "headline": "Introduction of Gelatin",
      "text": "By the late 19th century, the use of gelatin replaced the marshmallow sap, making the production process easier and more efficient.",
      "date": "1880"
    },
    {
      "headline": "Industrial Production",
      "text": "In the late 19th and early 20th centuries, marshmallows began to be produced on an industrial scale, making them widely available to the public.",
      "date": "1900"
    },
    {
      "headline": "Invention of the Extrusion Process",
      "text": "In 1948, Alex Doumak patented the extrusion process, which involves pumping marshmallow mixture through tubes and cutting it into cylindrical pieces, revolutionizing marshmallow production.",
      "date": "1948"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Commission of the Requiem",
      "text": "In the summer of 1791, Wolfgang Amadeus Mozart received a commission from Count Franz von Walsegg to compose a Requiem Mass. The Count intended to use the piece to commemorate the first anniversary of his wife's death.",
      "date": "1791"
    },
    {
      "headline": "Mozart Begins Composing the Requiem",
      "text": "Mozart began composing the Requiem in D minor, K. 626, in Vienna in late 1791. He worked on the piece alongside other compositions, including 'The Magic Flute' and 'La clemenza di Tito'.",
      "date": "1791"
    },
    {
      "headline": "Mozart's Death",
      "text": "Wolfgang Amadeus Mozart died on 5 December 1791, leaving the Requiem unfinished. At the time of his death, he had completed only a portion of the work.",
      "date": "1791-12-05"
    },
    {
      "headline": "Completion by Franz Xaver Süssmayr",
      "text": "After Mozart's death, his widow Constanze sought to have the Requiem completed. Franz Xaver Süssmayr, a student of Mozart, completed the Requiem in 1792, using Mozart's sketches and instructions.",
      "date": "1792"
    },
    {
      "headline": "Delivery to Count Franz von Walsegg",
      "text": "The completed version of the Requiem was delivered to Count Franz von Walsegg in 1792. The Count used it for a requiem service on 14 February 1792 to commemorate the first anniversary of his wife's death.",
      "date": "1792-02-14"
    }
  ]
}

