    },
    {
      "headline": "Partnership with H&M",
      "text": "In 2018, Klarna announced a partnership with H&M, one of the world's largest fashion retailers, to provide a seamless shopping experience for customers.",
      "date": "2018"
    },
    {
      "headline": "Valuation Reaches $5.5 Billion",
      "text": "In 2019, Klarna's valuation reached $5.5 billion after a funding round, making it one of the most valuable fintech companies in Europe.",
      "date": "2019"
    },
    {
      "headline": "Klarna's Valuation Surpasses $10 Billion",
      "text": "In September 2020, Klarna's valuation surpassed $10 billion following a $650 million funding round.",
      "date": "2020-09"
    },
    {
      "headline": "Klarna's Valuation Reaches $31 Billion",
      "text": "In March 2021, Klarna's valuation reached $31 billion after a $1 billion funding round, further solidifying its position as a leading fintech company.",
      "date": "2021-03"
