      "headline": "Birth of John Singer Sargent",
      "text": "John Singer Sargent was born on January 12, 1856, in Florence, Italy.",
      "date": "1856-01-12"
    },
    {
      "headline": "Sargent's Education",
      "text": "In 1874, Sargent began his formal art education at the École des Beaux-Arts in Paris, where he studied under Carolus-Duran.",
      "date": "1874"
    },
    {
      "headline": "First Major Exhibition",
      "text": "In 1877, Sargent exhibited his first major work, 'Portrait of a Young Man,' at the Paris Salon.",
      "date": "1877"
    },
    {
      "headline": "Exhibition of 'El Jaleo'",
      "text": "In 1882, Sargent exhibited 'El Jaleo' at the Paris Salon, which was well-received and established his reputation as a talented artist.",
      "date": "1882"
    },
    {
      "headline": "Scandal of 'Portrait of Madame X'",
      "text": "In 1884, Sargent exhibited 'Portrait of Madame X' at the Paris Salon, which caused a scandal due to its provocative pose and attire.",
      "date": "1884"
    },
    {
      "headline": "Move to London",
      "text": "Following the scandal of 'Portrait of Madame X,' Sargent moved to London in 1886 to continue his career.",
      "date": "1886"
    },
    {
      "headline": "Exhibition at the Royal Academy",
      "text": "In 1891, Sargent exhibited at the Royal Academy in London, further solidifying his reputation as a leading portrait artist.",
      "date": "1891"
    },
    {
      "headline": "Completion of 'Carnation, Lily, Lily, Rose'",
      "text": "In 1887, Sargent completed 'Carnation, Lily, Lily, Rose,' a painting that became one of his most famous works.",
      "date": "1887"
    },
    {
      "headline": "Mural Commissions",
      "text": "In the 1890s, Sargent received several mural commissions, including works for the Boston Public Library and the Museum of Fine Arts, Boston.",
      "date": "1890"
    },
    {
      "headline": "Retirement from Portrait Painting",
      "text": "In 1907, Sargent announced his retirement from portrait painting to focus on landscapes and murals.",
      "date": "1907"
    },
    {
      "headline": "World War I Contributions",
      "text": "During World War I, Sargent was commissioned to create war-themed paintings, including 'Gassed,' completed in 1919.",
      "date": "1919"
    },
    {
      "headline": "Death of John Singer Sargent",
      "text": "John Singer Sargent died on April 14, 1925, in London, England.",
      "date": "1925-04-14"
    }
  ]
}

