    },
    {
      "headline": "Investigation Begins",
      "text": "Following the bombings, investigations were launched to determine the perpetrators. The attacks were linked to the terrorist organization al-Qaeda.",
      "date": "1998-08"
    },
    {
      "headline": "U.S. Response",
      "text": "In response to the bombings, the United States launched Operation Infinite Reach, which included missile strikes against al-Qaeda targets in Sudan and Afghanistan on August 20, 1998.",
      "date": "1998-08-20"
    },
    {
      "headline": "Indictments Issued",
      "text": "In November 1998, the United States indicted several individuals, including Osama bin Laden, for their roles in the embassy bombings.",
      "date": "1998-11"
    },
    {
      "headline": "Trial and Convictions",
      "text": "In May 2001, four men were convicted in a U.S. federal court for their involvement in the bombings. They were sentenced to life imprisonment without the possibility of parole.",
      "date": "2001-05"
    }
  ]
}

{
