  "timeline": [
    {
      "headline": "Discovery of Fermentation",
      "text": "The process of fermentation was discovered by ancient civilizations, which used it to produce bread, beer, and wine. This is one of the earliest examples of biotechnology.",
      "date": "-7000"
    },
    {
      "headline": "First Use of Selective Breeding",
      "text": "Selective breeding of plants and animals was practiced by early farmers to enhance desirable traits, laying the foundation for modern genetic engineering.",
      "date": "-8000"
    },
    {
      "headline": "Discovery of Penicillin",
      "text": "In 1928, Alexander Fleming discovered penicillin, the first true antibiotic, which revolutionized medicine and is a cornerstone of pharmaceutical biotechnology.",
      "date": "1928"
    },
    {
      "headline": "Discovery of the Structure of DNA",
      "text": "In 1953, James Watson and Francis Crick discovered the double helix structure of DNA, a pivotal moment in biotechnology that paved the way for genetic engineering.",
      "date": "1953"
    },
    {
      "headline": "First Recombinant DNA Molecule",
      "text": "In 1973, Stanley Cohen and Herbert Boyer created the first recombinant DNA molecule, marking the beginning of genetic engineering.",
      "date": "1973"
    },
    {
      "headline": "First Genetically Modified Organism",
      "text": "In 1974, Rudolf Jaenisch created the first genetically modified animal, a mouse, using recombinant DNA technology.",
      "date": "1974"
    },
    {
      "headline": "First Biotech Company Founded",
      "text": "Genentech, the first biotechnology company, was founded in 1976, focusing on the development of recombinant DNA technology.",
      "date": "1976"
    },
    {
      "headline": "Approval of First Biotech Drug",
      "text": "In 1982, the FDA approved Humulin, the first human insulin produced using recombinant DNA technology, for use by diabetic patients.",
      "date": "1982"
    },
    {
      "headline": "First Genetically Modified Plant",
      "text": "In 1983, the first genetically modified plant was created, a tobacco plant resistant to antibiotics, demonstrating the potential of genetic engineering in agriculture.",
      "date": "1983"
    },
    {
      "headline": "Completion of the Human Genome Project",
      "text": "In 2003, the Human Genome Project was completed, mapping the entire human genome and providing a foundation for advances in biotechnology and personalized medicine.",
      "date": "2003"
    },
    {
      "headline": "CRISPR-Cas9 Gene Editing",
      "text": "In 2012, the CRISPR-Cas9 gene-editing technology was developed, allowing precise modifications to DNA and revolutionizing genetic engineering.",
      "date": "2012"
    }
  ]
}

