    {
      "headline": "Berlin Declaration",
      "text": "On 5 June 1945, the Berlin Declaration was issued, marking the official beginning of Allied-occupied Germany. The declaration stripped Nazi Germany of its sovereignty and established the Allied Control Council (ACC) to administer the country.",
      "date": "1945-06-05"
    },
    {
      "headline": "Germany's Formal Surrender",
      "text": "Germany formally surrendered on 8 May 1945, leading to the end of World War II in Europe. This surrender paved the way for the occupation and administration of Germany by the Allies.",
      "date": "1945-05-08"
    },
    {
      "headline": "Establishment of the Allied Control Council",
      "text": "The Allied Control Council (ACC) was established to exercise joint authority and sovereignty over Germany. It was composed of representatives from the United States, the United Kingdom, the Soviet Union, and France.",
      "date": "1945-06"
    },
    {
      "headline": "Nuremberg Trials Begin",
      "text": "On 20 November 1945, the Nuremberg Trials began. These were a series of military tribunals held to prosecute prominent leaders of Nazi Germany for war crimes.",
      "date": "1945-11-20"
    },
    {
      "headline": "Marshall Plan Announced",
      "text": "In June 1947, the United States announced the Marshall Plan, an economic aid program to help rebuild European economies, including Germany, after the devastation of World War II.",
      "date": "1947-06"
    },
    {
      "headline": "Currency Reform in Western Zones",
      "text": "On 20 June 1948, a currency reform was implemented in the Western zones of Germany, introducing the Deutsche Mark and stabilizing the economy.",
      "date": "1948-06-20"
    },
    {
      "headline": "Berlin Blockade and Airlift",
      "text": "The Berlin Blockade began on 24 June 1948, when the Soviet Union blocked all ground routes to West Berlin. In response, the Western Allies organized the Berlin Airlift to supply the city by air.",
      "date": "1948-06-24"
    },
    {
      "headline": "End of Berlin Blockade",
      "text": "The Berlin Blockade ended on 12 May 1949, after the Soviet Union lifted the blockade, allowing ground access to West Berlin to resume.",
      "date": "1949-05-12"
    },
    {
      "headline": "Establishment of West Germany",
      "text": "On 23 May 1949, the Federal Republic of Germany (West Germany) was officially established, marking the end of Allied-occupied Germany in the western zones.",
      "date": "1949-05-23"
    }
  ]
}

