{
  "timeline": [
    {
      "headline": "First Committee Formed",
      "text": "On July 4, 1776, the Continental Congress appointed the first committee to design the Great Seal of the United States. The committee included Benjamin Franklin, John Adams, and Thomas Jefferson.",
      "date": "1776-07-04"
    },
    {
      "headline": "Second Committee Formed",
      "text": "On March 25, 1780, a second committee was formed to design the Great Seal, consisting of James Lovell, John Morin Scott, and William Churchill Houston.",
      "date": "1780-03-25"
    },
    {
      "headline": "Third Committee Formed",
      "text": "On May 4, 1782, a third committee was formed, including Arthur Middleton, Elias Boudinot, and Edward Rutledge.",
      "date": "1782-05-04"
    },
    {
      "headline": "Great Seal Adopted",
      "text": "On June 20, 1782, the design for the Great Seal of the United States was finally approved by the Continental Congress.",
      "date": "1782-06-20"
    },
    {
      "headline": "First Use of the Great Seal",
      "text": "The Great Seal was first used on September 16, 1782, to authenticate a document sent to George Washington.",
      "date": "1782-09-16"
    },
    {
      "headline": "First Die of the Great Seal",
      "text": "The first die of the Great Seal was cut in 1782 by engraver Robert Scot, who was appointed by Secretary of Congress Charles Thomson.",
      "date": "1782"
    },
    {
      "headline": "Reverse of the Great Seal",
      "text": "The reverse of the Great Seal, featuring the unfinished pyramid and the Eye of Providence, has never been cut as a die and is not used as an official seal.",
      "date": "1782"
    },
    {
      "headline": "Current Die Created",
      "text": "The current die of the Great Seal was created in 1904 by the Bureau of Engraving and Printing.",
      "date": "1904"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of the Cambridge Five",
      "text": "The Cambridge Five spy ring began to form in the 1930s when a group of students at the University of Cambridge were recruited by Soviet intelligence.",
      "date": "1930"
    },
    {
      "headline": "Kim Philby Joins MI6",
      "text": "In 1940, Kim Philby, one of the members of the Cambridge Five, joined the British Secret Intelligence Service (MI6) and began passing information to the Soviet Union.",
      "date": "1940"
    },
    {
      "headline": "Guy Burgess and Donald Maclean in the Foreign Office",
      "text": "During the early 1940s, Guy Burgess and Donald Maclean, both members of the Cambridge Five, held positions in the British Foreign Office, allowing them access to sensitive information.",
      "date": "1940"
    },
    {
      "headline": "Anthony Blunt's Role",
      "text": "Anthony Blunt, another member of the Cambridge Five, worked as a spy for the Soviet Union while holding a position at the British Royal Household during the 1940s.",
      "date": "1940"
    },
    {
      "headline": "John Cairncross Identified",
      "text": "John Cairncross, the fifth member of the Cambridge Five, was identified as a Soviet spy. He worked in various government departments during the 1940s.",
      "date": "1940"
    },
    {
      "headline": "Burgess and Maclean Defect",
      "text": "In 1951, Guy Burgess and Donald Maclean defected to the Soviet Union after being tipped off about their impending exposure as spies.",
      "date": "1951"
    },
    {
      "headline": "Philby Defects to the Soviet Union",
      "text": "In 1963, Kim Philby defected to the Soviet Union after being exposed as a member of the Cambridge Five.",
      "date": "1963"
    },
    {
      "headline": "Anthony Blunt's Confession",
      "text": "In 1964, Anthony Blunt confessed to being a member of the Cambridge Five, but his confession was kept secret until 1979.",
      "date": "1964"
    },
    {
      "headline": "Public Revelation of Blunt's Espionage",
      "text": "In 1979, the British government publicly revealed that Anthony Blunt had been a member of the Cambridge Five.",
      "date": "1979"
    }
  ]
}

