    },
    {
      "headline": "Recognition by Emperor Bahadur Shah I",
      "text": "In 1707, the Maratha Empire was recognized as a tributary state by Emperor Bahadur Shah I following a prolonged rebellion.",
      "date": "1707"
    },
    {
      "headline": "Influence over Delhi Politics",
      "text": "Between 1737 and 1803, the Marathas significantly influenced imperial politics at Delhi, despite recognizing the Mughal emperor as their nominal suzerain.",
      "date": "1737"
    },
    {
      "headline": "Battle of Panipat",
      "text": "The Third Battle of Panipat took place on January 14, 1761, where the Marathas were defeated by the Afghan king Ahmad Shah Abdali.",
      "date": "1761-01-14"
    },
    {
      "headline": "Anglo-Maratha Wars",
      "text": "The Anglo-Maratha Wars were a series of conflicts between the British East India Company and the Maratha Empire, occurring from 1775 to 1818.",
      "date": "1775"
    },
    {
      "headline": "End of the Maratha Empire",
      "text": "The Maratha Empire effectively ended in 1818 after the Third Anglo-Maratha War, leading to British control over most of India.",
      "date": "1818"
    }
  ]
}

