{
  "timeline": [
    {
      "headline": "Establishment of the Kingdom of Bavaria",
      "text": "The Kingdom of Bavaria was established on January 1, 1806, when the Electorate of Bavaria was elevated to a kingdom by Napoleon Bonaparte.",
      "date": "1806-01-01"
    },
    {
      "headline": "Bavaria Joins the Confederation of the Rhine",
      "text": "In July 1806, Bavaria joined the Confederation of the Rhine, a confederation of client states of the First French Empire.",
      "date": "1806-07"
    },
    {
      "headline": "Bavaria's Participation in the Napoleonic Wars",
      "text": "Bavaria was an ally of France during the Napoleonic Wars, participating in various campaigns until the defeat of Napoleon in 1814.",
      "date": "1814"
    },
    {
      "headline": "Congress of Vienna",
      "text": "In 1815, the Congress of Vienna recognized Bavaria as a sovereign kingdom and confirmed its territorial gains.",
      "date": "1815"
    },
    {
      "headline": "Bavaria Joins the German Confederation",
      "text": "In 1815, Bavaria became a member of the German Confederation, a loose association of German states.",
      "date": "1815"
    },
    {
      "headline": "Bavarian Constitution of 1818",
      "text": "On May 26, 1818, King Maximilian I Joseph of Bavaria promulgated a new constitution, establishing a constitutional monarchy.",
      "date": "1818-05-26"
    },
    {
      "headline": "Revolutions of 1848",
      "text": "In 1848, Bavaria experienced revolutionary uprisings as part of the wider Revolutions of 1848 in the German states, leading to some liberal reforms.",
      "date": "1848"
    },
    {
      "headline": "Bavaria in the Austro-Prussian War",
      "text": "In 1866, Bavaria sided with Austria in the Austro-Prussian War but was defeated by Prussia.",
      "date": "1866"
    },
    {
      "headline": "Bavaria Joins the North German Confederation",
      "text": "Following the Austro-Prussian War, Bavaria joined the North German Confederation in 1867.",
      "date": "1867"
    },
    {
      "headline": "Unification of Germany",
      "text": "On January 18, 1871, Bavaria became a federated state of the newly formed German Empire, following the unification of Germany.",
      "date": "1871-01-18"
    },
    {
      "headline": "End of the Kingdom of Bavaria",
      "text": "The Kingdom of Bavaria came to an end on November 7, 1918, following the abdication of King Ludwig III amidst the German Revolution.",
      "date": "1918-11-07"
    }
  ]
}

{
  "timeline": [
