      "headline": "Independence of Myanmar",
      "text": "Myanmar gained independence from British rule on January 4, 1948. The Tatmadaw was established as the armed forces of the newly independent nation.",
      "date": "1948-01-04"
    },
    {
      "headline": "General Ne Win's Coup",
      "text": "On March 2, 1962, General Ne Win led a coup d'état, overthrowing the civilian government and establishing military rule in Myanmar.",
      "date": "1962-03-02"
    },
    {
      "headline": "Burmese Way to Socialism",
      "text": "Following the 1962 coup, General Ne Win implemented the Burmese Way to Socialism, a policy aimed at creating an autarkic society.",
      "date": "1962"
    },
    {
      "headline": "1988 Uprising",
      "text": "In 1988, nationwide protests erupted against the military regime. The Tatmadaw violently repressed these protests, resulting in thousands of deaths.",
      "date": "1988"
    },
    {
      "headline": "1990 General Elections",
      "text": "The military agreed to hold free elections in 1990. The National League for Democracy, led by Aung San Suu Kyi, won a landslide victory, but the Tatmadaw ignored the results and continued to hold power.",
      "date": "1990"
    },
    {
      "headline": "Rohingya Conflict Escalation",
      "text": "In the 1990s, the conflict involving Buddhists and Rohingya Muslims in Rakhine State escalated due to attacks by the Rohingya Solidarity Organization (RSO) on Tatmadaw forces.",
      "date": "1990s"
    },
    {
      "headline": "Rohingya Genocide",
      "text": "Starting in 2017, the Tatmadaw was involved in a campaign against the Rohingya minority in Rakhine State, which has been described as genocide by the United Nations and other international bodies.",
      "date": "2017"
    }
  ]
}

