    {
      "headline": "KTM Files for Bankruptcy",
      "text": "In 1991, KTM filed for bankruptcy due to financial difficulties, leading to a restructuring of the company.",
      "date": "1991"
    },
    {
      "headline": "KTM Restructured",
      "text": "In 1992, KTM was restructured and divided into four separate entities: KTM Sportmotorcycle GmbH, KTM Fahrrad GmbH, KTM Kühler GmbH, and KTM Werkzeugbau GmbH.",
      "date": "1992"
    },
    {
      "headline": "Bajaj Auto Acquires Stake in KTM",
