{
  "timeline": [
    {
      "headline": "Foundation of Mercia",
      "text": "Mercia was founded in the early 6th century as one of the Anglo-Saxon kingdoms during the Heptarchy period in what is now the Midlands of England.",
      "date": "0500"
    },
    {
      "headline": "Reign of King Penda",
      "text": "King Penda, one of Mercia's most powerful rulers, reigned from approximately 626 to 655. He was known for his military prowess and expansion of Mercian territory.",
      "date": "0626"
    },
    {
      "headline": "Battle of the Winwaed",
      "text": "In 655, King Penda was defeated and killed at the Battle of the Winwaed by Oswiu of Northumbria, marking a significant turning point in Mercian history.",
      "date": "0655"
    },
    {
      "headline": "Reign of King Æthelred",
      "text": "King Æthelred ruled Mercia from 675 to 704, during which he expanded the kingdom's influence and power.",
      "date": "0675"
    },
    {
      "headline": "Reign of King Offa",
      "text": "King Offa, who reigned from 757 to 796, is one of the most notable Mercian kings. He is known for constructing Offa's Dyke, a large earthwork marking the boundary between Mercia and Welsh kingdoms.",
      "date": "0757"
    },
    {
      "headline": "Construction of Offa's Dyke",
      "text": "During King Offa's reign, Offa's Dyke was constructed, serving as a defensive structure and a boundary between Mercia and the Welsh kingdoms.",
      "date": "0780"
    },
    {
      "headline": "Death of King Offa",
      "text": "King Offa died in 796, marking the end of a significant era of Mercian dominance in England.",
      "date": "0796"
    },
    {
      "headline": "Reign of King Coenwulf",
      "text": "King Coenwulf ruled from 796 to 821, continuing the legacy of strong Mercian leadership.",
      "date": "0796"
    },
    {
      "headline": "Decline of Mercia",
      "text": "After the death of King Coenwulf in 821, Mercia began to decline in power, eventually becoming overshadowed by the rise of Wessex.",
      "date": "0821"
    },
    {
      "headline": "End of Mercian Independence",
      "text": "By the early 10th century, Mercia had lost its independence and was absorbed into the Kingdom of England.",
      "date": "0910"
    }
  ]
}

