    {
      "headline": "Reign of Jayavarman VII",
      "text": "Jayavarman VII reigned from 1181 to 1218 CE and is known for his extensive building projects, including the Bayon temple and the city of Angkor Thom.",
      "date": "1181"
    },
    {
      "headline": "Sack of Angkor",
      "text": "In 1177 CE, the Chams invaded and sacked Angkor, leading to a period of instability until Jayavarman VII's reign.",
      "date": "1177"
    },
    {
      "headline": "Decline of the Khmer Empire",
      "text": "The decline of the Khmer Empire began in the 13th century due to internal strife, external pressures, and environmental changes, leading to the eventual fall of Angkor in 1431 CE.",
      "date": "1300"
    },
    {
      "headline": "Fall of Angkor",
      "text": "In 1431 CE, Angkor was abandoned after a siege by the Ayutthaya Kingdom, marking the end of the Khmer Empire's dominance in the region.",
