{
  "timeline": [
    {
      "headline": "Birth of Piet Mondrian",
      "text": "Piet Mondrian was born on March 7, 1872, in Amersfoort, Netherlands.",
      "date": "1872-03-07"
    },
    {
      "headline": "Education at Rijksakademie van Beeldende Kunsten",
      "text": "In 1892, Mondrian enrolled at the Rijksakademie van Beeldende Kunsten in Amsterdam, where he studied art.",
      "date": "1892"
    },
    {
      "headline": "First Major Exhibition",
      "text": "In 1903, Mondrian held his first major exhibition at the Stedelijk Museum in Amsterdam.",
      "date": "1903"
    },
    {
      "headline": "Move to Paris",
      "text": "In 1911, Mondrian moved to Paris, where he was influenced by the Cubist style of Pablo Picasso and Georges Braque.",
      "date": "1911"
    },
    {
      "headline": "Adoption of Abstract Style",
      "text": "By 1914, Mondrian had begun to develop his own abstract style, moving away from figurative painting.",
      "date": "1914"
    },
    {
      "headline": "Co-founding De Stijl Movement",
      "text": "In 1917, Mondrian co-founded the De Stijl art movement with Theo van Doesburg, which advocated for pure abstraction and simplicity.",
      "date": "1917"
    },
    {
      "headline": "Publication of 'De Nieuwe Beelding in de Schilderkunst'",
      "text": "In 1917, Mondrian published a series of essays titled 'De Nieuwe Beelding in de Schilderkunst' ('The New Plastic in Painting'), outlining his artistic theories.",
      "date": "1917"
    },
    {
      "headline": "Return to Paris",
      "text": "In 1919, Mondrian returned to Paris, where he continued to develop his abstract style.",
      "date": "1919"
    },
    {
      "headline": "Move to London",
      "text": "In 1938, Mondrian moved to London to escape the growing threat of World War II.",
      "date": "1938"
    },
    {
      "headline": "Move to New York City",
      "text": "In 1940, Mondrian moved to New York City, where he was inspired by the city's architecture and jazz music.",
      "date": "1940"
    },
    {
      "headline": "Creation of 'Broadway Boogie Woogie'",
      "text": "In 1942-1943, Mondrian created one of his most famous works, 'Broadway Boogie Woogie', inspired by the cityscape and jazz music of New York.",
      "date": "1943"
    },
    {
      "headline": "Death of Piet Mondrian",
      "text": "Piet Mondrian died on February 1, 1944, in New York City, United States.",
      "date": "1944-02-01"
    }
  ]
}

