  "timeline": [
    {
      "headline": "Albert Einstein's Birth",
      "text": "Albert Einstein was born on March 14, 1879, in Ulm, in the Kingdom of Württemberg in the German Empire.",
      "date": "1879-03-14"
    },
    {
      "headline": "Publication of Special Relativity",
      "text": "In 1905, Albert Einstein published his paper 'On the Electrodynamics of Moving Bodies', which introduced the special theory of relativity. This paper was published on June 30, 1905, and revolutionized the understanding of space and time.",
      "date": "1905-06-30"
    },
    {
      "headline": "Introduction of the Theory's Postulates",
      "text": "Einstein's special relativity is based on two postulates: the laws of physics are invariant in all inertial frames of reference, and the speed of light in a vacuum is the same for all observers, regardless of the motion of the light source or observer.",
      "date": "1905"
    },
    {
      "headline": "Development of Lorentz Transformations",
      "text": "The Lorentz transformations, which describe how measurements of space and time by two observers are related, were integral to the formulation of special relativity. These transformations were developed by Hendrik Lorentz prior to Einstein's work and were incorporated into the theory.",
      "date": "1905"
    },
    {
      "headline": "Mass-Energy Equivalence",
      "text": "Einstein's theory of special relativity led to the famous equation E=mc², which expresses the equivalence of mass and energy. This was a groundbreaking concept that emerged from the theory.",
      "date": "1905"
    },
    {
      "headline": "Experimental Confirmation",
      "text": "The theory of special relativity was experimentally confirmed through various experiments, such as the Michelson-Morley experiment, which demonstrated the constancy of the speed of light.",
      "date": "1887"
    },
    {
      "headline": "Impact on Physics",
      "text": "Special relativity had a profound impact on the field of physics, influencing the development of quantum mechanics and general relativity, and changing the understanding of space and time.",
      "date": "20th century"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Introduction of Technicolor Process 1",
      "text": "Technicolor Process 1 was introduced in 1916. It was the first color motion picture process developed by Technicolor, marking the beginning of the company's innovations in color film technology.",
      "date": "1916"
    },
    {
      "headline": "Introduction of Technicolor Process 2",
      "text": "In 1917, Technicolor introduced Process 2, which was an improvement over the initial process. It used a two-color system that was more practical for film production.",
      "date": "1917"
    },
    {
      "headline": "Introduction of Technicolor Process 3",
      "text": "Technicolor Process 3 was introduced in 1922. This process was a subtractive color process that allowed for better color reproduction and was used in films such as 'The Toll of the Sea'.",
      "date": "1922"
    },
    {
      "headline": "Introduction of Technicolor Process 4",
      "text": "In 1932, Technicolor Process 4 was introduced. This three-strip color process became the standard for color films and was used in classics like 'The Wizard of Oz' and 'Gone with the Wind'.",
      "date": "1932"
    },
    {
      "headline": "Technicolor's Dominance in Color Film",
      "text": "Throughout the 1930s and 1940s, Technicolor became the dominant color process in Hollywood, known for its vibrant and saturated colors.",
      "date": "1930-1940"
    },
    {
      "headline": "Decline of Technicolor's Three-Strip Process",
      "text": "By the 1950s, the three-strip Technicolor process began to decline as new color film technologies, such as Eastmancolor, became more popular due to their lower cost and ease of use.",
      "date": "1950"
    },
    {
      "headline": "Technicolor's Transition to Other Technologies",
      "text": "In the latter half of the 20th century, Technicolor transitioned to other technologies and services, including film processing and digital imaging, to adapt to the changing film industry.",
      "date": "1960-2000"
    }
  ]
}

