{
  "timeline": [
    {
      "headline": "Construction of the Great Stupa",
      "text": "The Great Stupa at Sanchi was originally commissioned by the Mauryan emperor Ashoka in the 3rd century BCE. It is one of the oldest stone structures in India and was built to house relics of the Buddha.",
      "date": "-0243"
    },
    {
      "headline": "Enlargement of the Great Stupa",
      "text": "During the Shunga period, the Great Stupa was enlarged. The original brick structure was covered with stone slabs, and the dome was expanded to almost twice its original size. This renovation took place in the 2nd century BCE.",
      "date": "-0150"
    },
    {
      "headline": "Addition of the Toranas",
      "text": "In the 1st century BCE, four elaborately carved gateways, known as toranas, were added to the Great Stupa. These gateways are decorated with intricate carvings depicting scenes from the life of the Buddha and Jataka tales.",
      "date": "-0100"
    },
    {
      "headline": "Gupta Period Renovations",
      "text": "During the Gupta period, around the 4th to 5th centuries CE, further additions and renovations were made to the Sanchi complex. This included the construction of smaller stupas and temples.",
      "date": "0400"
    },
    {
      "headline": "Rediscovery by British Officer",
      "text": "In 1818, the Sanchi Stupa was rediscovered by a British officer named General Taylor. This marked the beginning of renewed interest and preservation efforts for the site.",
      "date": "1818"
    },
    {
      "headline": "Restoration by Sir John Marshall",
      "text": "Between 1912 and 1919, Sir John Marshall, the then Director-General of the Archaeological Survey of India, led extensive restoration work at Sanchi. This helped preserve the site and its structures for future generations.",
      "date": "1912"
    },
    {
      "headline": "UNESCO World Heritage Site Designation",
      "text": "In 1989, the Buddhist Monuments at Sanchi, including the Great Stupa, were designated as a UNESCO World Heritage Site, recognizing their historical and cultural significance.",
      "date": "1989"
    }
  ]
}

