    {
      "headline": "Start of the Battle of Điện Biên Phủ",
      "text": "The Battle of Điện Biên Phủ began on 13 March 1954, marking the start of a major confrontation between the French Union forces and the Viet Minh.",
      "date": "1954-03-13"
    },
    {
      "headline": "Viet Minh Launches Assault",
      "text": "On 13 March 1954, the Viet Minh launched a massive artillery bombardment against the French positions, marking the beginning of the battle.",
      "date": "1954-03-13"
    },
    {
      "headline": "Fall of Beatrice",
      "text": "On 14 March 1954, the French strongpoint Beatrice fell to the Viet Minh after a night of intense fighting.",
      "date": "1954-03-14"
    },
    {
      "headline": "Fall of Gabrielle",
      "text": "On 17 March 1954, the French strongpoint Gabrielle was captured by the Viet Minh, further weakening the French defensive position.",
      "date": "1954-03-17"
    },
    {
      "headline": "Fall of Anne-Marie",
      "text": "On 30 March 1954, the Viet Minh captured the French strongpoint Anne-Marie, continuing their advance.",
      "date": "1954-03-30"
    },
    {
      "headline": "French Counterattack",
      "text": "On 31 March 1954, the French forces launched a counterattack to regain lost positions, but it was largely unsuccessful.",
      "date": "1954-03-31"
    },
    {
      "headline": "Fall of Dominique and Eliane",
      "text": "By 1 May 1954, the Viet Minh had captured the French strongpoints Dominique and Eliane, further tightening their grip on the French positions.",
      "date": "1954-05-01"
    },
    {
      "headline": "Final Assault and French Surrender",
      "text": "On 7 May 1954, the Viet Minh launched a final assault on the remaining French positions, leading to the surrender of the French forces and the end of the battle.",
      "date": "1954-05-07"
    },
    {
      "headline": "End of the Battle of Điện Biên Phủ",
      "text": "The Battle of Điện Biên Phủ ended on 7 May 1954 with a decisive victory for the Viet Minh, marking a turning point in the First Indochina War.",
      "date": "1954-05-07"
    }
  ]
}

