{
  "timeline": [
    {
      "headline": "Beginning of the Old Norse Period",
      "text": "Old Norse began to develop as a distinct language around the 8th century, coinciding with the start of the Viking Age.",
      "date": "0700"
    },
    {
      "headline": "Viking Age",
      "text": "The Viking Age, from approximately 793 to 1066, was a period of significant expansion and influence for Old Norse speakers, as they explored, raided, and settled across Europe.",
      "date": "0793"
    },
    {
      "headline": "Christianization of Scandinavia",
      "text": "The Christianization of Scandinavia, occurring primarily between the 8th and 12th centuries, influenced the Old Norse language by introducing Latin script and Christian terminology.",
      "date": "0800"
    },
    {
      "headline": "Consolidation of Scandinavian Kingdoms",
      "text": "During the 10th and 11th centuries, the consolidation of Scandinavian kingdoms began, which helped standardize the Old Norse language across regions.",
      "date": "0900"
    },
    {
      "headline": "Old Norse Literature Flourishes",
      "text": "The 13th century saw the flourishing of Old Norse literature, including the writing of sagas and Eddas, which are key sources of Norse mythology and history.",
      "date": "1200"
    },
    {
      "headline": "Transition to Middle Ages and Language Divergence",
      "text": "By the 15th century, Old Norse had evolved into distinct languages, such as Old Icelandic and Old Norwegian, marking the end of the Old Norse period.",
      "date": "1400"
    }
  ]
}

