{
  "timeline": [
    {
      "headline": "Founding of Rome",
      "text": "According to legend, Rome was founded in 753 BCE. The Roman calendar is believed to have originated around this time.",
      "date": "-0753"
    },
    {
      "headline": "Introduction of the Roman Calendar",
      "text": "The original Roman calendar is believed to have been introduced by Romulus, the first king of Rome, around 738 BCE. It was a lunar calendar with 10 months.",
      "date": "-0738"
    },
    {
      "headline": "Reform by King Numa Pompilius",
      "text": "Around 713 BCE, King Numa Pompilius reformed the Roman calendar by adding the months of January and February, making it a 12-month calendar.",
      "date": "-0713"
    },
    {
      "headline": "Introduction of the Intercalary Month",
      "text": "To align the calendar with the solar year, an intercalary month called Mercedonius was introduced around 450 BCE.",
      "date": "-0450"
    },
    {
      "headline": "Julian Calendar Reform",
      "text": "In 46 BCE, Julius Caesar reformed the Roman calendar, creating the Julian calendar. This reform introduced a 365-day year with a leap year every four years.",
      "date": "-0046"
    },
    {
      "headline": "Augustan Reform",
      "text": "In 8 BCE, Emperor Augustus made further adjustments to the Julian calendar, fixing the leap year cycle.",
      "date": "-0008"
    },
    {
      "headline": "Adoption of the Gregorian Calendar",
      "text": "The Julian calendar remained in use until it was gradually replaced by the Gregorian calendar, starting in 1582 CE.",
      "date": "1582"
    }
  ]
}

