      "headline": "First Recorded Human Activity",
      "text": "The Isles of Scilly have evidence of human activity dating back to the Neolithic period, around 2500 BCE.",
      "date": "-2500"
    },
    {
      "headline": "Roman Occupation",
      "text": "During the Roman period, the Isles of Scilly were known as 'Insulae Sillinae'. The Romans used the islands as a trading post.",
      "date": "0000"
    },
    {
      "headline": "Norman Conquest",
      "text": "After the Norman Conquest of England in 1066, the Isles of Scilly were included in the Domesday Book of 1086.",
      "date": "1086"
    },
    {
      "headline": "Civil War Fortifications",
      "text": "During the English Civil War (1642–1651), the Isles of Scilly were fortified by the Royalists and became a base for privateering.",
      "date": "1642"
    },
    {
      "headline": "Scilly Naval Disaster",
      "text": "In 1707, the Isles of Scilly were the site of a naval disaster when four British warships were wrecked, resulting in the loss of nearly 2,000 lives.",
      "date": "1707"
    },
    {
      "headline": "Establishment of the Duchy of Cornwall",
      "text": "In 1753, the Isles of Scilly were included in the Duchy of Cornwall, which manages the land and property of the Prince of Wales.",
      "date": "1753"
    },
    {
      "headline": "Lighthouse Construction",
      "text": "The Bishop Rock Lighthouse, one of the most famous lighthouses in the world, was completed in 1858.",
      "date": "1858"
    },
    {
      "headline": "World War II",
      "text": "During World War II, the Isles of Scilly were fortified and used as a base for anti-submarine warfare.",
      "date": "1939"
    },
    {
      "headline": "Designation as Area of Outstanding Natural Beauty",
      "text": "In 1975, the Isles of Scilly were designated as an Area of Outstanding Natural Beauty.",
      "date": "1975"
    }
  ]
}

