{
  "timeline": [
    {
      "headline": "First Known Murder",
      "text": "The first known murder by John Bunting and his accomplices occurred in August 1992. The victim was Clinton Trezise, whose body was found buried in a shallow grave in Lower Light, South Australia.",
      "date": "1992-08"
    },
    {
      "headline": "Second Murder",
      "text": "In 1995, the second known victim, Ray Davies, was murdered by the group. His body was not discovered until the investigation into the Snowtown murders began.",
      "date": "1995"
    },
    {
      "headline": "Third Murder",
      "text": "In 1997, Suzanne Allen was murdered. Her body was found wrapped in 11 different plastic bags.",
      "date": "1997"
    },
    {
      "headline": "Fourth Murder",
      "text": "In 1998, Michael Gardiner was murdered by the group.",
      "date": "1998"
    },
    {
      "headline": "Fifth Murder",
      "text": "In 1998, Barry Lane was murdered. He was a former lover of Robert Wagner and was killed due to his knowledge of the previous murders.",
      "date": "1998"
    },
    {
      "headline": "Sixth Murder",
      "text": "In 1998, Thomas Trevilyan was murdered. His death was initially staged to look like a suicide.",
      "date": "1998"
    },
    {
      "headline": "Seventh Murder",
      "text": "In 1998, Gavin Porter was murdered. He was a friend of James Vlassakis.",
      "date": "1998"
    },
    {
      "headline": "Eighth Murder",
      "text": "In 1999, Frederick Brooks was murdered. His body was found in a barrel in the bank vault in Snowtown.",
      "date": "1999"
    },
    {
      "headline": "Ninth Murder",
      "text": "In 1999, Gary O'Dwyer was murdered. His body was also found in a barrel in the bank vault in Snowtown.",
      "date": "1999"
    },
    {
      "headline": "Tenth Murder",
      "text": "In 1999, Elizabeth Haydon was murdered. Her body was found in the bank vault in Snowtown.",
      "date": "1999"
    },
    {
      "headline": "Eleventh Murder",
      "text": "In 1999, David Johnson was murdered. He was the last known victim of the group.",
      "date": "1999"
    },
    {
      "headline": "Discovery of Bodies",
      "text": "On May 20, 1999, the bodies of eight victims were discovered in barrels in a disused bank vault in Snowtown, South Australia, leading to the arrest of the perpetrators.",
      "date": "1999-05-20"
    },
    {
      "headline": "Arrests and Charges",
      "text": "In May 1999, John Bunting, Robert Wagner, James Vlassakis, and Mark Haydon were arrested and charged with multiple counts of murder.",
