    {
      "headline": "Sudetenland becomes part of the Czech state",
      "text": "Since the 9th century, the regions that would later be known as the Sudetenland were an integral part of the Czech state both geographically and politically.",
      "date": "-0800"
    },
    {
      "headline": "Sudeten Germans settle in the region",
      "text": "During the Middle Ages, German speakers began to settle in the border districts of Bohemia, Moravia, and Czech Silesia, which later became known as the Sudetenland.",
      "date": "1200"
    },
    {
      "headline": "Sudetenland under Habsburg rule",
      "text": "The regions of Bohemia, Moravia, and Czech Silesia, including the Sudetenland, came under the control of the Habsburg Monarchy, becoming part of the Austro-Hungarian Empire.",
      "date": "1526"
    },
    {
      "headline": "End of World War I and formation of Czechoslovakia",
      "text": "Following the end of World War I in 1918, the Austro-Hungarian Empire was dissolved, and the Sudetenland became part of the newly formed Czechoslovakia.",
      "date": "1918"
    },
    {
      "headline": "Sudeten German Party gains influence",
      "text": "In the 1930s, the Sudeten German Party, led by Konrad Henlein, gained significant influence among the Sudeten Germans, advocating for greater autonomy.",
      "date": "1930"
    },
    {
      "headline": "Munich Agreement and annexation by Nazi Germany",
      "text": "On September 30, 1938, the Munich Agreement was signed, allowing Nazi Germany to annex the Sudetenland. This was part of Adolf Hitler's expansionist policies.",
      "date": "1938-09-30"
    },
    {
      "headline": "End of World War II and return to Czechoslovakia",
      "text": "After the defeat of Nazi Germany in 1945, the Sudetenland was returned to Czechoslovakia. The German-speaking population was expelled in the aftermath.",
      "date": "1945"
    }
  ]
}

