{
  "timeline": [
    {
      "headline": "Formation of Earth",
      "text": "Earth formed approximately 4.54 billion years ago from the solar nebula, the disc-shaped cloud of gas and dust left over from the Sun's formation.",
      "date": "-4540000000"
    },
    {
      "headline": "Formation of the Moon",
      "text": "The Moon formed about 4.5 billion years ago, likely as a result of a collision between Earth and a Mars-sized body called Theia.",
      "date": "-4500000000"
    },
    {
      "headline": "Late Heavy Bombardment",
      "text": "Around 4.1 to 3.8 billion years ago, the Late Heavy Bombardment occurred, during which a large number of asteroids collided with the early terrestrial planets in the inner Solar System.",
      "date": "-4100000000"
    },
    {
      "headline": "First Evidence of Life",
      "text": "The earliest evidence of life on Earth dates back to about 3.5 billion years ago, with the discovery of stromatolites and microfossils.",
      "date": "-3500000000"
    },
    {
      "headline": "Great Oxidation Event",
      "text": "Approximately 2.4 billion years ago, the Great Oxidation Event occurred, marking the first significant increase in Earth's atmospheric oxygen levels due to photosynthetic organisms.",
      "date": "-2400000000"
    },
    {
      "headline": "Snowball Earth",
      "text": "Between 720 and 635 million years ago, Earth experienced severe glaciations known as 'Snowball Earth,' where ice sheets possibly reached the equator.",
      "date": "-720000000"
    },
    {
      "headline": "Cambrian Explosion",
      "text": "Around 541 million years ago, the Cambrian Explosion occurred, a period of rapid evolutionary development and diversification of life forms.",
      "date": "-541000000"
    },
    {
      "headline": "Permian-Triassic Extinction Event",
      "text": "Approximately 252 million years ago, the Permian-Triassic extinction event, the most severe extinction event in Earth's history, wiped out about 96% of marine species and 70% of terrestrial vertebrate species.",
      "date": "-252000000"
    },
    {
      "headline": "Cretaceous-Paleogene Extinction Event",
      "text": "About 66 million years ago, the Cretaceous-Paleogene extinction event led to the extinction of approximately 75% of Earth's species, including the non-avian dinosaurs, likely due to a massive asteroid impact.",
      "date": "-66000000"
    },
    {
      "headline": "Pleistocene Epoch",
      "text": "The Pleistocene Epoch, starting around 2.58 million years ago, was characterized by repeated glacial cycles and the evolution of Homo sapiens.",
      "date": "-2580000"
    },
    {
      "headline": "Holocene Epoch",
      "text": "The Holocene Epoch began approximately 11,700 years ago, marking the end of the last Ice Age and the rise of human civilization.",
      "date": "-11700"
    }
  ]
}

