{
  "timeline": [
    {
      "headline": "Early Theories of Race",
      "text": "In the 18th century, the concept of race began to take shape with the work of naturalists like Carl Linnaeus and Johann Friedrich Blumenbach, who classified humans into different races based on physical characteristics.",
      "date": "1700"
    },
    {
      "headline": "Blumenbach's Racial Classification",
      "text": "In 1779, Johann Friedrich Blumenbach proposed one of the first classifications of the human races, dividing them into five categories: Caucasian, Mongolian, Malayan, Ethiopian, and American.",
      "date": "1779"
    },
    {
      "headline": "Rise of Scientific Racism",
      "text": "During the 19th century, scientific racism gained prominence with the misuse of Darwinian theories and the development of anthropometry, which attempted to measure human physical variation to support racial hierarchies.",
      "date": "1800"
    },
    {
      "headline": "Gobineau's Essay on the Inequality of Human Races",
      "text": "In 1853-1855, Arthur de Gobineau published 'An Essay on the Inequality of the Human Races', which argued that racial differences were the source of human civilization's decline.",
      "date": "1853"
    },
    {
      "headline": "Eugenics Movement",
      "text": "In the late 19th and early 20th centuries, the eugenics movement emerged, advocating for the improvement of human populations through controlled breeding, often based on racial theories.",
      "date": "1880"
    },
    {
      "headline": "The Passing of the Great Race",
      "text": "In 1916, Madison Grant published 'The Passing of the Great Race', which promoted the idea of Nordic superiority and influenced immigration policies in the United States.",
      "date": "1916"
    },
    {
      "headline": "Nazi Racial Theories",
      "text": "During the 1930s and 1940s, Nazi Germany implemented racial theories that led to the Holocaust, using pseudoscientific ideas to justify the extermination of Jews and other groups.",
      "date": "1930"
    },
    {
      "headline": "UNESCO Statement on Race",
      "text": "In 1950, UNESCO released a statement declaring that all humans belong to the same species and that 'race' is not a biological reality but a social myth.",
      "date": "1950"
    },
    {
      "headline": "Decline of Scientific Racism",
      "text": "By the mid-20th century, scientific racism was largely discredited within the scientific community, as advances in genetics showed that racial categories have no biological basis.",
      "date": "1950"
    }
  ]
}

