{
  "timeline": [
    {
      "headline": "Founding of the Katipunan",
      "text": "The Katipunan, officially known as the Kataastaasang Kagalanggalangang Katipunan ng mga Anak ng Bayan, was founded on July 7, 1892, by Filipino nationalists including Deodato Arellano, Andrés Bonifacio, Valentin Diaz, Ladislao Diwa, José Dizon, and Teodoro Plata. The organization aimed to gain independence from the Spanish Empire through armed revolution.",
      "date": "1892-07-07"
    },
    {
      "headline": "First Supremo of the Katipunan",
      "text": "Deodato Arellano was elected as the first Supremo (leader) of the Katipunan in 1892, shortly after its founding.",
      "date": "1892"
    },
    {
      "headline": "Andrés Bonifacio becomes Supremo",
      "text": "In 1895, Andrés Bonifacio became the Supremo of the Katipunan, leading the organization towards more active revolutionary activities.",
      "date": "1895"
    },
    {
      "headline": "Discovery of the Katipunan",
      "text": "The existence of the Katipunan was discovered by Spanish authorities in August 1896, which led to increased crackdowns and the eventual start of the Philippine Revolution.",
      "date": "1896-08"
    },
    {
      "headline": "Cry of Pugad Lawin",
      "text": "On August 23, 1896, the Katipunan, led by Andrés Bonifacio, initiated the Philippine Revolution with the Cry of Pugad Lawin, where members tore their cedulas (residence certificates) as a sign of defiance against Spanish rule.",
      "date": "1896-08-23"
    },
    {
      "headline": "Battle of San Juan del Monte",
      "text": "The first major battle of the Philippine Revolution, the Battle of San Juan del Monte, took place on August 30, 1896, marking the beginning of open hostilities between the Katipunan and Spanish forces.",
      "date": "1896-08-30"
    },
    {
      "headline": "Tejeros Convention",
      "text": "On March 22, 1897, the Tejeros Convention was held, where internal conflicts within the Katipunan led to the election of Emilio Aguinaldo as the President of a new revolutionary government, sidelining Bonifacio.",
      "date": "1897-03-22"
    },
    {
      "headline": "Execution of Andrés Bonifacio",
      "text": "Andrés Bonifacio was executed on May 10, 1897, after being charged with treason and sedition by the revolutionary government led by Emilio Aguinaldo.",
      "date": "1897-05-10"
    },
    {
      "headline": "End of the Katipunan",
      "text": "The Katipunan effectively dissolved as a revolutionary organization after the establishment of the First Philippine Republic in 1899, following the conclusion of the Spanish-American War and the Treaty of Paris.",
      "date": "1899"
    }
  ]
}

{
  "timeline": [
