{
  "timeline": [
    {
      "headline": "Beginning of the Meiji Era",
      "text": "The Meiji era began on October 23, 1868, marking the start of Emperor Meiji's reign and the beginning of Japan's transformation from a feudal society to a modern state.",
      "date": "1868-10-23"
    },
    {
      "headline": "Meiji Restoration",
      "text": "In 1868, the Meiji Restoration marked the return of political power to the Emperor of Japan, ending the Tokugawa shogunate and initiating major political, economic, and social changes.",
      "date": "1868"
    },
    {
      "headline": "Abolition of the Han System",
      "text": "In 1871, the han system, which was the domain system of the feudal lords, was abolished and replaced with a prefecture system, centralizing power under the Meiji government.",
      "date": "1871"
    },
    {
      "headline": "Iwakura Mission",
      "text": "From 1871 to 1873, the Iwakura Mission, a Japanese diplomatic journey around the world, was undertaken to study Western institutions and technologies.",
      "date": "1871"
    },
    {
      "headline": "Introduction of the Conscription Law",
      "text": "In 1873, the Conscription Law was introduced, mandating military service for all males, which helped modernize Japan's military forces.",
      "date": "1873"
    },
    {
      "headline": "Satsuma Rebellion",
      "text": "The Satsuma Rebellion occurred in 1877, led by Saigō Takamori, as a revolt of disaffected samurai against the new imperial government.",
      "date": "1877"
    },
    {
      "headline": "Promulgation of the Meiji Constitution",
      "text": "On February 11, 1889, the Meiji Constitution was promulgated, establishing a constitutional monarchy with a parliamentary system.",
      "date": "1889-02-11"
    },
    {
      "headline": "First Sino-Japanese War",
      "text": "The First Sino-Japanese War took place from 1894 to 1895, resulting in Japan's victory and the Treaty of Shimonoseki, which expanded Japan's influence in Asia.",
      "date": "1894"
    },
    {
      "headline": "Russo-Japanese War",
      "text": "From 1904 to 1905, the Russo-Japanese War was fought, marking Japan's emergence as a major world power after defeating Russia.",
      "date": "1904"
    },
    {
      "headline": "Annexation of Korea",
      "text": "In 1910, Japan formally annexed Korea, expanding its empire and influence in East Asia.",
      "date": "1910"
    },
    {
      "headline": "End of the Meiji Era",
      "text": "The Meiji era ended on July 30, 1912, with the death of Emperor Meiji, leading to the succession of Emperor Taishō and the beginning of the Taishō era.",
      "date": "1912-07-30"
    }
  ]
}

