{
  "timeline": [
    {
      "headline": "Marriage of Richard and Mildred Loving",
      "text": "Richard Loving, a white man, and Mildred Jeter, a woman of African American and Native American descent, were married in Washington, D.C., on June 2, 1958. They returned to their home in Caroline County, Virginia, where interracial marriage was illegal.",
      "date": "1958-06-02"
    },
    {
      "headline": "Arrest of the Lovings",
      "text": "On July 11, 1958, the Lovings were arrested in their home in Virginia for violating the state's anti-miscegenation statute, the Racial Integrity Act of 1924.",
      "date": "1958-07-11"
    },
    {
      "headline": "Initial Conviction",
      "text": "In January 1959, the Lovings pleaded guilty to charges of 'cohabiting as man and wife, against the peace and dignity of the Commonwealth' and were sentenced to one year in prison, with the sentence suspended on the condition that they leave Virginia and not return together for 25 years.",
      "date": "1959-01"
    },
    {
      "headline": "Appeal to the Supreme Court of Virginia",
      "text": "The Lovings, with the help of the American Civil Liberties Union (ACLU), appealed their conviction to the Supreme Court of Virginia, which upheld the original ruling in 1966.",
      "date": "1966"
    },
    {
      "headline": "U.S. Supreme Court Hearing",
      "text": "The U.S. Supreme Court heard oral arguments in Loving v. Virginia on April 10, 1967.",
      "date": "1967-04-10"
    },
    {
      "headline": "Supreme Court Decision",
      "text": "On June 12, 1967, the U.S. Supreme Court issued a unanimous decision in Loving v. Virginia, striking down laws banning interracial marriage as unconstitutional under the Equal Protection and Due Process Clauses of the Fourteenth Amendment.",
      "date": "1967-06-12"
    },
    {
      "headline": "Impact on Same-Sex Marriage",
      "text": "Beginning in 2013, Loving v. Virginia was cited as precedent in U.S. federal court decisions ruling that restrictions on same-sex marriage were unconstitutional, influencing cases such as Obergefell v. Hodges in 2015.",
      "date": "2013"
    }
  ]
}

