{
  "timeline": [
    {
      "headline": "Early Inhabitants",
      "text": "The indigenous peoples of Sakhalin, including the Ainu, Oroks, and Nivkhs, have inhabited the island for thousands of years. These groups lived primarily by fishing, hunting, and gathering.",
      "date": "-10000"
    },
    {
      "headline": "First Recorded Exploration",
      "text": "In 1643, the Dutch explorer Maarten Gerritsz Vries was the first European to explore the waters around Sakhalin.",
      "date": "1643"
    },
    {
      "headline": "Japanese Exploration",
      "text": "In 1809, Japanese explorer Mamiya Rinzō confirmed that Sakhalin was an island by discovering and mapping the Mamiya Strait (now known as the Strait of Tartary).",
      "date": "1809"
    },
    {
      "headline": "Treaty of Shimoda",
      "text": "In 1855, the Treaty of Shimoda was signed between Russia and Japan, allowing both countries to settle in Sakhalin without a clear boundary.",
      "date": "1855"
    },
    {
      "headline": "Treaty of Saint Petersburg",
      "text": "In 1875, the Treaty of Saint Petersburg was signed, with Japan ceding all of Sakhalin to Russia in exchange for the Kuril Islands.",
      "date": "1875"
    },
    {
      "headline": "Russo-Japanese War",
      "text": "During the Russo-Japanese War (1904-1905), Japan occupied the southern part of Sakhalin.",
      "date": "1904"
    },
    {
      "headline": "Treaty of Portsmouth",
      "text": "In 1905, the Treaty of Portsmouth ended the Russo-Japanese War, with Russia ceding the southern half of Sakhalin to Japan.",
      "date": "1905"
    },
    {
      "headline": "Soviet Invasion of South Sakhalin",
      "text": "In August 1945, the Soviet Union invaded and occupied the southern part of Sakhalin during the final days of World War II.",
      "date": "1945-08"
    },
    {
      "headline": "Sakhalin Becomes Part of the Soviet Union",
      "text": "In 1945, following Japan's defeat in World War II, the entire island of Sakhalin was incorporated into the Soviet Union.",
      "date": "1945"
    },
    {
      "headline": "Sakhalin Earthquake",
      "text": "On May 28, 1995, a devastating earthquake struck the island, particularly affecting the town of Neftegorsk, resulting in significant loss of life and destruction.",
      "date": "1995-05-28"
    }
  ]
}

