{
  "timeline": [
    {
      "headline": "Code of Hammurabi",
      "text": "The Code of Hammurabi, dating back to around 1754 BCE, is one of the earliest known sets of laws that institutionalized slavery as an established practice in Mesopotamia.",
      "date": "-1754"
    },
    {
      "headline": "Slavery in Ancient Egypt",
      "text": "Slavery was present in Ancient Egypt, with records indicating its existence during the Old Kingdom period (c. 2686–2181 BCE). Slaves were often prisoners of war or people who had fallen into debt.",
      "date": "-2686"
    },
    {
      "headline": "Slavery in Ancient Greece",
      "text": "Slavery was a fundamental part of Ancient Greek society, with slaves being used in households, agriculture, mines, and as skilled artisans. This practice was prevalent from around the 8th century BCE.",
      "date": "-0800"
    },
    {
      "headline": "Roman Slavery",
      "text": "Slavery was integral to Roman society and economy, with slaves being used for labor, entertainment, and domestic services. The Roman Republic (509–27 BCE) and the Roman Empire (27 BCE–476 CE) both heavily relied on slave labor.",
      "date": "-0509"
    },
    {
      "headline": "Trans-Saharan Slave Trade",
      "text": "The Trans-Saharan Slave Trade began around the 7th century CE, involving the trade of slaves across the Sahara Desert to North Africa and the Middle East.",
      "date": "0700"
    },
    {
      "headline": "Slavery in the Islamic World",
      "text": "From the 7th century onwards, slavery was practiced in the Islamic world, with slaves being used in various roles, including soldiers, servants, and laborers.",
      "date": "0700"
    },
    {
      "headline": "Viking Slave Trade",
      "text": "During the Viking Age (c. 793–1066 CE), Vikings engaged in slave trading, capturing people from the British Isles and other parts of Europe to sell in markets across Europe and the Middle East.",
      "date": "0793"
    },
    {
      "headline": "Atlantic Slave Trade",
      "text": "The Atlantic Slave Trade began in the 16th century and involved the transportation of enslaved Africans to the Americas. It became a major part of the economy in the 17th and 18th centuries.",
      "date": "1500"
    },
    {
      "headline": "Abolition of the Slave Trade Act",
      "text": "The British Parliament passed the Abolition of the Slave Trade Act in 1807, making it illegal to engage in the slave trade throughout the British Empire.",
      "date": "1807"
    },
    {
      "headline": "Emancipation Proclamation",
      "text": "On January 1, 1863, U.S. President Abraham Lincoln issued the Emancipation Proclamation, declaring all slaves in Confederate-held territory to be free.",
      "date": "1863-01-01"
    },
    {
      "headline": "13th Amendment to the U.S. Constitution",
      "text": "The 13th Amendment, ratified on December 6, 1865, abolished slavery in the United States.",
      "date": "1865-12-06"
    },
    {
      "headline": "Slavery Abolished in Brazil",
      "text": "On May 13, 1888, Brazil abolished slavery with the signing of the Lei Áurea (Golden Law) by Princess Isabel.",
      "date": "1888-05-13"
    }
  ]
}

