}

{
  "timeline": [
    {
      "headline": "Birth of Tecumseh",
      "text": "Tecumseh was born in March 1768 in the Shawnee village of Piqua, along the Mad River in present-day Ohio.",
      "date": "1768-03"
    },
    {
      "headline": "Battle of Fallen Timbers",
      "text": "On August 20, 1794, Tecumseh participated in the Battle of Fallen Timbers, where Native American forces were defeated by the United States Army led by General Anthony Wayne.",
      "date": "1794-08-20"
    },
    {
      "headline": "Formation of Tecumseh's Confederacy",
      "text": "In the early 1800s, Tecumseh began forming a confederacy of Native American tribes to resist the encroachment of settlers on their lands.",
      "date": "1800"
    },
    {
      "headline": "Battle of Tippecanoe",
      "text": "On November 7, 1811, Tecumseh's confederacy was defeated by American forces led by Governor William Henry Harrison at the Battle of Tippecanoe.",
      "date": "1811-11-07"
    },
    {
      "headline": "Alliance with the British",
      "text": "During the War of 1812, Tecumseh allied with the British against the United States, hoping to protect Native American lands.",
      "date": "1812"
    },
    {
      "headline": "Death of Tecumseh",
      "text": "Tecumseh was killed on October 5, 1813, at the Battle of the Thames in present-day Ontario, Canada, marking the end of his confederacy's resistance.",
      "date": "1813-10-05"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of Bernicia",
      "text": "The kingdom of Bernicia was established in the early 6th century, around 547, when Anglian settlers established a kingdom in what is now southeastern Scotland and northeastern England.",
      "date": "0547"
    },
    {
      "headline": "Formation of Deira",
      "text": "The kingdom of Deira was established in the late 6th century, around 559, in what is now Yorkshire.",
      "date": "0559"
    },
    {
      "headline": "Unification of Bernicia and Deira",
      "text": "In 604, Æthelfrith, king of Bernicia, united the kingdoms of Bernicia and Deira to form the kingdom of Northumbria.",
      "date": "0604"
    },
    {
      "headline": "Reign of King Edwin",
      "text": "King Edwin ruled Northumbria from 616 to 633, during which time he expanded the kingdom and converted to Christianity.",
      "date": "0616"
    },
    {
      "headline": "Battle of Hatfield Chase",
      "text": "In 633, King Edwin was defeated and killed by an alliance of Penda of Mercia and Cadwallon of Gwynedd at the Battle of Hatfield Chase.",
      "date": "0633"
    },
    {
      "headline": "Reign of King Oswald",
      "text": "King Oswald ruled from 634 to 642, re-establishing Northumbrian power and promoting Christianity.",
      "date": "0634"
    },
    {
      "headline": "Battle of Maserfield",
      "text": "In 642, King Oswald was killed at the Battle of Maserfield by Penda of Mercia.",
      "date": "0642"
    },
    {
      "headline": "Reign of King Oswiu",
      "text": "King Oswiu ruled from 642 to 670, consolidating power and defeating Penda at the Battle of the Winwaed in 655.",
      "date": "0642"
    },
    {
      "headline": "Synod of Whitby",
      "text": "In 664, the Synod of Whitby was held, where King Oswiu decided to follow Roman rather than Celtic ecclesiastical practices, aligning Northumbria with the wider Christian Church.",
      "date": "0664"
    },
    {
      "headline": "Reign of King Ecgfrith",
      "text": "King Ecgfrith ruled from 670 to 685, during which time Northumbria reached its greatest territorial extent.",
      "date": "0670"
    },
    {
      "headline": "Battle of Nechtansmere",
      "text": "In 685, King Ecgfrith was defeated and killed by the Picts at the Battle of Nechtansmere, leading to the loss of Northumbrian control over southern Scotland.",
      "date": "0685"
    },
    {
      "headline": "Viking Invasions",
      "text": "In the late 8th century, Viking raids began, with the first recorded attack on Lindisfarne in 793, marking the beginning of increased Viking activity in the region.",
      "date": "0793"
    },
    {
      "headline": "Fall of Northumbria",
      "text": "In 867, the Viking Great Heathen Army captured York, leading to the decline of Northumbrian power and the establishment of the Viking kingdom of Jorvik.",
      "date": "0867"
    },
    {
      "headline": "Integration into England",
      "text": "By the mid-10th century, Northumbria was fully integrated into the emerging kingdom of England under the rule of King Æthelstan.",
      "date": "0954"
    }
  ]
}

