{
  "timeline": [
    {
      "headline": "Birth of Robert Catesby",
      "text": "Robert Catesby was born in 1573 in Warwickshire, England.",
      "date": "1573"
    },
    {
      "headline": "Education at Oxford University",
      "text": "Catesby was educated at Oxford University. He left college before taking his degree, presumably to avoid swearing the Oath of Supremacy.",
      "date": "1590"
    },
    {
      "headline": "Marriage to a Protestant",
      "text": "In 1593, Robert Catesby married a Protestant woman and fathered two children. One child survived birth and was baptized in a Protestant church.",
      "date": "1593"
    },
    {
      "headline": "Participation in the Essex Rebellion",
      "text": "In 1601, Catesby took part in the Essex Rebellion. He was captured and fined, after which he sold his estate at Chastleton.",
      "date": "1601"
    },
    {
      "headline": "Planning the Gunpowder Plot",
      "text": "Robert Catesby became the leader of a group of English Catholics who planned the failed Gunpowder Plot of 1605, aiming to assassinate King James I and restore a Catholic monarch to the throne.",
      "date": "1604"
    },
    {
      "headline": "Death of Robert Catesby",
      "text": "Robert Catesby died on November 8, 1605, during a shootout with government forces at Holbeche House in Staffordshire, England.",
      "date": "1605-11-08"
    }
  ]
}

