{
  "timeline": [
    {
      "headline": "Beginning of Iran's Nuclear Program",
      "text": "Iran's nuclear program began in the 1950s with the help of the United States under the Atoms for Peace program.",
      "date": "1950"
    },
    {
      "headline": "Establishment of the Tehran Nuclear Research Center",
      "text": "In 1967, the Tehran Nuclear Research Center was established, equipped with a 5-megawatt nuclear research reactor provided by the United States.",
      "date": "1967"
    },
    {
      "headline": "Iran Signs the Nuclear Non-Proliferation Treaty",
      "text": "Iran signed the Nuclear Non-Proliferation Treaty (NPT) in 1968, committing to not pursue nuclear weapons.",
      "date": "1968"
    },
    {
      "headline": "Construction of Bushehr Nuclear Power Plant",
      "text": "Construction of the Bushehr Nuclear Power Plant began in 1975 with the help of German companies.",
      "date": "1975"
    },
    {
      "headline": "Iranian Revolution and Halt of Nuclear Program",
      "text": "The 1979 Iranian Revolution led to a temporary halt in Iran's nuclear program as Western companies withdrew.",
      "date": "1979"
    },
    {
      "headline": "Revival of Nuclear Program",
      "text": "In the mid-1980s, Iran revived its nuclear program with assistance from countries like China and Russia.",
      "date": "1980"
    },
    {
      "headline": "Discovery of Natanz and Arak Facilities",
      "text": "In 2002, the existence of Iran's Natanz uranium enrichment facility and Arak heavy water plant was revealed by an Iranian opposition group.",
      "date": "2002"
    },
    {
      "headline": "Iran Agrees to Suspend Uranium Enrichment",
      "text": "In 2003, Iran agreed to suspend uranium enrichment and allow more inspections by the International Atomic Energy Agency (IAEA).",
      "date": "2003"
    },
    {
      "headline": "Resumption of Uranium Enrichment",
      "text": "In 2006, Iran resumed uranium enrichment, leading to international tensions and sanctions.",
      "date": "2006"
    },
    {
      "headline": "Joint Comprehensive Plan of Action (JCPOA)",
      "text": "In 2015, Iran and the P5+1 countries reached the Joint Comprehensive Plan of Action (JCPOA), limiting Iran's nuclear activities in exchange for sanctions relief.",
      "date": "2015"
    },
    {
      "headline": "US Withdrawal from JCPOA",
      "text": "In 2018, the United States unilaterally withdrew from the JCPOA, leading to increased tensions and Iran resuming some nuclear activities.",
      "date": "2018"
    }
  ]
}

