{
  "timeline": [
    {
      "headline": "Birth of Le Corbusier",
      "text": "Charles-Édouard Jeanneret, known as Le Corbusier, was born on October 6, 1887, in La Chaux-de-Fonds, Switzerland.",
      "date": "1887-10-06"
    },
    {
      "headline": "First House Design",
      "text": "In 1907, Le Corbusier designed his first house, the Villa Fallet, in La Chaux-de-Fonds, Switzerland.",
      "date": "1907"
    },
    {
      "headline": "Move to Paris",
      "text": "Le Corbusier moved to Paris in 1917, where he would eventually establish his career as an architect.",
      "date": "1917"
    },
    {
      "headline": "Founding of L'Esprit Nouveau",
      "text": "In 1920, Le Corbusier co-founded the avant-garde magazine L'Esprit Nouveau, which promoted modernist ideas in art and architecture.",
      "date": "1920"
    },
    {
      "headline": "Publication of 'Vers une architecture'",
      "text": "In 1923, Le Corbusier published 'Vers une architecture', a seminal book that laid out his ideas on modern architecture.",
      "date": "1923"
    },
    {
      "headline": "Design of Villa Savoye",
      "text": "Le Corbusier designed the Villa Savoye, a modernist villa in Poissy, France, completed in 1931. It is one of his most famous works.",
      "date": "1931"
    },
    {
      "headline": "Naturalization as a French Citizen",
      "text": "On September 19, 1930, Le Corbusier acquired French nationality by naturalization.",
      "date": "1930-09-19"
    },
    {
      "headline": "Publication of 'La Ville Radieuse'",
      "text": "In 1935, Le Corbusier published 'La Ville Radieuse', a book outlining his vision for a utopian city.",
      "date": "1935"
    },
    {
      "headline": "Design of the Unité d'Habitation",
      "text": "Le Corbusier designed the Unité d'Habitation in Marseille, France, completed in 1952, a significant example of modernist residential architecture.",
      "date": "1952"
    },
    {
      "headline": "Design of Chandigarh",
      "text": "In the 1950s, Le Corbusier was commissioned to design the city of Chandigarh in India, a major urban planning project.",
      "date": "1950"
    },
    {
      "headline": "Death of Le Corbusier",
      "text": "Le Corbusier died on August 27, 1965, in Roquebrune-Cap-Martin, France.",
      "date": "1965-08-27"
    }
  ]
}

