{
  "timeline": [
    {
      "headline": "Birth of Joseph Haydn",
      "text": "Franz Joseph Haydn was born on March 31, 1732, in Rohrau, Austria.",
      "date": "1732-03-31"
    },
    {
      "headline": "Choirboy at St. Stephen's Cathedral",
      "text": "In 1740, Haydn was recruited to be a choirboy at St. Stephen's Cathedral in Vienna, where he received his early musical education.",
      "date": "1740"
    },
    {
      "headline": "Dismissal from St. Stephen's",
      "text": "In 1749, Haydn was dismissed from St. Stephen's Cathedral after his voice broke, ending his time as a choirboy.",
      "date": "1749"
    },
    {
      "headline": "Employment with Count Morzin",
      "text": "In 1757, Haydn became the Kapellmeister for Count Morzin, marking his first significant employment as a composer.",
      "date": "1757"
    },
    {
      "headline": "Marriage to Maria Anna Keller",
      "text": "On November 26, 1760, Haydn married Maria Anna Keller.",
      "date": "1760-11-26"
    },
    {
      "headline": "Appointment at the Esterházy Court",
      "text": "In 1761, Haydn was appointed as Vice-Kapellmeister to the Esterházy family, one of the most influential positions of his career.",
      "date": "1761"
    },
    {
      "headline": "Promotion to Kapellmeister",
      "text": "In 1766, Haydn was promoted to Kapellmeister at the Esterházy court, following the death of his predecessor, Gregor Werner.",
      "date": "1766"
    },
    {
      "headline": "Publication of 'The Creation'",
      "text": "In 1798, Haydn's oratorio 'The Creation' was first performed, becoming one of his most celebrated works.",
      "date": "1798"
    },
