      "date": "1643"
    },
    {
      "headline": "Creation of the Dukedom of Marlborough",
      "text": "The Dukedom of Marlborough was created in 1702 for John Churchill, a member of the Spencer family, after his military victories during the War of the Spanish Succession.",
      "date": "1702"
    },
    {
      "headline": "Birth of Sir Winston Churchill",
      "text": "Sir Winston Churchill, a prominent member of the Spencer family, was born on November 30, 1874. He would later become the Prime Minister of the United Kingdom during World War II.",
      "date": "1874-11-30"
    },
    {
      "headline": "Birth of Diana, Princess of Wales",
      "text": "Diana, Princess of Wales, was born on July 1, 1961. She was a member of the Spencer family and became one of the most famous figures in the world.",
