      "headline": "Ancient Settlement",
      "text": "Hebron is one of the oldest cities in the region, with evidence of settlement dating back to the Chalcolithic period, around 3500 BCE.",
      "date": "-3500"
    },
    {
      "headline": "Biblical Era",
      "text": "Hebron is mentioned in the Hebrew Bible as the home of Abraham and the burial place of the patriarchs and matriarchs, around 2000 BCE.",
      "date": "-2000"
    },
    {
      "headline": "David's Reign",
      "text": "King David was anointed in Hebron and reigned there for seven years before moving his capital to Jerusalem, around 1010 BCE.",
      "date": "-1010"
    },
    {
      "headline": "Roman Period",
      "text": "During the Roman period, Hebron was known as a significant Jewish city, with a large Jewish population until the Bar Kokhba revolt (132-136 CE).",
      "date": "0132"
    },
    {
      "headline": "Islamic Conquest",
      "text": "Hebron was conquered by Muslim forces in 637 CE, and the city became an important Islamic center.",
      "date": "0637"
    },
    {
      "headline": "Crusader Period",
      "text": "Hebron was captured by the Crusaders in 1100 and was known as 'Castellion Saint Abraham'. It was recaptured by Saladin in 1187.",
      "date": "1100"
    },
    {
      "headline": "Mamluk Period",
      "text": "Under Mamluk rule (1260-1517), Hebron became a center of Islamic learning and pilgrimage.",
      "date": "1260"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Hebron came under Ottoman rule in 1517, and the city continued to be an important religious and commercial center.",
      "date": "1517"
    },
    {
      "headline": "Hebron Massacre",
      "text": "In 1929, a violent massacre occurred in Hebron, resulting in the deaths of 67 Jews and the evacuation of the Jewish community.",
      "date": "1929"
    },
    {
      "headline": "Jordanian Control",
      "text": "After the 1948 Arab-Israeli War, Hebron came under Jordanian control until 1967.",
      "date": "1948"
    },
    {
      "headline": "Israeli Occupation",
      "text": "Hebron was occupied by Israel during the Six-Day War in 1967 and remains a focal point of Israeli-Palestinian tensions.",
      "date": "1967"
    },
    {
      "headline": "Hebron Protocol",
      "text": "In 1997, the Hebron Protocol was signed, dividing the city into areas of Palestinian and Israeli control.",
      "date": "1997"
    }
  ]
}

