{
  "timeline": [
    {
      "headline": "Beginning of the Holocene Epoch",
      "text": "The Holocene epoch began approximately 11,700 years ago, marking the end of the last Ice Age and the start of significant human impact on the environment.",
      "date": "-09700"
    },
    {
      "headline": "Start of the Holocene Extinction",
      "text": "The Holocene extinction, also known as the Anthropocene extinction, is considered to have started around 10,000 years ago with the advent of significant human activity, including hunting and habitat alteration.",
      "date": "-08000"
    },
    {
      "headline": "Extinction of the Dodo",
      "text": "The dodo, a flightless bird native to Mauritius, became extinct in the late 17th century due to overhunting by humans and predation by introduced species. The last widely accepted sighting was in 1662.",
      "date": "1662"
    },
    {
      "headline": "Extinction of the Great Auk",
      "text": "The Great Auk, a large flightless bird found in the North Atlantic, was driven to extinction by hunting for its feathers, meat, fat, and oil. The last known individuals were killed in 1844.",
      "date": "1844"
    },
    {
      "headline": "Passenger Pigeon Extinction",
      "text": "Once the most abundant bird in North America, the passenger pigeon was driven to extinction by hunting and habitat destruction. The last known individual, named Martha, died in captivity in 1914.",
      "date": "1914-09-01"
    },
    {
      "headline": "Extinction of the Thylacine",
      "text": "The thylacine, or Tasmanian tiger, was a carnivorous marsupial native to Tasmania. The last known thylacine died in captivity at the Hobart Zoo in 1936.",
      "date": "1936-09-07"
    },
    {
      "headline": "Introduction of the Term 'Anthropocene'",
      "text": "The term 'Anthropocene' was popularized in 2000 by atmospheric chemist Paul Crutzen to describe the current geological age, viewed as the period during which human activity has been the dominant influence on climate and the environment.",
      "date": "2000"
    },
    {
      "headline": "UN Report on Biodiversity Loss",
      "text": "In 2019, a UN report warned that one million species are at risk of extinction due to human activities, highlighting the severity of the ongoing Holocene extinction.",
      "date": "2019"
    }
  ]
}

