{
  "timeline": [
    {
      "headline": "Initial Public Attention",
      "text": "The accusations of sexual abuse and cover-ups within the Catholic Church began to receive significant public attention during the late 1980s.",
      "date": "1980"
    },
    {
      "headline": "Spotlight Investigation",
      "text": "In 2002, The Boston Globe's Spotlight team published a series of articles exposing widespread sexual abuse by priests in the Boston area and the systemic cover-up by the Church hierarchy.",
      "date": "2002"
    },
    {
      "headline": "U.S. Conference of Catholic Bishops' Charter",
      "text": "In June 2002, the U.S. Conference of Catholic Bishops adopted the Charter for the Protection of Children and Young People, establishing guidelines for addressing allegations of sexual abuse.",
      "date": "2002-06"
    },
    {
      "headline": "John Jay Report",
      "text": "In 2004, the John Jay College of Criminal Justice released a report commissioned by the U.S. Conference of Catholic Bishops, detailing the extent of sexual abuse by priests in the United States from 1950 to 2002.",
      "date": "2004"
    },
    {
      "headline": "Irish Government Reports",
      "text": "Between 2005 and 2009, several reports commissioned by the Irish government, including the Ferns Report, the Ryan Report, and the Murphy Report, revealed widespread abuse and cover-ups in Ireland.",
      "date": "2005"
    },
    {
      "headline": "Pope Benedict XVI's Apology",
      "text": "In March 2010, Pope Benedict XVI issued a pastoral letter to Irish Catholics, apologizing for the abuse and cover-ups.",
      "date": "2010-03"
    },
    {
      "headline": "Pennsylvania Grand Jury Report",
      "text": "In August 2018, a Pennsylvania grand jury report was released, detailing over 1,000 cases of sexual abuse by more than 300 priests in six dioceses over a 70-year period.",
      "date": "2018-08"
    },
    {
      "headline": "Vatican Summit on Sexual Abuse",
      "text": "In February 2019, Pope Francis convened a summit at the Vatican to address the issue of sexual abuse within the Church, attended by bishops from around the world.",
      "date": "2019-02"
    }
  ]
}

