{
  "timeline": [
    {
      "headline": "Origin of Humorism",
      "text": "Humorism originated in Ancient Greece, with the theory being attributed to Hippocrates, who lived from around 460 to 370 BCE. The theory proposed that the human body was made up of four humors: blood, phlegm, black bile, and yellow bile.",
      "date": "-0460"
    },
    {
      "headline": "Development by Galen",
      "text": "Galen, a prominent Greek physician, further developed the theory of humorism around 200 CE. He expanded on Hippocrates' ideas and linked the humors to the four temperaments: sanguine, phlegmatic, melancholic, and choleric.",
      "date": "0200"
    },
    {
      "headline": "Adoption in Roman Medicine",
      "text": "Humorism was adopted by Roman physicians and became a central part of Roman medical practice. It influenced medical thinking and practice throughout the Roman Empire.",
      "date": "0200"
    },
    {
      "headline": "Influence in Medieval Medicine",
      "text": "During the Middle Ages, humorism was the dominant theory in European medicine. It was integrated into the medical teachings of the time, influencing treatments and diagnoses.",
      "date": "1100"
    },
    {
      "headline": "Decline of Humorism",
      "text": "The decline of humorism began in the 17th century with the advent of modern medical science. The discovery of blood circulation by William Harvey in 1628 challenged the humoral theory.",
      "date": "1628"
    },
    {
      "headline": "End of Humorism's Dominance",
      "text": "By the 19th century, humorism was largely discredited and replaced by more scientific approaches to medicine, such as germ theory and cellular pathology.",
      "date": "1800"
    }
  ]
}

