{
  "timeline": [
    {
      "headline": "Early Settlement",
      "text": "The Hazaras are believed to have settled in the central highlands of Afghanistan, known as Hazarajat, during the early centuries of the Islamic era. Their origins are debated, with some theories suggesting Mongol descent.",
      "date": "-0700"
    },
    {
      "headline": "Mongol Influence",
      "text": "The Hazaras are often associated with Mongol ancestry, particularly due to their physical features and some cultural practices. This connection is believed to have strengthened during the Mongol invasion of the region in the 13th century.",
      "date": "1200"
    },
    {
      "headline": "Safavid Era",
      "text": "During the Safavid dynasty (1501–1736), the Hazaras were part of the Persian Empire and were influenced by Shia Islam, which remains the predominant religion among Hazaras today.",
      "date": "1501"
    },
    {
      "headline": "Durrani Empire",
      "text": "In the mid-18th century, the Hazaras became part of the Durrani Empire, founded by Ahmad Shah Durrani in 1747, which marked the beginning of modern Afghanistan.",
      "date": "1747"
    },
    {
      "headline": "Persecution under Abdur Rahman Khan",
      "text": "In the late 19th century, the Hazaras faced severe persecution under the rule of Abdur Rahman Khan (1880–1901), who sought to consolidate power by subjugating various ethnic groups, including the Hazaras.",
      "date": "1880"
    },
    {
      "headline": "20th Century Migration",
      "text": "Throughout the 20th century, many Hazaras migrated to neighboring countries, such as Pakistan and Iran, due to ongoing conflict and persecution in Afghanistan.",
      "date": "1900"
    },
    {
      "headline": "Soviet-Afghan War",
      "text": "During the Soviet-Afghan War (1979–1989), the Hazaras were involved in resistance efforts against Soviet forces and the communist Afghan government.",
      "date": "1979"
    },
    {
      "headline": "Post-Taliban Era",
      "text": "After the fall of the Taliban in 2001, the Hazaras gained increased political representation in Afghanistan, although they continue to face discrimination and violence.",
      "date": "2001"
    },
    {
      "headline": "Recent Attacks",
      "text": "In recent years, the Hazaras have been targeted in sectarian attacks by extremist groups, highlighting ongoing security challenges for the community.",
      "date": "2010"
    }
  ]
}

