{
  "timeline": [
    {
      "headline": "First Ecumenical Council",
      "text": "The First Ecumenical Council, also known as the First Council of Nicaea, was convened by Emperor Constantine I in 325. It was the first effort to attain consensus in the church through an assembly representing all of Christendom.",
      "date": "0325"
    },
    {
      "headline": "Council of Chalcedon",
      "text": "The Council of Chalcedon was held in 451. It was the fourth ecumenical council of the Christian Church, and it defined the two natures (divine and human) of Jesus Christ.",
      "date": "0451"
    },
    {
      "headline": "Great Schism",
      "text": "The Great Schism, also known as the East-West Schism, occurred in 1054. It was the break of communion between what are now the Roman Catholic Church and Eastern Orthodox Churches.",
      "date": "1054"
    },
    {
      "headline": "Fall of Constantinople",
      "text": "The Fall of Constantinople in 1453 marked the end of the Byzantine Empire. This event significantly impacted the Eastern Orthodox Church, as Constantinople was a major center of Orthodoxy.",
      "date": "1453"
    },
    {
      "headline": "Council of Florence",
      "text": "The Council of Florence took place between 1431 and 1449. It was an attempt to reunite the Eastern Orthodox and Roman Catholic Churches, but ultimately failed to achieve lasting unity.",
      "date": "1431-1449"
    },
    {
      "headline": "Autocephaly of the Russian Orthodox Church",
      "text": "In 1589, the Russian Orthodox Church was granted autocephaly, making it independent from the Patriarchate of Constantinople.",
      "date": "1589"
    },
    {
      "headline": "Establishment of the Ecumenical Patriarchate of Constantinople",
      "text": "The Ecumenical Patriarchate of Constantinople was established as the leading authority in the Eastern Orthodox Church, with the Patriarch of Constantinople recognized as the 'first among equals' among Orthodox bishops.",
      "date": "451"
    },
    {
      "headline": "Recognition of the Autocephaly of the Orthodox Church of Ukraine",
      "text": "In 2019, the Ecumenical Patriarchate of Constantinople granted autocephaly to the Orthodox Church of Ukraine, leading to significant tensions with the Russian Orthodox Church.",
      "date": "2019"
    }
  ]
}

