{
  "timeline": [
    {
      "headline": "Formation of All-India Muslim League",
      "text": "The All-India Muslim League was established on December 30, 1906, in Dhaka. It was founded with the aim of representing and securing Muslim interests in British India.",
      "date": "1906-12-30"
    },
    {
      "headline": "Simla Deputation",
      "text": "In 1906, a delegation of Muslim leaders, known as the Simla Deputation, met with the Viceroy of India, Lord Minto, to demand separate electorates for Muslims.",
      "date": "1906"
    },
    {
      "headline": "First Session of the Muslim League",
      "text": "The first session of the All-India Muslim League was held in Karachi on December 29, 1907.",
      "date": "1907-12-29"
    },
    {
      "headline": "Muslim League's Demand for Separate Electorates",
      "text": "In 1909, the Muslim League successfully lobbied for separate electorates for Muslims in the Indian Councils Act of 1909.",
      "date": "1909"
    },
    {
      "headline": "Lucknow Pact",
      "text": "In 1916, the Muslim League and the Indian National Congress reached an agreement known as the Lucknow Pact, which marked a significant step towards Hindu-Muslim unity.",
      "date": "1916"
    },
    {
      "headline": "Jinnah Joins Muslim League",
      "text": "In 1913, Muhammad Ali Jinnah joined the All-India Muslim League, eventually becoming one of its most prominent leaders.",
      "date": "1913"
    },
    {
      "headline": "Lahore Resolution",
      "text": "On March 23, 1940, the Muslim League passed the Lahore Resolution, calling for the creation of 'independent states' for Muslims in northwestern and eastern zones of India.",
      "date": "1940-03-23"
    },
    {
      "headline": "Direct Action Day",
      "text": "On August 16, 1946, the Muslim League called for Direct Action Day to demand the creation of Pakistan, leading to widespread communal riots.",
      "date": "1946-08-16"
    },
    {
      "headline": "Partition of India",
      "text": "On August 15, 1947, British India was partitioned into India and Pakistan, fulfilling the Muslim League's demand for a separate Muslim state.",
      "date": "1947-08-15"
    },
    {
      "headline": "Dissolution of All-India Muslim League",
      "text": "After the creation of Pakistan in 1947, the All-India Muslim League was dissolved, and its successor, the Muslim League, continued to function in Pakistan.",
      "date": "1947"
    }
  ]
}

