{
  "timeline": [
    {
      "headline": "Haiti Earthquake Occurs",
      "text": "A catastrophic magnitude 7.0 Mw earthquake struck Haiti at 16:53 local time on Tuesday, 12 January 2010. The epicenter was near the town of Léogâne, Ouest department, approximately 25 kilometres (16 mi) west of Port-au-Prince, Haiti's capital.",
      "date": "2010-01-12"
    },
    {
      "headline": "Immediate Aftermath and Casualties",
      "text": "In the immediate aftermath of the earthquake, it was estimated that 230,000 people died, 300,000 were injured, and 1.5 million were displaced. The earthquake caused widespread devastation in Port-au-Prince and surrounding areas.",
      "date": "2010-01"
    },
    {
      "headline": "International Response Begins",
      "text": "Following the earthquake, international aid began to arrive in Haiti. Countries and organizations worldwide pledged support and sent rescue teams, medical supplies, and financial aid to assist in the relief efforts.",
      "date": "2010-01"
    },
    {
      "headline": "UN Headquarters in Haiti Destroyed",
      "text": "The United Nations Stabilization Mission in Haiti (MINUSTAH) headquarters was destroyed in the earthquake, resulting in the deaths of many UN personnel, including the head of the mission, Hédi Annabi.",
      "date": "2010-01-12"
    },
    {
      "headline": "Cholera Outbreak",
      "text": "In October 2010, a cholera outbreak began in Haiti, which was linked to the unsanitary conditions following the earthquake. The outbreak resulted in thousands of deaths and further strained the country's recovery efforts.",
      "date": "2010-10"
    },
    {
      "headline": "Reconstruction and Recovery Efforts",
      "text": "In the years following the earthquake, Haiti faced significant challenges in reconstruction and recovery. Efforts were made to rebuild infrastructure, provide housing for displaced individuals, and restore basic services.",
      "date": "2010-2015"
    }
  ]
}

