{
  "timeline": [
    {
      "headline": "Birth of Władysław Szpilman",
      "text": "Władysław Szpilman was born on December 5, 1911, in Sosnowiec, Poland.",
      "date": "1911-12-05"
    },
    {
      "headline": "Studies at the Chopin Academy of Music",
      "text": "In 1931, Szpilman began his studies at the Chopin Academy of Music in Warsaw, Poland.",
      "date": "1931"
    },
    {
      "headline": "Further Studies in Berlin",
      "text": "Szpilman continued his music education in Berlin at the Academy of Arts, studying under renowned teachers such as Leonid Kreutzer and Artur Schnabel.",
      "date": "1933"
    },
    {
      "headline": "Return to Warsaw",
      "text": "After the rise of the Nazi regime, Szpilman returned to Warsaw in 1935 to continue his career as a pianist and composer.",
      "date": "1935"
    },
    {
      "headline": "Radio Warsaw Pianist",
      "text": "Szpilman became a pianist for Polish Radio in Warsaw, where he performed regularly until the outbreak of World War II.",
      "date": "1935"
    },
    {
      "headline": "German Invasion of Poland",
      "text": "On September 1, 1939, Germany invaded Poland, marking the beginning of World War II. Szpilman continued to play live on Polish Radio until the station was bombed.",
      "date": "1939-09-01"
    },
    {
      "headline": "Warsaw Ghetto",
      "text": "In 1940, Szpilman and his family were forced into the Warsaw Ghetto, where he continued to perform in cafes.",
      "date": "1940"
    },
    {
      "headline": "Escape from Deportation",
      "text": "In 1942, during the mass deportation of Jews to extermination camps, Szpilman was saved by a friend from being sent to Treblinka.",
      "date": "1942"
    },
    {
      "headline": "Hiding in Warsaw",
      "text": "Szpilman spent the remainder of the war hiding in various locations around Warsaw, surviving with the help of friends and strangers.",
      "date": "1942-1945"
    },
    {
      "headline": "Liberation and Return to Polish Radio",
      "text": "After the liberation of Warsaw in 1945, Szpilman returned to Polish Radio, where he played Chopin's Nocturne in C-sharp minor, the same piece he had played when the station went off the air in 1939.",
      "date": "1945"
    },
    {
      "headline": "Publication of Memoir",
      "text": "In 1946, Szpilman published his memoir, 'Śmierć Miasta' (Death of a City), which recounted his experiences during the war. It was later republished as 'The Pianist'.",
      "date": "1946"
    },
    {
      "headline": "Career as a Composer",
      "text": "Throughout the post-war years, Szpilman composed numerous classical and popular music pieces, contributing significantly to Polish music.",
      "date": "1945-2000"
    },
    {
      "headline": "Death of Władysław Szpilman",
      "text": "Władysław Szpilman passed away on July 6, 2000, in Warsaw, Poland, leaving behind a legacy as a celebrated pianist and composer.",
      "date": "2000-07-06"
    }
  ]
}

