    {
      "headline": "Founding of Jackson",
      "text": "Jackson was founded in 1821 as the site for a new state capital, named after General Andrew Jackson, who later became President of the United States.",
      "date": "1821"
    },
    {
      "headline": "Jackson Becomes State Capital",
      "text": "In 1822, Jackson was officially designated as the capital of Mississippi.",
      "date": "1822"
    },
    {
      "headline": "Jackson Incorporated",
      "text": "Jackson was incorporated as a city in 1823.",
      "date": "1823"
    },
    {
      "headline": "Civil War and Siege of Jackson",
      "text": "During the American Civil War, Jackson was a strategic location and was captured by Union forces in May 1863. The city was burned and destroyed during the Siege of Jackson in July 1863.",
      "date": "1863-07"
    },
    {
      "headline": "Reconstruction Era",
      "text": "Following the Civil War, Jackson underwent reconstruction and began to rebuild from the destruction it faced during the war.",
      "date": "1865"
    },
    {
      "headline": "Great Mississippi Flood",
      "text": "In 1927, Jackson was affected by the Great Mississippi Flood, one of the most destructive river floods in U.S. history.",
      "date": "1927"
    },
    {
      "headline": "Civil Rights Movement",
      "text": "Jackson was a significant location during the Civil Rights Movement in the 1960s, with events such as the Freedom Rides and the assassination of civil rights leader Medgar Evers in 1963.",
      "date": "1963"
    },
    {
      "headline": "Jackson State University Shooting",
      "text": "On May 15, 1970, two students were killed and twelve were injured by police gunfire at Jackson State College (now Jackson State University) during a protest against the Vietnam War.",
      "date": "1970-05-15"
    },
    {
      "headline": "Population Decline",
      "text": "Between 2010 and 2020, Jackson experienced a significant population decline of 11.42%, the largest of any major U.S. city during that decade.",
      "date": "2020"
    }
  ]
}

