    {
      "headline": "Munich Air Disaster",
      "text": "On 6 February 1958, British European Airways Flight 609 crashed on its third attempt to take off at Munich-Riem Airport in Munich, West Germany. The aircraft was carrying the Manchester United football team, nicknamed the 'Busby Babes', along with supporters and journalists.",
      "date": "1958-02-06"
    },
    {
      "headline": "Immediate Aftermath",
      "text": "There were 44 people on board the flight. 20 of them died at the scene of the crash. The injured, some unconscious, were taken to Munich's Rechts der Isar Hospital.",
      "date": "1958-02-06"
    },
    {
      "headline": "Death Toll Rises",
      "text": "In the days following the crash, three more individuals succumbed to their injuries at the hospital, bringing the total number of fatalities to 23.",
      "date": "1958-02-07"
    },
    {
      "headline": "Survivors",
      "text": "Despite the tragedy, there were 21 survivors from the crash, including some members of the Manchester United football team.",
      "date": "1958-02-06"
    }
  ]
}

{
  "timeline": [
