{
  "timeline": [
    {
      "headline": "Introduction of Christianity to Japan",
      "text": "Christianity was introduced to Japan by Jesuit missionaries, with Francis Xavier arriving in Kagoshima in 1549.",
      "date": "1549"
    },
    {
      "headline": "Christianity Gains Followers",
      "text": "By the late 16th century, Christianity had gained a significant number of followers, with estimates of up to 300,000 converts.",
      "date": "1590"
    },
    {
      "headline": "Edict of Banishment",
      "text": "In 1614, the Tokugawa shogunate issued an edict banning Christianity and expelling missionaries.",
      "date": "1614"
    },
    {
      "headline": "Shimabara Rebellion",
      "text": "The Shimabara Rebellion (1637-1638) was a revolt largely involving Christian peasants against the shogunate, which was suppressed with great loss of life.",
      "date": "1637"
    },
    {
      "headline": "Sakoku Policy",
      "text": "The Sakoku policy, fully implemented by 1639, isolated Japan from foreign influence and severely restricted Christianity.",
      "date": "1639"
    },
    {
      "headline": "Hidden Christians",
      "text": "During the period of persecution, many Christians practiced their faith in secret, known as 'Kakure Kirishitan' or Hidden Christians.",
      "date": "1640"
    },
    {
      "headline": "End of Isolation",
      "text": "Japan ended its isolationist policy with the Meiji Restoration in 1868, leading to the lifting of the ban on Christianity.",
      "date": "1868"
    },
    {
      "headline": "Freedom of Religion",
      "text": "The Meiji Constitution of 1889 granted freedom of religion, allowing Christianity to be practiced openly again.",
      "date": "1889"
    },
    {
      "headline": "Post-War Growth",
      "text": "After World War II, Christianity experienced a period of growth in Japan, with increased missionary activity and conversions.",
      "date": "1945"
    },
    {
      "headline": "Christian Population Decline",
      "text": "In recent years, the Christian population in Japan has declined, with 1.26 million Christians reported in 2022, down from 1.9 million in 2019.",
      "date": "2022"
    }
  ]
}

