{
  "timeline": [
    {
      "headline": "Coronation of Nabopolassar",
      "text": "Nabopolassar was crowned as the King of Babylon, marking the beginning of the Neo-Babylonian Empire. This event took place in 626 BC.",
      "date": "-0626"
    },
    {
      "headline": "Fall of the Assyrian Empire",
      "text": "The Neo-Babylonian Empire was firmly established with the fall of the Assyrian Empire in 612 BC. This marked a significant expansion of Babylonian power.",
      "date": "-0612"
    },
    {
      "headline": "Reign of Nebuchadnezzar II",
      "text": "Nebuchadnezzar II, one of the most famous Babylonian kings, reigned from 605 BC to 562 BC. He is known for his military conquests and the construction of the Hanging Gardens of Babylon.",
      "date": "-0605"
    },
    {
      "headline": "Construction of the Hanging Gardens",
      "text": "During the reign of Nebuchadnezzar II, the Hanging Gardens of Babylon were constructed, which became one of the Seven Wonders of the Ancient World. This is believed to have occurred around 600 BC.",
      "date": "-0600"
    },
    {
      "headline": "Fall of Jerusalem",
      "text": "In 587 BC, Nebuchadnezzar II captured Jerusalem, leading to the destruction of Solomon's Temple and the Babylonian Exile of the Jewish people.",
      "date": "-0587"
    },
    {
      "headline": "Death of Nebuchadnezzar II",
      "text": "Nebuchadnezzar II died in 562 BC, marking the end of his influential reign over the Neo-Babylonian Empire.",
      "date": "-0562"
    },
    {
      "headline": "Reign of Nabonidus",
      "text": "Nabonidus became the king of Babylon in 556 BC. His reign was marked by religious reforms and his extended stay in the Arabian desert.",
      "date": "-0556"
    },
    {
      "headline": "Conquest by the Achaemenid Empire",
      "text": "The Neo-Babylonian Empire was conquered by the Achaemenid Persian Empire in 539 BC, marking the collapse of the Chaldean dynasty.",
      "date": "-0539"
    }
  ]
}

{
