{
  "timeline": [
    {
      "headline": "Beginning of the February Revolution",
      "text": "The February Revolution began on March 8, 1917 (February 23 in the Julian calendar), with demonstrations and strikes in Petrograd (now St. Petersburg) due to food shortages and discontent with the Tsarist regime.",
      "date": "1917-03-08"
    },
    {
      "headline": "International Women's Day Protest",
      "text": "On March 8, 1917, International Women's Day, women textile workers in Petrograd went on strike, demanding bread and peace, which marked the start of the February Revolution.",
      "date": "1917-03-08"
    },
    {
      "headline": "General Strike in Petrograd",
      "text": "By March 10, 1917, the strike had spread to other industries, and Petrograd was paralyzed by a general strike involving over 200,000 workers.",
      "date": "1917-03-10"
    },
    {
      "headline": "Mutiny of the Petrograd Garrison",
      "text": "On March 12, 1917, soldiers of the Petrograd garrison mutinied, refusing to suppress the protests and instead joining the demonstrators.",
      "date": "1917-03-12"
    },
    {
      "headline": "Formation of the Provisional Government",
      "text": "On March 15, 1917, the Russian Provisional Government was formed by members of the Duma, marking the end of the Tsarist autocracy.",
      "date": "1917-03-15"
    },
    {
      "headline": "Abdication of Tsar Nicholas II",
      "text": "Tsar Nicholas II abdicated the throne on March 15, 1917, effectively ending the Romanov dynasty's rule over Russia.",
      "date": "1917-03-15"
    },
    {
      "headline": "Establishment of Dual Power",
      "text": "Following the abdication of the Tsar, a system of dual power was established between the Provisional Government and the Petrograd Soviet, leading to political instability.",
      "date": "1917-03"
    }
  ]
}

