{
  "timeline": [
    {
      "headline": "Birth of Genrikh Yagoda",
      "text": "Genrikh Grigoryevich Yagoda was born on November 7, 1891, in Rybinsk, Russian Empire.",
      "date": "1891-11-07"
    },
    {
      "headline": "Appointment as Director of the NKVD",
      "text": "In 1934, Genrikh Yagoda was appointed as the director of the NKVD, the Soviet Union's security and intelligence agency, by Joseph Stalin.",
      "date": "1934"
    },
    {
      "headline": "Supervision of the White Sea–Baltic Canal Construction",
      "text": "Yagoda supervised the construction of the White Sea–Baltic Canal with Naftaly Frenkel, using penal labor from the gulag system. The project resulted in the deaths of 12,000–25,000 laborers.",
      "date": "1931"
    },
    {
      "headline": "Role in the Great Purge",
      "text": "As director of the NKVD, Yagoda supervised arrests, show trials, and executions of the Old Bolsheviks Lev Kamenev and Grigory Zinoviev, which were climactic events of the Great Purge.",
      "date": "1936"
    },
    {
      "headline": "Dismissal from NKVD",
      "text": "In September 1936, Yagoda was dismissed from his position as director of the NKVD and replaced by Nikolai Yezhov.",
      "date": "1936-09"
    },
    {
      "headline": "Arrest and Trial",
      "text": "Yagoda was arrested in 1937 and later tried during the Trial of the Twenty-One, one of the Moscow Trials.",
      "date": "1937"
    },
    {
      "headline": "Execution",
      "text": "Genrikh Yagoda was executed on March 15, 1938, after being found guilty in the Moscow Trials.",
      "date": "1938-03-15"
    }
  ]
}

