{
  "timeline": [
    {
      "headline": "British Rule Begins",
      "text": "British rule in Hong Kong began in 1841 following the First Opium War and the signing of the Treaty of Nanking.",
      "date": "1841"
    },
    {
      "headline": "Treaty of Nanking",
      "text": "The Treaty of Nanking was signed on 29 August 1842, ceding Hong Kong Island to the United Kingdom in perpetuity.",
      "date": "1842-08-29"
    },
    {
      "headline": "Convention of Peking",
      "text": "The Convention of Peking was signed on 24 October 1860, ceding the Kowloon Peninsula to the United Kingdom.",
      "date": "1860-10-24"
    },
    {
      "headline": "Second Convention of Peking",
      "text": "The Second Convention of Peking was signed on 9 June 1898, leasing the New Territories to the United Kingdom for 99 years.",
      "date": "1898-06-09"
    },
    {
      "headline": "Sino-British Joint Declaration",
      "text": "The Sino-British Joint Declaration was signed on 19 December 1984, agreeing that Hong Kong would be handed back to China in 1997.",
      "date": "1984-12-19"
    },
    {
      "headline": "Handover of Hong Kong",
      "text": "The handover of Hong Kong from the United Kingdom to the People's Republic of China occurred at midnight on 1 July 1997, ending 156 years of British rule.",
      "date": "1997-07-01"
    }
  ]
}

