{
  "timeline": [
    {
      "headline": "Origin of Bridge",
      "text": "Bridge evolved from earlier trick-taking games such as whist. The earliest form of bridge was known as 'Biritch' or 'Russian Whist', which dates back to the 19th century.",
      "date": "1800"
    },
    {
      "headline": "Development of Auction Bridge",
      "text": "Auction bridge, a precursor to contract bridge, was developed in the early 20th century. It introduced the concept of bidding, which is central to modern bridge.",
      "date": "1904"
    },
    {
      "headline": "Introduction of Contract Bridge",
      "text": "Contract bridge was developed in the 1920s by Harold Stirling Vanderbilt. He introduced the concept of a contract, where players bid to determine the number of tricks they must take.",
      "date": "1925"
    },
    {
      "headline": "First Contract Bridge Book",
      "text": "The first book on contract bridge, 'Contract Bridge Blue Book' by Ely Culbertson, was published in 1929, helping to popularize the game.",
      "date": "1929"
    },
    {
      "headline": "Formation of the World Bridge Federation",
      "text": "The World Bridge Federation (WBF) was founded in 1958 to govern international competitive bridge.",
      "date": "1958"
    },
    {
      "headline": "Introduction of Duplicate Bridge",
      "text": "Duplicate bridge, a form of bridge where the same hands are played at multiple tables to reduce the element of luck, became popular in the mid-20th century.",
      "date": "1950"
    },
    {
      "headline": "First World Bridge Series Championships",
      "text": "The first World Bridge Series Championships were held in 1960, establishing a global competitive platform for bridge players.",
      "date": "1960"
    },
    {
      "headline": "Bridge Becomes a Mind Sport",
      "text": "In 1999, the International Olympic Committee recognized bridge as a mind sport, acknowledging its strategic and intellectual aspects.",
      "date": "1999"
    }
  ]
}

{
