    },
    {
      "headline": "Move to New York City",
      "text": "In 1922, Thelonious Monk's family moved to New York City, where he grew up in the San Juan Hill neighborhood of Manhattan.",
      "date": "1922"
    },
    {
      "headline": "Began Playing Piano",
      "text": "Monk began playing the piano at the age of six, showing early signs of his musical talent.",
      "date": "1923"
    },
    {
      "headline": "Joined Minton's Playhouse",
      "text": "In the early 1940s, Monk became the house pianist at Minton's Playhouse in Harlem, a venue that was pivotal in the development of bebop.",
      "date": "1941"
    },
    {
      "headline": "First Recording Session",
      "text": "Thelonious Monk participated in his first recording session as a member of Coleman Hawkins' band in 1944.",
      "date": "1944"
