    }
  ]
}

{
  "timeline": [
    {
      "headline": "Introduction of Bacchanalia to Rome",
      "text": "The Bacchanalia, festivals of Bacchus, were introduced to Rome around 200 BC. These festivals were based on the ecstatic elements of the Greek Dionysia and were associated with Rome's native cult of Liber.",
      "date": "-0200"
    },
    {
      "headline": "Senate Suppression of Bacchanalia",
      "text": "In 186 BC, the Roman Senate issued the Senatus consultum de Bacchanalibus, a decree that severely restricted the Bacchanalia. This was due to concerns over the secretive and potentially subversive nature of the rites.",
      "date": "-0186"
    },
    {
      "headline": "Impact of the Senatus consultum de Bacchanalibus",
      "text": "Following the decree in 186 BC, the Bacchanalia were largely suppressed in Rome and throughout the Italian peninsula. The decree required that any gatherings for the Bacchanalia had to be approved by the Senate and attended by no more than five people.",
      "date": "-0186"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Accession of Adad-nirari II",
      "text": "Adad-nirari II ascended to the throne in 911 BCE, marking the beginning of the Neo-Assyrian Empire.",
      "date": "-0911"
    },
    {
      "headline": "Reign of Ashurnasirpal II",
      "text": "Ashurnasirpal II reigned from 883 to 859 BCE and expanded the empire through military campaigns and the establishment of a new capital at Kalhu.",
      "date": "-0883"
    },
    {
      "headline": "Reign of Shalmaneser III",
      "text": "Shalmaneser III reigned from 859 to 824 BCE, known for his campaigns against the kingdoms of Urartu and the Levant.",
      "date": "-0859"
    },
    {
      "headline": "Battle of Qarqar",
      "text": "In 853 BCE, Shalmaneser III fought the Battle of Qarqar against a coalition of Levantine kings, including Ahab of Israel.",
      "date": "-0853"
    },
    {
      "headline": "Reign of Tiglath-Pileser III",
      "text": "Tiglath-Pileser III reigned from 745 to 727 BCE, implementing administrative reforms and expanding the empire's territory.",
      "date": "-0745"
    },
    {
      "headline": "Fall of Damascus",
      "text": "In 732 BCE, Tiglath-Pileser III captured Damascus, further consolidating Assyrian control over the Levant.",
      "date": "-0732"
    },
    {
      "headline": "Reign of Sargon II",
      "text": "Sargon II reigned from 722 to 705 BCE, known for his conquest of Israel and the establishment of the new capital at Dur-Sharrukin.",
      "date": "-0722"
    },
    {
      "headline": "Fall of Samaria",
      "text": "In 722 BCE, Sargon II captured Samaria, leading to the fall of the Kingdom of Israel.",
      "date": "-0722"
    },
    {
      "headline": "Reign of Sennacherib",
      "text": "Sennacherib reigned from 705 to 681 BCE, famous for his military campaigns and the destruction of Babylon.",
      "date": "-0705"
    },
    {
      "headline": "Siege of Jerusalem",
      "text": "In 701 BCE, Sennacherib laid siege to Jerusalem, an event recorded in both Assyrian and biblical sources.",
      "date": "-0701"
    },
    {
      "headline": "Reign of Esarhaddon",
      "text": "Esarhaddon reigned from 681 to 669 BCE, known for rebuilding Babylon and conquering Egypt.",
      "date": "-0681"
    },
    {
      "headline": "Conquest of Egypt",
      "text": "In 671 BCE, Esarhaddon successfully conquered Egypt, extending Assyrian control into North Africa.",
      "date": "-0671"
    },
    {
      "headline": "Reign of Ashurbanipal",
      "text": "Ashurbanipal reigned from 669 to 631 BCE, noted for his extensive library at Nineveh and campaigns in Elam.",
      "date": "-0669"
    },
    {
      "headline": "Fall of Nineveh",
      "text": "In 612 BCE, the city of Nineveh fell to a coalition of Babylonians, Medes, and Scythians, marking the end of the Neo-Assyrian Empire.",
      "date": "-0612"
    }
  ]
}

