    {
      "headline": "Spanish Inquisition",
      "text": "The Spanish Inquisition was established in 1478 by Catholic Monarchs Ferdinand II of Aragon and Isabella I of Castile, with the approval of Pope Sixtus IV. It was intended to maintain Catholic orthodoxy in their kingdoms.",
      "date": "1478"
    },
    {
      "headline": "Portuguese Inquisition",
      "text": "The Portuguese Inquisition was established in 1536 by King John III of Portugal, with the approval of Pope Paul III. It was similar in purpose to the Spanish Inquisition.",
      "date": "1536"
    },
    {
      "headline": "Roman Inquisition",
      "text": "The Roman Inquisition was established in 1542 by Pope Paul III with the papal bull 'Licet ab initio'. It was part of the Counter-Reformation efforts to combat Protestantism and other heresies.",
      "date": "1542"
    },
    {
      "headline": "Galileo's Trial",
      "text": "In 1633, the Roman Inquisition tried Galileo Galilei for heresy due to his support of heliocentrism, which was contrary to the Church's teachings at the time. He was found guilty and placed under house arrest.",
      "date": "1633"
    },
    {
      "headline": "Abolition of the Spanish Inquisition",
      "text": "The Spanish Inquisition was officially abolished in 1834 by a royal decree from Queen Isabella II of Spain.",
      "date": "1834"
    },
    {
      "headline": "Abolition of the Portuguese Inquisition",
      "text": "The Portuguese Inquisition was abolished in 1821 as part of the liberal reforms following the Liberal Revolution of 1820.",
      "date": "1821"
    }
  ]
