      "headline": "Rubens Becomes a Master",
      "text": "In 1598, Rubens was admitted to the Guild of St. Luke in Antwerp as a master painter.",
      "date": "1598"
    },
    {
      "headline": "Travel to Italy",
      "text": "In 1600, Rubens traveled to Italy, where he studied the works of Italian masters and worked as a court painter for the Duke of Mantua.",
      "date": "1600"
    },
    {
      "headline": "Return to Antwerp",
      "text": "Rubens returned to Antwerp in 1608 following the death of his mother.",
      "date": "1608"
    },
    {
      "headline": "Marriage to Isabella Brant",
      "text": "On October 3, 1609, Rubens married Isabella Brant, the daughter of a prominent Antwerp citizen.",
      "date": "1609-10-03"
    },
    {
      "headline": "Appointment as Court Painter",
      "text": "In 1609, Rubens was appointed court painter by Albert VII, Archduke of Austria, and Infanta Isabella Clara Eugenia of Spain, the governors of the Low Countries.",
      "date": "1609"
    },
    {
      "headline": "Rubens' Workshop",
      "text": "By 1610, Rubens had established a large workshop in Antwerp, where he employed many apprentices and assistants.",
      "date": "1610"
    },
    {
      "headline": "Diplomatic Missions",
      "text": "From 1621 to 1630, Rubens undertook several diplomatic missions across Europe, including to Spain and England.",
      "date": "1621"
    },
    {
      "headline": "Marriage to Helena Fourment",
      "text": "On December 6, 1630, Rubens married Helena Fourment, who was 16 years old at the time.",
      "date": "1630-12-06"
    },
    {
      "headline": "Death of Peter Paul Rubens",
      "text": "Peter Paul Rubens died on May 30, 1640, in Antwerp, Spanish Netherlands (now Belgium).",
      "date": "1640-05-30"
    }
  ]
}

