{
  "timeline": [
    {
      "headline": "Council of Rome",
      "text": "In 382, the Council of Rome was convened by Pope Damasus I. It is traditionally believed to have determined the canon of the Bible, including the deuterocanonical books recognized by the Catholic Church.",
      "date": "0382"
    },
    {
      "headline": "Council of Hippo",
      "text": "In 393, the Council of Hippo, a regional council in North Africa, reaffirmed the canon of the Bible, including the deuterocanonical books.",
      "date": "0393"
    },
    {
      "headline": "Council of Carthage",
      "text": "In 397, the Council of Carthage further confirmed the canon of the Bible as recognized by the Catholic Church.",
      "date": "0397"
    },
    {
      "headline": "Vulgate Translation",
      "text": "In 405, St. Jerome completed the Vulgate, a Latin translation of the Bible, which included the deuterocanonical books and became the Catholic Church's official Bible.",
      "date": "0405"
    },
    {
      "headline": "Council of Trent",
      "text": "In 1546, the Council of Trent officially defined the canon of the Catholic Bible, reaffirming the inclusion of the deuterocanonical books.",
      "date": "1546"
    },
    {
      "headline": "Clementine Vulgate",
      "text": "In 1592, Pope Clement VIII promulgated the Clementine Vulgate, an official edition of the Vulgate, which remained the standard Bible of the Catholic Church until the 20th century.",
      "date": "1592"
    },
    {
      "headline": "Divino Afflante Spiritu",
      "text": "In 1943, Pope Pius XII issued the encyclical Divino Afflante Spiritu, encouraging the translation of the Bible from original languages rather than the Latin Vulgate.",
      "date": "1943"
    },
    {
      "headline": "Second Vatican Council",
      "text": "Between 1962 and 1965, the Second Vatican Council took place, leading to significant liturgical reforms, including the use of vernacular languages in the liturgy and the encouragement of new translations of the Bible.",
      "date": "1962-1965"
    },
    {
      "headline": "Nova Vulgata",
      "text": "In 1979, the Nova Vulgata, a revised version of the Vulgate, was promulgated by Pope John Paul II as the official Latin text of the Catholic Church.",
      "date": "1979"
    }
  ]
}

