{
  "timeline": [
    {
      "headline": "Commission of The Last Judgment",
      "text": "Pope Clement VII commissioned Michelangelo to paint The Last Judgment on the altar wall of the Sistine Chapel. The commission was given in 1534, shortly before the pope's death.",
      "date": "1534"
    },
    {
      "headline": "Michelangelo Begins Work",
      "text": "Michelangelo began work on The Last Judgment in 1536, under the patronage of Pope Paul III, who succeeded Clement VII.",
      "date": "1536"
    },
    {
      "headline": "Completion of The Last Judgment",
      "text": "Michelangelo completed The Last Judgment in 1541. The fresco covers the entire altar wall of the Sistine Chapel and depicts the Second Coming of Christ and the final judgment of souls.",
      "date": "1541"
    },
    {
      "headline": "Controversy and Criticism",
      "text": "Upon its completion, The Last Judgment faced criticism for its depiction of nudity and was considered controversial by some members of the Catholic Church.",
      "date": "1541"
    },
    {
      "headline": "The Fig-Leaf Campaign",
      "text": "In the 1560s, under the direction of Pope Pius IV, the Council of Trent deemed the nudity in The Last Judgment inappropriate. Artist Daniele da Volterra was commissioned to paint draperies over the genitals of the figures, earning him the nickname 'Il Braghettone' or 'The Breeches Maker'.",
      "date": "1565"
    },
    {
      "headline": "Restoration of The Last Judgment",
      "text": "The Last Judgment underwent a major restoration from 1980 to 1994. The restoration removed centuries of grime and some of the draperies added in the 16th century, revealing Michelangelo's original work.",
      "date": "1980-1994"
    }
  ]
}

