      "date": "1941-09"
    },
    {
      "headline": "Stalemate Period",
      "text": "From 1942 to 1943, the war reached a stalemate with both sides fortifying their positions. There were no significant territorial changes during this period.",
      "date": "1942"
    },
    {
      "headline": "Soviet Offensive",
      "text": "In June 1944, the Soviet Union launched a major offensive against Finnish positions, breaking through the Finnish defenses and forcing a retreat.",
      "date": "1944-06"
    },
    {
      "headline": "Battle of Tali-Ihantala",
      "text": "From 25 June to 9 July 1944, the Battle of Tali-Ihantala took place, which was the largest battle in the history of the Nordic countries. Finnish forces managed to halt the Soviet advance.",
      "date": "1944-06-25"
    },
    {
      "headline": "Moscow Armistice",
      "text": "On 19 September 1944, the Continuation War ended with the signing of the Moscow Armistice. Finland agreed to cede territory to the Soviet Union and pay reparations.",
      "date": "1944-09-19"
    }
  ]
}

