{
  "timeline": [
    {
      "headline": "Establishment of Luxembourg Castle",
      "text": "Luxembourg Castle was established by the Franks in the Early Middle Ages, around which the settlement that would become Luxembourg City developed.",
      "date": "-0963"
    },
    {
      "headline": "Acquisition by Siegfried, Count of the Ardennes",
      "text": "In 963, Siegfried, Count of the Ardennes, acquired the rocky promontory and its Roman fortifications, marking the foundation of Luxembourg City.",
      "date": "0963"
    },
    {
      "headline": "City Charter Granted",
      "text": "In 1244, Luxembourg City was granted a city charter, which provided it with certain rights and privileges, contributing to its growth and development.",
      "date": "1244"
    },
    {
      "headline": "Fortifications Expanded",
      "text": "During the 14th and 15th centuries, Luxembourg City saw significant expansion of its fortifications, making it one of the strongest fortresses in Europe.",
      "date": "1300"
    },
    {
      "headline": "Spanish Rule",
      "text": "In 1555, Luxembourg came under Spanish rule as part of the Spanish Netherlands, which lasted until the Treaty of the Pyrenees in 1659.",
      "date": "1555"
    },
    {
      "headline": "French Conquest",
      "text": "In 1684, Luxembourg City was conquered by the French under Louis XIV, who further strengthened its fortifications.",
      "date": "1684"
    },
    {
      "headline": "Treaty of Ryswick",
      "text": "In 1697, the Treaty of Ryswick returned Luxembourg City to Spanish control after being under French rule.",
      "date": "1697"
    },
    {
      "headline": "Austrian Rule",
      "text": "In 1715, Luxembourg City came under Austrian rule as part of the Austrian Netherlands following the War of Spanish Succession.",
      "date": "1715"
    },
    {
      "headline": "French Revolutionary Wars",
      "text": "In 1795, Luxembourg City was annexed by France during the French Revolutionary Wars and became part of the Département des Forêts.",
      "date": "1795"
    },
    {
      "headline": "Congress of Vienna",
      "text": "In 1815, the Congress of Vienna established Luxembourg as a Grand Duchy in personal union with the Netherlands, and Luxembourg City became a federal fortress of the German Confederation.",
      "date": "1815"
    },
    {
      "headline": "Luxembourg Crisis",
      "text": "In 1867, the Luxembourg Crisis was resolved by the Treaty of London, which declared Luxembourg's neutrality and led to the dismantling of its fortifications.",
      "date": "1867"
    },
    {
      "headline": "World War II German Occupation",
      "text": "During World War II, Luxembourg City was occupied by German forces from 1940 until its liberation by Allied forces in 1944.",
      "date": "1940"
    },
    {
      "headline": "Liberation by Allied Forces",
      "text": "In 1944, Luxembourg City was liberated by Allied forces, marking the end of German occupation during World War II.",
      "date": "1944"
    },
    {
      "headline": "European Union Institutions",
      "text": "In the latter half of the 20th century, Luxembourg City became one of the capitals of the European Union, hosting several EU institutions.",
      "date": "1950"
    }
  ]
}

