{
  "timeline": [
    {
      "headline": "First Appearance of Ammonoids",
      "text": "Ammonoids first appeared during the Devonian period, approximately 409 million years ago.",
      "date": "-0409"
    },
    {
      "headline": "Ammonoids Diversification",
      "text": "During the Devonian period, ammonoids rapidly diversified into numerous forms and occupied various marine environments.",
      "date": "-0400"
    },
    {
      "headline": "Ammonoids in the Carboniferous",
      "text": "Ammonoids continued to thrive and diversify throughout the Carboniferous period, approximately 359 to 299 million years ago.",
      "date": "-0359"
    },
    {
      "headline": "Ammonoids in the Permian",
      "text": "Ammonoids persisted through the Permian period, approximately 299 to 251 million years ago, adapting to various ecological niches.",
      "date": "-0299"
    },
    {
      "headline": "Permian-Triassic Extinction Event",
      "text": "Around 252 million years ago, the Permian-Triassic extinction event caused a significant reduction in ammonoid diversity.",
      "date": "-0252"
    },
    {
      "headline": "Recovery and Radiation in the Triassic",
      "text": "Following the Permian-Triassic extinction, ammonoids rapidly recovered and radiated during the Triassic period, approximately 251 to 201 million years ago.",
      "date": "-0251"
    },
    {
      "headline": "Ammonoids in the Jurassic",
      "text": "Ammonoids flourished during the Jurassic period, approximately 201 to 145 million years ago, with the order Ammonitida being particularly prominent.",
      "date": "-0201"
    },
    {
      "headline": "Ammonoids in the Cretaceous",
      "text": "Ammonoids continued to be abundant and diverse throughout the Cretaceous period, approximately 145 to 66 million years ago.",
      "date": "-0145"
    },
    {
      "headline": "Cretaceous-Paleogene Extinction Event",
      "text": "The Cretaceous-Paleogene extinction event, around 66 million years ago, led to the extinction of the last ammonoid species.",
      "date": "-0066"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Origins of Kickboxing",
      "text": "Kickboxing originated in the 1950s to 1970s as a hybrid martial art combining elements of traditional karate with Western boxing techniques. It was developed as a full-contact sport that allowed practitioners to use both punches and kicks.",
      "date": "1950"
    },
