    {
      "headline": "Promoted to Major",
      "text": "In 1920, Manstein was promoted to the rank of Major in the post-war Reichswehr.",
      "date": "1920"
    },
    {
      "headline": "Promotion to Colonel",
      "text": "Manstein was promoted to the rank of Colonel in 1934.",
      "date": "1934"
    },
    {
      "headline": "Chief of Staff of Army Group South",
      "text": "In 1939, Manstein was appointed Chief of Staff to Gerd von Rundstedt's Army Group South during the invasion of Poland.",
      "date": "1939"
    },
    {
      "headline": "Fall Gelb Plan",
      "text": "Manstein played a key role in developing the plan for the invasion of France, known as Fall Gelb, in 1940.",
      "date": "1940"
    },
    {
      "headline": "Promoted to General",
      "text": "In 1940, following the successful invasion of France, Manstein was promoted to General.",
      "date": "1940"
    },
