    {
      "headline": "Siege of Sevastopol",
      "text": "Manstein led the 11th Army during the Siege of Sevastopol, which ended in a German victory in July 1942.",
      "date": "1942-07"
    },
    {
      "headline": "Promoted to Field Marshal",
      "text": "On July 1, 1942, Manstein was promoted to the rank of Field Marshal.",
      "date": "1942-07-01"
    },
    {
      "headline": "Battle of Stalingrad",
      "text": "In late 1942, Manstein was involved in the failed attempt to relieve the encircled German 6th Army at Stalingrad.",
      "date": "1942"
    },
    {
      "headline": "Dismissal from Command",
      "text": "In March 1944, Manstein was dismissed from his command by Adolf Hitler.",
      "date": "1944-03"
    },
    {
      "headline": "War Crimes Trial",
      "text": "After World War II, Manstein was tried for war crimes and sentenced to 18 years in prison in 1949.",
      "date": "1949"
    },
    {
      "headline": "Release from Prison",
      "text": "Manstein was released from prison in 1953 after serving four years of his sentence.",
      "date": "1953"
    },
    {
      "headline": "Death of Erich von Manstein",
      "text": "Erich von Manstein died on June 10, 1973, in Irschenhausen, Bavaria, West Germany.",
