{
  "timeline": [
    {
      "headline": "Introduction of the Wheel of the Year",
      "text": "The concept of the Wheel of the Year was introduced in the mid-20th century by British neopagans. It combines the four solar events marked by many European peoples with the four midpoint festivals celebrated by Insular Celtic peoples.",
      "date": "1950"
    },
    {
      "headline": "Yule",
      "text": "Yule is one of the festivals in the Wheel of the Year, celebrated around the winter solstice. It marks the rebirth of the sun and the beginning of the lengthening of days.",
      "date": "0000-12-21"
    },
    {
      "headline": "Imbolc",
      "text": "Imbolc is celebrated on February 1st or 2nd, marking the midpoint between the winter solstice and the spring equinox. It is associated with the onset of spring and the goddess Brigid.",
      "date": "0000-02-01"
    },
    {
      "headline": "Ostara",
      "text": "Ostara is celebrated around the spring equinox, marking the balance of day and night and the arrival of spring.",
      "date": "0000-03-21"
    },
    {
      "headline": "Beltane",
      "text": "Beltane is celebrated on May 1st, marking the midpoint between the spring equinox and the summer solstice. It is associated with fertility and the beginning of the pastoral summer season.",
      "date": "0000-05-01"
    },
    {
      "headline": "Litha",
      "text": "Litha is celebrated around the summer solstice, marking the longest day of the year and the height of summer.",
      "date": "0000-06-21"
    },
    {
      "headline": "Lughnasadh",
      "text": "Lughnasadh is celebrated on August 1st, marking the midpoint between the summer solstice and the autumn equinox. It is associated with the first harvest and the god Lugh.",
      "date": "0000-08-01"
    },
    {
      "headline": "Mabon",
      "text": "Mabon is celebrated around the autumn equinox, marking the balance of day and night and the second harvest.",
      "date": "0000-09-21"
    },
    {
      "headline": "Samhain",
      "text": "Samhain is celebrated on October 31st, marking the midpoint between the autumn equinox and the winter solstice. It is associated with the end of the harvest season and the beginning of winter.",
      "date": "0000-10-31"
    }
  ]
}

