{
  "timeline": [
    {
      "headline": "1919 World Series Begins",
      "text": "The 1919 World Series between the Chicago White Sox and the Cincinnati Reds began on October 1, 1919.",
      "date": "1919-10-01"
    },
    {
      "headline": "Game-Fixing Scandal Unfolds",
      "text": "During the 1919 World Series, eight members of the Chicago White Sox were accused of intentionally losing games in exchange for money from a gambling syndicate.",
      "date": "1919-10"
    },
    {
      "headline": "World Series Concludes",
      "text": "The Cincinnati Reds won the 1919 World Series on October 9, 1919, defeating the Chicago White Sox.",
      "date": "1919-10-09"
    },
    {
      "headline": "Grand Jury Investigation",
      "text": "In September 1920, a grand jury was convened to investigate allegations of game-fixing in the 1919 World Series.",
      "date": "1920-09"
    },
    {
      "headline": "Players Indicted",
      "text": "On October 22, 1920, eight Chicago White Sox players were indicted for conspiracy to defraud the public.",
      "date": "1920-10-22"
    },
    {
      "headline": "Trial of the Accused Players",
      "text": "The trial of the eight accused players began on June 27, 1921.",
      "date": "1921-06-27"
    },
    {
      "headline": "Players Acquitted",
      "text": "On August 2, 1921, the eight players were acquitted of all charges related to the Black Sox Scandal.",
      "date": "1921-08-02"
    },
    {
      "headline": "Judge Kenesaw Mountain Landis Appointed",
      "text": "In response to the scandal, Judge Kenesaw Mountain Landis was appointed as the first Commissioner of Baseball on November 12, 1920, with absolute control over the sport.",
      "date": "1920-11-12"
    },
    {
      "headline": "Players Banned for Life",
      "text": "Despite their acquittal, on August 3, 1921, Commissioner Landis banned all eight players from professional baseball for life to restore the sport's integrity.",
      "date": "1921-08-03"
    }
  ]
}

