{
  "timeline": [
    {
      "headline": "Start of the Thirty Years' War",
      "text": "The Thirty Years' War began in 1618, a series of conflicts primarily fought in Central Europe involving many of the great powers of the time.",
      "date": "1618"
    },
    {
      "headline": "Negotiations Begin",
      "text": "Negotiations for peace began in 1644 in the Westphalian cities of Osnabrück and Münster, involving various European powers.",
      "date": "1644"
    },
    {
      "headline": "Signing of the Treaty of Münster",
      "text": "On October 24, 1648, the Treaty of Münster was signed, marking the end of the Eighty Years' War between Spain and the Dutch Republic.",
      "date": "1648-10-24"
    },
    {
      "headline": "Signing of the Treaty of Osnabrück",
      "text": "On October 24, 1648, the Treaty of Osnabrück was signed, concluding the Thirty Years' War in the Holy Roman Empire.",
      "date": "1648-10-24"
    },
    {
      "headline": "End of the Thirty Years' War",
      "text": "The Peace of Westphalia, consisting of the Treaties of Münster and Osnabrück, officially ended the Thirty Years' War on October 24, 1648.",
      "date": "1648-10-24"
    },
    {
      "headline": "Impact on the Holy Roman Empire",
      "text": "The Peace of Westphalia resulted in significant territorial and political changes within the Holy Roman Empire, granting greater autonomy to its constituent states.",
      "date": "1648"
    },
    {
      "headline": "Recognition of Sovereignty",
      "text": "The treaties recognized the sovereignty of over 300 German principalities, effectively decentralizing the Holy Roman Empire.",
      "date": "1648"
    },
    {
      "headline": "Religious Tolerance Established",
      "text": "The Peace of Westphalia established a precedent for religious tolerance, allowing rulers to choose the religion of their own state (cuius regio, eius religio).",
      "date": "1648"
    },
    {
      "headline": "Impact on International Law",
      "text": "The Peace of Westphalia is often cited as the beginning of the modern international system of sovereign states, influencing the development of international law.",
      "date": "1648"
    }
  ]
}

