{
  "timeline": [
    {
      "headline": "HS2 Project Announcement",
      "text": "The High Speed 2 (HS2) project was officially announced by the UK government as a plan to create a high-speed railway connecting London and Birmingham, with further extensions to Manchester and Leeds.",
      "date": "2010"
    },
    {
      "headline": "HS2 Phase 1 Approval",
      "text": "The UK government approved the first phase of the HS2 project, which would connect London and Birmingham, in January 2012.",
      "date": "2012-01"
    },
    {
      "headline": "HS2 Hybrid Bill Introduced",
      "text": "The HS2 Hybrid Bill, which would grant the powers to construct and operate Phase 1 of the railway, was introduced to the UK Parliament in November 2013.",
      "date": "2013-11"
    },
    {
      "headline": "Royal Assent for Phase 1",
      "text": "The HS2 Phase 1 Hybrid Bill received Royal Assent, allowing construction to begin, in February 2017.",
      "date": "2017-02"
    },
    {
      "headline": "Construction Begins",
      "text": "Construction of the HS2 railway officially began in September 2020, marking the start of building the new high-speed line.",
      "date": "2020-09"
    },
    {
      "headline": "Phase 2a Approval",
      "text": "The UK Parliament approved Phase 2a of HS2, which extends the line from Birmingham to Crewe, in February 2021.",
      "date": "2021-02"
    },
    {
      "headline": "Phase 2b Announcement",
      "text": "The UK government announced the Integrated Rail Plan for Phase 2b, detailing the extension of HS2 to Manchester and the East Midlands, in November 2021.",
      "date": "2021-11"
    },
    {
      "headline": "Expected Completion",
      "text": "The majority of the HS2 project is planned to be completed by 2033, providing high-speed rail services across major cities in the UK.",
      "date": "2033"
    }
  ]
}

