{
  "timeline": [
    {
      "headline": "February 1974 United Kingdom General Election",
      "text": "The February 1974 United Kingdom general election was held on Thursday, 28 February 1974. The Labour Party, led by Harold Wilson, gained 14 seats but was seventeen short of an overall majority. The Conservative Party, led by Edward Heath, lost 28 seats, resulting in a hung parliament, the first since 1929.",
      "date": "1974-02-28"
    },
    {
      "headline": "Hung Parliament Result",
      "text": "The election resulted in a hung parliament, with no party gaining an overall majority. This was the first hung parliament in the UK since 1929.",
      "date": "1974-02-28"
    },
    {
      "headline": "Edward Heath Seeks Coalition",
      "text": "Following the hung parliament result, incumbent Prime Minister Edward Heath sought a coalition with the Liberal Party. However, the two parties failed to come to an agreement.",
      "date": "1974-02"
    },
    {
      "headline": "Harold Wilson Becomes Prime Minister",
      "text": "After the failed coalition talks, Harold Wilson became Prime Minister for a second time, leading a minority government.",
      "date": "1974-03"
    },
    {
      "headline": "UK as a Member of the European Communities",
      "text": "The February 1974 election was the first general election to be held with the United Kingdom as a member state of the European Communities (EC), commonly known as the 'Common Market'.",
      "date": "1974-02-28"
    },
    {
      "headline": "Call for Another Election",
      "text": "Harold Wilson called another early election in September 1974, which was held in October and resulted in a Labour majority.",
      "date": "1974-09"
    }
  ]
}

