      "headline": "Birth of Syngman Rhee",
      "text": "Syngman Rhee was born on March 26, 1875, in Hwanghae Province, Korea.",
      "date": "1875-03-26"
    },
    {
      "headline": "Education in the United States",
      "text": "In 1904, Rhee traveled to the United States to pursue higher education. He attended George Washington University, Harvard University, and Princeton University, where he earned a Ph.D. in 1910.",
      "date": "1910"
    },
    {
      "headline": "President of the Provisional Government of the Republic of Korea",
      "text": "In 1919, Syngman Rhee was elected as the first president of the Provisional Government of the Republic of Korea, a government-in-exile based in Shanghai.",
      "date": "1919"
    },
    {
      "headline": "Impeachment from Provisional Government",
      "text": "Rhee was impeached from his position as president of the Provisional Government in 1925 due to political disagreements and accusations of authoritarianism.",
      "date": "1925"
    },
    {
      "headline": "Re-elected President of the Provisional Government",
      "text": "In 1947, Rhee was re-elected as the president of the Provisional Government of the Republic of Korea.",
      "date": "1947"
    },
    {
      "headline": "First President of South Korea",
      "text": "On August 15, 1948, Syngman Rhee became the first president of South Korea, following the establishment of the Republic of Korea.",
      "date": "1948-08-15"
    },
    {
      "headline": "Korean War",
      "text": "During Rhee's presidency, the Korean War broke out on June 25, 1950, lasting until 1953. Rhee played a significant role in the conflict, advocating for a strong military response against North Korea.",
      "date": "1950-06-25"
    },
    {
      "headline": "April Revolution and Resignation",
      "text": "In April 1960, widespread protests known as the April Revolution erupted against Rhee's government due to electoral fraud and authoritarian practices. On April 26, 1960, Rhee resigned from the presidency and went into exile in Hawaii.",
      "date": "1960-04-26"
    },
    {
      "headline": "Death of Syngman Rhee",
      "text": "Syngman Rhee died on July 19, 1965, in Honolulu, Hawaii, United States.",
      "date": "1965-07-19"
    }
  ]
}

