{
  "timeline": [
    {
      "headline": "Murder of James Byrd Jr.",
      "text": "On June 7, 1998, James Byrd Jr. was brutally murdered by Shawn Berry, Lawrence Brewer, and John King in Jasper, Texas. Byrd was dragged for three miles behind a Ford pickup truck along an asphalt road. He remained conscious for much of the ordeal and was killed when his body hit the edge of a culvert, severing his right arm and head. The murderers then drove on for another 1.5 miles before dumping his torso in front of a Black church.",
      "date": "1998-06-07"
    },
    {
      "headline": "Arrests and Charges",
      "text": "Following the murder, Shawn Berry, Lawrence Brewer, and John King were arrested and charged with capital murder. The case drew national attention due to its brutal nature and racial motivations.",
      "date": "1998-06"
    },
    {
      "headline": "Trial and Convictions",
      "text": "In 1999, John King and Lawrence Brewer were convicted of capital murder and sentenced to death. Shawn Berry received a life sentence. The trials highlighted issues of racial violence and hate crimes in the United States.",
      "date": "1999"
    },
    {
      "headline": "Execution of Lawrence Brewer",
      "text": "Lawrence Brewer was executed by lethal injection on September 21, 2011, for his role in the murder of James Byrd Jr.",
      "date": "2011-09-21"
    },
    {
      "headline": "Execution of John King",
      "text": "John King was executed by lethal injection on April 24, 2019, for his role in the murder of James Byrd Jr.",
      "date": "2019-04-24"
    },
    {
      "headline": "Impact on Hate Crime Legislation",
      "text": "The murder of James Byrd Jr. led to the passing of the James Byrd Jr. Hate Crimes Act in Texas in 2001. It also contributed to the federal Matthew Shepard and James Byrd Jr. Hate Crimes Prevention Act, signed into law by President Barack Obama on October 28, 2009.",
      "date": "2009-10-28"
    }
  ]
}

