      "headline": "Sigmund Freud's Birth",
      "text": "Sigmund Freud, the founder of psychoanalysis, was born on May 6, 1856, in Freiberg, Moravia, which is now part of the Czech Republic.",
      "date": "1856-05-06"
    },
    {
      "headline": "Freud's Medical Degree",
      "text": "In 1881, Sigmund Freud received his medical degree from the University of Vienna.",
      "date": "1881"
    },
    {
      "headline": "Freud's Study with Jean-Martin Charcot",
      "text": "In 1885, Freud went to Paris to study with Jean-Martin Charcot, a neurologist known for his work on hypnosis and hysteria.",
      "date": "1885"
    },
    {
      "headline": "Freud's Collaboration with Josef Breuer",
      "text": "In 1895, Freud collaborated with Josef Breuer on the book 'Studies on Hysteria', which laid the groundwork for psychoanalysis.",
      "date": "1895"
    },
    {
      "headline": "Publication of 'The Interpretation of Dreams'",
      "text": "In 1899, Freud published 'The Interpretation of Dreams', introducing his theory of the unconscious with respect to dream interpretation.",
      "date": "1899"
    },
    {
      "headline": "Founding of the Vienna Psychoanalytic Society",
      "text": "In 1902, Freud founded the Vienna Psychoanalytic Society, which became a central hub for the development of psychoanalytic theory.",
      "date": "1902"
    },
    {
      "headline": "Publication of 'Three Essays on the Theory of Sexuality'",
      "text": "In 1905, Freud published 'Three Essays on the Theory of Sexuality', which expanded on his theories of childhood sexuality and the Oedipus complex.",
      "date": "1905"
    },
    {
      "headline": "First International Psychoanalytical Congress",
      "text": "In 1908, the first International Psychoanalytical Congress was held in Salzburg, marking the international expansion of psychoanalysis.",
      "date": "1908"
    },
    {
      "headline": "Freud's Emigration to London",
      "text": "In 1938, Freud emigrated to London to escape the Nazi annexation of Austria.",
      "date": "1938"
    },
    {
      "headline": "Sigmund Freud's Death",
      "text": "Sigmund Freud died on September 23, 1939, in London, England.",
      "date": "1939-09-23"
    }
  ]
}

