{
  "timeline": [
    {
      "headline": "Formation of NAACP",
      "text": "The National Association for the Advancement of Colored People (NAACP) was formed on February 12, 1909. It was established as an interracial endeavor to advance justice for African Americans by a group including W. E. B. Du Bois, Mary White Ovington, Moorfield Storey, Ida B. Wells, Lillian Wald, and Henry Moskowitz.",
      "date": "1909-02-12"
    },
    {
      "headline": "First Annual Conference",
      "text": "The NAACP held its first annual conference in 1910, which marked the beginning of its organized efforts to combat racial discrimination and promote civil rights.",
      "date": "1910"
    },
    {
      "headline": "Publication of The Crisis",
      "text": "In November 1910, the NAACP began publishing The Crisis, its official magazine, edited by W. E. B. Du Bois. The magazine became a leading voice for civil rights and social justice.",
      "date": "1910-11"
    },
    {
      "headline": "Legal Defense Fund Established",
      "text": "In 1939, the NAACP established the Legal Defense and Educational Fund, which became a separate legal entity in 1957. It played a crucial role in the legal strategy to end racial segregation.",
      "date": "1939"
    },
    {
      "headline": "Brown v. Board of Education",
      "text": "On May 17, 1954, the NAACP achieved a landmark victory in the Supreme Court case Brown v. Board of Education, which declared racial segregation in public schools unconstitutional.",
      "date": "1954-05-17"
    },
    {
      "headline": "Civil Rights Act of 1964",
      "text": "The NAACP played a significant role in the passage of the Civil Rights Act of 1964, which outlawed discrimination based on race, color, religion, sex, or national origin.",
      "date": "1964"
    },
    {
      "headline": "Voting Rights Act of 1965",
      "text": "The NAACP was instrumental in the passage of the Voting Rights Act of 1965, which aimed to overcome legal barriers at the state and local levels that prevented African Americans from exercising their right to vote.",
      "date": "1965"
    },
