    {
      "headline": "Formation of Field Operations Group (FOG)",
      "text": "In 1980, the Field Operations Group (FOG) was formed as a response to the failed Operation Eagle Claw, the mission to rescue American hostages in Iran. The unit was created to provide better intelligence support for special operations.",
      "date": "1980"
    },
    {
      "headline": "Renaming to Intelligence Support Activity (ISA)",
      "text": "In 1981, the Field Operations Group was renamed the Intelligence Support Activity (ISA). This change marked the formal establishment of the unit as a dedicated intelligence gathering component within the U.S. Army.",
      "date": "1981"
    },
    {
      "headline": "Operation Winter Harvest",
      "text": "In 1982, the ISA participated in Operation Winter Harvest, an operation aimed at capturing drug lord Pablo Escobar. This operation highlighted the unit's capabilities in intelligence gathering and direct action.",
      "date": "1982"
    },
    {
      "headline": "Involvement in Operation Urgent Fury",
      "text": "In 1983, the ISA was involved in Operation Urgent Fury, the U.S. invasion of Grenada. The unit provided critical intelligence support that contributed to the success of the operation.",
      "date": "1983"
    },
    {
      "headline": "Participation in Operation Just Cause",
      "text": "In 1989, the ISA played a significant role in Operation Just Cause, the U.S. invasion of Panama. The unit's intelligence efforts were crucial in locating and capturing Panamanian leader Manuel Noriega.",
      "date": "1989"
    },
    {
      "headline": "Role in the Gulf War",
      "text": "During the Gulf War in 1991, the ISA provided intelligence support to U.S. forces, demonstrating its importance in modern military operations.",
      "date": "1991"
    },
    {
      "headline": "Involvement in the War on Terror",
      "text": "Following the September 11 attacks in 2001, the ISA became heavily involved in the War on Terror, providing intelligence support for operations in Afghanistan and Iraq.",
      "date": "2001"
    },
    {
      "headline": "Renaming to Mission Support Activity (MSA)",
      "text": "In the 2000s, the unit was renamed the Mission Support Activity (MSA) as part of a restructuring effort within the Joint Special Operations Command (JSOC).",
      "date": "2000s"
    }
  ]
}

