{
  "timeline": [
    {
      "headline": "Early Origins of Flamenco",
      "text": "Flamenco's origins are believed to date back to the 9th century, with influences from the music and dance of the Romani people, as well as from the Moors, Jews, and indigenous Andalusians.",
      "date": "-0800"
    },
    {
      "headline": "First Written Reference to Flamenco",
      "text": "The first written reference to flamenco appeared in the literature of the late 18th century. Flamenco was mentioned in the book 'Las Cartas Marruecas' by José Cadalso, published in 1774.",
      "date": "1774"
    },
    {
      "headline": "Golden Age of Flamenco",
      "text": "The period from 1869 to 1910 is known as the Golden Age of Flamenco. During this time, flamenco music and dance became popular in cafés cantantes (music cafés) throughout Spain.",
      "date": "1869"
    },
    {
      "headline": "Development of Flamenco Guitar",
      "text": "In the late 19th and early 20th centuries, the flamenco guitar began to develop as a distinct style, with guitarists like Ramón Montoya pioneering new techniques.",
      "date": "1900"
    },
    {
      "headline": "Flamenco Becomes a Symbol of Spanish Culture",
      "text": "In the 1920s and 1930s, flamenco became a symbol of Spanish culture, with artists like Carmen Amaya and Antonio de Triana gaining international fame.",
      "date": "1920"
    },
    {
      "headline": "Flamenco Renaissance",
      "text": "The 1950s and 1960s saw a flamenco renaissance, with artists like Paco de Lucía and Camarón de la Isla modernizing the genre and bringing it to a global audience.",
      "date": "1950"
    },
    {
      "headline": "UNESCO Recognition",
      "text": "In 2010, UNESCO declared flamenco as an Intangible Cultural Heritage of Humanity, recognizing its cultural significance and historical importance.",
      "date": "2010"
    }
  ]
}

