{
  "timeline": [
    {
      "headline": "Discovery of Marburg Virus",
      "text": "In 1967, the Marburg virus was first recognized during outbreaks of hemorrhagic fever in laboratories in Marburg and Frankfurt, Germany, and in Belgrade, Yugoslavia (now Serbia). The outbreaks were associated with laboratory work using African green monkeys imported from Uganda.",
      "date": "1967"
    },
    {
      "headline": "First Recorded Outbreak",
      "text": "The first recorded outbreak of Marburg virus disease occurred in 1967, affecting laboratory workers and medical personnel. A total of 31 people were infected, and 7 died.",
      "date": "1967"
    },
    {
      "headline": "Identification as a Filovirus",
      "text": "Following its discovery, Marburg virus was identified as a member of the Filoviridae family, which also includes the Ebola virus.",
      "date": "1967"
    },
    {
      "headline": "Subsequent Outbreaks",
      "text": "Since its discovery, there have been several outbreaks of Marburg virus disease, including in Angola (2004-2005), the Democratic Republic of the Congo (1998-2000), and Uganda (2012).",
      "date": "2004"
    },
    {
      "headline": "Angola Outbreak",
      "text": "The largest outbreak of Marburg virus disease occurred in Angola from 2004 to 2005, resulting in over 250 deaths.",
      "date": "2004"
    },
    {
      "headline": "Uganda Outbreak",
      "text": "In 2012, an outbreak of Marburg virus disease occurred in Uganda, resulting in several cases and fatalities.",
      "date": "2012"
    },
    {
      "headline": "Classification as a Risk Group 4 Pathogen",
      "text": "The World Health Organization classifies Marburg virus as a Risk Group 4 Pathogen, indicating it poses a high risk to individual and community health.",
      "date": "2023"
    },
    {
      "headline": "Designation as a Category A Bioterrorism Agent",
      "text": "The Centers for Disease Control and Prevention lists Marburg virus as a Category A Bioterrorism Agent, indicating it poses a significant threat to national security.",
      "date": "2023"
    }
  ]
}

