{
  "timeline": [
    {
      "headline": "First Unmanned Hot Air Balloon Flight",
      "text": "On June 4, 1783, the Montgolfier brothers, Joseph-Michel and Jacques-Étienne, launched the first unmanned hot air balloon in Annonay, France. The balloon rose to an altitude of about 1,000 meters and traveled approximately 2 kilometers.",
      "date": "1783-06-04"
    },
    {
      "headline": "First Manned Hot Air Balloon Flight",
      "text": "On November 21, 1783, Jean-François Pilâtre de Rozier and François Laurent d'Arlandes made the first untethered manned flight in a hot air balloon. The flight took place in Paris, France, and lasted about 25 minutes, covering a distance of approximately 9 kilometers.",
      "date": "1783-11-21"
    },
    {
      "headline": "First Manned Hydrogen Balloon Flight",
      "text": "On December 1, 1783, Jacques Charles and Nicolas-Louis Robert launched the first manned hydrogen balloon flight from the Tuileries Gardens in Paris. This flight marked the beginning of gas ballooning.",
      "date": "1783-12-01"
    },
    {
      "headline": "First Crossing of the English Channel by Balloon",
      "text": "On January 7, 1785, Jean-Pierre Blanchard and John Jeffries became the first to cross the English Channel in a balloon. They flew from Dover, England, to Calais, France.",
      "date": "1785-01-07"
    },
    {
      "headline": "First Solo Transatlantic Balloon Flight",
      "text": "On August 11, 1978, Ben Abruzzo, Maxie Anderson, and Larry Newman completed the first successful transatlantic flight in a hot air balloon. The balloon, named Double Eagle II, flew from Presque Isle, Maine, USA, to Miserey, France.",
      "date": "1978-08-11"
    },
    {
      "headline": "First Solo Round-the-World Balloon Flight",
      "text": "On March 20, 1999, Bertrand Piccard and Brian Jones completed the first non-stop balloon flight around the world. The Breitling Orbiter 3 took off from Château-d'Oex, Switzerland, and landed in Egypt after traveling 45,755 kilometers in 19 days, 21 hours, and 47 minutes.",
      "date": "1999-03-20"
    }
  ]
}

