    {
      "headline": "Five Dynasties and Ten Kingdoms Period",
      "text": "Fujian was part of the Min Kingdom during the Five Dynasties and Ten Kingdoms period, which lasted from 909 to 945.",
      "date": "0909"
    },
    {
      "headline": "Song Dynasty Economic Growth",
      "text": "During the Song dynasty, Fujian experienced significant economic growth, becoming a major center for trade and commerce.",
      "date": "1000"
    },
    {
      "headline": "Ming Dynasty Maritime Trade",
      "text": "In the Ming dynasty, Fujian was a hub for maritime trade, with the port city of Quanzhou serving as a major trading center.",
      "date": "1400"
    },
    {
      "headline": "Qing Dynasty and Taiwan",
      "text": "During the Qing dynasty, Fujian served as a base for the Qing conquest of Taiwan in 1683.",
      "date": "1683"
    },
    {
      "headline": "Republic of China Era",
      "text": "After the fall of the Qing dynasty, Fujian became part of the Republic of China in 1912.",
      "date": "1912"
