    {
      "headline": "Establishment of the Pale of Settlement",
      "text": "In 1791, the Russian Empire established the Pale of Settlement, a region in which Jews were allowed to reside. This area included parts of present-day Poland, Latvia, Lithuania, Ukraine, and Belarus.",
      "date": "1791"
    },
    {
      "headline": "Expansion of the Pale",
      "text": "Throughout the early 19th century, the borders of the Pale of Settlement were adjusted several times, expanding and contracting as the Russian Empire acquired new territories.",
      "date": "1800"
    },
    {
      "headline": "Restrictions on Jewish Residency",
      "text": "By the mid-19th century, restrictions tightened, and Jews were largely confined to the Pale. They were prohibited from living in rural areas and certain cities within the Pale.",
      "date": "1850"
    },
    {
      "headline": "May Laws",
      "text": "In 1882, the Russian government enacted the May Laws, which further restricted Jewish residency and economic activities within the Pale of Settlement.",
      "date": "1882"
    },
    {
      "headline": "Pogroms and Emigration",
      "text": "Between 1881 and 1914, waves of pogroms (violent riots aimed at the massacre or expulsion of Jews) occurred in the Pale, prompting mass emigration of Jews to the United States and other countries.",
      "date": "1881"
    },
    {
      "headline": "World War I and the Pale",
      "text": "During World War I, many Jews were expelled from the Pale as the front lines moved. The Russian army accused them of collaborating with the enemy.",
      "date": "1914"
    },
    {
      "headline": "Abolition of the Pale of Settlement",
      "text": "The Pale of Settlement was officially abolished in 1917 following the Russian Revolution, allowing Jews to live freely throughout the Russian Empire.",
      "date": "1917"
    }
  ]
}

