{
  "timeline": [
    {
      "headline": "Richard Feynman's Lecture",
      "text": "On December 29, 1959, physicist Richard Feynman gave a lecture titled 'There's Plenty of Room at the Bottom' at an American Physical Society meeting at Caltech. He discussed the possibility of manipulating individual atoms, which is considered a foundational concept for nanotechnology.",
      "date": "1959-12-29"
    },
    {
      "headline": "Introduction of the Term 'Nanotechnology'",
      "text": "In 1974, the term 'nanotechnology' was first used by Norio Taniguchi, a professor at Tokyo Science University, to describe semiconductor processes that occurred on the order of a nanometer.",
      "date": "1974"
    },
    {
      "headline": "Development of the Scanning Tunneling Microscope",
      "text": "In 1981, Gerd Binnig and Heinrich Rohrer at IBM Zurich Research Laboratory developed the scanning tunneling microscope (STM), which allowed scientists to visualize surfaces at the atomic level. This invention was crucial for the advancement of nanotechnology.",
      "date": "1981"
    },
    {
      "headline": "Discovery of Fullerenes",
      "text": "In 1985, scientists Robert Curl, Harold Kroto, and Richard Smalley discovered fullerenes, a new form of carbon molecule, which opened up new possibilities in nanotechnology. They were awarded the Nobel Prize in Chemistry in 1996 for this discovery.",
      "date": "1985"
    },
    {
      "headline": "Invention of the Atomic Force Microscope",
      "text": "In 1986, the atomic force microscope (AFM) was invented by Gerd Binnig, Calvin Quate, and Christoph Gerber. This tool allowed for imaging, measuring, and manipulating matter at the nanoscale.",
      "date": "1986"
    },
    {
      "headline": "Publication of 'Engines of Creation'",
      "text": "In 1986, K. Eric Drexler published 'Engines of Creation: The Coming Era of Nanotechnology,' which popularized the concept of molecular nanotechnology and its potential impacts on society.",
      "date": "1986"
    },
    {
      "headline": "Formation of the National Nanotechnology Initiative",
      "text": "In 2000, the United States government launched the National Nanotechnology Initiative (NNI) to coordinate federal nanotechnology research and development. This initiative significantly increased funding and interest in nanotechnology.",
      "date": "2000"
    },
    {
      "headline": "First Nanotechnology-Based Cancer Treatment Approved",
      "text": "In 2005, the FDA approved the first nanotechnology-based cancer treatment, Abraxane, which uses nanoparticles to deliver chemotherapy drugs more effectively to cancer cells.",
      "date": "2005"
    }
  ]
}

