{
  "timeline": [
    {
      "headline": "Hernán Cortés Arrives in Mexico",
      "text": "On March 4, 1519, Hernán Cortés and his expedition landed on the coast of Mexico near present-day Veracruz. This marked the beginning of the Spanish conquest of the Aztec Empire.",
      "date": "1519-03-04"
    },
    {
      "headline": "Foundation of Veracruz",
      "text": "In April 1519, Cortés founded the settlement of Villa Rica de la Vera Cruz, which served as a base for the Spanish operations in Mexico.",
      "date": "1519-04"
    },
    {
      "headline": "Alliance with Tlaxcala",
      "text": "In September 1519, after initial hostilities, Cortés formed an alliance with the Tlaxcalans, who became crucial allies against the Aztecs.",
      "date": "1519-09"
    },
    {
      "headline": "Massacre at Cholula",
      "text": "In October 1519, Cortés and his forces massacred thousands of Cholulans, an event that demonstrated Spanish military power and intimidation tactics.",
      "date": "1519-10"
    },
    {
      "headline": "Entry into Tenochtitlan",
      "text": "On November 8, 1519, Cortés and his forces entered the Aztec capital of Tenochtitlan, where they were initially received by Emperor Moctezuma II.",
      "date": "1519-11-08"
    },
    {
      "headline": "Capture of Moctezuma II",
      "text": "In November 1519, shortly after entering Tenochtitlan, Cortés took Moctezuma II hostage in an attempt to control the Aztec Empire.",
      "date": "1519-11"
    },
    {
      "headline": "La Noche Triste",
      "text": "On June 30, 1520, the Spanish and their allies were forced to flee Tenochtitlan during a violent uprising, an event known as La Noche Triste.",
      "date": "1520-06-30"
    },
    {
      "headline": "Battle of Otumba",
      "text": "On July 7, 1520, the Spanish and their allies won a crucial victory against the Aztecs at the Battle of Otumba, allowing them to regroup and plan further attacks.",
      "date": "1520-07-07"
    },
    {
      "headline": "Siege of Tenochtitlan",
      "text": "In May 1521, Cortés began the siege of Tenochtitlan, which lasted for several months and involved fierce fighting and significant loss of life.",
      "date": "1521-05"
    },
    {
      "headline": "Fall of Tenochtitlan",
      "text": "On August 13, 1521, Tenochtitlan fell to the Spanish and their allies, marking the end of the Aztec Empire and the beginning of Spanish dominance in central Mexico.",
      "date": "1521-08-13"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Introduction of Favicon",
      "text": "The favicon was first introduced by Microsoft in Internet Explorer 5, released in March 1999. It allowed web designers to associate a small icon with a website, which would appear in the browser's address bar and bookmarks.",
      "date": "1999-03"
    },
    {
      "headline": "Standardization in HTML",
      "text": "Favicons became standardized with the introduction of the HTML 4.01 specification in December 1999, which allowed web designers to link to a favicon using the <link> tag in the HTML head.",
      "date": "1999-12"
    },
    {
      "headline": "Widespread Adoption",
      "text": "By the early 2000s, favicons were widely adopted by web browsers beyond Internet Explorer, including Mozilla Firefox and Opera, enhancing the visual identification of websites.",
      "date": "2000"
    },
    {
      "headline": "Support for PNG Format",
      "text": "In 2005, browsers began to support the PNG format for favicons, allowing for better image quality and transparency compared to the original ICO format.",
      "date": "2005"
    },
    {
      "headline": "Introduction of High-Resolution Favicons",
      "text": "With the advent of high-resolution displays, such as Apple's Retina Display, browsers started supporting higher resolution favicons in 2010, allowing for clearer and more detailed icons.",
      "date": "2010"
    },
    {
      "headline": "Favicon Usage in Mobile Browsers",
      "text": "As mobile browsing became more prevalent, favicons were adapted for use in mobile browsers and app icons, further increasing their importance in web design.",
      "date": "2010s"
    }
  ]
}

