    },
    {
      "headline": "Tipu Sultan's rule",
      "text": "Tipu Sultan, son of Hyder Ali, ruled Mysore from 1782 until his death in 1799. He was known for his resistance against British expansion.",
      "date": "1782"
    },
    {
      "headline": "Fourth Anglo-Mysore War",
      "text": "The Fourth Anglo-Mysore War took place in 1799, resulting in the death of Tipu Sultan and the end of his rule.",
      "date": "1799"
    },
    {
      "headline": "Restoration of the Wadiyar dynasty",
      "text": "After the fall of Tipu Sultan, the British restored the Wadiyar dynasty to power in Mysore in 1799.",
      "date": "1799"
    },
    {
      "headline": "Mysore Palace construction",
      "text": "The construction of the current Mysore Palace began in 1897 and was completed in 1912, becoming a major landmark.",
      "date": "1897"
