      "date": "1904-02-08"
    },
    {
      "headline": "Japan-Korea Treaty of 1905",
      "text": "On November 17, 1905, the Japan-Korea Treaty of 1905 was signed, making Korea a protectorate of Japan and stripping the Korean Empire of its diplomatic sovereignty.",
      "date": "1905-11-17"
    },
    {
      "headline": "Assassination of Empress Myeongseong",
      "text": "Empress Myeongseong, also known as Queen Min, was assassinated by Japanese agents on October 8, 1895, which led to increased tensions and was a precursor to the establishment of the Korean Empire.",
      "date": "1895-10-08"
    },
    {
      "headline": "Japan-Korea Treaty of 1907",
      "text": "The Japan-Korea Treaty of 1907, signed on July 24, 1907, further reduced Korea's sovereignty by disbanding the Korean military and placing Japanese advisors in key government positions.",
      "date": "1907-07-24"
    },
    {
      "headline": "Annexation of Korea by Japan",
      "text": "On August 22, 1910, the Japan-Korea Annexation Treaty was signed, officially annexing Korea into the Japanese Empire and marking the end of the Korean Empire.",
      "date": "1910-08-22"
    }
  ]
}

