{
  "timeline": [
    {
      "headline": "ARPANET Project Initiation",
      "text": "The ARPANET project was initiated by the Advanced Research Projects Agency (ARPA) of the United States Department of Defense in 1966.",
      "date": "1966"
    },
    {
      "headline": "First ARPANET Node",
      "text": "The first ARPANET node was installed at the University of California, Los Angeles (UCLA) on September 2, 1969.",
      "date": "1969-09-02"
    },
    {
      "headline": "First Message Sent",
      "text": "The first message was sent over the ARPANET from UCLA to the Stanford Research Institute (SRI) on October 29, 1969. The message was intended to be 'LOGIN', but only 'LO' was transmitted before the system crashed.",
      "date": "1969-10-29"
    },
    {
      "headline": "ARPANET Expands",
      "text": "By December 1969, four nodes were connected: UCLA, Stanford Research Institute, University of California, Santa Barbara, and the University of Utah.",
      "date": "1969-12"
    },
    {
      "headline": "Introduction of Email",
      "text": "Email was introduced on the ARPANET in 1971, becoming the network's most popular application.",
      "date": "1971"
    },
    {
      "headline": "Network Control Protocol (NCP)",
      "text": "The Network Control Protocol (NCP) was implemented on the ARPANET in 1970, allowing for the first host-to-host protocol.",
      "date": "1970"
    },
    {
      "headline": "International Connections",
      "text": "The ARPANET made its first international connections in 1973, linking to the University College London in England and the Royal Radar Establishment in Norway.",
      "date": "1973"
    },
    {
      "headline": "TCP/IP Protocol Adoption",
      "text": "The ARPANET began transitioning to the TCP/IP protocol suite on January 1, 1983, marking the beginning of the modern Internet.",
      "date": "1983-01-01"
    },
    {
      "headline": "ARPANET Decommissioned",
      "text": "The ARPANET was officially decommissioned in 1990, having been replaced by newer networks using the TCP/IP protocol.",
      "date": "1990"
    }
  ]
}

