{
  "timeline": [
    {
      "headline": "Introduction of the Zeta Function",
      "text": "The Riemann zeta function was first introduced by Leonhard Euler in the 18th century. Euler studied the function for real arguments greater than 1.",
      "date": "1740"
    },
    {
      "headline": "Riemann's Extension",
      "text": "Bernhard Riemann extended the definition of the zeta function to complex numbers and formulated the Riemann Hypothesis in his 1859 paper 'On the Number of Primes Less Than a Given Magnitude'.",
      "date": "1859"
    },
    {
      "headline": "Riemann Hypothesis",
      "text": "The Riemann Hypothesis, proposed by Bernhard Riemann in 1859, conjectures that all non-trivial zeros of the zeta function have a real part of 1/2.",
      "date": "1859"
    },
    {
      "headline": "Functional Equation",
      "text": "Riemann discovered the functional equation of the zeta function, which relates the values of the function at s and 1-s.",
      "date": "1859"
    },
    {
      "headline": "Analytic Continuation",
      "text": "Riemann also showed how to extend the zeta function to a meromorphic function on the entire complex plane, except for a simple pole at s = 1.",
      "date": "1859"
    },
    {
      "headline": "Connection to Prime Numbers",
      "text": "Riemann's work established a deep connection between the zeta function and the distribution of prime numbers, influencing the field of analytic number theory.",
      "date": "1859"
    }
  ]
}

