    {
      "headline": "Beginning of the Siege of Jadotville",
      "text": "The siege of Jadotville began on 13 September 1961. A small contingent of the Irish Army's 35th Battalion, designated 'A' Company, was besieged at the UN base near the mining town of Jadotville by Katangese forces loyal to the secessionist State of Katanga.",
      "date": "1961-09-13"
    },
    {
      "headline": "Duration of the Siege",
      "text": "The siege lasted for five days, from 13 September 1961 to 17 September 1961. During this time, the Irish troops, despite being heavily outnumbered and outgunned, managed to hold off repeated attacks by the Katangese forces.",
      "date": "1961-09-13"
    },
    {
      "headline": "End of the Siege",
      "text": "The siege ended on 17 September 1961 when the Irish troops, running low on supplies and ammunition, were forced to surrender to the Katangese forces. Despite their surrender, the Irish soldiers were later released and returned home safely.",
      "date": "1961-09-17"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of David Livingstone",
      "text": "David Livingstone was born on March 19, 1813, in Blantyre, South Lanarkshire, Scotland.",
      "date": "1813-03-19"
    },
    {
      "headline": "Education and Early Career",
      "text": "In 1836, Livingstone began studying medicine and theology at the University of Glasgow, which he completed in 1840.",
      "date": "1836"
    },
    {
      "headline": "Departure to Africa",
      "text": "Livingstone was ordained as a missionary and left for Africa in 1840 under the London Missionary Society.",
      "date": "1840"
    },
    {
      "headline": "Marriage to Mary Moffat",
      "text": "David Livingstone married Mary Moffat, the daughter of missionary Robert Moffat, on January 2, 1845.",
      "date": "1845-01-02"
    },
    {
      "headline": "Exploration of the Zambezi River",
      "text": "In 1853, Livingstone began his exploration of the Zambezi River, which he continued until 1856.",
      "date": "1853"
    },
    {
      "headline": "Discovery of Victoria Falls",
      "text": "On November 16, 1855, Livingstone discovered the Victoria Falls on the Zambezi River, naming them after Queen Victoria.",
      "date": "1855-11-16"
    },
    {
      "headline": "Publication of 'Missionary Travels and Researches in South Africa'",
      "text": "In 1857, Livingstone published his book 'Missionary Travels and Researches in South Africa', which became a bestseller.",
      "date": "1857"
    },
    {
      "headline": "Zambezi Expedition",
      "text": "Livingstone led the British government-funded Zambezi Expedition from 1858 to 1864 to explore Eastern and Central Africa.",
      "date": "1858"
    },
    {
      "headline": "Death of Mary Livingstone",
      "text": "Mary Livingstone died of malaria on April 27, 1862, during the Zambezi Expedition.",
      "date": "1862-04-27"
    },
    {
      "headline": "Exploration of Lake Malawi",
      "text": "In 1861, Livingstone explored Lake Malawi, contributing to the geographical understanding of the region.",
      "date": "1861"
    },
    {
      "headline": "Search for the Source of the Nile",
      "text": "Livingstone embarked on an expedition in 1866 to find the source of the Nile, which lasted until 1873.",
      "date": "1866"
    },
    {
      "headline": "Meeting with Henry Morton Stanley",
      "text": "On November 10, 1871, journalist Henry Morton Stanley found Livingstone in Ujiji, Tanzania, famously greeting him with 'Dr. Livingstone, I presume?'",
      "date": "1871-11-10"
    },
    {
      "headline": "Death of David Livingstone",
      "text": "David Livingstone died from malaria and internal bleeding due to dysentery on May 1, 1873, in Chief Chitambo's village at Ilala, near Lake Bangweulu, Zambia.",
      "date": "1873-05-01"
    }
  ]
}

