{
  "timeline": [
    {
      "headline": "Existence of Stegosaurus",
      "text": "Stegosaurus lived during the Late Jurassic period, approximately between 155 and 145 million years ago. Fossils have been found in the western United States and Portugal.",
      "date": "-0155"
    },
    {
      "headline": "Discovery of Stegosaurus Fossils",
      "text": "The first Stegosaurus fossils were discovered in the late 19th century in the Morrison Formation of the western United States.",
      "date": "1877"
    },
    {
      "headline": "Naming of Stegosaurus",
      "text": "The genus Stegosaurus was named by Othniel Charles Marsh in 1877. The name means 'roofed lizard', referring to its distinctive back plates.",
      "date": "1877"
    },
    {
      "headline": "Recognition of Stegosaurus Species",
      "text": "Of the species classified in the upper Morrison Formation, only three are universally recognized: S. stenops, S. ungulatus, and S. sulcatus.",
      "date": "Late 19th century"
    },
    {
      "headline": "Coexistence with Other Dinosaurs",
      "text": "Stegosaurus lived alongside other dinosaurs such as Apatosaurus, Diplodocus, Camarasaurus, and Allosaurus, the latter of which may have preyed on it.",
      "date": "-0155 to -0145"
    }
  ]
}

