{
  "timeline": [
    {
      "headline": "Partition of British India",
      "text": "In 1947, British India was partitioned into two independent dominions, India and Pakistan. The princely state of Jammu and Kashmir, which included the region now known as Gilgit-Baltistan, became a disputed territory between India and Pakistan.",
      "date": "1947"
    },
    {
      "headline": "Establishment of Gilgit Agency",
      "text": "In 1947, the Gilgit Agency was established by the British, which included the Gilgit region and was administered separately from the princely state of Jammu and Kashmir.",
      "date": "1947"
    },
    {
      "headline": "Revolt in Gilgit",
      "text": "On November 1, 1947, the local population of Gilgit revolted against the Maharaja of Jammu and Kashmir's rule and declared accession to Pakistan.",
      "date": "1947-11-01"
    },
    {
      "headline": "Formation of Northern Areas",
      "text": "In 1970, the region was reorganized and renamed as the 'Northern Areas' by Pakistan, which included the districts of Gilgit and Baltistan.",
      "date": "1970"
    },
    {
      "headline": "Karakoram Highway Completion",
      "text": "In 1978, the Karakoram Highway, connecting Pakistan with China through Gilgit-Baltistan, was completed, enhancing trade and travel between the two countries.",
      "date": "1978"
    },
    {
      "headline": "Gilgit-Baltistan Empowerment and Self-Governance Order",
      "text": "In 2009, Pakistan introduced the Gilgit-Baltistan Empowerment and Self-Governance Order, granting the region a degree of autonomy and establishing a legislative assembly.",
      "date": "2009"
    },
    {
      "headline": "Gilgit-Baltistan Order",
      "text": "In 2018, the Government of Pakistan promulgated the Gilgit-Baltistan Order, replacing the 2009 order, which further defined the governance structure of the region.",
      "date": "2018"
    }
  ]
}

