{
  "timeline": [
    {
      "headline": "Creation of COBOL",
      "text": "In 1959, COBOL (Common Business-Oriented Language) was created as a result of a conference sponsored by the U.S. Department of Defense. The language was designed to be a portable, business-oriented programming language.",
      "date": "1959"
    },
    {
      "headline": "First COBOL Specification",
      "text": "The first COBOL specification was completed in December 1959. This specification laid the groundwork for the development and implementation of COBOL compilers.",
      "date": "1959-12"
    },
    {
      "headline": "First COBOL Program Runs",
      "text": "In 1960, the first COBOL program was run on two different types of computers, demonstrating its portability. This was a significant milestone in the language's development.",
      "date": "1960"
    },
    {
      "headline": "COBOL 60 Standard",
      "text": "In 1961, COBOL 60 was published as the first official standard for the language, providing a more formalized structure for COBOL programming.",
      "date": "1961"
    },
    {
      "headline": "COBOL 61 Extended",
      "text": "In 1963, COBOL 61 Extended was released, which included new features and improvements over the original COBOL 60 standard.",
      "date": "1963"
    },
    {
      "headline": "COBOL 68 Standard",
      "text": "In 1968, the COBOL 68 standard was published, further refining the language and adding new capabilities.",
      "date": "1968"
    },
    {
      "headline": "COBOL 74 Standard",
      "text": "In 1974, the COBOL 74 standard was introduced, which included enhancements such as structured programming constructs.",
      "date": "1974"
    },
    {
      "headline": "COBOL 85 Standard",
      "text": "In 1985, the COBOL 85 standard was released, introducing new features like scope terminators and intrinsic functions, making the language more robust.",
      "date": "1985"
    },
    {
      "headline": "COBOL 2002 Standard",
      "text": "In 2002, the COBOL 2002 standard was published, adding support for object-oriented programming, which was a significant update to the language.",
      "date": "2002"
    },
    {
      "headline": "COBOL 2014 Standard",
      "text": "In 2014, the COBOL 2014 standard was released, which included updates and improvements to the language, ensuring its continued relevance in modern computing environments.",
      "date": "2014"
    }
  ]
}

{
