    {
      "headline": "Five Points Riot",
      "text": "The Five Points Riot occurred in 1834, highlighting the tensions between different ethnic groups in the neighborhood.",
      "date": "1834"
    },
    {
      "headline": "Draft Riots",
      "text": "The New York City Draft Riots in 1863 were partly centered in the Five Points area, exacerbating the neighborhood's reputation for violence.",
      "date": "1863"
