      "headline": "U.S. Supreme Court Halts Recount",
      "text": "On December 9, 2000, the U.S. Supreme Court halted the Florida recount.",
      "date": "2000-12-09"
    },
    {
      "headline": "Bush v. Gore Decision",
      "text": "On December 12, 2000, the U.S. Supreme Court issued its decision in Bush v. Gore, effectively awarding Florida's electoral votes to George W. Bush.",
      "date": "2000-12-12"
    },
    {
      "headline": "Certification of Results",
      "text": "Florida's Secretary of State certified the election results, awarding the state's 25 electoral votes to George W. Bush, who won the presidency.",
      "date": "2000-12-12"
    }
  ]
}

