{
  "timeline": [
    {
      "headline": "Discovery of the Body",
      "text": "On 1948-12-01, the body of an unidentified man was found on Somerton Beach, Adelaide, South Australia. The man was discovered lying on the sand with his head resting against the seawall, legs extended and feet crossed.",
      "date": "1948-12-01"
    },
    {
      "headline": "Autopsy and Initial Investigation",
      "text": "An autopsy was conducted on 1948-12-02, revealing no obvious cause of death. The man was of British appearance, thought to be aged about 40–45, and in top physical condition. He was dressed in a suit and tie, with no identification.",
      "date": "1948-12-02"
    },
    {
      "headline": "Discovery of the 'Tamám Shud' Scrap",
      "text": "In January 1949, a small piece of paper with the words 'Tamám Shud' was found in a hidden pocket of the man's trousers. The phrase, meaning 'It is finished', was identified as being torn from the final page of a book, the Rubaiyat of Omar Khayyám.",
      "date": "1949-01"
    },
    {
      "headline": "Discovery of the Rubaiyat",
      "text": "In July 1949, a copy of the Rubaiyat of Omar Khayyám was found in the back seat of a car near where the body was discovered. The book had a section torn out that matched the 'Tamám Shud' scrap.",
      "date": "1949-07"
    },
    {
      "headline": "Inquest and Continued Investigation",
      "text": "An inquest into the man's death was held in 1949, but it failed to determine the identity of the man or the cause of death. The case remained open, with numerous theories but no conclusive evidence.",
      "date": "1949"
    },
    {
      "headline": "DNA Analysis and Identification",
      "text": "In July 2022, DNA analysis led to the identification of the Somerton Man as Carl 'Charles' Webb, an electrical engineer and instrument maker born in 1905 in Melbourne, Australia.",
      "date": "2022-07"
    }
  ]
}

