    },
    {
      "headline": "Webster-Ashburton Treaty",
      "text": "Signed on August 9, 1842, the Webster-Ashburton Treaty resolved border disputes between the United States and British North America, particularly in the Maine-New Brunswick area.",
      "date": "1842-08-09"
    },
    {
      "headline": "Oregon Treaty",
      "text": "The Oregon Treaty was signed on June 15, 1846, establishing the 49th parallel as the boundary between the United States and British North America from the Rocky Mountains to the Strait of Georgia.",
      "date": "1846-06-15"
    },
    {
      "headline": "Alaska Purchase",
      "text": "On March 30, 1867, the United States purchased Alaska from Russia, establishing a new boundary with British North America.",
      "date": "1867-03-30"
    },
    {
      "headline": "International Boundary Commission",
      "text": "The International Boundary Commission was established in 1908 to maintain the boundary between Canada and the United States.",
      "date": "1908"
    },
    {
      "headline": "International Joint Commission",
      "text": "Established in 1909, the International Joint Commission was created to manage and resolve boundary water issues between Canada and the United States.",
      "date": "1909"
    },
    {
      "headline": "Canada Border Services Agency",
      "text": "The Canada Border Services Agency (CBSA) was established in 2003 to manage the flow of people and goods across the Canadian border.",
      "date": "2003"
    },
    {
      "headline": "U.S. Customs and Border Protection",
      "text": "U.S. Customs and Border Protection (CBP) was formed in 2003 as part of the Department of Homeland Security to manage and secure the United States' borders.",
      "date": "2003"
    }
  ]
}

