      "headline": "Outbreak of the Peloponnesian War",
      "text": "The Peloponnesian War began in 431 BCE, with Pericles leading Athens during the initial years of the conflict.",
      "date": "-0431"
    },
    {
      "headline": "Death of Pericles",
      "text": "Pericles died in 429 BCE, during a plague that struck Athens amidst the Peloponnesian War.",
      "date": "-0429"
    }
  ]
}

