{
  "timeline": [
    {
      "headline": "Deportation to Babylon",
      "text": "Shadrach, Meshach, and Abednego, originally named Hananiah, Mishael, and Azariah, were among the young Jewish nobles taken to Babylon by Nebuchadnezzar II after the conquest of Jerusalem. They were selected to be trained in the Chaldean language and literature to serve in the king's court. This event is traditionally dated to around 605 BCE.",
      "date": "-0605"
    },
    {
      "headline": "Renaming in Babylon",
      "text": "Upon their arrival in Babylon, Hananiah, Mishael, and Azariah were given new Babylonian names: Shadrach, Meshach, and Abednego, respectively. This renaming was part of their assimilation into Babylonian culture.",
      "date": "-0605"
    },
    {
      "headline": "Refusal to Bow to the Image",
      "text": "Shadrach, Meshach, and Abednego refused to bow to the golden image set up by King Nebuchadnezzar, defying the king's decree. This act of defiance is recorded in the Book of Daniel, chapter 3, and is traditionally dated to the reign of Nebuchadnezzar II, around 587 BCE.",
      "date": "-0587"
    },
    {
      "headline": "Thrown into the Fiery Furnace",
      "text": "As punishment for their refusal to worship the golden image, Shadrach, Meshach, and Abednego were thrown into a fiery furnace. However, they were miraculously unharmed, and a fourth figure, described as 'like a son of God,' was seen with them in the flames.",
      "date": "-0587"
    },
    {
      "headline": "Recognition by Nebuchadnezzar",
      "text": "After witnessing the miraculous survival of Shadrach, Meshach, and Abednego, King Nebuchadnezzar praised their God and issued a decree that no one should speak against the God of Shadrach, Meshach, and Abednego.",
      "date": "-0587"
    }
  ]
}

