      "text": "On December 10, 1948, the Universal Declaration of Human Rights was adopted by the United Nations General Assembly. Article 15 of the declaration states that everyone has the right to a nationality.",
      "date": "1948-12-10"
    },
    {
      "headline": "1954 Convention Relating to the Status of Stateless Persons",
      "text": "On September 28, 1954, the Convention Relating to the Status of Stateless Persons was adopted. It aims to ensure that stateless people enjoy a minimum set of human rights.",
      "date": "1954-09-28"
    },
    {
      "headline": "1961 Convention on the Reduction of Statelessness",
      "text": "On August 30, 1961, the Convention on the Reduction of Statelessness was adopted. It provides measures to prevent statelessness at birth and later in life.",
      "date": "1961-08-30"
    },
    {
      "headline": "UNHCR's Global Campaign to End Statelessness",
      "text": "In November 2014, the United Nations High Commissioner for Refugees (UNHCR) launched a global campaign to end statelessness within a decade.",
      "date": "2014-11"
    },
    {
      "headline": "Global Action Plan to End Statelessness",
      "text": "In 2014, the UNHCR published the Global Action Plan to End Statelessness, outlining 10 actions to resolve existing major situations of statelessness and prevent new cases from emerging.",
      "date": "2014"
    },
    {
      "headline": "High-Level Segment on Statelessness",
      "text": "In October 2019, the UNHCR held a High-Level Segment on Statelessness, where governments and other stakeholders made pledges to address statelessness.",
      "date": "2019-10"
    },
    {
      "headline": "UNHCR's 2022 Report on Statelessness",
      "text": "At the end of 2022, the United Nations High Commissioner for Refugees estimated 4.4 million people worldwide as either stateless or of undetermined nationality, 90,800 more than at the end of 2021.",
      "date": "2022"
    }
  ]
