    {
      "headline": "Introduction of 'A Diamond is Forever' Slogan",
      "text": "In 1947, De Beers introduced the iconic advertising slogan 'A Diamond is Forever', which became one of the most successful marketing campaigns in history.",
      "date": "1947"
    },
