    {
      "headline": "Development of Electronic ABS",
      "text": "In 1971, Chrysler, in collaboration with Bendix Corporation, introduced the first electronic ABS system, known as 'Sure Brake', for the Imperial.",
      "date": "1971"
    },
    {
      "headline": "Bosch's ABS System",
      "text": "In 1978, Bosch developed the first electronic four-wheel multi-channel ABS system, which was introduced on the Mercedes-Benz S-Class.",
      "date": "1978"
    },
    {
      "headline": "ABS Becomes Standard",
      "text": "By the late 1980s and early 1990s, ABS became a standard feature in many vehicles, particularly in Europe and North America.",
      "date": "1990"
    },
    {
      "headline": "Motorcycle ABS Introduction",
      "text": "In 1988, BMW introduced the first motorcycle with ABS, the BMW K100.",
      "date": "1988"
    },
    {
      "headline": "Mandatory ABS in EU",
      "text": "In 2004, the European Union mandated that all new passenger cars must be equipped with ABS.",
      "date": "2004"
    }
  ]
}

