{
  "timeline": [
    {
      "headline": "Camera Obscura Described",
      "text": "The camera obscura, a device that projects an image of its surroundings onto a screen, was described by Mozi in China and Aristotle in Greece as early as the 5th and 4th centuries BCE.",
      "date": "-0500"
    },
    {
      "headline": "First Photograph",
      "text": "In 1826 or 1827, Joseph Nicéphore Niépce created the first permanent photograph using a process called heliography. The photograph was titled 'View from the Window at Le Gras'.",
      "date": "1826"
    },
    {
      "headline": "Daguerreotype Process Announced",
      "text": "On January 7, 1839, Louis Daguerre announced the daguerreotype process, the first publicly available photographic process, which produced a single image on a silvered copper plate.",
      "date": "1839-01-07"
    },
    {
      "headline": "Calotype Process Patented",
      "text": "In 1841, William Henry Fox Talbot patented the calotype process, which allowed for multiple copies of a photograph to be made from a single negative.",
      "date": "1841"
    },
    {
      "headline": "Collodion Process Introduced",
      "text": "In 1851, Frederick Scott Archer introduced the collodion process, which significantly reduced exposure times and allowed for sharper images.",
      "date": "1851"
    },
    {
      "headline": "Invention of the Dry Plate Process",
      "text": "In 1871, Richard Leach Maddox invented the dry plate process, which used gelatin instead of collodion and allowed for the mass production of photographic plates.",
      "date": "1871"
    },
    {
      "headline": "Kodak Camera Released",
      "text": "In 1888, George Eastman released the Kodak camera, which was pre-loaded with enough film for 100 exposures, making photography accessible to the general public.",
      "date": "1888"
    },
    {
      "headline": "Introduction of Color Photography",
      "text": "In 1907, the Lumière brothers introduced the Autochrome Lumière, the first commercially successful color photography process.",
      "date": "1907"
    },
    {
      "headline": "Polaroid Instant Camera Invented",
      "text": "In 1948, Edwin Land introduced the first Polaroid instant camera, which could produce a finished photograph in about one minute.",
      "date": "1948"
    },
    {
      "headline": "Digital Photography Emerges",
      "text": "In 1975, Steven Sasson, an engineer at Eastman Kodak, created the first digital camera, marking the beginning of digital photography.",
      "date": "1975"
    }
  ]
}

