{
  "timeline": [
    {
      "headline": "First Amateur Radio Transmission",
      "text": "In 1901, Guglielmo Marconi successfully transmitted the first radio signal across the Atlantic Ocean, which inspired many amateur radio enthusiasts to experiment with radio technology.",
      "date": "1901"
    },
    {
      "headline": "Formation of the American Radio Relay League (ARRL)",
      "text": "The ARRL was founded in 1914 by Hiram Percy Maxim to promote the interests of amateur radio operators in the United States.",
      "date": "1914"
    },
    {
      "headline": "Amateur Radio Service Established",
      "text": "In 1912, the Radio Act of 1912 was passed in the United States, which required all amateur radio operators to be licensed and established the Amateur Radio Service.",
      "date": "1912"
    },
    {
      "headline": "International Amateur Radio Union (IARU) Founded",
      "text": "The IARU was founded in 1925 to promote and defend the interests of amateur radio operators worldwide.",
      "date": "1925"
    },
    {
      "headline": "Amateur Radio Banned During World War I",
      "text": "During World War I, amateur radio operations were banned in many countries, including the United States, to prevent enemy espionage.",
      "date": "1917"
    },
    {
      "headline": "Resumption of Amateur Radio Post-World War I",
      "text": "After World War I, amateur radio operations resumed in 1919, with many operators returning to the airwaves.",
      "date": "1919"
    },
    {
      "headline": "Amateur Radio and World War II",
      "text": "During World War II, amateur radio was again banned in many countries, but operators contributed to the war effort by serving as radio operators in the military.",
      "date": "1939"
    },
    {
      "headline": "Post-World War II Resurgence",
      "text": "After World War II, amateur radio experienced a resurgence, with many veterans continuing their interest in radio communications.",
      "date": "1945"
    },
    {
      "headline": "Introduction of Single Sideband (SSB)",
      "text": "In the 1950s, Single Sideband (SSB) became popular among amateur radio operators, offering more efficient use of the radio spectrum.",
      "date": "1950"
    },
    {
      "headline": "Launch of OSCAR 1",
      "text": "In 1961, the first amateur radio satellite, OSCAR 1, was launched, marking a significant milestone in amateur radio technology.",
      "date": "1961"
    },
    {
      "headline": "Digital Modes and the Internet",
      "text": "In the late 20th century, digital modes such as Packet Radio and the integration of the Internet expanded the capabilities and reach of amateur radio.",
      "date": "1980"
    }
  ]
}

