{
  "timeline": [
    {
      "headline": "Prediction by Satyendra Nath Bose and Albert Einstein",
      "text": "In the early 1920s, Satyendra Nath Bose and Albert Einstein predicted the existence of a new state of matter, now known as Bose–Einstein condensate (BEC). This prediction was based on Bose's work on quantum statistics and Einstein's extension of it to atoms.",
      "date": "1920"
    },
    {
      "headline": "Bose's Paper on Quantum Statistics",
      "text": "In 1924, Satyendra Nath Bose sent a paper to Albert Einstein describing a statistical model that led to the prediction of the Bose–Einstein condensate. Einstein translated the paper into German and submitted it for publication.",
      "date": "1924"
    },
    {
      "headline": "Einstein's Extension of Bose's Work",
      "text": "In 1925, Albert Einstein extended Bose's ideas to atoms, predicting that at very low temperatures, particles would occupy the same quantum state, forming a Bose–Einstein condensate.",
      "date": "1925"
    },
    {
      "headline": "First Experimental Observation of BEC",
      "text": "On June 5, 1995, Eric Cornell and Carl Wieman at the University of Colorado at Boulder successfully created the first Bose–Einstein condensate using rubidium atoms cooled to near absolute zero.",
      "date": "1995-06-05"
    },
    {
      "headline": "Nobel Prize in Physics",
      "text": "In 2001, Eric Cornell, Carl Wieman, and Wolfgang Ketterle were awarded the Nobel Prize in Physics for their achievements in the creation of Bose–Einstein condensates.",
      "date": "2001"
    }
  ]
}

