    {
      "headline": "Byzantine Era",
      "text": "In the 4th century CE, Nicosia became the seat of a bishopric and was fortified.",
      "date": "0400"
    },
    {
      "headline": "Capital of Cyprus",
      "text": "In 965 CE, Nicosia became the capital of Cyprus under Byzantine rule.",
      "date": "0965"
