    {
      "headline": "Lusignan Rule",
      "text": "In 1192, Nicosia came under the rule of the Lusignan dynasty, who made it their capital.",
      "date": "1192"
    },
    {
      "headline": "Venetian Rule",
      "text": "In 1489, Cyprus was sold to the Republic of Venice, and Nicosia became a Venetian city.",
      "date": "1489"
    },
    {
      "headline": "Ottoman Conquest",
      "text": "In 1570, Nicosia was conquered by the Ottoman Empire after a 40-day siege.",
      "date": "1570"
    },
    {
      "headline": "British Rule",
      "text": "In 1878, Cyprus, including Nicosia, was leased to the British Empire.",
      "date": "1878"
    },
    {
