      "headline": "Treaty of Ribe",
      "text": "In 1460, the Treaty of Ribe was signed, which stated that Schleswig and Holstein should remain 'forever undivided'.",
      "date": "1460"
    },
    {
      "headline": "First Schleswig War",
      "text": "The First Schleswig War took place from 1848 to 1851, a conflict between Denmark and the German Confederation over the status of Schleswig and Holstein.",
      "date": "1848"
    },
    {
      "headline": "Second Schleswig War",
      "text": "The Second Schleswig War occurred in 1864, resulting in the defeat of Denmark and the cession of Schleswig and Holstein to Prussia and Austria.",
      "date": "1864"
    },
    {
      "headline": "Austro-Prussian War and Annexation",
      "text": "In 1866, following the Austro-Prussian War, Prussia annexed Schleswig and Holstein.",
      "date": "1866"
    },
    {
      "headline": "Formation of the Province of Schleswig-Holstein",
      "text": "In 1867, the Province of Schleswig-Holstein was established as part of the Kingdom of Prussia.",
      "date": "1867"
    },
    {
      "headline": "Plebiscites and Division",
      "text": "In 1920, following World War I, plebiscites were held in Schleswig, resulting in the northern part joining Denmark and the southern part remaining in Germany.",
      "date": "1920"
    },
    {
      "headline": "Creation of the State of Schleswig-Holstein",
      "text": "In 1946, Schleswig-Holstein became a state of the Federal Republic of Germany.",
      "date": "1946"
    },
    {
      "headline": "Capital Moved to Kiel",
      "text": "In 1949, Kiel was designated as the capital of Schleswig-Holstein.",
      "date": "1949"
    }
  ]
}

