    {
      "headline": "Naming the Disorder",
      "text": "In 1828, Friedrich Hopff, a student at the University of Zurich, coined the term 'hemophilia' in his dissertation.",
      "date": "1828"
    },
    {
      "headline": "Royal Disease",
      "text": "Hemophilia became known as the 'Royal Disease' in the 19th century after it affected the descendants of Queen Victoria of England, who was a carrier of the disease.",
      "date": "1800s"
    },
    {
      "headline": "Discovery of Hemophilia A and B",
      "text": "In the 20th century, scientists discovered that hemophilia could be classified into two types: Hemophilia A, caused by a deficiency in clotting factor VIII, and Hemophilia B, caused by a deficiency in clotting factor IX.",
      "date": "1900s"
    },
    {
      "headline": "Development of Clotting Factor Concentrates",
      "text": "In the 1960s, the development of clotting factor concentrates revolutionized the treatment of hemophilia, allowing for home treatment and improved quality of life.",
      "date": "1960"
    },
    {
      "headline": "HIV/AIDS Crisis",
      "text": "In the late 1970s and early 1980s, many people with hemophilia became infected with HIV due to contaminated blood products, leading to a major health crisis.",
      "date": "1980"
    },
    {
      "headline": "Introduction of Recombinant Factor Products",
      "text": "In the 1990s, the introduction of recombinant factor products, which are not derived from human blood, significantly reduced the risk of viral infections.",
      "date": "1990"
    },
    {
      "headline": "Gene Therapy Advances",
      "text": "In the 21st century, advances in gene therapy have shown promise in providing long-term treatment for hemophilia, with several clinical trials underway.",
      "date": "2000s"
    }
  ]
}

