{
  "timeline": [
    {
      "headline": "Start of Protests",
      "text": "In March 2011, popular discontent with the rule of Bashar al-Assad triggered large-scale protests and pro-democracy rallies across Syria, as part of the wider Arab Spring protests in the region.",
      "date": "2011-03"
    },
    {
      "headline": "Formation of Rebel Groups",
      "text": "After months of crackdown by the government's security apparatus, various armed rebel groups such as the Free Syrian Army began forming across the country, marking the beginning of the Syrian insurgency in 2011.",
      "date": "2011"
    },
    {
      "headline": "Escalation to Civil War",
      "text": "By mid-2012, the insurgency had escalated into a full-blown civil war, with significant battles occurring in major cities such as Aleppo and Damascus.",
      "date": "2012"
    },
    {
      "headline": "Battle of Aleppo Begins",
      "text": "In July 2012, the Battle of Aleppo began, becoming one of the longest and most destructive battles of the Syrian Civil War.",
      "date": "2012-07"
    },
    {
      "headline": "Chemical Weapons Attack in Ghouta",
      "text": "On August 21, 2013, a chemical weapons attack occurred in the Ghouta area, leading to international condemnation and a U.S.-Russia brokered agreement to dismantle Syria's chemical weapons.",
      "date": "2013-08-21"
    },
    {
      "headline": "Rise of ISIS",
      "text": "In 2014, the Islamic State of Iraq and Syria (ISIS) gained control over large territories in Syria, declaring a caliphate and further complicating the conflict.",
      "date": "2014"
    },
    {
      "headline": "Russian Military Intervention",
      "text": "In September 2015, Russia began a military intervention in Syria, providing air support to the Assad government and altering the dynamics of the conflict.",
      "date": "2015-09"
    },
    {
      "headline": "Recapture of Aleppo",
      "text": "In December 2016, Syrian government forces recaptured the city of Aleppo from rebel groups, marking a significant turning point in the war.",
      "date": "2016-12"
    },
    {
      "headline": "U.S. Airstrikes on Shayrat Airbase",
      "text": "On April 7, 2017, the United States launched airstrikes on the Shayrat Airbase in response to a chemical attack in Khan Shaykhun.",
      "date": "2017-04-07"
    },
    {
      "headline": "Turkish Offensive in Afrin",
      "text": "In January 2018, Turkey launched a military offensive in the Afrin region against the Kurdish YPG militia, part of the Syrian Democratic Forces.",
      "date": "2018-01"
    },
    {
      "headline": "Fall of ISIS Caliphate",
      "text": "In March 2019, the Syrian Democratic Forces declared the territorial defeat of ISIS with the capture of the last stronghold in Baghouz.",
      "date": "2019-03"
    },
    {
      "headline": "Syrian Constitutional Committee",
      "text": "In October 2019, the Syrian Constitutional Committee was formed to draft a new constitution as part of a UN-led peace process.",
      "date": "2019-10"
    }
  ]
}

