{
  "timeline": [
    {
      "headline": "Birth of Guglielmo Marconi",
      "text": "Guglielmo Giovanni Maria Marconi was born on April 25, 1874, in Bologna, Italy.",
      "date": "1874-04-25"
    },
    {
      "headline": "First Wireless Transmission",
      "text": "In 1895, Marconi successfully transmitted wireless signals over a distance of about one and a half miles in Italy.",
      "date": "1895"
    },
    {
      "headline": "Patent for Wireless Telegraphy",
      "text": "On June 2, 1896, Marconi filed his first patent for a system of wireless telegraphy in England.",
      "date": "1896-06-02"
    },
    {
      "headline": "Establishment of Marconi's Wireless Telegraph Company",
      "text": "In 1897, Marconi founded the Wireless Telegraph & Signal Company in London, which later became known as Marconi's Wireless Telegraph Company.",
      "date": "1897"
    },
    {
      "headline": "First Transatlantic Wireless Communication",
      "text": "On December 12, 1901, Marconi successfully transmitted the first transatlantic wireless signal from Poldhu, Cornwall, to St. John's, Newfoundland.",
      "date": "1901-12-12"
    },
    {
      "headline": "Nobel Prize in Physics",
      "text": "In 1909, Guglielmo Marconi was awarded the Nobel Prize in Physics, shared with Karl Ferdinand Braun, for their contributions to the development of wireless telegraphy.",
      "date": "1909"
    },
    {
      "headline": "Marconi's Involvement in World War I",
      "text": "During World War I, Marconi served as a lieutenant in the Italian Army and later as a commander in the Italian Navy, contributing to military communications.",
      "date": "1914"
    },
    {
      "headline": "Marconi's Work on Microwave Transmission",
      "text": "In the 1930s, Marconi began experimenting with microwave transmission, laying groundwork for future developments in radar and microwave communication.",
      "date": "1930"
    },
    {
      "headline": "Death of Guglielmo Marconi",
      "text": "Guglielmo Marconi passed away on July 20, 1937, in Rome, Italy, at the age of 63.",
      "date": "1937-07-20"
    }
  ]
}

