{
  "timeline": [
    {
      "headline": "Initiation of the Quadrilateral Security Dialogue",
      "text": "In 2007, the Quadrilateral Security Dialogue, also known as the Quad, was initiated by Japanese Prime Minister Shinzo Abe. This grouping included Australia, India, Japan, and the United States, with the support of Australian Prime Minister John Howard, Indian Prime Minister Manmohan Singh, and U.S. Vice President Dick Cheney.",
      "date": "2007"
    },
    {
      "headline": "Exercise Malabar",
      "text": "In 2007, the Quad was paralleled by joint military exercises of an unprecedented scale, titled Exercise Malabar. These exercises were seen as a response to increased Chinese economic and military power.",
      "date": "2007"
    },
    {
      "headline": "Hiatus of the Quad",
      "text": "After its initial formation, the Quad went into a period of dormancy due to changes in political leadership and concerns about antagonizing China.",
      "date": "2008"
    },
    {
      "headline": "Revival of the Quad",
      "text": "In November 2017, the Quad was revived with a meeting of officials from the four member countries on the sidelines of the ASEAN and East Asia Summits in Manila.",
      "date": "2017-11"
    },
    {
      "headline": "First Ministerial Meeting",
      "text": "In September 2019, the first ministerial-level meeting of the Quad took place in New York City, marking a significant step in the formalization of the dialogue.",
      "date": "2019-09"
    },
    {
      "headline": "First Quad Leaders' Summit",
      "text": "On March 12, 2021, the first-ever Quad Leaders' Summit was held virtually, attended by the leaders of the four member countries.",
      "date": "2021-03-12"
    },
    {
      "headline": "In-Person Quad Leaders' Summit",
      "text": "On September 24, 2021, the first in-person Quad Leaders' Summit was held in Washington, D.C., hosted by U.S. President Joe Biden.",
      "date": "2021-09-24"
    }
  ]
}

