    {
      "headline": "Belsen Trial",
      "text": "Irma Grese was tried at the Belsen Trial, which began on September 17, 1945, for war crimes committed at Auschwitz and Bergen-Belsen.",
      "date": "1945-09-17"
    },
    {
      "headline": "Sentenced to Death",
      "text": "On November 17, 1945, Irma Grese was sentenced to death for her crimes during the Belsen Trial.",
      "date": "1945-11-17"
    },
    {
      "headline": "Execution",
      "text": "Irma Grese was executed by hanging on December 13, 1945, at Hamelin Prison in Germany.",
      "date": "1945-12-13"
    }
  ]
}

