    },
    {
      "headline": "Identification as the Most Luminous X-ray Cluster",
      "text": "The Phoenix Cluster is identified as the most luminous X-ray cluster discovered, producing more X-rays than any other known massive cluster.",
      "date": "2010"
    },
    {
      "headline": "Location and Distance",
      "text": "The Phoenix Cluster is located at a comoving distance of 8.61 billion light-years from Earth.",
      "date": "2010"
    },
