{
  "timeline": [
    {
      "headline": "First Recognized Cybercrime",
      "text": "In 1971, the first recognized cybercrime occurred when a hacker named John Draper, also known as 'Captain Crunch,' used a whistle from a cereal box to make free phone calls by mimicking the tones used by the phone system.",
      "date": "1971"
    },
    {
      "headline": "Creation of the First Computer Virus",
      "text": "In 1983, Fred Cohen, a graduate student at the University of Southern California, created the first computer virus as part of a research project. This virus was designed to demonstrate how a malicious program could spread.",
      "date": "1983"
    },
    {
      "headline": "Morris Worm Incident",
      "text": "On November 2, 1988, the Morris Worm, one of the first computer worms distributed via the Internet, was released by Robert Tappan Morris. It caused significant disruption and led to the first conviction under the Computer Fraud and Abuse Act.",
      "date": "1988-11-02"
    },
    {
      "headline": "Introduction of the Computer Fraud and Abuse Act",
      "text": "In 1986, the United States introduced the Computer Fraud and Abuse Act (CFAA), which was one of the first laws to address cybercrime and unauthorized access to computers.",
      "date": "1986"
    },
    {
      "headline": "Melissa Virus Outbreak",
      "text": "In March 1999, the Melissa virus, a mass-mailing macro virus, spread rapidly via email, causing widespread disruption and leading to the arrest of its creator, David L. Smith.",
      "date": "1999-03"
    },
    {
      "headline": "Establishment of the Convention on Cybercrime",
      "text": "In November 2001, the Council of Europe established the Convention on Cybercrime, the first international treaty seeking to address Internet and computer crime by harmonizing national laws and improving investigative techniques.",
      "date": "2001-11"
    },
    {
      "headline": "Operation Shady RAT Uncovered",
      "text": "In 2011, McAfee uncovered Operation Shady RAT, a series of cyber attacks that targeted over 70 global organizations, including governments and corporations, over a five-year period.",
      "date": "2011"
    },
    {
      "headline": "WannaCry Ransomware Attack",
      "text": "In May 2017, the WannaCry ransomware attack affected hundreds of thousands of computers worldwide, encrypting data and demanding ransom payments in Bitcoin.",
      "date": "2017-05"
    },
    {
      "headline": "Introduction of the General Data Protection Regulation (GDPR)",
      "text": "On May 25, 2018, the European Union implemented the General Data Protection Regulation (GDPR), which set strict guidelines for data protection and privacy, impacting how organizations handle personal data.",
      "date": "2018-05-25"
    },
    {
      "headline": "SolarWinds Cyberattack",
      "text": "In December 2020, the SolarWinds cyberattack was discovered, where hackers compromised the software supply chain of SolarWinds, affecting numerous government agencies and private companies.",
      "date": "2020-12"
    }
  ]
}

