      "headline": "Independence of Angola",
      "text": "Angola gained independence from Portugal on November 11, 1975. This marked the beginning of the Angolan Civil War as former anti-colonial guerrilla movements, MPLA and UNITA, vied for power.",
      "date": "1975-11-11"
    },
    {
      "headline": "Battle of Quifangondo",
      "text": "On November 10, 1975, the Battle of Quifangondo took place, where MPLA forces, with Cuban support, defeated FNLA forces, solidifying MPLA's control over Luanda.",
      "date": "1975-11-10"
    },
    {
      "headline": "Cuban Military Intervention",
      "text": "In late 1975, Cuba began sending troops to support the MPLA, significantly impacting the course of the war by providing crucial military assistance.",
      "date": "1975"
    },
    {
      "headline": "South African Intervention",
      "text": "In 1975, South Africa intervened in the Angolan Civil War, supporting UNITA and FNLA against the MPLA.",
      "date": "1975"
    },
    {
      "headline": "Bicesse Accords",
      "text": "On May 31, 1991, the Bicesse Accords were signed between MPLA and UNITA, aiming to establish peace and a multi-party democracy in Angola.",
      "date": "1991-05-31"
    },
    {
      "headline": "Resumption of Civil War",
      "text": "Despite the Bicesse Accords, civil war resumed in Angola in 1992 following disputed elections.",
      "date": "1992"
    },
    {
      "headline": "Lusaka Protocol",
      "text": "On November 20, 1994, the Lusaka Protocol was signed, attempting to end hostilities and integrate UNITA into the Angolan government.",
      "date": "1994-11-20"
    },
    {
      "headline": "Death of Jonas Savimbi",
      "text": "On February 22, 2002, Jonas Savimbi, leader of UNITA, was killed by Angolan government forces, leading to the end of major hostilities.",
      "date": "2002-02-22"
    },
    {
      "headline": "End of the Angolan Civil War",
      "text": "The Angolan Civil War officially ended on April 4, 2002, with the signing of a peace agreement between the MPLA government and UNITA.",
      "date": "2002-04-04"
    }
  ]
}

