    {
      "headline": "Annulment of Marriage",
      "text": "Ruskin's marriage to Effie Gray was annulled in 1854 due to non-consummation.",
      "date": "1854"
    },
    {
      "headline": "Publication of 'The Stones of Venice'",
      "text": "Between 1851 and 1853, Ruskin published 'The Stones of Venice', a three-volume treatise on Venetian art and architecture.",
      "date": "1851"
    },
    {
      "headline": "Lectures on Architecture and Painting",
      "text": "In 1853, Ruskin delivered a series of lectures on architecture and painting, which were later published.",
      "date": "1853"
    },
    {
      "headline": "Publication of 'Unto This Last'",
      "text": "In 1860, Ruskin published 'Unto This Last', a series of essays on political economy that criticized the industrial capitalist system.",
      "date": "1860"
    },
    {
      "headline": "Slade Professor of Fine Art at Oxford",
      "text": "Ruskin was appointed the first Slade Professor of Fine Art at Oxford University in 1869.",
      "date": "1869"
    },
    {
      "headline": "Founding of the Guild of St George",
      "text": "In 1871, Ruskin founded the Guild of St George, an organization aimed at promoting social reform and the arts.",
      "date": "1871"
    },
    {
      "headline": "Publication of 'Fors Clavigera'",
      "text": "Ruskin began publishing 'Fors Clavigera', a series of letters to the working men of England, in 1871.",
      "date": "1871"
    },
    {
      "headline": "Resignation from Oxford",
      "text": "Ruskin resigned from his position as Slade Professor of Fine Art at Oxford in 1879 due to health issues.",
      "date": "1879"
    },
