  ]
}

{
  "timeline": [
    {
      "headline": "Thomas More's 'Utopia' Published",
      "text": "In 1516, Thomas More published 'Utopia', a book that introduced the idea of a society where everyone receives a basic income, laying early conceptual groundwork for UBI.",
      "date": "1516"
    },
    {
      "headline": "Thomas Paine Proposes Basic Income",
      "text": "In 1797, Thomas Paine proposed a basic income in his pamphlet 'Agrarian Justice', suggesting payments to all citizens funded by a tax on landowners.",
      "date": "1797"
    },
    {
      "headline": "Bertrand Russell Advocates for Basic Income",
      "text": "In 1918, philosopher Bertrand Russell advocated for a basic income in his book 'Roads to Freedom', arguing for economic security for all.",
      "date": "1918"
    },
    {
      "headline": "Milton Friedman's Negative Income Tax",
      "text": "In the 1960s, economist Milton Friedman proposed a negative income tax, a concept related to UBI, where people earning below a certain amount receive supplemental pay from the government.",
      "date": "1960"
    },
    {
      "headline": "Alaska Permanent Fund Established",
      "text": "In 1982, Alaska established the Alaska Permanent Fund, which provides annual dividends to residents, a form of partial UBI.",
      "date": "1982"
    },
    {
      "headline": "Mongolia Implements Partial UBI",
      "text": "In 2010, Mongolia implemented a partial UBI funded by mining revenues, providing regular payments to its citizens.",
      "date": "2010"
    },
    {
      "headline": "Iran Implements Cash Transfer Program",
      "text": "In 2011, Iran replaced subsidies with a cash transfer program, effectively creating a partial UBI for its citizens.",
      "date": "2011"
    },
    {
      "headline": "Finland's Basic Income Experiment",
      "text": "From 2017 to 2018, Finland conducted a basic income experiment, providing 2,000 unemployed citizens with a monthly income to study its effects.",
      "date": "2017"
    },
    {
      "headline": "Spain's Minimum Vital Income",
      "text": "In 2020, Spain introduced the Minimum Vital Income, a form of guaranteed minimum income aimed at reducing poverty, influenced by UBI concepts.",
      "date": "2020"
    }
  ]
}

