    {
      "headline": "Early Concept of Astronomical Unit",
      "text": "The concept of the astronomical unit (AU) as the average distance from the Earth to the Sun has been used since ancient times, although not precisely defined.",
      "date": "-0001"
    },
    {
      "headline": "First Measurement Attempts",
      "text": "In the 17th century, astronomers like Giovanni Cassini and Jean Richer attempted to measure the astronomical unit using observations of Mars and the method of parallax.",
      "date": "1672"
    },
    {
      "headline": "Improved Measurements",
      "text": "In the 18th and 19th centuries, the transit of Venus was used to improve measurements of the astronomical unit, notably by astronomers like Jeremiah Horrocks and James Cook.",
      "date": "1761"
    },
    {
      "headline": "Modern Definition",
      "text": "In 1976, the International Astronomical Union (IAU) defined the astronomical unit as the distance from the Earth to the Sun at which a particle of negligible mass, in an unperturbed orbit, would have an orbital period of one Gaussian year.",
      "date": "1976"
    },
    {
      "headline": "Redefinition of the Astronomical Unit",
      "text": "On August 31, 2012, the International Astronomical Union redefined the astronomical unit as exactly 149,597,870,700 meters.",
      "date": "2012-08-31"
    }
  ]
}

