{
  "timeline": [
    {
      "headline": "Establishment of the Xia Dynasty",
      "text": "According to traditional Chinese historiography, the Xia Dynasty was established by Yu the Great after Shun, the last of the Five Emperors, gave the throne to him. This event is traditionally dated to around 2070 BCE.",
      "date": "-2070"
    },
    {
      "headline": "Reign of Yu the Great",
      "text": "Yu the Great is credited with founding the Xia Dynasty and is known for his flood control efforts. His reign is traditionally dated from 2070 BCE to 2061 BCE.",
      "date": "-2070"
    },
    {
      "headline": "Reign of Qi of Xia",
      "text": "Qi of Xia, the son of Yu the Great, succeeded his father and became the second ruler of the Xia Dynasty. His reign is traditionally dated from 2061 BCE to 2037 BCE.",
      "date": "-2061"
    },
    {
      "headline": "Reign of Taikang",
      "text": "Taikang, the son of Qi, became the third ruler of the Xia Dynasty. His reign is traditionally dated from 2037 BCE to 2029 BCE.",
      "date": "-2037"
    },
    {
      "headline": "Reign of Zhongkang",
      "text": "Zhongkang, the brother of Taikang, succeeded him and became the fourth ruler of the Xia Dynasty. His reign is traditionally dated from 2029 BCE to 1987 BCE.",
      "date": "-2029"
    },
    {
      "headline": "Reign of Xiang of Xia",
      "text": "Xiang of Xia, the son of Zhongkang, became the fifth ruler of the Xia Dynasty. His reign is traditionally dated from 1987 BCE to 1975 BCE.",
      "date": "-1987"
    },
    {
      "headline": "Reign of Shaokang",
      "text": "Shaokang, the son of Xiang, restored the Xia Dynasty after a period of decline. His reign is traditionally dated from 1975 BCE to 1966 BCE.",
      "date": "-1975"
    },
    {
      "headline": "Reign of Zhu of Xia",
      "text": "Zhu of Xia, the son of Shaokang, became the seventh ruler of the Xia Dynasty. His reign is traditionally dated from 1966 BCE to 1921 BCE.",
      "date": "-1966"
    },
    {
      "headline": "Reign of Huai of Xia",
      "text": "Huai of Xia, the son of Zhu, became the eighth ruler of the Xia Dynasty. His reign is traditionally dated from 1921 BCE to 1908 BCE.",
      "date": "-1921"
    },
    {
      "headline": "Reign of Mang of Xia",
      "text": "Mang of Xia, the son of Huai, became the ninth ruler of the Xia Dynasty. His reign is traditionally dated from 1908 BCE to 1879 BCE.",
      "date": "-1908"
    },
    {
      "headline": "Reign of Xie of Xia",
      "text": "Xie of Xia, the son of Mang, became the tenth ruler of the Xia Dynasty. His reign is traditionally dated from 1879 BCE to 1845 BCE.",
      "date": "-1879"
    },
    {
      "headline": "Reign of Bu Jiang",
      "text": "Bu Jiang, the son of Xie, became the eleventh ruler of the Xia Dynasty. His reign is traditionally dated from 1845 BCE to 1837 BCE.",
      "date": "-1845"
    },
    {
      "headline": "Reign of Jiong of Xia",
      "text": "Jiong of Xia, the son of Bu Jiang, became the twelfth ruler of the Xia Dynasty. His reign is traditionally dated from 1837 BCE to 1810 BCE.",
      "date": "-1837"
    },
    {
      "headline": "Reign of Jin of Xia",
      "text": "Jin of Xia, the son of Jiong, became the thirteenth ruler of the Xia Dynasty. His reign is traditionally dated from 1810 BCE to 1789 BCE.",
      "date": "-1810"
    },
    {
      "headline": "Reign of Kong Jia",
      "text": "Kong Jia, the son of Jin, became the fourteenth ruler of the Xia Dynasty. His reign is traditionally dated from 1789 BCE to 1758 BCE.",
      "date": "-1789"
    },
    {
      "headline": "Reign of Gao of Xia",
      "text": "Gao of Xia, the son of Kong Jia, became the fifteenth ruler of the Xia Dynasty. His reign is traditionally dated from 1758 BCE to 1747 BCE.",
      "date": "-1758"
    },
    {
      "headline": "Reign of Fa of Xia",
      "text": "Fa of Xia, the son of Gao, became the sixteenth ruler of the Xia Dynasty. His reign is traditionally dated from 1747 BCE to 1728 BCE.",
      "date": "-1747"
    },
    {
      "headline": "Reign of Jie of Xia",
      "text": "Jie of Xia, the son of Fa, became the seventeenth and last ruler of the Xia Dynasty. His reign is traditionally dated from 1728 BCE to 1675 BCE. He was known for his tyrannical rule, which led to the fall of the Xia Dynasty.",
      "date": "-1728"
    },
    {
      "headline": "Fall of the Xia Dynasty",
      "text": "The Xia Dynasty was overthrown by the Shang Dynasty, traditionally dated to around 1675 BCE, marking the end of the Xia Dynasty.",
      "date": "-1675"
    }
  ]
}

