    {
      "headline": "Historical Observation",
      "text": "A similar spot was observed from 1665 to 1713. If this was the same storm, it would suggest the Great Red Spot has existed for at least 359 years. However, a study from 2024 suggests this is not the case.",
      "date": "1665"
    },
    {
      "headline": "Study Challenges Historical Continuity",
      "text": "A study conducted in 2024 suggests that the Great Red Spot observed from 1665 to 1713 is not the same storm as the one observed from 1831 onwards.",
      "date": "2024"
    }
  ]
}

