      "headline": "Cornish as Main Language of Cornwall",
      "text": "For centuries, Cornish was the main language of Cornwall, maintaining close links with its sister language Breton.",
      "date": "1200"
    },
    {
      "headline": "Decline of Cornish Language",
      "text": "Cornish was gradually pushed westwards by English and began to decline as a community language.",
      "date": "1600"
    },
    {
      "headline": "Cornish Language as a Vernacular",
      "text": "Cornish continued to function as a common community language in parts of Cornwall until the mid 18th century.",
      "date": "1750"
    },
    {
      "headline": "Traditional Speakers in the 19th Century",
      "text": "There is some evidence for traditional speakers of the Cornish language persisting into the 19th century.",
      "date": "1800"
    },
    {
      "headline": "Revival Efforts Begin",
      "text": "Efforts to revive the Cornish language began in the early 20th century.",
      "date": "1904"
    },
    {
      "headline": "Recognition as a Minority Language",
      "text": "In 2002, Cornish was recognized as a minority language under the European Charter for Regional or Minority Languages.",
      "date": "2002"
    },
    {
      "headline": "Cornish Language Strategy",
      "text": "In 2015, the UK government announced a Cornish Language Strategy to support the language's development.",
      "date": "2015"
    }
  ]
}

