{
  "timeline": [
    {
      "headline": "Founding of Yangon",
      "text": "Yangon was founded as Dagon in the early 11th century (circa 1028-1043) by the Mon people, who inhabited Lower Burma.",
      "date": "1028"
    },
    {
      "headline": "Renaming to Yangon",
      "text": "In 1755, King Alaungpaya conquered Dagon, renamed it 'Yangon', which means 'End of Strife', and expanded the settlement.",
      "date": "1755"
    },
    {
      "headline": "British Occupation",
      "text": "Yangon was captured by the British during the First Anglo-Burmese War in 1824, but was returned to Burmese control after the war.",
      "date": "1824"
    },
    {
      "headline": "Second Anglo-Burmese War",
      "text": "In 1852, during the Second Anglo-Burmese War, the British captured Yangon again and transformed it into the commercial and political hub of British Burma.",
      "date": "1852"
    },
    {
      "headline": "Yangon as Capital of British Burma",
      "text": "Yangon became the capital of British Burma in 1885 after the annexation of Upper Burma.",
      "date": "1885"
    },
    {
      "headline": "World War II Occupation",
      "text": "Yangon was occupied by Japanese forces from 1942 to 1945 during World War II.",
      "date": "1942"
    },
    {
      "headline": "Independence of Burma",
      "text": "On January 4, 1948, Burma gained independence from British rule, and Yangon became the capital of the newly independent country.",
      "date": "1948-01-04"
    },
    {
      "headline": "Renaming to Yangon",
      "text": "In 1989, the military government officially changed the English name of the city from Rangoon to Yangon.",
      "date": "1989"
    },
    {
      "headline": "Relocation of Capital",
      "text": "In November 2005, the military government began relocating the capital to Naypyidaw, officially designating it as the capital in 2006.",
      "date": "2006"
    }
  ]
}

