    {
      "headline": "Enrollment at Little Rock Central High School",
      "text": "In 1957, the Little Rock Nine, a group of nine African American students, enrolled at Little Rock Central High School in Little Rock, Arkansas. This marked a significant event in the American Civil Rights Movement as it challenged racial segregation in public schools.",
      "date": "1957"
    },
    {
      "headline": "Little Rock Crisis Begins",
      "text": "On September 4, 1957, the Little Rock Nine were initially prevented from entering Little Rock Central High School by the Arkansas National Guard, under the orders of Governor Orval Faubus. This event marked the beginning of the Little Rock Crisis.",
      "date": "1957-09-04"
    },
    {
      "headline": "Intervention by President Eisenhower",
      "text": "On September 24, 1957, President Dwight D. Eisenhower intervened by sending federal troops from the 101st Airborne Division to escort and protect the Little Rock Nine, ensuring their safe entry into the school.",
      "date": "1957-09-24"
    },
    {
      "headline": "Successful Entry into School",
      "text": "On September 25, 1957, under the protection of federal troops, the Little Rock Nine successfully entered Little Rock Central High School, marking a pivotal moment in the desegregation of public schools in the United States.",
      "date": "1957-09-25"
    },
    {
      "headline": "Completion of the School Year",
      "text": "Despite facing significant challenges and hostility, the Little Rock Nine completed the 1957-1958 school year at Little Rock Central High School, demonstrating resilience and courage in the face of adversity.",
      "date": "1958"
    }
  ]
}

