{
  "timeline": [
    {
      "headline": "Ancient Tourism",
      "text": "Tourism can be traced back to ancient civilizations such as Egypt, Greece, and Rome, where people traveled for religious festivals, trade, and leisure. Notable sites included the Pyramids of Giza and the Oracle of Delphi.",
      "date": "-0300"
    },
    {
      "headline": "Medieval Pilgrimages",
      "text": "During the Middle Ages, religious pilgrimages became a significant form of tourism, with destinations like Jerusalem, Rome, and Santiago de Compostela attracting travelers.",
      "date": "1000"
    },
    {
      "headline": "The Grand Tour",
      "text": "In the 17th and 18th centuries, the Grand Tour became popular among young European aristocrats, who traveled across Europe to experience art, culture, and history, particularly in Italy and France.",
      "date": "1600"
    },
    {
      "headline": "The Rise of Modern Tourism",
      "text": "The Industrial Revolution in the 19th century led to the development of railways and steamships, making travel more accessible and affordable. Thomas Cook organized the first package tour in 1841.",
      "date": "1841"
    },
    {
      "headline": "Post-War Tourism Boom",
      "text": "After World War II, the rise of commercial aviation and increased disposable income led to a boom in international tourism. The 1950s and 1960s saw the growth of mass tourism.",
      "date": "1950"
    },
    {
      "headline": "The Establishment of the UNWTO",
      "text": "The United Nations World Tourism Organization (UNWTO) was established in 1975 to promote responsible, sustainable, and universally accessible tourism.",
      "date": "1975"
    },
    {
      "headline": "Digital Revolution in Tourism",
      "text": "The late 20th and early 21st centuries saw the rise of the internet and digital platforms, transforming how people plan and book travel, with companies like Expedia and Airbnb emerging.",
      "date": "1995"
    },
    {
      "headline": "Impact of COVID-19 on Tourism",
      "text": "The COVID-19 pandemic in 2020 led to unprecedented global travel restrictions, severely impacting the tourism industry and prompting a shift towards domestic travel and virtual tourism experiences.",
      "date": "2020"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of the Women's Social and Political Union (WSPU)",
      "text": "In 1903, Emmeline Pankhurst founded the Women's Social and Political Union (WSPU) in the United Kingdom. This organization was dedicated to securing women's right to vote through direct action and civil disobedience.",
      "date": "1903"
    },
    {
      "headline": "Coining of the Term 'Suffragette'",
      "text": "In 1906, a reporter writing in the Daily Mail coined the term 'suffragette' to describe members of the WSPU. The term was initially intended to belittle the women advocating for women's suffrage, but the militants embraced it, even adopting it for use as the title of the newspaper published by the WSPU.",
      "date": "1906"
    },
    {
      "headline": "Militant Actions Intensify",
      "text": "From 1908 onwards, suffragettes intensified their militant actions, including hunger strikes, chaining themselves to railings, and breaking windows to draw attention to their cause.",
      "date": "1908"
    },
    {
      "headline": "Cat and Mouse Act",
      "text": "In 1913, the British government passed the Prisoners (Temporary Discharge for Ill Health) Act, commonly known as the Cat and Mouse Act. This allowed the temporary release of suffragettes on hunger strike, only to re-arrest them once they had recovered.",
      "date": "1913"
    },
    {
      "headline": "Emily Davison's Protest",
      "text": "On June 4, 1913, suffragette Emily Davison stepped in front of King George V's horse at the Epsom Derby as a protest for women's suffrage. She died four days later from her injuries.",
      "date": "1913-06-04"
    },
    {
      "headline": "World War I and the Suspension of Suffragette Activities",
      "text": "In 1914, with the outbreak of World War I, Emmeline Pankhurst and the WSPU suspended their militant activities to support the war effort.",
      "date": "1914"
    },
    {
      "headline": "Representation of the People Act 1918",
      "text": "On February 6, 1918, the Representation of the People Act was passed in the UK, granting voting rights to women over the age of 30 who met certain property qualifications.",
      "date": "1918-02-06"
    },
    {
      "headline": "Equal Franchise Act 1928",
      "text": "On July 2, 1928, the Equal Franchise Act was passed, granting equal voting rights to women and men over the age of 21 in the UK.",
      "date": "1928-07-02"
    }
  ]
}

