    },
    {
      "headline": "Marriage to Richard Pankhurst",
      "text": "In 1879, Emmeline Goulden married Richard Pankhurst, a lawyer known for supporting women's suffrage and other radical causes.",
      "date": "1879"
    },
    {
      "headline": "Founding of the Women's Franchise League",
      "text": "In 1889, Emmeline Pankhurst co-founded the Women's Franchise League, which advocated for the right of married women to vote in local elections.",
      "date": "1889"
    },
    {
      "headline": "Death of Richard Pankhurst",
      "text": "Richard Pankhurst died suddenly in 1898, leaving Emmeline to care for their children and continue their shared political work.",
      "date": "1898"
    },
    {
      "headline": "Founding of the Women's Social and Political Union (WSPU)",
      "text": "In 1903, Emmeline Pankhurst founded the Women's Social and Political Union (WSPU), a militant organization dedicated to achieving women's suffrage.",
      "date": "1903"
    },
    {
      "headline": "First Imprisonment",
      "text": "Emmeline Pankhurst was first imprisoned in 1908 for her involvement in suffragette protests.",
      "date": "1908"
    },
    {
      "headline": "Cat and Mouse Act",
      "text": "In 1913, the British government passed the 'Cat and Mouse Act', allowing the temporary release of suffragettes on hunger strike, only to re-arrest them once they recovered. Emmeline Pankhurst was frequently affected by this act.",
      "date": "1913"
    },
    {
      "headline": "World War I and Suspension of Suffrage Activities",
      "text": "In 1914, with the outbreak of World War I, Emmeline Pankhurst suspended WSPU's militant suffrage activities to support the war effort.",
      "date": "1914"
    },
    {
      "headline": "Women Gain Partial Suffrage",
      "text": "In 1918, the Representation of the People Act was passed, granting voting rights to women over the age of 30 who met minimum property requirements.",
      "date": "1918"
    },
    {
      "headline": "Formation of the Women's Party",
      "text": "In 1917, Emmeline Pankhurst founded the Women's Party, focusing on promoting women's rights and equality.",
      "date": "1917"
    },
    {
      "headline": "Death of Emmeline Pankhurst",
      "text": "Emmeline Pankhurst died on June 14, 1928, in Hampstead, London, shortly before women were granted equal voting rights with men.",
      "date": "1928-06-14"
    }
  ]
}

