    {
      "headline": "Albert Einstein's General Theory of Relativity",
      "text": "In 1915, Albert Einstein published his General Theory of Relativity, which provided a new understanding of gravity and laid the groundwork for modern cosmology.",
      "date": "1915"
    },
    {
      "headline": "Friedmann's Expanding Universe Models",
      "text": "In 1922, Alexander Friedmann derived solutions to Einstein's field equations that suggested the universe could be expanding, contrary to the then-prevailing static universe model.",
      "date": "1922"
    },
    {
      "headline": "Hubble's Law of Cosmic Expansion",
      "text": "In 1929, Edwin Hubble published his observations showing that galaxies are moving away from us, leading to the formulation of Hubble's Law, which states that the velocity of a galaxy is proportional to its distance from us.",
      "date": "1929"
