{
  "timeline": [
    {
      "headline": "Birth of Gregor Mendel",
      "text": "Gregor Mendel, known as the father of modern genetics, was born on July 20, 1822, in Heinzendorf bei Odrau, Austrian Empire (now Hynčice, Czech Republic).",
      "date": "1822-07-20"
    },
    {
      "headline": "Mendel's Experiments with Pea Plants",
      "text": "Between 1856 and 1863, Gregor Mendel conducted experiments on pea plants in the garden of his monastery in Brno. He studied the inheritance of traits such as color and shape, leading to the formulation of the laws of inheritance.",
      "date": "1856"
    },
    {
      "headline": "Publication of Mendel's Laws",
      "text": "In 1866, Gregor Mendel published his findings on the inheritance of traits in the paper 'Experiments on Plant Hybridization', establishing the laws of inheritance that would later become known as Mendel's Laws.",
      "date": "1866"
    },
    {
      "headline": "Rediscovery of Mendel's Work",
      "text": "In 1900, Mendel's work was independently rediscovered by Hugo de Vries, Carl Correns, and Erich von Tschermak, leading to the recognition of Mendel's contributions to genetics.",
      "date": "1900"
    },
    {
      "headline": "Chromosome Theory of Inheritance",
      "text": "In 1902, Walter Sutton and Theodor Boveri proposed the Chromosome Theory of Inheritance, which identified chromosomes as the carriers of genetic material.",
      "date": "1902"
    },
    {
      "headline": "Discovery of DNA Structure",
      "text": "In 1953, James Watson and Francis Crick, with contributions from Rosalind Franklin and Maurice Wilkins, discovered the double helix structure of DNA, revolutionizing the field of genetics.",
      "date": "1953"
    },
    {
      "headline": "Human Genome Project",
      "text": "Launched in 1990 and completed in 2003, the Human Genome Project was an international scientific research project aimed at mapping and understanding all the genes of the human species.",
      "date": "1990"
    },
    {
      "headline": "Completion of the Human Genome Project",
      "text": "In 2003, the Human Genome Project was completed, providing a comprehensive map of the human genome and marking a significant milestone in genetics research.",
      "date": "2003"
    }
  ]
}

{
  "timeline": [
