{
  "timeline": [
    {
      "headline": "Grito de Dolores",
      "text": "On September 16, 1810, Miguel Hidalgo y Costilla, a Catholic priest, issued the Grito de Dolores, calling for the end of Spanish rule in Mexico. This event marked the beginning of the Mexican War of Independence.",
      "date": "1810-09-16"
    },
    {
      "headline": "Battle of Monte de las Cruces",
      "text": "On October 30, 1810, the insurgent forces led by Miguel Hidalgo defeated the Spanish colonial forces at the Battle of Monte de las Cruces.",
      "date": "1810-10-30"
    },
    {
      "headline": "Capture and Execution of Miguel Hidalgo",
      "text": "Miguel Hidalgo was captured on March 21, 1811, and executed by firing squad on July 30, 1811, marking a significant setback for the independence movement.",
      "date": "1811-07-30"
    },
    {
      "headline": "Morelos Takes Command",
      "text": "After Hidalgo's execution, José María Morelos took command of the insurgent forces and continued the fight for independence.",
      "date": "1811"
    },
    {
      "headline": "Siege of Cuautla",
      "text": "From February 19 to May 2, 1812, José María Morelos led the Siege of Cuautla, successfully resisting the Spanish royalist forces.",
      "date": "1812-02-19"
    },
    {
      "headline": "Congress of Chilpancingo",
      "text": "On September 13, 1813, the Congress of Chilpancingo was convened by Morelos, where the independence of Mexico was formally declared.",
      "date": "1813-09-13"
    },
    {
      "headline": "Capture and Execution of Morelos",
      "text": "José María Morelos was captured on November 5, 1815, and executed on December 22, 1815, dealing another blow to the independence movement.",
      "date": "1815-12-22"
    },
    {
      "headline": "Plan of Iguala",
      "text": "On February 24, 1821, Agustín de Iturbide and Vicente Guerrero proclaimed the Plan of Iguala, which called for Mexican independence, constitutional monarchy, and equal rights for Spaniards and Creoles.",
      "date": "1821-02-24"
    },
    {
      "headline": "Treaty of Córdoba",
      "text": "On August 24, 1821, the Treaty of Córdoba was signed, recognizing Mexican independence from Spain.",
      "date": "1821-08-24"
    },
    {
      "headline": "Declaration of Independence of the Mexican Empire",
      "text": "On September 28, 1821, the Declaration of Independence of the Mexican Empire was drafted in Mexico City, marking the official end of Spanish rule.",
      "date": "1821-09-28"
    }
  ]
}

