    },
    {
      "headline": "Baptism of Arthur",
      "text": "Arthur was baptized at Winchester Cathedral on 24 September 1486.",
      "date": "1486-09-24"
    },
    {
      "headline": "Created Duke of Cornwall",
      "text": "Arthur was created Duke of Cornwall at birth in 1486, a title traditionally held by the heir apparent to the English throne.",
      "date": "1486"
    },
    {
      "headline": "Created Prince of Wales and Earl of Chester",
      "text": "On 29 November 1489, Arthur was formally created Prince of Wales and Earl of Chester, further solidifying his status as the heir apparent.",
