{
  "timeline": [
    {
      "headline": "Discovery of Polyethylene",
      "text": "Polyethylene was first synthesized by the German chemist Hans von Pechmann, who prepared it by accident in 1898 while heating diazomethane.",
      "date": "1898"
    },
    {
      "headline": "Industrial Production Begins",
      "text": "The first industrially practical polyethylene synthesis was discovered by Eric Fawcett and Reginald Gibson at the ICI works in Northwich, England. The first synthesis was carried out on March 27, 1933.",
      "date": "1933-03-27"
    },
    {
      "headline": "Commercial Production",
      "text": "Commercial production of polyethylene began in 1939 by Imperial Chemical Industries (ICI) in the United Kingdom.",
      "date": "1939"
    },
    {
      "headline": "High-Density Polyethylene (HDPE) Developed",
      "text": "In 1953, Karl Ziegler of the Kaiser Wilhelm Institute (now the Max Planck Institute) developed a new catalyst that allowed for the production of high-density polyethylene (HDPE).",
      "date": "1953"
    },
    {
      "headline": "Ziegler-Natta Catalyst",
      "text": "In 1963, Karl Ziegler and Giulio Natta were awarded the Nobel Prize in Chemistry for their work on the Ziegler-Natta catalyst, which revolutionized the production of polyethylene.",
      "date": "1963"
    },
    {
      "headline": "Global Production Milestone",
      "text": "By 2017, over 100 million tonnes of polyethylene resins were being produced annually, accounting for 34% of the total plastics market.",
      "date": "2017"
    }
  ]
}

