{
  "timeline": [
    {
      "headline": "Introduction of the Voting Rights Act",
      "text": "The Voting Rights Act of 1965 was introduced in Congress as a response to the widespread racial discrimination in voting, particularly in the Southern United States.",
      "date": "1965"
    },
    {
      "headline": "Signing of the Voting Rights Act",
      "text": "On August 6, 1965, President Lyndon B. Johnson signed the Voting Rights Act into law. This landmark legislation aimed to overcome legal barriers at the state and local levels that prevented African Americans from exercising their right to vote under the 15th Amendment.",
      "date": "1965-08-06"
    },
    {
      "headline": "First Amendment to the Act",
      "text": "In 1970, Congress amended the Voting Rights Act to prohibit literacy tests and to reduce the residency requirements for voting in presidential elections.",
      "date": "1970"
    },
    {
      "headline": "Second Amendment to the Act",
      "text": "In 1975, the Act was amended to protect the voting rights of 'language minority groups' by prohibiting voting discrimination and requiring certain jurisdictions to provide bilingual voting materials.",
      "date": "1975"
    },
    {
      "headline": "Third Amendment to the Act",
      "text": "The 1982 amendment extended the special provisions of the Act, including the preclearance requirement, for 25 years.",
      "date": "1982"
    },
    {
      "headline": "Fourth Amendment to the Act",
      "text": "In 1992, the Act was amended to provide additional protections for voters with disabilities and to improve access to voting for all Americans.",
      "date": "1992"
    },
    {
      "headline": "Fifth Amendment to the Act",
      "text": "In 2006, Congress reauthorized the Voting Rights Act for another 25 years, reaffirming its commitment to protecting the voting rights of all Americans.",
      "date": "2006"
    }
  ]
}

