{
  "timeline": [
    {
      "headline": "Establishment of the Congo Free State",
      "text": "In 1885, the Congo Free State was established under the personal rule of King Leopold II of Belgium. This marked the beginning of a period characterized by severe exploitation and atrocities committed against the Congolese population.",
      "date": "1885"
    },
    {
      "headline": "Introduction of Forced Labor Policies",
      "text": "In the late 19th century, King Leopold II implemented forced labor policies to extract natural rubber from the Congo Free State. These policies were enforced by colonial administrators and led to widespread abuse and exploitation of the local population.",
      "date": "1890"
    },
    {
      "headline": "Reports of Atrocities Emerge",
      "text": "By the late 1890s, reports of atrocities, including mutilations and killings, began to emerge from the Congo Free State. These reports were brought to international attention by missionaries and other observers.",
      "date": "1890"
    },
    {
      "headline": "International Outcry and Investigations",
      "text": "In the early 1900s, international outcry over the atrocities in the Congo Free State grew. Investigations and reports by figures such as E.D. Morel and Roger Casement highlighted the severe human rights abuses occurring under Leopold's rule.",
      "date": "1900"
    },
    {
      "headline": "Casement Report Published",
      "text": "In 1904, the Casement Report, authored by British consul Roger Casement, was published. It provided detailed accounts of the atrocities and abuses in the Congo Free State, further fueling international condemnation.",
      "date": "1904"
    },
    {
      "headline": "Transfer of Control to Belgium",
      "text": "In 1908, due to mounting international pressure and condemnation, King Leopold II was forced to cede control of the Congo Free State to the Belgian government, which then established the Belgian Congo.",
      "date": "1908"
    }
  ]
}

