{
  "timeline": [
    {
      "headline": "Origin of Morganatic Marriage",
      "text": "The concept of morganatic marriage originated in the medieval period, primarily in the German-speaking regions of Europe. It was a way to allow marriages between individuals of unequal social rank without affecting the inheritance rights of the higher-ranking party's family.",
      "date": "-1000"
    },
    {
      "headline": "Legal Recognition in the Holy Roman Empire",
      "text": "Morganatic marriages were legally recognized in the Holy Roman Empire, which existed from 962 to 1806. These marriages were often used by nobility to marry commoners without granting them or their offspring any claim to titles or estates.",
      "date": "0962"
    },
    {
      "headline": "Morganatic Marriage of Archduke Franz Ferdinand",
      "text": "On July 1, 1900, Archduke Franz Ferdinand of Austria entered into a morganatic marriage with Countess Sophie Chotek. As a result, Sophie was not given the title of Empress, and their children were excluded from the line of succession to the Austro-Hungarian throne.",
      "date": "1900-07-01"
    },
    {
      "headline": "End of the Holy Roman Empire",
      "text": "The Holy Roman Empire was dissolved in 1806, but the practice of morganatic marriage continued in various forms in Europe, particularly in German-speaking countries.",
      "date": "1806"
    },
    {
      "headline": "Morganatic Marriage in Modern Times",
      "text": "While less common today, morganatic marriages still occur in some royal families. They are often seen as a way to preserve the integrity of royal titles and estates while allowing for personal choice in marriage.",
      "date": "2000"
    }
  ]
}

