{
  "timeline": [
    {
      "headline": "Settlement of Acadia",
      "text": "The first French settlement in Acadia was established in 1604 by Pierre Dugua, Sieur de Mons, and Samuel de Champlain on Saint Croix Island, located in present-day Maine.",
      "date": "1604"
    },
    {
      "headline": "Founding of Port Royal",
      "text": "In 1605, the French settlers moved their settlement to Port Royal, in present-day Nova Scotia, which became the first permanent European settlement in North America north of Florida.",
      "date": "1605"
    },
    {
      "headline": "Treaty of Utrecht",
      "text": "In 1713, the Treaty of Utrecht was signed, ending the War of the Spanish Succession. As part of the treaty, France ceded control of Acadia to Great Britain.",
      "date": "1713"
    },
    {
      "headline": "The Great Expulsion (Le Grand Dérangement)",
      "text": "Beginning in 1755, the British forcibly removed the Acadians from their lands in what is known as the Great Expulsion. Thousands of Acadians were deported to various British colonies and France.",
      "date": "1755"
    },
    {
      "headline": "Acadians Settle in Louisiana",
      "text": "Following their expulsion, many Acadians settled in Louisiana, where they became known as Cajuns. This migration occurred over several years, with significant numbers arriving by the late 1760s.",
      "date": "1760"
    },
    {
      "headline": "Return to Acadia",
      "text": "After the signing of the Treaty of Paris in 1763, which ended the Seven Years' War, some Acadians were allowed to return to their homeland, although they found their lands occupied by new settlers.",
      "date": "1763"
    },
    {
      "headline": "Recognition of Acadian Day",
      "text": "In 1881, the first National Acadian Convention was held in Memramcook, New Brunswick, where August 15 was chosen as the National Acadian Day.",
      "date": "1881"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Documented Gender-Affirming Surgery",
      "text": "In 1930, the first documented gender-affirming surgery was performed on Dora Richter, a transgender woman, in Germany. This marked a significant moment in the history of transgender healthcare.",
      "date": "1930"
    },
    {
      "headline": "Christine Jorgensen's Surgery",
      "text": "In 1952, Christine Jorgensen became the first American to undergo gender-affirming surgery in Denmark, bringing significant public attention to transgender issues.",
