{
  "timeline": [
    {
      "headline": "Enactment of Sakoku Edicts",
      "text": "The Sakoku policy was enacted by the Tokugawa shogunate under Tokugawa Iemitsu through a series of edicts from 1633 to 1639. These edicts severely limited relations and trade between Japan and other countries, banned almost all foreign nationals from entering Japan, and prohibited common Japanese people from leaving the country.",
      "date": "1633"
    },
    {
      "headline": "Completion of Sakoku Policy",
      "text": "By 1639, the Sakoku policy was fully implemented, marking the complete isolation of Japan from the outside world, with very limited exceptions for certain foreign entities.",
      "date": "1639"
    },
    {
      "headline": "Sakoku-ron Manuscript",
      "text": "In 1801, Japanese astronomer and translator Shizuki Tadao wrote the manuscript Sakoku-ron, which introduced the term 'sakoku' to describe Japan's isolationist policy. Shizuki coined the term while translating the works of the 17th-century German traveler Engelbert Kaempfer.",
      "date": "1801"
    },
    {
      "headline": "End of Sakoku",
      "text": "The Sakoku policy effectively ended in 1853 when Commodore Matthew Perry of the United States Navy arrived in Japan with a fleet of ships, leading to the opening of Japan to the West and the signing of the Convention of Kanagawa in 1854.",
      "date": "1853"
    }
  ]
}

