      "headline": "Birth of Nestorius",
      "text": "Nestorius was born around 386 in Germanicia, in the Roman province of Syria.",
      "date": "0386"
    },
    {
      "headline": "Nestorius Becomes Patriarch of Constantinople",
      "text": "In 428, Nestorius was appointed as the Patriarch of Constantinople, a significant position in the early Christian Church.",
      "date": "0428"
    },
    {
      "headline": "Council of Ephesus",
      "text": "In 431, the Council of Ephesus was convened, where Nestorius's teachings were condemned, leading to his deposition as Patriarch.",
      "date": "0431"
    },
    {
      "headline": "Exile of Nestorius",
      "text": "After being deposed, Nestorius was exiled to a monastery in Antioch and later to the Great Oasis of Hibis in Egypt around 435.",
      "date": "0435"
    },
    {
      "headline": "Death of Nestorius",
      "text": "Nestorius died around 450 in exile in the Great Oasis of Hibis, Egypt.",
      "date": "0450"
    },
    {
      "headline": "Spread of Nestorianism",
      "text": "After the Council of Ephesus, Nestorianism spread to the Sassanian Empire, where it was adopted by the Church of the East.",
      "date": "0431"
    },
    {
      "headline": "Synod of Seleucia-Ctesiphon",
      "text": "In 486, the Synod of Seleucia-Ctesiphon formally adopted Nestorian Christology, establishing the Church of the East as a distinct entity.",
      "date": "0486"
    },
    {
      "headline": "Nestorian Schism",
      "text": "The schism between the Nestorian Church and the Byzantine Church became more pronounced in the 5th and 6th centuries.",
      "date": "0500"
    },
    {
      "headline": "Nestorian Missionary Activity",
      "text": "During the 7th century, Nestorian missionaries spread Christianity along the Silk Road, reaching as far as China.",
      "date": "0600"
    },
    {
      "headline": "Nestorian Stele",
      "text": "In 781, the Nestorian Stele was erected in Xi'an, China, documenting the history of Christianity in China.",
      "date": "0781"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Discovery of the Rh Blood Group System",
      "text": "In 1937, the Rh blood group system was discovered by Karl Landsteiner and Alexander S. Wiener. They identified the Rh factor while studying the blood of rhesus monkeys, which led to the naming of the system.",
      "date": "1937"
    },
    {
      "headline": "Identification of the Rh(D) Antigen",
      "text": "In 1940, the Rh(D) antigen was identified as a significant factor in blood transfusion reactions. This discovery was crucial in understanding the compatibility of blood transfusions.",
      "date": "1940"
    },
    {
      "headline": "Introduction of Rh Immunoglobulin",
      "text": "In 1968, Rh immunoglobulin (Rho(D) immune globulin) was introduced to prevent hemolytic disease of the newborn. This treatment is given to Rh-negative mothers to prevent the development of antibodies against Rh-positive fetal blood cells.",
      "date": "1968"
    },
    {
      "headline": "Expansion of Defined Rh Antigens",
      "text": "By 2005, the Rh blood group system consisted of 49 defined blood group antigens, highlighting the complexity and importance of this blood group system in transfusion medicine.",
      "date": "2005"
    },
    {
      "headline": "Current Status of Rh Antigens",
      "text": "As of 2023, there are over 50 antigens in the Rh blood group system, with the D, C, c, E, and e antigens being the most prominent. The system continues to be a critical focus in transfusion and prenatal medicine.",
      "date": "2023"
    }
  ]
}

