{
  "timeline": [
    {
      "headline": "Discovery of Retinoic Acid",
      "text": "Retinoic acid, the active form of vitamin A, was discovered as a crucial compound in the regulation of cell growth and differentiation. This discovery laid the foundation for the development of tretinoin.",
      "date": "1960"
    },
    {
      "headline": "Introduction of Tretinoin for Acne Treatment",
      "text": "Tretinoin was introduced as a topical treatment for acne. It became widely used due to its effectiveness in promoting skin cell turnover and reducing acne lesions.",
      "date": "1971"
    },
    {
      "headline": "FDA Approval for Acne",
      "text": "The U.S. Food and Drug Administration (FDA) approved tretinoin as a prescription medication for the treatment of acne.",
      "date": "1971"
    },
    {
      "headline": "Use in Acute Promyelocytic Leukemia",
      "text": "Tretinoin was found to be effective in treating acute promyelocytic leukemia (APL) when the RARA-PML fusion mutation is present. It is taken orally for this purpose.",
      "date": "1980s"
    },
    {
      "headline": "FDA Approval for Acute Promyelocytic Leukemia",
      "text": "The FDA approved tretinoin for the treatment of acute promyelocytic leukemia, marking a significant advancement in cancer therapy.",
      "date": "1995"
    },
    {
      "headline": "Research on Photoaging",
      "text": "Tretinoin became the most extensively investigated retinoid therapy for photoaging, demonstrating its effectiveness in reducing fine wrinkles, hyperpigmentation, and roughness of facial skin.",
      "date": "1990s"
    }
  ]
}

