{
  "timeline": [
    {
      "headline": "Birth of Vidkun Quisling",
      "text": "Vidkun Abraham Lauritz Jonssøn Quisling was born on July 18, 1887, in Fyresdal, Telemark, Norway.",
      "date": "1887-07-18"
    },
    {
      "headline": "Graduation from Norwegian Military Academy",
      "text": "In 1911, Vidkun Quisling graduated from the Norwegian Military Academy with the highest score since the institution's founding.",
      "date": "1911"
    },
    {
      "headline": "Service in Russia",
      "text": "From 1922 to 1925, Quisling served as a military attaché in Petrograd (later Leningrad) and Moscow, Russia.",
      "date": "1922"
    },
    {
      "headline": "Humanitarian Work in Ukraine",
      "text": "In 1922, Quisling was involved in humanitarian work in Ukraine, where he worked with Fridtjof Nansen to aid famine victims.",
      "date": "1922"
    },
    {
      "headline": "Norwegian Minister of Defence",
      "text": "Vidkun Quisling served as Norway's Minister of Defence from 1931 to 1933.",
      "date": "1931"
    },
    {
      "headline": "Founding of Nasjonal Samling",
      "text": "In 1933, Quisling founded the fascist party Nasjonal Samling (National Unity) in Norway.",
      "date": "1933"
    },
    {
      "headline": "Coup Attempt",
      "text": "On April 9, 1940, during the German invasion of Norway, Quisling attempted a coup d'état by declaring himself Prime Minister in a radio broadcast.",
      "date": "1940-04-09"
    },
    {
      "headline": "Appointment as Minister-President",
      "text": "In February 1942, Quisling was appointed Minister-President of Norway by the German occupation authorities.",
      "date": "1942-02"
    },
    {
      "headline": "End of World War II and Arrest",
      "text": "Following the end of World War II in May 1945, Quisling was arrested by Norwegian authorities.",
      "date": "1945-05"
    },
    {
      "headline": "Trial and Execution",
      "text": "Vidkun Quisling was tried for treason, found guilty, and executed by firing squad on October 24, 1945.",
      "date": "1945-10-24"
    }
  ]
}

{
  "timeline": [
