{
  "timeline": [
    {
      "headline": "Roman Foundation",
      "text": "Córdoba was founded by the Romans in the 2nd century BCE as Corduba.",
      "date": "-0200"
    },
    {
      "headline": "Roman Capital",
      "text": "In 27 BCE, Córdoba became the capital of the Roman province of Hispania Baetica.",
      "date": "-0027"
    },
    {
      "headline": "Visigothic Rule",
      "text": "Córdoba came under Visigothic rule after the fall of the Roman Empire in the 5th century.",
      "date": "0500"
    },
    {
      "headline": "Umayyad Conquest",
      "text": "In 711, Córdoba was captured by the Umayyad Caliphate during the Muslim conquest of the Iberian Peninsula.",
      "date": "0711"
    },
    {
      "headline": "Capital of the Emirate of Córdoba",
      "text": "In 756, Abd al-Rahman I established Córdoba as the capital of the independent Emirate of Córdoba.",
      "date": "0756"
    },
    {
      "headline": "Córdoba Caliphate",
      "text": "In 929, Abd al-Rahman III declared Córdoba a caliphate, marking its peak as a center of learning and culture.",
      "date": "0929"
    },
    {
      "headline": "Fall of the Caliphate",
      "text": "In 1031, the Caliphate of Córdoba dissolved into several independent taifa kingdoms.",
      "date": "1031"
    },
    {
      "headline": "Christian Reconquest",
      "text": "Córdoba was captured by Ferdinand III of Castile in 1236 during the Reconquista.",
      "date": "1236"
    },
    {
      "headline": "Córdoba Cathedral",
      "text": "In 1523, construction began on the Cathedral of Córdoba, built within the former Great Mosque.",
      "date": "1523"
    },
    {
      "headline": "Modern Era",
      "text": "Córdoba became a provincial capital in the 19th century following the administrative division of Spain.",
      "date": "1800"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Inception of the World Press Freedom Index",
      "text": "The World Press Freedom Index was first published by Reporters Without Borders in 2002. It was created to rank countries based on their press freedom records from the previous year.",
      "date": "2002"
    },
    {
      "headline": "Annual Publication",
      "text": "Since its inception in 2002, the World Press Freedom Index has been published annually by Reporters Without Borders. It assesses the degree of freedom available to journalists in 180 countries and territories.",
      "date": "2003"
    },
    {
      "headline": "Introduction of New Criteria",
      "text": "Over the years, the methodology of the World Press Freedom Index has evolved, incorporating new criteria to better assess the freedom of the press in different countries. This includes factors such as media independence, legislative framework, and the safety of journalists.",
      "date": "2013"
    },
    {
      "headline": "20th Anniversary of the Index",
      "text": "In 2022, the World Press Freedom Index marked its 20th anniversary. The index continues to serve as a vital tool for assessing the state of press freedom worldwide.",
      "date": "2022"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Flight 191 Scheduled Route",
      "text": "Delta Air Lines Flight 191 was a regularly scheduled domestic service from Fort Lauderdale, Florida, to Los Angeles, California, with an intermediate stop at Dallas/Fort Worth International Airport (DFW).",
      "date": "1985"
    },
    {
      "headline": "Flight 191 Crash",
      "text": "On August 2, 1985, the Lockheed L-1011 TriStar operating Flight 191 encountered a microburst while on approach to land at DFW. The aircraft impacted ground just over one mile (1.6 km) short of the runway, struck a car near the airport, collided with two water tanks, and disintegrated.",
      "date": "1985-08-02"
    },
    {
      "headline": "Casualties",
      "text": "Out of the 163 occupants on board, 137 people died and 25 others were injured in the accident on August 2, 1985.",
      "date": "1985-08-02"
    }
  ]
}

