{
  "timeline": [
    {
      "headline": "Origin of the Term 'Otaku'",
      "text": "The term 'Otaku' began to be used in its contemporary sense in 1983, when Akio Nakamori published an essay in the magazine Manga Burikko. The essay described people with obsessive interests, particularly in anime and manga.",
      "date": "1983"
    },
    {
      "headline": "Otaku Culture Gains Popularity",
      "text": "Throughout the 1980s and 1990s, the otaku subculture gained popularity in Japan, characterized by a deep interest in anime, manga, and video games.",
      "date": "1980-1990"
    },
    {
      "headline": "Public Perception of Otaku",
      "text": "In the late 1980s, the term 'otaku' began to carry a negative connotation in Japan, partly due to media coverage of the 'Otaku Murderer' Tsutomu Miyazaki, which linked the term to antisocial behavior.",
      "date": "1989"
    },
    {
      "headline": "International Spread of Otaku Culture",
      "text": "By the late 1990s and early 2000s, otaku culture began to spread internationally, with anime and manga gaining popularity in countries outside Japan.",
      "date": "1990-2000"
    },
    {
      "headline": "Otaku Culture in the 21st Century",
      "text": "In the 21st century, otaku culture has become more mainstream, with anime conventions and online communities flourishing worldwide. The perception of otaku has also shifted, with many embracing the term as part of their identity.",
      "date": "2000-2023"
    }
  ]
}

