{
  "timeline": [
    {
      "headline": "Divergence from Elephant Ancestors",
      "text": "Mastodons, belonging to the genus Mammut, diverged from the ancestors of modern elephants at least 27–25 million years ago during the Oligocene epoch.",
      "date": "-00270000"
    },
    {
      "headline": "Appearance in North America",
      "text": "Mastodons became endemic to North America during the late Miocene epoch, which began around 23 million years ago.",
      "date": "-00230000"
    },
    {
      "headline": "Pleistocene Epoch",
      "text": "Mastodons thrived during the Pleistocene epoch, which lasted from about 2.58 million years ago to 11,700 years ago.",
      "date": "-0025800"
    },
    {
      "headline": "Extinction",
      "text": "Mastodons went extinct during the early Holocene epoch, around 11,000 years ago, likely due to a combination of climate change and overhunting by humans.",
      "date": "-0011000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of Inslaw, Inc.",
      "text": "Inslaw, Inc. was founded in Washington, D.C., as an information technology company specializing in case management software for corporate and government users.",
      "date": "1980"
    },
    {
      "headline": "Development of PROMIS",
      "text": "Inslaw developed PROMIS, an early case management software system designed to improve the efficiency of legal case management.",
      "date": "1982"
    },
    {
      "headline": "Contract with the Department of Justice",
      "text": "Inslaw entered into a contract with the United States Department of Justice to implement the PROMIS software system.",
      "date": "1982"
    },
    {
      "headline": "Lawsuit Against the Department of Justice",
      "text": "In 1986, Inslaw filed a lawsuit against the United States Department of Justice, alleging that the DOJ had conspired to drive Inslaw out of business by withholding payments and pirating the PROMIS software.",
      "date": "1986"
    },
    {
      "headline": "Bankruptcy Court Ruling",
      "text": "In 1987, a bankruptcy court ruled in favor of Inslaw, finding that the Department of Justice had taken the PROMIS software by 'trickery, fraud and deceit.'",
      "date": "1987"
    },
    {
      "headline": "Appeals and Legal Battles",
      "text": "Throughout the late 1980s and early 1990s, Inslaw and the Department of Justice were involved in ongoing legal battles and appeals regarding the PROMIS software case.",
      "date": "1987-1991"
    },
    {
      "headline": "Congressional Investigation",
      "text": "In 1992, a Congressional investigation was conducted into the allegations against the Department of Justice concerning the PROMIS software.",
      "date": "1992"
    },
    {
      "headline": "Final Legal Resolution",
      "text": "In 1997, the legal disputes between Inslaw and the Department of Justice were finally resolved, although the details of the resolution were not publicly disclosed.",
      "date": "1997"
    }
  ]
}

