{
  "timeline": [
    {
      "headline": "Munich Massacre",
      "text": "On September 5, 1972, during the Summer Olympics in Munich, West Germany, a Palestinian terrorist group called Black September took 11 members of the Israeli Olympic team hostage and eventually killed them.",
      "date": "1972-09-05"
    },
    {
      "headline": "Authorization of Operation Bayonet",
      "text": "In the autumn of 1972, Israeli Prime Minister Golda Meir authorized Mossad to carry out Operation Bayonet, a covert operation to assassinate individuals involved in the Munich massacre.",
      "date": "1972"
    },
    {
      "headline": "Assassination of Wael Zwaiter",
      "text": "On October 16, 1972, Mossad agents assassinated Wael Zwaiter, a Palestinian translator and PLO representative, in Rome, Italy. He was accused of being involved in the Munich massacre.",
      "date": "1972-10-16"
    },
    {
      "headline": "Assassination of Mahmoud Hamshari",
      "text": "On December 8, 1972, Mahmoud Hamshari, the PLO representative in France, was assassinated by Mossad in Paris. He was killed by a bomb planted in his telephone.",
      "date": "1972-12-08"
    },
    {
      "headline": "Assassination of Hussein Al Bashir",
      "text": "On January 24, 1973, Hussein Al Bashir, a PLO operative, was killed by a bomb placed under his bed in Nicosia, Cyprus.",
      "date": "1973-01-24"
    },
    {
      "headline": "Assassination of Mohammad Boudia",
      "text": "On June 28, 1973, Mohammad Boudia, a senior PLO operative, was killed by a car bomb in Paris, France.",
      "date": "1973-06-28"
    },
    {
      "headline": "Lillehammer Affair",
      "text": "On July 21, 1973, Mossad agents mistakenly assassinated Ahmed Bouchiki, a Moroccan waiter, in Lillehammer, Norway, believing him to be Ali Hassan Salameh, a key figure in Black September.",
      "date": "1973-07-21"
    },
    {
      "headline": "Assassination of Ali Hassan Salameh",
      "text": "On January 22, 1979, Ali Hassan Salameh, a senior member of Black September and the PLO, was killed by a car bomb in Beirut, Lebanon, orchestrated by Mossad.",
      "date": "1979-01-22"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Publication of 'The Yellow Wallpaper'",
      "text": "'The Yellow Wallpaper' was first published in January 1892 in The New England Magazine. This short story by Charlotte Perkins Gilman is considered an important early work of American feminist literature.",
      "date": "1892-01"
    },
    {
      "headline": "Recognition as a Feminist Work",
      "text": "Over time, 'The Yellow Wallpaper' has been recognized as an important early work of American feminist literature for its depiction of the mental and physical health issues faced by women in the 19th century.",
      "date": "1900"
    },
    {
      "headline": "Acclaimed as Horror Fiction",
      "text": "In addition to its feminist themes, 'The Yellow Wallpaper' is also lauded as an excellent work of horror fiction, showcasing the psychological horror experienced by the protagonist.",
      "date": "1900"
    }
  ]
}

