{
  "timeline": [
    {
      "headline": "Spanish Colonization Begins",
      "text": "In 1565, Miguel López de Legazpi established the first permanent Spanish settlement in the Philippines, marking the beginning of Spanish colonization.",
      "date": "1565"
    },
    {
      "headline": "Establishment of Manila",
      "text": "In 1571, Manila was established as the capital of the Spanish East Indies, becoming the center of Spanish political, religious, and economic activities in the region.",
      "date": "1571"
    },
    {
      "headline": "Galleon Trade Commences",
      "text": "The Manila-Acapulco Galleon Trade began in 1565, linking the Philippines with Mexico and facilitating trade between Asia and the Americas until 1815.",
      "date": "1565"
    },
    {
      "headline": "British Occupation of Manila",
      "text": "From 1762 to 1764, British forces occupied Manila during the Seven Years' War, temporarily disrupting Spanish control.",
      "date": "1762"
    },
    {
      "headline": "End of the Galleon Trade",
      "text": "The Manila-Acapulco Galleon Trade ended in 1815, due to the Mexican War of Independence and changing global trade dynamics.",
      "date": "1815"
    },
    {
      "headline": "Mexican Independence",
      "text": "In 1821, Mexico gained independence from Spain, which led to the Philippines being directly governed by Spain rather than through the Viceroyalty of New Spain.",
      "date": "1821"
    },
    {
      "headline": "Cavite Mutiny",
      "text": "In 1872, the Cavite Mutiny occurred, a brief uprising of Filipino soldiers and workers that was quickly suppressed but led to increased Spanish repression.",
      "date": "1872"
    },
    {
      "headline": "Execution of Gomburza",
      "text": "In 1872, three Filipino priests, Mariano Gómez, José Burgos, and Jacinto Zamora, collectively known as Gomburza, were executed by Spanish authorities, fueling nationalist sentiments.",
      "date": "1872"
    },
    {
      "headline": "Philippine Revolution Begins",
      "text": "In 1896, the Philippine Revolution against Spanish rule began, led by the Katipunan, a secret society founded by Andrés Bonifacio.",
      "date": "1896"
    },
    {
      "headline": "Execution of José Rizal",
      "text": "On December 30, 1896, José Rizal, a prominent Filipino nationalist and reformist, was executed by Spanish authorities, becoming a martyr for the Philippine Revolution.",
      "date": "1896-12-30"
    },
    {
      "headline": "Spanish-American War",
      "text": "In 1898, the Spanish-American War broke out, leading to the defeat of Spanish forces in the Philippines by American forces.",
      "date": "1898"
    },
    {
      "headline": "Declaration of Philippine Independence",
      "text": "On June 12, 1898, Emilio Aguinaldo declared Philippine independence from Spain in Kawit, Cavite.",
      "date": "1898-06-12"
    },
    {
      "headline": "Treaty of Paris",
      "text": "On December 10, 1898, the Treaty of Paris was signed, ending the Spanish-American War and ceding the Philippines to the United States.",
      "date": "1898-12-10"
    }
  ]
}

{
  "timeline": [
