    {
      "headline": "Capoeira Legalized",
      "text": "In the 1930s, Capoeira was legalized in Brazil, largely due to the efforts of Mestre Bimba, who opened the first Capoeira school in 1932.",
      "date": "1930"
    },
    {
      "headline": "First Capoeira School",
      "text": "Mestre Bimba opened the first Capoeira school in Salvador, Bahia, in 1932, marking a significant step in the formalization and recognition of Capoeira.",
      "date": "1932"
    },
    {
      "headline": "Capoeira Recognized as Cultural Heritage",
      "text": "In 2008, Capoeira was declared an intangible cultural heritage of Brazil by the National Institute of Historic and Artistic Heritage (IPHAN).",
      "date": "2008"
    },
    {
      "headline": "UNESCO Recognition",
      "text": "In 2014, UNESCO recognized Capoeira as an intangible cultural heritage of humanity, acknowledging its cultural significance and global impact.",
      "date": "2014"
    }
  ]
}

