      "headline": "Birth of Ida B. Wells",
      "text": "Ida Bell Wells was born on July 16, 1862, in Holly Springs, Mississippi.",
      "date": "1862-07-16"
    },
    {
      "headline": "Yellow Fever Epidemic",
      "text": "In 1878, a yellow fever epidemic struck Holly Springs, Mississippi, killing both of Wells' parents and one of her siblings.",
      "date": "1878"
    },
    {
      "headline": "Move to Memphis",
      "text": "In 1883, Wells moved to Memphis, Tennessee, where she worked as a teacher and later became involved in journalism.",
      "date": "1883"
    },
    {
      "headline": "Incident on Chesapeake & Ohio Railroad",
      "text": "In 1884, Wells was forcibly removed from a train for refusing to give up her seat in the 'ladies' car,' leading her to file a lawsuit against the railroad company.",
      "date": "1884"
    },
    {
      "headline": "Co-Owner and Editor of Free Speech",
      "text": "In 1889, Wells became co-owner and editor of the Memphis Free Speech and Headlight, a local black newspaper.",
      "date": "1889"
    },
    {
      "headline": "Anti-Lynching Campaign",
      "text": "In 1892, following the lynching of three of her friends, Wells began her anti-lynching campaign, publishing articles and pamphlets to raise awareness.",
      "date": "1892"
    },
    {
      "headline": "Exile from Memphis",
      "text": "In 1892, after publishing her anti-lynching articles, Wells' newspaper office was destroyed by a mob, forcing her to leave Memphis for her safety.",
      "date": "1892"
    },
    {
      "headline": "Publication of 'Southern Horrors'",
      "text": "In 1892, Wells published 'Southern Horrors: Lynch Law in All Its Phases,' a pamphlet documenting lynching in the United States.",
      "date": "1892"
    },
    {
      "headline": "Co-Founder of the NAACP",
      "text": "In 1909, Wells was one of the founding members of the National Association for the Advancement of Colored People (NAACP).",
      "date": "1909"
    },
    {
      "headline": "Founding of the Negro Fellowship League",
      "text": "In 1910, Wells founded the Negro Fellowship League in Chicago to support black migrants from the South.",
      "date": "1910"
    },
    {
      "headline": "Participation in the Women's Suffrage Movement",
      "text": "In 1913, Wells participated in the suffrage parade in Washington, D.C., advocating for women's voting rights.",
      "date": "1913"
    },
    {
      "headline": "Death of Ida B. Wells",
      "text": "Ida B. Wells died on March 25, 1931, in Chicago, Illinois.",
      "date": "1931-03-25"
    }
  ]
}

