    {
      "headline": "Foundation of the Ilkhanate",
      "text": "The Ilkhanate was established by Hülegü Khan, a grandson of Genghis Khan, in 1256. Hülegü was tasked with expanding Mongol influence in the Middle East.",
      "date": "1256"
    },
    {
      "headline": "Capture of Baghdad",
      "text": "In 1258, Hülegü Khan captured Baghdad, marking the end of the Abbasid Caliphate. This event was a significant milestone in the expansion of the Ilkhanate.",
      "date": "1258"
    },
    {
      "headline": "Death of Möngke Khan",
      "text": "Möngke Khan, the brother of Hülegü and the Great Khan of the Mongol Empire, died in 1259. His death led to a division of the Mongol Empire and the establishment of the Ilkhanate as a separate khanate.",
      "date": "1259"
    },
    {
      "headline": "Battle of Ain Jalut",
      "text": "In 1260, the Ilkhanate forces were defeated by the Mamluks at the Battle of Ain Jalut in present-day Israel. This battle marked the first major defeat of the Mongols and halted their advance into Egypt.",
      "date": "1260"
    },
    {
      "headline": "Reign of Ghazan Khan",
      "text": "Ghazan Khan, who ruled from 1295 to 1304, converted to Islam and implemented significant reforms to integrate the Mongol administration with the local Persian culture.",
      "date": "1295"
    },
    {
      "headline": "Conversion to Islam",
      "text": "Under Ghazan Khan's rule, the Ilkhanate officially converted to Islam in 1295, which helped to stabilize the region and integrate the Mongols with the local population.",
      "date": "1295"
    },
    {
      "headline": "Death of Ghazan Khan",
      "text": "Ghazan Khan died in 1304, leaving behind a legacy of cultural integration and administrative reform in the Ilkhanate.",
      "date": "1304"
    },
    {
      "headline": "Reign of Öljaitü",
      "text": "Öljaitü, who ruled from 1304 to 1316, continued the policies of his predecessor and further strengthened the Ilkhanate's ties with the Islamic world.",
      "date": "1304"
    },
    {
      "headline": "Construction of Soltaniyeh",
      "text": "Öljaitü commissioned the construction of the Soltaniyeh Dome in 1305, which became a significant architectural achievement of the Ilkhanate.",
      "date": "1305"
    },
    {
      "headline": "Death of Öljaitü",
      "text": "Öljaitü died in 1316, marking the end of a period of relative stability and prosperity for the Ilkhanate.",
      "date": "1316"
    },
    {
      "headline": "Decline of the Ilkhanate",
      "text": "Following the death of Abu Sa'id in 1335, the Ilkhanate began to fragment and decline, leading to the eventual dissolution of centralized Mongol rule in Persia.",
      "date": "1335"
    }
  ]
}

