      "headline": "Coronation of Stephen I",
      "text": "Stephen I was crowned as the first King of Hungary, marking the establishment of the Kingdom of Hungary. This event took place around the year 1000.",
      "date": "1000"
    },
    {
      "headline": "Golden Bull of 1222",
      "text": "The Golden Bull of 1222 was issued by King Andrew II of Hungary. It was a seminal constitutional document that limited the power of the monarchy and established the rights of the nobility.",
      "date": "1222"
    },
    {
      "headline": "Battle of Mohács",
      "text": "The Battle of Mohács occurred on August 29, 1526. It was a decisive victory for the Ottoman Empire against the Kingdom of Hungary, leading to the partition of Hungary.",
      "date": "1526-08-29"
    },
    {
      "headline": "Habsburg Rule Begins",
      "text": "Following the Battle of Mohács and the subsequent partition, the Habsburgs began their rule over Hungary, which lasted until the end of World War I.",
      "date": "1526"
    },
    {
      "headline": "Austro-Hungarian Compromise of 1867",
      "text": "The Austro-Hungarian Compromise of 1867 established the dual monarchy of Austria-Hungary, granting Hungary significant autonomy within the empire.",
      "date": "1867"
    },
    {
      "headline": "End of the Austro-Hungarian Empire",
      "text": "The Austro-Hungarian Empire dissolved following its defeat in World War I, leading to the end of the Kingdom of Hungary as part of the empire.",
      "date": "1918"
    },
    {
      "headline": "Proclamation of the Hungarian Republic",
      "text": "The Hungarian Republic was proclaimed on November 16, 1918, marking the end of the Kingdom of Hungary as a monarchy.",
      "date": "1918-11-16"
    },
    {
      "headline": "Abolition of the Monarchy",
      "text": "The monarchy in Hungary was officially abolished on February 1, 1946, following the end of World War II.",
      "date": "1946-02-01"
    }
  ]
}

