    {
      "headline": "Alfonso II's Reign",
      "text": "Alfonso II, known as Alfonso the Chaste, ruled from 791 to 842 and established Oviedo as the capital of the Kingdom of Asturias.",
      "date": "0791"
    },
    {
      "headline": "Discovery of Santiago de Compostela",
      "text": "During Alfonso II's reign, the tomb of Saint James was discovered in Santiago de Compostela around 813, which became a major pilgrimage site.",
      "date": "0813"
    },
    {
      "headline": "End of the Kingdom of Asturias",
      "text": "The Kingdom of Asturias came to an end in 924 when it was succeeded by the Kingdom of León.",
      "date": "0924"
    },
    {
      "headline": "Asturias as a Province",
      "text": "In 1833, Asturias was established as a province within Spain during the territorial division of the country.",
      "date": "1833"
    },
    {
      "headline": "Asturias Gains Autonomy",
      "text": "Asturias became an autonomous community within Spain on December 30, 1981, with its own government and parliament.",
      "date": "1981-12-30"
    }
  ]
}

