    {
      "headline": "Acquisition of Elsag Bailey Process Automation",
      "text": "In 1998, ABB acquired Elsag Bailey Process Automation, a leading process automation company, further strengthening its position in the automation sector.",
      "date": "1998"
    },
    {
      "headline": "Divestment of Oil, Gas, and Petrochemicals Division",
      "text": "In 2004, ABB divested its Oil, Gas, and Petrochemicals division to focus on its core businesses of power and automation technologies.",
      "date": "2004"
