      "text": "In World War I, the Merchant Marine was instrumental in transporting American troops and supplies to Europe, supporting the Allied war effort.",
      "date": "1917-1918"
    },
    {
      "headline": "World War II Service",
      "text": "During World War II, the Merchant Marine was vital in delivering troops, supplies, and equipment to various theaters of war, suffering high casualty rates due to enemy attacks.",
      "date": "1939-1945"
    },
    {
      "headline": "Merchant Marine Act of 1936",
      "text": "The Merchant Marine Act of 1936 was enacted to promote the development and maintenance of a strong American merchant marine, ensuring the availability of a fleet capable of serving as a naval auxiliary in times of war or national emergency.",
      "date": "1936"
    },
    {
      "headline": "Korean War Support",
      "text": "The Merchant Marine supported the United States military efforts during the Korean War by transporting troops and supplies to the Korean Peninsula.",
      "date": "1950-1953"
    },
    {
      "headline": "Vietnam War Involvement",
      "text": "During the Vietnam War, the Merchant Marine transported military personnel and equipment to Southeast Asia, playing a crucial role in the logistics of the conflict.",
      "date": "1955-1975"
    },
    {
      "headline": "Persian Gulf War Operations",
      "text": "In the Persian Gulf War, the Merchant Marine was essential in transporting military equipment and supplies to the Middle East, supporting Operation Desert Shield and Operation Desert Storm.",
      "date": "1990-1991"
    }
  ]
}

