{
  "timeline": [
    {
      "headline": "Establishment of January 1 as New Year's Day",
      "text": "In 45 BCE, with the introduction of the Julian calendar by Julius Caesar, January 1 was established as the first day of the year. This reform aligned the calendar with the solar year and marked the beginning of the year on January 1.",
      "date": "-0045"
    },
    {
      "headline": "Adoption of the Gregorian Calendar",
      "text": "In 1582, Pope Gregory XIII introduced the Gregorian calendar, which reformed the Julian calendar. This calendar retained January 1 as New Year's Day and corrected the drift of the calendar with respect to the equinoxes.",
      "date": "1582"
    },
    {
      "headline": "Adoption of Gregorian Calendar in Great Britain and its Colonies",
      "text": "In 1752, Great Britain and its colonies adopted the Gregorian calendar. This change moved the start of the year from March 25 to January 1, aligning with the calendar used by most of Western Europe.",
      "date": "1752"
    },
    {
      "headline": "New Year's Day as a Public Holiday",
      "text": "Over time, January 1 became widely recognized as a public holiday in many countries, marking the beginning of the new year with celebrations and traditions.",
      "date": "Various"
    }
  ]
}

