{
  "timeline": [
    {
      "headline": "Birth of Abhay Charan De",
      "text": "Abhay Charan De, later known as A. C. Bhaktivedanta Swami Prabhupada, was born on September 1, 1896, in Calcutta, India.",
      "date": "1896-09-01"
    },
    {
      "headline": "Meeting with Bhaktisiddhanta Sarasvati",
      "text": "In 1922, Abhay Charan De met his spiritual master, Bhaktisiddhanta Sarasvati, who instructed him to spread the teachings of Lord Krishna in the English language.",
      "date": "1922"
    },
    {
      "headline": "Initiation as a Disciple",
      "text": "In 1933, Abhay Charan De was formally initiated as a disciple of Bhaktisiddhanta Sarasvati in Allahabad, India.",
      "date": "1933"
    },
    {
      "headline": "Receiving the Title 'Bhaktivedanta'",
      "text": "In 1944, Abhay Charan De started the publication of 'Back to Godhead', a bi-weekly magazine, and was awarded the title 'Bhaktivedanta' by his godbrothers.",
      "date": "1944"
    },
    {
      "headline": "Sannyasa Initiation",
      "text": "On September 17, 1959, Abhay Charan De took the renounced order of life, sannyasa, and became known as Bhaktivedanta Swami.",
      "date": "1959-09-17"
    },
    {
      "headline": "Arrival in the United States",
      "text": "On September 17, 1965, Bhaktivedanta Swami arrived in the United States aboard the cargo ship Jaladuta, landing in Boston before heading to New York City.",
      "date": "1965-09-17"
    },
    {
      "headline": "Founding of ISKCON",
      "text": "In July 1966, Bhaktivedanta Swami founded the International Society for Krishna Consciousness (ISKCON) in New York City.",
      "date": "1966-07"
    },
    {
      "headline": "Publication of 'Bhagavad-gita As It Is'",
      "text": "In 1968, Bhaktivedanta Swami published 'Bhagavad-gita As It Is', which became one of his most significant works.",
      "date": "1968"
    },
    {
      "headline": "Establishment of the Bhaktivedanta Book Trust",
      "text": "In 1972, Bhaktivedanta Swami established the Bhaktivedanta Book Trust, which became the world's largest publisher of books on the philosophy, religion, and culture of India.",
      "date": "1972"
    },
    {
      "headline": "Passing of A. C. Bhaktivedanta Swami Prabhupada",
      "text": "A. C. Bhaktivedanta Swami Prabhupada passed away on November 14, 1977, in Vrindavan, India.",
      "date": "1977-11-14"
    }
  ]
}

