{
  "timeline": [
    {
      "headline": "Edmund Husserl's Publication of 'Logical Investigations'",
      "text": "In 1900-1901, Edmund Husserl published 'Logical Investigations', which is considered the founding work of phenomenology. This work laid the groundwork for phenomenology as a philosophical movement.",
      "date": "1900"
    },
    {
      "headline": "Husserl's 'Ideas: General Introduction to Pure Phenomenology'",
      "text": "In 1913, Edmund Husserl published 'Ideas: General Introduction to Pure Phenomenology', further developing his phenomenological philosophy and introducing key concepts such as 'epoché' and 'phenomenological reduction'.",
      "date": "1913"
    },
    {
      "headline": "Martin Heidegger's 'Being and Time'",
      "text": "In 1927, Martin Heidegger, a student of Husserl, published 'Being and Time', which expanded phenomenology by exploring the nature of being and introducing existential themes.",
      "date": "1927"
    },
    {
      "headline": "Jean-Paul Sartre's 'Being and Nothingness'",
      "text": "In 1943, Jean-Paul Sartre published 'Being and Nothingness', applying phenomenological methods to existentialism and exploring concepts like freedom, bad faith, and the nature of consciousness.",
      "date": "1943"
    },
    {
      "headline": "Maurice Merleau-Ponty's 'Phenomenology of Perception'",
      "text": "In 1945, Maurice Merleau-Ponty published 'Phenomenology of Perception', emphasizing the embodied nature of human experience and perception.",
      "date": "1945"
    },
    {
      "headline": "Husserl's 'The Crisis of European Sciences and Transcendental Phenomenology'",
      "text": "In 1954, posthumously, Edmund Husserl's 'The Crisis of European Sciences and Transcendental Phenomenology' was published, addressing the role of phenomenology in the sciences and its potential to address the crisis of European rationalism.",
      "date": "1954"
    }
  ]
}

