{
  "timeline": [
    {
      "headline": "Birth of Norodom Sihanouk",
      "text": "Norodom Sihanouk was born on October 31, 1922, in Phnom Penh, Cambodia.",
      "date": "1922-10-31"
    },
    {
      "headline": "Ascension to the Throne",
      "text": "On April 25, 1941, Norodom Sihanouk was crowned King of Cambodia at the age of 18.",
      "date": "1941-04-25"
    },
    {
      "headline": "Japanese Occupation",
      "text": "During World War II, Cambodia was under Japanese occupation from 1941 to 1945. Sihanouk remained as king during this period.",
      "date": "1941"
    },
    {
      "headline": "Independence from France",
      "text": "On November 9, 1953, Cambodia gained independence from France, with Sihanouk playing a significant role in the negotiations.",
      "date": "1953-11-09"
    },
    {
      "headline": "Abdication and Political Leadership",
      "text": "In March 1955, Sihanouk abdicated the throne in favor of his father, Norodom Suramarit, to engage more actively in politics.",
      "date": "1955-03"
    },
    {
      "headline": "Formation of Sangkum",
      "text": "In 1955, Sihanouk founded the Sangkum Reastr Niyum, a political movement that dominated Cambodian politics until 1970.",
      "date": "1955"
    },
    {
      "headline": "Becomes Prime Minister",
      "text": "Sihanouk served as the Prime Minister of Cambodia from 1955 to 1960.",
      "date": "1955"
    },
    {
      "headline": "Death of Norodom Suramarit",
      "text": "King Norodom Suramarit, Sihanouk's father, died on April 3, 1960, leading to Sihanouk becoming the Head of State.",
      "date": "1960-04-03"
    },
    {
      "headline": "Overthrown by a Coup",
      "text": "On March 18, 1970, Sihanouk was overthrown in a coup led by General Lon Nol while he was abroad.",
      "date": "1970-03-18"
    },
    {
      "headline": "Khmer Rouge Regime",
      "text": "Sihanouk returned to Cambodia in 1975 after the Khmer Rouge took power, initially serving as a figurehead head of state.",
      "date": "1975"
    },
    {
      "headline": "House Arrest",
      "text": "In 1976, Sihanouk was placed under house arrest by the Khmer Rouge, where he remained until the regime's fall in 1979.",
      "date": "1976"
    },
    {
      "headline": "Exile in China and North Korea",
      "text": "After the fall of the Khmer Rouge in 1979, Sihanouk lived in exile, primarily in China and North Korea.",
      "date": "1979"
    },
    {
      "headline": "Return to Cambodia",
      "text": "Sihanouk returned to Cambodia in 1991 following the Paris Peace Accords, which aimed to end the Cambodian-Vietnamese War.",
      "date": "1991"
    },
    {
      "headline": "Reinstated as King",
      "text": "On September 24, 1993, Sihanouk was reinstated as King of Cambodia after the restoration of the monarchy.",
      "date": "1993-09-24"
    },
    {
      "headline": "Abdication",
      "text": "Sihanouk abdicated the throne again on October 7, 2004, due to health reasons.",
      "date": "2004-10-07"
    },
    {
      "headline": "Death",
      "text": "Norodom Sihanouk passed away on October 15, 2012, in Beijing, China.",
      "date": "2012-10-15"
    }
  ]
}

