      "headline": "Formation of Theravāda",
      "text": "Theravāda Buddhism is believed to have formed after the Second Buddhist Council, which took place approximately 100 years after the Buddha's death, around 383 BCE. It emerged as a distinct school of Buddhism.",
      "date": "-0383"
    },
    {
      "headline": "Third Buddhist Council",
      "text": "The Third Buddhist Council was convened by Emperor Ashoka around 250 BCE in Pataliputra. It was during this council that the Theravāda school was further solidified and the Pāli Canon was compiled.",
      "date": "-0250"
    },
    {
      "headline": "Introduction to Sri Lanka",
      "text": "Theravāda Buddhism was introduced to Sri Lanka in the 3rd century BCE by Mahinda, the son of Emperor Ashoka, around 250 BCE. This marked the beginning of Theravāda's spread outside India.",
      "date": "-0250"
    },
    {
      "headline": "Compilation of the Pāli Canon",
      "text": "The Pāli Canon, the authoritative scripture of Theravāda Buddhism, was committed to writing in Sri Lanka during the reign of King Vattagamani Abhaya, around 29 BCE.",
      "date": "-0029"
    },
    {
      "headline": "Spread to Southeast Asia",
      "text": "Theravāda Buddhism spread to Southeast Asia, including regions like Myanmar, Thailand, Laos, and Cambodia, between the 5th and 13th centuries CE.",
      "date": "0500"
    },
    {
      "headline": "Reformation in Sri Lanka",
      "text": "In the 12th century, Theravāda Buddhism underwent a reformation in Sri Lanka under the influence of King Parakramabahu I, who unified the monastic community.",
      "date": "1153"
    },
    {
      "headline": "Modern Revival",
      "text": "In the 19th and 20th centuries, Theravāda Buddhism experienced a revival and spread to the West, with increased interest and scholarship in the Pāli Canon and meditation practices.",
      "date": "1800"
    }
  ]
}

