    {
      "headline": "Plague of Justinian",
      "text": "The Plague of Justinian, caused by Yersinia pestis, began in 541 CE and is considered the first recorded pandemic caused by this bacterium. It affected the Byzantine Empire and Mediterranean port cities, killing an estimated 25 to 50 million people.",
      "date": "0541"
    },
    {
      "headline": "Black Death",
      "text": "The Black Death, one of the deadliest pandemics in human history, was caused by Yersinia pestis. It began in 1347 and lasted until 1351, killing an estimated 75 to 200 million people across Europe, Asia, and North Africa.",
      "date": "1347"
    },
    {
      "headline": "Third Pandemic",
      "text": "The Third Pandemic of plague began in 1855 in Yunnan, China, and spread globally. It lasted until the mid-20th century, causing millions of deaths worldwide.",
      "date": "1855"
    },
    {
      "headline": "Discovery of Yersinia pestis",
      "text": "Yersinia pestis was discovered in 1894 by Alexandre Yersin, a Swiss-French physician and bacteriologist, during an outbreak in Hong Kong.",
      "date": "1894"
    },
    {
      "headline": "Genome Sequencing",
      "text": "The genome of Yersinia pestis was sequenced in 2001, providing insights into its virulence and evolutionary history.",
      "date": "2001"
    }
  ]
}

