{
  "timeline": [
    {
      "headline": "Beginning of the Harlem Renaissance",
      "text": "The Harlem Renaissance began in the early 1920s, marking a period of cultural, social, and artistic explosion centered in Harlem, New York City.",
      "date": "1920"
    },
    {
      "headline": "Publication of 'The New Negro'",
      "text": "In 1925, Alain Locke published 'The New Negro', an anthology that became a defining text of the Harlem Renaissance, promoting African-American cultural and intellectual contributions.",
      "date": "1925"
    },
    {
      "headline": "Establishment of the Cotton Club",
      "text": "The Cotton Club, a famous Harlem nightclub, opened in 1923 and became a hub for jazz music and African-American performers, despite its whites-only audience policy.",
      "date": "1923"
    },
    {
      "headline": "Langston Hughes Publishes 'The Weary Blues'",
      "text": "In 1926, Langston Hughes published his first book of poetry, 'The Weary Blues', which became a significant work of the Harlem Renaissance.",
      "date": "1926"
    },
    {
      "headline": "Founding of the Negro Experimental Theatre",
      "text": "In 1929, the Negro Experimental Theatre was founded by playwright and director Abram Hill, contributing to the theatrical aspect of the Harlem Renaissance.",
      "date": "1929"
    },
    {
      "headline": "End of the Harlem Renaissance",
      "text": "The Harlem Renaissance began to decline in the mid-1930s, largely due to the Great Depression, which affected funding and support for the arts.",
      "date": "1935"
    }
  ]
}

