{
  "timeline": [
    {
      "headline": "1948 Arab–Israeli War",
      "text": "In 1948, following the Arab–Israeli War, East Jerusalem was captured and held by Jordan. This marked the division of Jerusalem into East and West, with East Jerusalem under Jordanian control.",
      "date": "1948"
    },
    {
      "headline": "Jordanian Annexation",
      "text": "In 1950, Jordan formally annexed East Jerusalem along with the rest of the West Bank. This annexation was recognized only by Pakistan and the United Kingdom.",
      "date": "1950"
    },
    {
      "headline": "Six-Day War",
      "text": "In June 1967, during the Six-Day War, Israel captured East Jerusalem from Jordan. This led to the reunification of Jerusalem under Israeli control, although East Jerusalem is considered occupied territory under international law.",
      "date": "1967-06"
    },
    {
      "headline": "Jerusalem Law",
      "text": "In 1980, the Israeli Knesset passed the Jerusalem Law, declaring Jerusalem, including East Jerusalem, as the 'complete and united' capital of Israel. This move was not recognized internationally and led to a United Nations Security Council resolution condemning the annexation.",
      "date": "1980"
    },
    {
      "headline": "Oslo Accords",
      "text": "In 1993, the Oslo Accords were signed, which included provisions for future negotiations on the status of Jerusalem. East Jerusalem's status remains one of the core issues in the Israeli-Palestinian conflict.",
      "date": "1993"
    },
    {
      "headline": "UNESCO Resolution",
      "text": "In 2016, UNESCO passed a resolution that criticized Israeli actions in East Jerusalem and referred to the area as 'occupied Palestinian territory'.",
      "date": "2016"
    },
    {
      "headline": "US Embassy Move",
      "text": "In 2018, the United States moved its embassy from Tel Aviv to Jerusalem, recognizing the city as Israel's capital. This move was controversial and not recognized by many other countries, as it included East Jerusalem.",
      "date": "2018"
    }
  ]
}

