{
  "timeline": [
    {
      "headline": "Emergence of Trigonometry",
      "text": "Trigonometry emerged in the Hellenistic world during the 3rd century BC from applications of geometry to astronomical studies.",
      "date": "-0300"
    },
    {
      "headline": "Hipparchus Develops Trigonometry",
      "text": "Around 150 BC, Hipparchus, a Greek astronomer, is credited with compiling the first known trigonometric table, which was a table of chords.",
      "date": "-0150"
    },
    {
      "headline": "Ptolemy's Almagest",
      "text": "In the 2nd century AD, Claudius Ptolemy expanded on Hipparchus's work in his astronomical treatise, the Almagest, which included a comprehensive table of chords.",
      "date": "0150"
    },
    {
      "headline": "Indian Mathematicians Develop Sine Function",
      "text": "By the 5th century AD, Indian mathematicians like Aryabhata had developed the sine function and created the earliest-known tables of values for trigonometric ratios.",
      "date": "0500"
    },
    {
      "headline": "Islamic Golden Age Contributions",
      "text": "During the Islamic Golden Age (8th to 14th century), scholars like Al-Khwarizmi and Al-Battani made significant contributions to trigonometry, including the development of tangent and cotangent functions.",
      "date": "0800"
    },
    {
      "headline": "Regiomontanus's Work on Trigonometry",
      "text": "In the 15th century, the German mathematician Regiomontanus wrote 'De Triangulis Omnimodis', a comprehensive work on trigonometry.",
      "date": "1464"
    },
    {
      "headline": "Introduction of Trigonometric Functions in Europe",
      "text": "In the 16th century, European mathematicians like Rheticus and Copernicus introduced trigonometric functions such as sine, cosine, and tangent to Europe.",
      "date": "1540"
    },
    {
      "headline": "Development of Modern Trigonometry",
      "text": "In the 17th century, Isaac Newton and James Stirling contributed to the development of modern trigonometry, including the use of infinite series to calculate trigonometric functions.",
      "date": "1670"
    }
  ]
}

