{
  "timeline": [
    {
      "headline": "Emergence of Mahāyāna Buddhism",
      "text": "Mahayana Buddhism began to emerge as a distinct movement within Indian Buddhism around the 1st century CE. It introduced new texts and ideas, including the concept of the bodhisattva path.",
      "date": "0001"
    },
    {
      "headline": "Development of Mahāyāna Sūtras",
      "text": "Between the 1st and 5th centuries CE, numerous Mahāyāna sūtras were composed, including the Lotus Sūtra, the Heart Sūtra, and the Diamond Sūtra. These texts emphasized the bodhisattva ideal and the concept of emptiness (śūnyatā).",
      "date": "0100"
    },
    {
      "headline": "Spread of Mahāyāna to Central Asia and China",
      "text": "By the 2nd century CE, Mahāyāna Buddhism began to spread along the Silk Road to Central Asia and China, where it was translated into Chinese and began to influence local Buddhist practices.",
      "date": "0200"
    },
    {
      "headline": "Rise of Mahāyāna Schools",
      "text": "During the 4th to 6th centuries CE, various schools of Mahāyāna Buddhism developed, including the Madhyamaka and Yogācāra schools, which offered different philosophical interpretations of Mahāyāna teachings.",
      "date": "0400"
    },
    {
      "headline": "Introduction of Mahāyāna to Japan",
      "text": "In the 6th century CE, Mahāyāna Buddhism was introduced to Japan, where it became a major religious and cultural influence, leading to the development of distinct Japanese Buddhist schools such as Zen and Pure Land.",
      "date": "0600"
    },
    {
      "headline": "Development of Vajrayāna Buddhism",
      "text": "By the 7th century CE, Vajrayāna or Tantric Buddhism, a subset of Mahāyāna, began to develop in India. It incorporated esoteric practices and rituals aimed at achieving Buddhahood more rapidly.",
      "date": "0700"
    },
    {
      "headline": "Mahāyāna Influence in Tibet",
      "text": "In the 8th century CE, Mahāyāna Buddhism, along with Vajrayāna, was introduced to Tibet, where it became the dominant form of Buddhism and led to the development of Tibetan Buddhism.",
      "date": "0800"
    }
  ]
}

