    {
      "headline": "Planning of Operation Crossroads",
      "text": "Planning for Operation Crossroads began in 1945, shortly after the end of World War II. The tests were intended to investigate the effects of nuclear weapons on naval ships.",
      "date": "1945"
    },
    {
      "headline": "Selection of Bikini Atoll",
      "text": "In early 1946, Bikini Atoll in the Marshall Islands was selected as the site for the tests. The location was chosen for its remote location and suitable conditions for testing.",
      "date": "1946"
    },
    {
      "headline": "Relocation of Bikini Atoll Inhabitants",
      "text": "In March 1946, the inhabitants of Bikini Atoll were relocated to Rongerik Atoll to make way for the nuclear tests.",
      "date": "1946-03"
    },
    {
      "headline": "Test Able",
      "text": "Test Able was conducted on July 1, 1946. It was an airburst detonation of a nuclear bomb dropped from a B-29 bomber, detonated at an altitude of 520 feet above the target fleet.",
      "date": "1946-07-01"
    },
    {
      "headline": "Test Baker",
      "text": "Test Baker was conducted on July 25, 1946. It was an underwater detonation of a nuclear bomb, detonated 90 feet underwater, causing significant contamination of the target fleet.",
      "date": "1946-07-25"
    },
    {
      "headline": "Cancellation of Test Charlie",
      "text": "A third test, Test Charlie, was planned but ultimately canceled due to concerns about radioactive contamination and logistical challenges.",
      "date": "1946"
    },
    {
      "headline": "Impact and Legacy",
      "text": "Operation Crossroads had significant impacts on military strategy and public perception of nuclear weapons. It highlighted the destructive power of nuclear weapons and the challenges of radioactive contamination.",
      "date": "1946"
    }
  ]
}

