    {
      "headline": "Discovery of Gold",
      "text": "On January 24, 1848, gold was discovered by James W. Marshall at Sutter's Mill in Coloma, California.",
      "date": "1848-01-24"
    },
    {
      "headline": "Start of the Gold Rush",
      "text": "The news of gold discovery spread, initiating the California Gold Rush, which brought approximately 300,000 people to California from the rest of the United States and abroad.",
      "date": "1848"
    },
    {
      "headline": "California's Rapid Population Growth",
      "text": "The influx of people due to the gold rush significantly increased California's population, contributing to its rapid path to statehood.",
      "date": "1848-1855"
    },
    {
      "headline": "Economic Impact",
      "text": "The sudden influx of gold into the money supply reinvigorated the American economy during the gold rush period.",
      "date": "1848-1855"
    },
    {
      "headline": "California Statehood",
      "text": "California was admitted as a state in the United States as part of the Compromise of 1850, largely due to the population boom from the gold rush.",
      "date": "1850"
    },
    {
      "headline": "Impact on Native Californians",
      "text": "The gold rush had severe effects on Native Californians, accelerating their population's decline due to disease, starvation, and the California genocide.",
      "date": "1848-1855"
    },
    {
      "headline": "End of the Gold Rush",
      "text": "The California Gold Rush began to decline around 1855 as gold became harder to find and the easy-to-reach deposits were exhausted.",
      "date": "1855"
    }
  ]
}

