  "timeline": [
    {
      "headline": "Beginning of the Permian Period",
      "text": "The Permian Period began approximately 298.9 million years ago, marking the end of the Carboniferous Period.",
      "date": "-298900000"
    },
    {
      "headline": "Formation of Pangaea",
      "text": "During the Permian, the supercontinent Pangaea was fully assembled, leading to significant climatic changes and the development of extensive arid regions.",
      "date": "-298900000"
    },
    {
      "headline": "Diversification of Reptiles",
      "text": "The Permian Period saw a significant diversification of reptiles, including the ancestors of mammals and dinosaurs.",
      "date": "-298900000"
    },
    {
      "headline": "Development of Gymnosperms",
      "text": "Gymnosperms, including conifers, became more prevalent during the Permian, adapting to the drier climate.",
      "date": "-298900000"
    },
    {
      "headline": "End-Permian Extinction Event",
      "text": "Approximately 251.902 million years ago, the Permian Period ended with the largest mass extinction event in Earth's history, wiping out around 90% of marine species and 70% of terrestrial vertebrate species.",
      "date": "-251902000"
    },
    {
      "headline": "Introduction of the Permian Concept",
      "text": "In 1841, geologist Sir Roderick Murchison introduced the concept of the Permian Period, naming it after the region of Perm in Russia.",
      "date": "1841"
    }
  ]
}

