      "headline": "Invention of the Daguerreotype",
      "text": "The daguerreotype process was invented by Louis Daguerre in 1839. It was the first publicly available photographic process.",
      "date": "1839"
    },
    {
      "headline": "Announcement of the Daguerreotype",
      "text": "On January 7, 1839, François Arago announced the invention of the daguerreotype process to the French Academy of Sciences.",
      "date": "1839-01-07"
    },
    {
      "headline": "Public Release of the Daguerreotype",
      "text": "On August 19, 1839, the French government announced the daguerreotype process as a gift 'free to the world'.",
      "date": "1839-08-19"
    },
    {
      "headline": "First Daguerreotype of the Moon",
      "text": "In 1840, John William Draper took the first daguerreotype image of the Moon.",
      "date": "1840"
    },
    {
      "headline": "Daguerreotype in the United States",
      "text": "In 1840, Alexander S. Wolcott and John Johnson opened the first commercial daguerreotype studio in New York City.",
      "date": "1840"
    },
    {
      "headline": "Daguerreotype Patent in the United Kingdom",
      "text": "In 1841, Richard Beard obtained the patent rights for the daguerreotype process in the United Kingdom.",
      "date": "1841"
    },
    {
      "headline": "Daguerreotype Popularity Peak",
      "text": "During the 1840s and 1850s, the daguerreotype process became widely popular for portrait photography.",
      "date": "1840-1850"
    },
    {
      "headline": "Decline of the Daguerreotype",
      "text": "By the late 1850s, the daguerreotype process began to decline in popularity due to the introduction of new photographic processes like the ambrotype and tintype.",
      "date": "1850-1859"
    }
  ]
}

