    {
      "headline": "Formal Breeding Programs Initiated",
      "text": "In the 1930s, formal breeding programs for the Norwegian Forest Cat were initiated to preserve the breed's characteristics.",
      "date": "1930"
    },
    {
      "headline": "World War II Impact",
      "text": "During World War II, the Norwegian Forest Cat faced the threat of extinction due to the disruption of breeding programs.",
