{
  "timeline": [
    {
      "headline": "Pollock v. Farmers' Loan & Trust Co.",
      "text": "In 1895, the Supreme Court case of Pollock v. Farmers' Loan & Trust Co. ruled that taxes on income from property were direct taxes and had to be apportioned among the states according to population, making it difficult for Congress to impose income taxes.",
      "date": "1895"
    },
    {
      "headline": "Congress Passes the Sixteenth Amendment",
      "text": "In response to the Pollock decision, Congress passed the Sixteenth Amendment on July 2, 1909, allowing it to levy an income tax without apportioning it among the states based on population.",
      "date": "1909-07-02"
    },
    {
      "headline": "Ratification of the Sixteenth Amendment",
      "text": "The Sixteenth Amendment was ratified by the requisite number of states on February 3, 1913, officially becoming part of the United States Constitution.",
      "date": "1913-02-03"
    },
    {
      "headline": "Effect of the Sixteenth Amendment",
      "text": "The ratification of the Sixteenth Amendment effectively overruled the Supreme Court's decision in Pollock v. Farmers' Loan & Trust Co., allowing Congress to impose a federal income tax without apportionment among the states.",
      "date": "1913"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Émile Zola",
      "text": "Émile Édouard Charles Antoine Zola was born on April 2, 1840, in Paris, France.",
      "date": "1840-04-02"
    },
    {
      "headline": "Publication of 'Thérèse Raquin'",
      "text": "In 1867, Zola published 'Thérèse Raquin', which marked his first major success and established him as a significant literary figure.",
      "date": "1867"
    },
    {
      "headline": "Beginning of the Rougon-Macquart series",
      "text": "In 1871, Zola began publishing the Rougon-Macquart series, a monumental cycle of 20 novels exploring the impact of heredity and environment on a family during the Second French Empire.",
      "date": "1871"
    },
    {
      "headline": "Publication of 'L'Assommoir'",
      "text": "In 1877, Zola published 'L'Assommoir', one of his most famous novels, which depicted the struggles of the working class in Paris.",
      "date": "1877"
    },
    {
      "headline": "Publication of 'Germinal'",
      "text": "In 1885, Zola published 'Germinal', a novel about the harsh conditions of coal miners in northern France, which became one of his most acclaimed works.",
      "date": "1885"
    },
    {
      "headline": "Publication of 'J'Accuse…!'",
      "text": "On January 13, 1898, Zola published 'J'Accuse…!', an open letter to the President of France, in the newspaper L'Aurore, defending Alfred Dreyfus and accusing the French government of anti-Semitism and wrongful imprisonment.",
      "date": "1898-01-13"
    },
    {
      "headline": "Exile in England",
      "text": "Following the publication of 'J'Accuse…!', Zola was convicted of libel and fled to England in 1898 to avoid imprisonment. He returned to France in 1899 after the Dreyfus affair began to resolve.",
      "date": "1898"
    },
    {
      "headline": "Nomination for Nobel Prize in Literature",
      "text": "Zola was nominated for the first Nobel Prize in Literature in 1901 and again in 1902.",
      "date": "1901"
    },
    {
      "headline": "Death of Émile Zola",
      "text": "Émile Zola died on September 29, 1902, in Paris, France, from carbon monoxide poisoning caused by a blocked chimney.",
