{
  "timeline": [
    {
      "headline": "Emergence of Cargo Cults",
      "text": "Cargo cults began to emerge in the late 19th century among indigenous Melanesians as a reaction to Western colonization and the introduction of Western goods and practices.",
      "date": "1800"
    },
    {
      "headline": "Colonial Influence and Cultural Disruption",
      "text": "Throughout the late 19th and early 20th centuries, Western colonization disrupted traditional Melanesian village life, leading to the rise of cargo cults as a response to the inequality and cultural changes imposed by colonial powers.",
      "date": "1900"
    },
    {
      "headline": "World War II and the Expansion of Cargo Cults",
      "text": "During World War II, the presence of military personnel and the influx of Western goods intensified the beliefs and practices of cargo cults. Indigenous people observed the abundance of goods brought by the military and believed that these goods were created by ancestral spirits.",
      "date": "1940"
    },
    {
      "headline": "John Frum Movement",
      "text": "One of the most well-known cargo cults, the John Frum movement, emerged on the island of Tanna in Vanuatu. Followers believed that a messianic figure named John Frum would return with an abundance of goods and lead them to prosperity.",
      "date": "1940"
    },
    {
      "headline": "Post-War Period and Continued Belief",
      "text": "After World War II, many cargo cults continued to exist, with followers maintaining their beliefs in the eventual return of their ancestors and the arrival of cargo. These movements often included rituals that mimicked military practices, such as marching and flag-raising.",
      "date": "1950"
    },
    {
      "headline": "Anthropological Studies",
      "text": "Throughout the 20th century, anthropologists studied cargo cults to understand their origins and significance. They described these movements as rooted in pre-existing Melanesian beliefs and as a reaction to the social and economic disruptions caused by colonialism.",
      "date": "1960"
    }
  ]
}

