{
  "timeline": [
    {
      "headline": "First Particle Accelerator",
      "text": "In 1928, Rolf Widerøe, a Norwegian engineer, built the first linear particle accelerator, which accelerated potassium ions.",
      "date": "1928"
    },
    {
      "headline": "Cyclotron Invention",
      "text": "In 1930, Ernest O. Lawrence and M. Stanley Livingston invented the cyclotron, a type of particle accelerator that uses a magnetic field to bend the path of charged particles.",
      "date": "1930"
    },
    {
      "headline": "First Cyclotron Operation",
      "text": "In 1932, the first cyclotron was successfully operated at the University of California, Berkeley.",
      "date": "1932"
    },
    {
      "headline": "Development of Synchrotron",
      "text": "In 1945, the concept of the synchrotron was proposed by Vladimir Veksler and Edwin McMillan independently, leading to the development of this type of accelerator.",
      "date": "1945"
    },
    {
      "headline": "First Synchrotron Light Source",
      "text": "In 1947, the first synchrotron light was observed at the General Electric research laboratory in Schenectady, New York.",
      "date": "1947"
    },
    {
      "headline": "Invention of the Betatron",
      "text": "In 1940, Donald Kerst invented the betatron, a type of particle accelerator that accelerates electrons using a changing magnetic field.",
      "date": "1940"
    },
    {
      "headline": "Construction of the Large Hadron Collider",
      "text": "Construction of the Large Hadron Collider (LHC) began in 1998 at CERN, near Geneva, Switzerland. It is the world's largest and most powerful particle accelerator.",
      "date": "1998"
    },
    {
      "headline": "First Beam in the LHC",
      "text": "On September 10, 2008, the first beam was successfully circulated in the Large Hadron Collider.",
      "date": "2008-09-10"
    },
    {
      "headline": "Discovery of the Higgs Boson",
      "text": "On July 4, 2012, CERN announced the discovery of a new particle consistent with the Higgs boson, a fundamental particle predicted by the Standard Model of particle physics.",
      "date": "2012-07-04"
    }
  ]
}

