{
  "timeline": [
    {
      "headline": "First Abolitionist Society",
      "text": "In 1775, the first abolitionist society in the United States was founded in Philadelphia, Pennsylvania. It was called the Society for the Relief of Free Negroes Unlawfully Held in Bondage.",
      "date": "1775"
    },
    {
      "headline": "Pennsylvania Abolition Act",
      "text": "On March 1, 1780, Pennsylvania passed the Act for the Gradual Abolition of Slavery, becoming the first state to begin an abolition of slavery.",
      "date": "1780-03-01"
    },
    {
      "headline": "Formation of the American Colonization Society",
      "text": "In 1816, the American Colonization Society was founded with the goal of relocating free African Americans to Africa, which led to the establishment of Liberia.",
      "date": "1816"
    },
    {
      "headline": "Publication of The Liberator",
      "text": "On January 1, 1831, William Lloyd Garrison published the first issue of The Liberator, an abolitionist newspaper that became influential in the movement.",
      "date": "1831-01-01"
    },
    {
      "headline": "Nat Turner's Rebellion",
      "text": "In August 1831, Nat Turner led a slave rebellion in Virginia, which heightened tensions between abolitionists and pro-slavery advocates.",
      "date": "1831-08"
    },
    {
      "headline": "American Anti-Slavery Society Founded",
      "text": "In 1833, the American Anti-Slavery Society was founded in Philadelphia, advocating for the immediate abolition of slavery.",
      "date": "1833"
    },
    {
      "headline": "Amistad Case",
      "text": "In 1839, the Amistad case began when African captives took control of the Spanish schooner La Amistad. The U.S. Supreme Court eventually ruled in their favor in 1841, allowing them to return to Africa.",
      "date": "1839"
    },
    {
      "headline": "Publication of Uncle Tom's Cabin",
      "text": "In 1852, Harriet Beecher Stowe published Uncle Tom's Cabin, a novel that depicted the harsh realities of slavery and fueled the abolitionist movement.",
      "date": "1852"
    },
    {
      "headline": "Dred Scott Decision",
      "text": "On March 6, 1857, the U.S. Supreme Court delivered the Dred Scott decision, ruling that African Americans could not be American citizens and had no standing to sue in federal court.",
      "date": "1857-03-06"
    },
    {
      "headline": "John Brown's Raid on Harpers Ferry",
      "text": "In October 1859, abolitionist John Brown led a raid on the federal armory at Harpers Ferry, intending to start an armed slave revolt.",
      "date": "1859-10"
    },
    {
      "headline": "Emancipation Proclamation",
      "text": "On January 1, 1863, President Abraham Lincoln issued the Emancipation Proclamation, declaring all slaves in Confederate-held territory to be free.",
      "date": "1863-01-01"
    },
    {
      "headline": "Thirteenth Amendment Ratified",
      "text": "On December 6, 1865, the Thirteenth Amendment to the United States Constitution was ratified, officially abolishing slavery in the United States.",
      "date": "1865-12-06"
    }
  ]
}

