    {
      "headline": "Start of Mining Operations",
      "text": "In 1915, the British began mining operations in the Ypres Salient, including the area around Messines, as part of their strategy to break the stalemate on the Western Front.",
      "date": "1915"
    },
    {
      "headline": "Formation of Tunnelling Companies",
      "text": "In February 1915, the British Army formed specialized tunnelling companies within the Royal Engineers to conduct underground warfare, including the planting of mines beneath enemy lines.",
      "date": "1915-02"
    },
    {
      "headline": "Completion of Mines",
      "text": "By mid-1917, the British had completed 21 mines beneath the German front lines near Messines, although two were abandoned due to waterlogging.",
      "date": "1917-06"
    },
    {
      "headline": "Detonation of Mines",
      "text": "On 7 June 1917, at 03:10 AM, 19 mines were detonated beneath the German lines at Messines Ridge, marking the start of the Battle of Messines. The explosions killed approximately 10,000 German soldiers and created 19 large craters.",
      "date": "1917-06-07"
    },
    {
      "headline": "Battle of Messines",
      "text": "The Battle of Messines took place from 7 to 14 June 1917, following the detonation of the mines. The British Second Army successfully captured the Messines Ridge from the German 4th Army.",
      "date": "1917-06-07"
    },
    {
      "headline": "Aftermath and Legacy",
      "text": "The success of the mines at Messines demonstrated the effectiveness of underground warfare and had a significant impact on future military strategies. The craters left by the explosions remain a visible reminder of the battle.",
      "date": "1917"
    }
  ]
}

