{
  "timeline": [
    {
      "headline": "Ancient Education System",
      "text": "In ancient India, education was imparted at gurukuls and was focused on subjects like the Vedas, mathematics, and philosophy. The education system was highly informal and based on oral transmission.",
      "date": "-1500"
    },
    {
      "headline": "Nalanda University Established",
      "text": "Nalanda University, one of the world's first residential universities, was established in the 5th century CE in Bihar, India. It became a renowned center for learning, attracting students from various countries.",
      "date": "0427"
    },
    {
      "headline": "British Colonial Education System",
      "text": "During the British colonial period, the education system in India was restructured to serve colonial interests. The English Education Act of 1835 marked the beginning of English education in India.",
      "date": "1835"
    },
    {
      "headline": "University of Calcutta Established",
      "text": "The University of Calcutta was established in 1857, becoming one of the first modern universities in India. It played a significant role in higher education during the colonial period.",
      "date": "1857"
    },
    {
      "headline": "Indian Education Commission",
      "text": "The Indian Education Commission, also known as the Hunter Commission, was appointed in 1882 to review the education system in India and make recommendations for improvements.",
      "date": "1882"
    },
    {
      "headline": "Wardha Scheme of Education",
      "text": "In 1937, Mahatma Gandhi proposed the Wardha Scheme of Education, which emphasized basic education in the mother tongue and vocational training.",
      "date": "1937"
    },
    {
      "headline": "University Grants Commission (UGC) Established",
      "text": "The University Grants Commission (UGC) was established in 1956 to coordinate, determine, and maintain standards of higher education in India.",
      "date": "1956"
    },
    {
      "headline": "National Policy on Education",
      "text": "The National Policy on Education was formulated in 1986, aiming to promote education among the country's people and address the challenges of access, equity, and quality.",
      "date": "1986"
    },
    {
      "headline": "Right to Education Act Enacted",
      "text": "The Right of Children to Free and Compulsory Education Act was enacted in 2009, making education a fundamental right for children aged 6 to 14 years in India.",
      "date": "2009"
    }
  ]
}

