{
  "timeline": [
    {
      "headline": "Earliest Evidence of Cremation",
      "text": "The earliest evidence of cremation dates back to the early Stone Age, around 20,000 years ago, with the discovery of the Mungo Lady, a partially cremated body found in Lake Mungo, Australia.",
      "date": "-18000"
    },
    {
      "headline": "Cremation in Ancient Greece",
      "text": "Cremation became a common practice in Ancient Greece by the time of the Homeric epics, around the 8th century BCE, where it was often used for warriors who died in battle.",
      "date": "-0800"
    },
    {
      "headline": "Cremation in Ancient Rome",
      "text": "In Ancient Rome, cremation was a standard practice by the 5th century BCE, particularly among the upper classes, until it was gradually replaced by inhumation around the 2nd century CE.",
      "date": "-0500"
    },
    {
      "headline": "Decline of Cremation in Europe",
      "text": "With the rise of Christianity in Europe, cremation declined significantly as burial became the preferred method of body disposition, due to the belief in bodily resurrection.",
      "date": "0300"
    },
    {
      "headline": "Revival of Cremation in the Modern Era",
      "text": "Cremation was reintroduced in the Western world in the late 19th century, with the first modern crematorium built in Milan, Italy, in 1876.",
      "date": "1876"
    },
    {
      "headline": "Cremation Act in the United Kingdom",
      "text": "The Cremation Act of 1902 was passed in the United Kingdom, providing a legal framework for the practice of cremation.",
      "date": "1902"
    },
    {
      "headline": "Cremation in the United States",
      "text": "The first crematorium in the United States was built in Washington, Pennsylvania, in 1876, marking the beginning of the practice in the country.",
      "date": "1876"
    },
    {
      "headline": "Cremation Becomes More Common",
      "text": "By the late 20th century, cremation became increasingly popular worldwide, with many countries seeing a significant rise in cremation rates due to factors such as cost, environmental concerns, and changing religious attitudes.",
      "date": "1980"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Council of Florence",
      "text": "In 1439, the Council of Florence attempted to reunite the Eastern and Western Churches. Although the union was not widely accepted in the East, it set a precedent for future unions.",
      "date": "1439"
    },
