{
  "timeline": [
    {
      "headline": "First Observation of Electroluminescence in Organic Materials",
      "text": "In 1950, André Bernanose and co-workers at the Nancy-Université in France observed electroluminescence in organic materials for the first time. They applied high-voltage alternating current (AC) fields in air to materials such as acridine orange, either deposited on or dissolved in cellulose or cellophane thin films.",
      "date": "1950"
    },
    {
      "headline": "First Diode Structure",
      "text": "In 1963, Martin Pope and his group at New York University developed ohmic dark-injecting electrode contacts to organic crystals. They demonstrated the first diode structure with an organic semiconductor, which is a foundational concept for OLED technology.",
      "date": "1963"
    },
    {
      "headline": "First Practical OLED Device",
      "text": "In 1987, Ching W. Tang and Steven Van Slyke at Eastman Kodak built the first practical OLED device. It was a two-layer structure with separate hole-transporting and electron-transporting layers, which significantly improved efficiency and performance.",
      "date": "1987"
    },
    {
      "headline": "Introduction of Polymer OLEDs",
      "text": "In 1990, Richard Friend and his group at the University of Cambridge reported a polymer-based OLED. This discovery opened the door for the development of flexible and large-area OLED displays.",
      "date": "1990"
    },
    {
      "headline": "First Commercial OLED Display",
      "text": "In 1997, Pioneer Corporation released the first commercial OLED display, which was used in car audio systems. This marked the beginning of OLED technology's entry into consumer electronics.",
      "date": "1997"
    },
    {
      "headline": "First OLED TV",
      "text": "In 2007, Sony launched the XEL-1, the world's first OLED television, featuring an 11-inch screen. This was a significant milestone in OLED technology, showcasing its potential for high-quality display applications.",
      "date": "2007"
    },
    {
      "headline": "Introduction of Flexible OLED Displays",
      "text": "In 2013, Samsung released the Galaxy Round, the first smartphone with a flexible OLED display. This innovation demonstrated the versatility and potential of OLED technology for new form factors in consumer electronics.",
      "date": "2013"
    },
    {
      "headline": "Advancements in White OLEDs",
      "text": "In the 2010s, significant advancements were made in the development of white OLEDs, which are crucial for solid-state lighting applications. These developments have the potential to revolutionize energy-efficient lighting solutions.",
      "date": "2010"
    }
  ]
}

