{
  "timeline": [
    {
      "headline": "Franz Mesmer's Animal Magnetism",
      "text": "In the late 18th century, Franz Mesmer developed the theory of 'animal magnetism', which laid the groundwork for the modern concept of hypnosis. Mesmer believed that a natural energy transfer occurred between all animated and inanimate objects, which he called 'animal magnetism'.",
      "date": "1770"
    },
    {
      "headline": "James Braid Coins the Term 'Hypnosis'",
      "text": "In 1843, Scottish surgeon James Braid coined the term 'hypnosis', derived from the Greek word 'hypnos', meaning sleep. Braid's work helped to shift the understanding of hypnosis from Mesmer's mystical theories to a more scientific perspective.",
      "date": "1843"
    },
    {
      "headline": "Jean-Martin Charcot's Hypnosis Studies",
      "text": "In the late 19th century, French neurologist Jean-Martin Charcot used hypnosis as a tool to study hysteria and other neurological disorders. His work contributed to the acceptance of hypnosis in the medical community.",
      "date": "1880"
    },
    {
      "headline": "Sigmund Freud's Use of Hypnosis",
      "text": "In the late 19th and early 20th centuries, Sigmund Freud used hypnosis in his early work on psychoanalysis. However, he later abandoned it in favor of free association.",
      "date": "1890"
    },
    {
      "headline": "Milton Erickson's Hypnotherapy",
      "text": "In the mid-20th century, American psychiatrist Milton Erickson developed innovative techniques in hypnotherapy, emphasizing the use of indirect suggestion and storytelling. His work greatly influenced modern hypnotherapy practices.",
      "date": "1950"
    },
    {
      "headline": "American Medical Association Recognizes Hypnosis",
      "text": "In 1958, the American Medical Association recognized hypnosis as a legitimate therapeutic tool, which helped to further its acceptance in the medical field.",
      "date": "1958"
    },
    {
      "headline": "British Medical Association Endorses Hypnosis",
      "text": "In 1955, the British Medical Association endorsed the use of hypnosis in medical practice, acknowledging its potential benefits in treatment.",
      "date": "1955"
    }
  ]
}

