    {
      "headline": "Foundation by the Romans",
      "text": "Palma was founded as a Roman camp upon the remains of a Talaiotic settlement. The exact date is not known, but it was during the Roman conquest of the Balearic Islands in 123 BCE.",
      "date": "-0123"
    },
    {
      "headline": "Conquest by the Vandals",
      "text": "In 455, Palma was conquered by the Vandals, a Germanic tribe that established a kingdom in North Africa and the western Mediterranean.",
      "date": "0455"
    },
    {
      "headline": "Byzantine Rule",
      "text": "After the fall of the Vandal Kingdom, Palma came under Byzantine rule in 534, becoming part of the Byzantine province of Spania.",
      "date": "0534"
    },
    {
      "headline": "Muslim Conquest",
      "text": "In 902, Palma was conquered by the Moors, who integrated it into the Emirate of Córdoba.",
      "date": "0902"
    },
    {
      "headline": "Christian Reconquest",
      "text": "On December 31, 1229, King James I of Aragon captured Palma from the Moors, marking the beginning of Christian rule.",
      "date": "1229-12-31"
    },
    {
      "headline": "Establishment as Capital",
      "text": "In 1230, Palma was established as the capital of the Kingdom of Majorca, a vassal state of the Crown of Aragon.",
      "date": "1230"
    },
    {
      "headline": "Incorporation into the Crown of Aragon",
      "text": "In 1349, the Kingdom of Majorca was incorporated into the Crown of Aragon after the defeat of James III of Majorca.",
      "date": "1349"
    },
    {
      "headline": "Spanish War of Succession",
      "text": "During the War of Spanish Succession (1701-1714), Palma supported the Habsburgs. After the war, the city was integrated into the Bourbon Spain.",
      "date": "1715"
    },
    {
      "headline": "Modern Development",
      "text": "In the 20th century, Palma underwent significant urban development and became a major tourist destination.",
      "date": "1900"
    }
  ]
}

