    {
      "headline": "Tylenol Becomes Over-the-Counter",
      "text": "In 1960, Tylenol was made available as an over-the-counter medication, significantly increasing its accessibility to consumers.",
      "date": "1960"
    },
    {
      "headline": "Tylenol Murders",
      "text": "In 1982, the Tylenol murders occurred when seven people in the Chicago area died after ingesting Tylenol capsules that had been laced with cyanide. This led to major changes in packaging and product safety.",
      "date": "1982"
    },
    {
      "headline": "Introduction of Tamper-Resistant Packaging",
      "text": "Following the 1982 Tylenol murders, Johnson & Johnson introduced tamper-resistant packaging for Tylenol products, setting a new standard for the pharmaceutical industry.",
      "date": "1982"
    },
    {
      "headline": "Recall of Tylenol Products",
      "text": "In 2010, Johnson & Johnson issued a massive recall of Tylenol products due to reports of a musty odor caused by contamination with a chemical used in wooden pallets.",
      "date": "2010"
    },
    {
      "headline": "Spin-off to Kenvue",
      "text": "In 2023, Johnson & Johnson completed the spin-off of its consumer health business, Kenvue, which now owns the Tylenol brand.",
      "date": "2023"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Beginning of the Early Modern Period",
      "text": "The early modern period is generally considered to have begun around the start of the 16th century. This period followed the Middle Ages and preceded the advent of modernity.",
      "date": "1500"
    },
    {
      "headline": "Discovery of the Americas",
      "text": "Christopher Columbus's voyages, beginning in 1492, led to the widespread awareness of the Americas in Europe, marking a significant event in the early modern period.",
      "date": "1492"
    },
    {
      "headline": "Protestant Reformation",
      "text": "The Protestant Reformation began in 1517 when Martin Luther published his Ninety-Five Theses, challenging the practices of the Catholic Church.",
      "date": "1517"
    },
    {
      "headline": "Scientific Revolution",
      "text": "The Scientific Revolution, which began in the 16th century, was a series of events that marked the emergence of modern science with developments in mathematics, physics, astronomy, biology, and chemistry.",
      "date": "1543"
    },
    {
      "headline": "Spanish Armada",
      "text": "In 1588, the Spanish Armada, a large fleet sent by Spain to invade England, was defeated by the English navy, marking a turning point in naval warfare and European power dynamics.",
      "date": "1588"
    },
    {
      "headline": "Thirty Years' War",
      "text": "The Thirty Years' War, a series of conflicts primarily fought in Central Europe, began in 1618 and ended in 1648 with the Peace of Westphalia, reshaping the political map of Europe.",
      "date": "1618"
    },
    {
      "headline": "Peace of Westphalia",
      "text": "The Peace of Westphalia, signed in 1648, ended the Thirty Years' War and marked a significant development in the state system and international law.",
      "date": "1648"
    },
    {
      "headline": "Glorious Revolution",
      "text": "The Glorious Revolution of 1688 saw the overthrow of King James II of England by a union of English Parliamentarians with the Dutch stadtholder William III of Orange-Nassau.",
      "date": "1688"
    },
    {
      "headline": "Enlightenment",
      "text": "The Enlightenment, an intellectual and philosophical movement that dominated the world of ideas in Europe during the 18th century, emphasized reason, individualism, and skepticism of traditional doctrines.",
      "date": "1700"
    },
    {
      "headline": "American Revolution",
      "text": "The American Revolution, which began in 1775, was a colonial revolt against British rule, leading to the founding of the United States of America.",
      "date": "1775"
    },
    {
      "headline": "French Revolution",
      "text": "The French Revolution, beginning in 1789, was a period of radical social and political change in France that had a major impact on France and the world.",
      "date": "1789"
    },
    {
      "headline": "End of the Early Modern Period",
      "text": "The early modern period is generally considered to have ended at the start of the 19th century, transitioning into the modern period.",
      "date": "1800"
    }
  ]
}

