      "headline": "Formation of the Kalmar Union",
      "text": "The Kalmar Union was formed on June 17, 1397, when Queen Margaret of Denmark successfully united the three kingdoms of Denmark, Sweden, and Norway under a single monarch at a meeting in Kalmar, Sweden.",
      "date": "1397-06-17"
    },
    {
      "headline": "Queen Margaret's Rule",
      "text": "Queen Margaret ruled as the de facto leader of the Kalmar Union until her death in 1412. She was instrumental in maintaining the union and managing the affairs of the three kingdoms.",
      "date": "1397-1412"
    },
    {
      "headline": "Death of Queen Margaret",
      "text": "Queen Margaret died on October 28, 1412. Her death marked the end of her influential leadership over the Kalmar Union.",
      "date": "1412-10-28"
    },
    {
      "headline": "Eric of Pomerania's Reign",
      "text": "Eric of Pomerania, the adopted son of Queen Margaret, became the king of the Kalmar Union after her death. His reign lasted from 1396 to 1439, but he faced significant challenges in maintaining the union.",
      "date": "1396-1439"
    },
    {
      "headline": "Deposition of Eric of Pomerania",
      "text": "Eric of Pomerania was deposed as king of the Kalmar Union in 1439 due to his inability to manage the kingdoms effectively and growing dissatisfaction among the nobility.",
      "date": "1439"
    },
    {
      "headline": "Charles VIII of Sweden's Reign",
      "text": "Charles VIII of Sweden was elected king of Sweden in 1448, marking a period of instability and intermittent conflicts within the Kalmar Union.",
      "date": "1448"
    },
    {
      "headline": "Christian I's Reign",
      "text": "Christian I became king of Denmark and Norway in 1448 and later king of Sweden in 1457, attempting to restore the union's stability.",
      "date": "1448-1457"
    },
    {
      "headline": "Sten Sture the Elder's Regency",
      "text": "Sten Sture the Elder served as regent of Sweden from 1470 to 1497 and again from 1501 to 1503, opposing the union and promoting Swedish independence.",
      "date": "1470-1497"
    },
    {
      "headline": "Stockholm Bloodbath",
      "text": "The Stockholm Bloodbath occurred in November 1520, when Christian II of Denmark executed Swedish nobles and clergy, intensifying resistance against the union.",
      "date": "1520-11"
    },
    {
      "headline": "End of the Kalmar Union",
      "text": "The Kalmar Union effectively ended in 1523 when Gustav Vasa was elected king of Sweden, leading to Sweden's independence from the union.",
      "date": "1523"
    }
  ]
}

