  "timeline": [
    {
      "headline": "Poland's Round Table Talks",
      "text": "In February 1989, the Polish government began negotiations with the opposition, leading to the Round Table Agreement in April 1989. This agreement allowed for partially free elections, which resulted in a significant victory for the opposition.",
      "date": "1989-02"
    },
