{
  "timeline": [
    {
      "headline": "Capture of Lahore",
      "text": "In 1799, Maharaja Ranjit Singh captured Lahore, marking the beginning of the Sikh Empire.",
      "date": "1799"
    },
    {
      "headline": "Formation of the Sikh Empire",
      "text": "The Sikh Empire was officially established in 1799, forged from a collection of autonomous misls under the leadership of Maharaja Ranjit Singh.",
      "date": "1799"
    },
    {
      "headline": "Conquest of Multan",
      "text": "In 1818, the Sikh Empire expanded its territory by conquering Multan.",
      "date": "1818"
    },
    {
      "headline": "Conquest of Kashmir",
      "text": "In 1819, the Sikh Empire further expanded by conquering Kashmir.",
      "date": "1819"
    },
    {
      "headline": "Conquest of Peshawar",
      "text": "In 1834, the Sikh Empire conquered Peshawar, extending its influence further west.",
      "date": "1834"
    },
    {
      "headline": "Death of Maharaja Ranjit Singh",
      "text": "Maharaja Ranjit Singh, the founder of the Sikh Empire, died on June 27, 1839.",
      "date": "1839-06-27"
    },
    {
      "headline": "First Anglo-Sikh War",
      "text": "The First Anglo-Sikh War took place from 1845 to 1846, resulting in the British gaining significant control over the Sikh Empire.",
      "date": "1845"
    },
    {
      "headline": "Treaty of Lahore",
      "text": "On March 9, 1846, the Treaty of Lahore was signed, marking the end of the First Anglo-Sikh War and ceding significant territories to the British.",
      "date": "1846-03-09"
    },
    {
      "headline": "Second Anglo-Sikh War",
      "text": "The Second Anglo-Sikh War occurred from 1848 to 1849, leading to the complete annexation of the Sikh Empire by the British East India Company.",
      "date": "1848"
    },
    {
      "headline": "Annexation by the British",
      "text": "In 1849, following the Second Anglo-Sikh War, the Sikh Empire was defeated and annexed by the British East India Company.",
      "date": "1849"
    }
  ]
}

