{
  "timeline": [
    {
      "headline": "Initial Development of the Roman Forum",
      "text": "The Roman Forum began as a marketplace in the 7th century BCE. It was initially a marshy area that was drained by the construction of the Cloaca Maxima, one of the world's earliest sewage systems.",
      "date": "-0700"
    },
    {
      "headline": "Construction of the Regia",
      "text": "The Regia, a building that served as the residence of the kings of Rome and later the office of the Pontifex Maximus, was constructed in the Roman Forum around the 7th century BCE.",
      "date": "-0700"
    },
    {
      "headline": "Temple of Saturn Built",
      "text": "The Temple of Saturn, one of the earliest temples in the Roman Forum, was dedicated in 497 BCE. It served as the state treasury.",
      "date": "-0497"
    },
    {
      "headline": "Temple of Castor and Pollux Dedicated",
      "text": "The Temple of Castor and Pollux was dedicated in 484 BCE. It commemorated the victory at the Battle of Lake Regillus.",
      "date": "-0484"
    },
    {
      "headline": "Construction of the Basilica Aemilia",
      "text": "The Basilica Aemilia, a public building for business and legal matters, was constructed in 179 BCE.",
      "date": "-0179"
    },
    {
      "headline": "Julius Caesar's Forum Expansion",
      "text": "Julius Caesar expanded the Roman Forum by constructing the Forum of Caesar, which was completed in 46 BCE.",
      "date": "-0046"
    },
    {
      "headline": "Augustus Completes the Temple of Divus Julius",
      "text": "In 29 BCE, Augustus completed the Temple of Divus Julius, dedicated to Julius Caesar, in the Roman Forum.",
      "date": "-0029"
    },
    {
      "headline": "Construction of the Arch of Septimius Severus",
      "text": "The Arch of Septimius Severus, a triumphal arch commemorating the victories of Emperor Septimius Severus, was constructed in 203 CE.",
      "date": "0203"
    },
    {
      "headline": "Decline of the Roman Forum",
      "text": "By the 4th century CE, the Roman Forum began to decline as the center of political life shifted to the new capital, Constantinople.",
      "date": "0300"
    },
    {
      "headline": "Excavations Begin",
      "text": "Excavations of the Roman Forum began in the 18th century, uncovering many of its ancient structures.",
      "date": "1700"
    }
  ]
}

