      "headline": "Birth of Benito Juárez",
      "text": "Benito Pablo Juárez García was born on March 21, 1806, in San Pablo Guelatao, Oaxaca, Mexico.",
      "date": "1806-03-21"
    },
    {
      "headline": "Graduation from Law School",
      "text": "In 1834, Benito Juárez graduated from the Institute of Sciences and Arts of Oaxaca with a law degree.",
      "date": "1834"
    },
    {
      "headline": "Elected to Oaxaca City Council",
      "text": "In 1831, Juárez was elected to the Oaxaca City Council, marking the beginning of his political career.",
      "date": "1831"
    },
    {
      "headline": "Governor of Oaxaca",
      "text": "Juárez served as the Governor of Oaxaca from 1847 to 1852, where he implemented liberal reforms.",
      "date": "1847"
    },
    {
      "headline": "Exile to New Orleans",
      "text": "In 1853, Juárez was exiled to New Orleans due to his opposition to the dictatorship of Antonio López de Santa Anna.",
      "date": "1853"
    },
    {
      "headline": "Return to Mexico and Minister of Justice",
      "text": "Juárez returned to Mexico in 1855 and was appointed Minister of Justice under President Juan Álvarez.",
      "date": "1855"
    },
    {
      "headline": "President of the Supreme Court",
      "text": "In 1857, Juárez became the President of the Supreme Court of Mexico, a position that placed him next in line for the presidency.",
      "date": "1857"
    },
    {
      "headline": "Assumes Presidency of Mexico",
      "text": "Juárez assumed the presidency of Mexico on January 19, 1858, following the resignation of Ignacio Comonfort.",
      "date": "1858-01-19"
    },
    {
      "headline": "Victory in the Reform War",
      "text": "Juárez led the Liberals to victory in the Reform War, which ended in 1861, solidifying his leadership and the liberal reforms.",
      "date": "1861"
    },
    {
      "headline": "French Intervention and Empire of Maximilian",
      "text": "In 1864, the French installed Maximilian I as Emperor of Mexico, but Juárez continued to lead the resistance against the French occupation.",
      "date": "1864"
    },
    {
      "headline": "Restoration of the Republic",
      "text": "On June 15, 1867, Juárez returned to Mexico City, marking the end of the French intervention and the restoration of the Republic.",
      "date": "1867-06-15"
    },
    {
      "headline": "Re-election as President",
      "text": "Juárez was re-elected as President of Mexico in 1867 and again in 1871, continuing his efforts to modernize the country.",
      "date": "1867"
    },
    {
      "headline": "Death of Benito Juárez",
      "text": "Benito Juárez died of a heart attack on July 18, 1872, in Mexico City, Mexico.",
      "date": "1872-07-18"
    }
  ]
}

