    {
      "headline": "Start of the Trade War",
      "text": "In January 2018, U.S. President Donald Trump began setting tariffs and other trade barriers on China with the goal of forcing it to make changes to what the U.S. says are longstanding unfair trade practices and intellectual property theft.",
      "date": "2018-01"
    },
    {
      "headline": "First Tariffs Imposed",
      "text": "On March 22, 2018, President Trump announced tariffs on $50 billion worth of Chinese imports, citing the Section 301 investigation into China's unfair trade practices.",
      "date": "2018-03-22"
    },
    {
      "headline": "China's Retaliation",
      "text": "In April 2018, China retaliated by imposing tariffs on $3 billion worth of U.S. goods, including pork, fruit, and steel pipes.",
      "date": "2018-04"
    },
    {
      "headline": "Further Escalation",
      "text": "On July 6, 2018, the U.S. imposed a 25% tariff on $34 billion of Chinese goods, prompting China to respond with tariffs on U.S. goods of equal value.",
      "date": "2018-07-06"
    },
    {
      "headline": "Additional Tariffs Announced",
      "text": "In September 2018, the U.S. announced tariffs on an additional $200 billion worth of Chinese goods, with China responding with tariffs on $60 billion of U.S. goods.",
      "date": "2018-09"
    },
    {
      "headline": "Trade Talks and Temporary Truce",
      "text": "In December 2018, the U.S. and China agreed to a 90-day truce to allow for trade negotiations.",
      "date": "2018-12"
    },
    {
      "headline": "Trade War Intensifies",
      "text": "In May 2019, the U.S. increased tariffs on $200 billion of Chinese goods from 10% to 25%, and China retaliated with tariffs on $60 billion of U.S. goods.",
      "date": "2019-05"
    },
    {
      "headline": "Phase One Agreement",
      "text": "In January 2020, the U.S. and China signed a phase-one trade agreement, easing some of the tariffs and increasing Chinese purchases of U.S. goods.",
      "date": "2020-01"
    },
    {
      "headline": "End of Trump's Presidency",
      "text": "By the end of President Trump's first term in January 2021, the trade war was widely characterized as a failure for the United States.",
      "date": "2021-01"
    }
  ]
}

