    },
    {
      "headline": "Attainment of Enlightenment",
      "text": "After years of ascetic practices and meditation, Siddhartha Gautama attained enlightenment under the Bodhi tree in Bodh Gaya, India, at the age of 35. He became known as the Buddha, meaning 'the Enlightened One'.",
      "date": "-0528"
    },
    {
      "headline": "First Sermon at Sarnath",
      "text": "Shortly after his enlightenment, the Buddha delivered his first sermon at the Deer Park in Sarnath, India, where he taught the Four Noble Truths and the Eightfold Path.",
      "date": "-0528"
    },
    {
      "headline": "Formation of the Sangha",
      "text": "The Buddha established a monastic community, known as the Sangha, which included monks and later nuns, to spread his teachings and practice the path to enlightenment.",
      "date": "-0528"
    },
    {
      "headline": "Death and Parinirvana",
      "text": "The Buddha passed away at the age of 80 in Kushinagar, India, achieving parinirvana, which is the final nirvana after death, free from the cycle of rebirth.",
      "date": "-0483"
    }
  ]
}

