    {
      "headline": "Establishment of Judaea as a Roman Province",
      "text": "In 6 CE, the Roman Empire established Judaea as a province, incorporating the regions of Judea, Idumea, Samaria, and Galilee, as well as parts of the coastal plain including Philistia.",
      "date": "0006"
    },
    {
      "headline": "Census of Quirinius",
      "text": "In 6 CE, the Roman governor Quirinius conducted a census in the newly established province of Judaea, which led to unrest among the Jewish population.",
      "date": "0006"
    },
    {
      "headline": "First Jewish–Roman War",
      "text": "The First Jewish–Roman War, also known as the Great Revolt, began in 66 CE as a result of religious tensions and Roman oppression, lasting until 73 CE.",
      "date": "0066"
    },
    {
      "headline": "Destruction of the Second Temple",
      "text": "In 70 CE, the Romans, led by future Emperor Titus, captured Jerusalem and destroyed the Second Temple, a pivotal event in Jewish history.",
      "date": "0070"
    },
    {
      "headline": "End of the First Jewish–Roman War",
      "text": "The First Jewish–Roman War ended in 73 CE with the fall of Masada, where the last Jewish rebels committed mass suicide rather than surrender to the Romans.",
      "date": "0073"
    },
    {
      "headline": "Kitos War",
      "text": "The Kitos War, a series of Jewish uprisings against Roman rule, occurred between 115 and 117 CE, primarily outside of Judaea but affecting the region.",
      "date": "0115"
    },
    {
      "headline": "Bar Kokhba Revolt",
      "text": "The Bar Kokhba Revolt, the third major Jewish rebellion against Roman rule, began in 132 CE under the leadership of Simon Bar Kokhba.",
      "date": "0132"
    },
    {
      "headline": "Suppression of the Bar Kokhba Revolt",
      "text": "The Bar Kokhba Revolt was suppressed by the Romans in 135 CE, leading to massive Jewish casualties and the expulsion of Jews from Jerusalem.",
      "date": "0135"
    },
    {
      "headline": "Renaming of the Province",
      "text": "Following the suppression of the Bar Kokhba Revolt in 135 CE, the Romans renamed the province Syria Palaestina in an attempt to minimize Jewish identification with the land.",
      "date": "0135"
    }
  ]
}

