{
  "timeline": [
    {
      "headline": "Emergence of Columbia as a Personification",
      "text": "Columbia emerged as a personification of the United States in the 18th century. The name 'Columbia' was derived from Christopher Columbus, and it was used as a poetic name for America.",
      "date": "1700"
    },
    {
      "headline": "Columbia in American Culture",
      "text": "Throughout the 18th and 19th centuries, Columbia was widely used in literature, art, and political discourse as a symbol of the United States.",
      "date": "1800"
    },
    {
      "headline": "Naming of the District of Columbia",
      "text": "In 1791, the capital of the United States was named the District of Columbia, further cementing the personification of Columbia as a symbol of the nation.",
      "date": "1791"
    },
    {
      "headline": "Columbia University Named",
      "text": "Columbia University, originally founded as King's College in 1754, was renamed in 1784 in honor of Columbia, reflecting the growing use of the personification.",
      "date": "1784"
    },
    {
      "headline": "Columbia Rediviva",
      "text": "The ship Columbia Rediviva, which completed the first American circumnavigation of the globe between 1787 and 1790, was named after the personification.",
      "date": "1787"
    },
    {
      "headline": "Columbia River Named",
      "text": "The Columbia River, one of the largest rivers in the Pacific Northwest, was named after the ship Columbia Rediviva in 1792.",
      "date": "1792"
    },
    {
      "headline": "Columbia in Popular Songs",
      "text": "The song 'Hail, Columbia' was written in 1798 and became an unofficial national anthem of the United States, further popularizing the personification.",
      "date": "1798"
    },
    {
      "headline": "Displacement by Statue of Liberty",
      "text": "By around 1920, images of the Statue of Liberty largely displaced Columbia as the female symbol of the United States, although Columbia continued to be used in various contexts.",
      "date": "1920"
    },
    {
      "headline": "Columbia Pictures Logo",
      "text": "Columbia remains a central element of the logo of the Hollywood film studio Columbia Pictures, founded in 1924, where she is depicted as a torch-bearing woman.",
      "date": "1924"
    }
  ]
}

