{
  "timeline": [
    {
      "headline": "Battle of Gonzales",
      "text": "On October 2, 1835, the first military engagement of the Texas Revolution took place at the Battle of Gonzales. Texian rebels resisted Mexican forces attempting to retrieve a cannon, marking the start of the revolution.",
      "date": "1835-10-02"
    },
    {
      "headline": "Siege of Bexar",
      "text": "From October to December 1835, Texian forces laid siege to the Mexican garrison at San Antonio de Bexar. The siege ended on December 9, 1835, with the surrender of Mexican General Martín Perfecto de Cos.",
      "date": "1835-12-09"
    },
    {
      "headline": "Declaration of Independence",
      "text": "On March 2, 1836, delegates at the Convention of 1836 signed the Texas Declaration of Independence, formally declaring independence from Mexico.",
      "date": "1836-03-02"
    },
    {
      "headline": "Fall of the Alamo",
      "text": "The Battle of the Alamo ended on March 6, 1836, after a 13-day siege by Mexican troops led by General Santa Anna. The Mexican forces overran the Alamo Mission in San Antonio, killing all of the Texian defenders.",
      "date": "1836-03-06"
    },
    {
      "headline": "Goliad Massacre",
      "text": "On March 27, 1836, over 400 Texian prisoners of war were executed by the Mexican Army at Goliad, under orders from General Santa Anna.",
      "date": "1836-03-27"
    },
    {
      "headline": "Battle of San Jacinto",
      "text": "On April 21, 1836, Texian forces led by General Sam Houston defeated the Mexican Army in a decisive battle at San Jacinto, capturing General Santa Anna and securing Texian independence.",
      "date": "1836-04-21"
    },
    {
      "headline": "Treaties of Velasco",
      "text": "On May 14, 1836, the Treaties of Velasco were signed by Santa Anna and the Republic of Texas, ending hostilities and recognizing Texas independence, although the Mexican government later repudiated the treaties.",
      "date": "1836-05-14"
    }
  ]
}

