{
  "timeline": [
    {
      "headline": "Beginning of the 20th Century",
      "text": "The 20th century began on January 1, 1901, marking the start of the 10th and last century of the 2nd millennium.",
      "date": "1901-01-01"
    },
    {
      "headline": "World War I",
      "text": "World War I, also known as the Great War, began on July 28, 1914, and lasted until November 11, 1918. It involved many of the world's great powers and was one of the deadliest conflicts in history.",
      "date": "1914-07-28"
    },
    {
      "headline": "Russian Revolution",
      "text": "The Russian Revolution in 1917 led to the overthrow of the Russian monarchy and the establishment of the Soviet Union.",
      "date": "1917"
    },
    {
      "headline": "End of World War I",
      "text": "World War I ended on November 11, 1918, with the signing of the Armistice of Compiègne.",
      "date": "1918-11-11"
    },
    {
      "headline": "Great Depression",
      "text": "The Great Depression was a severe worldwide economic depression that took place during the 1930s, beginning in the United States after a major fall in stock prices that started around September 4, 1929.",
      "date": "1929-09-04"
    },
    {
      "headline": "World War II",
      "text": "World War II was a global war that lasted from September 1, 1939, to September 2, 1945. It involved the vast majority of the world's countries and was the deadliest conflict in human history.",
      "date": "1939-09-01"
    },
    {
      "headline": "End of World War II",
      "text": "World War II ended on September 2, 1945, with the unconditional surrender of the Axis powers.",
      "date": "1945-09-02"
    },
    {
      "headline": "United Nations Founded",
      "text": "The United Nations was founded on October 24, 1945, to promote international cooperation and to prevent future conflicts.",
      "date": "1945-10-24"
    },
    {
      "headline": "Cold War Begins",
      "text": "The Cold War, a period of geopolitical tension between the Soviet Union and the United States and their respective allies, began shortly after World War II and lasted until the early 1990s.",
      "date": "1947"
    },
    {
      "headline": "Civil Rights Movement",
      "text": "The Civil Rights Movement in the United States was a decades-long struggle by African Americans and their allies to end institutionalized racial discrimination, disenfranchisement, and racial segregation. It gained momentum in the 1950s and 1960s.",
      "date": "1950"
    },
    {
      "headline": "First Man on the Moon",
      "text": "On July 20, 1969, American astronaut Neil Armstrong became the first person to walk on the Moon during NASA's Apollo 11 mission.",
      "date": "1969-07-20"
    },
    {
      "headline": "Fall of the Berlin Wall",
      "text": "The Berlin Wall, a symbol of the Cold War, fell on November 9, 1989, leading to the reunification of Germany.",
      "date": "1989-11-09"
