    },
    {
      "headline": "Exhibition at the World's Fair",
      "text": "In 1900, the Russian matryoshka dolls were presented at the World's Fair in Paris, where they earned a bronze medal and gained international recognition.",
      "date": "1900"
    },
    {
      "headline": "Mass Production Begins",
      "text": "By the early 20th century, matryoshka dolls began to be mass-produced in Russia, becoming a popular souvenir and symbol of Russian folk art.",
      "date": "1900-1910"
    },
    {
      "headline": "Cultural Symbolism",
      "text": "Throughout the 20th century, matryoshka dolls became a symbol of Russian culture and heritage, often used to represent the idea of 'motherhood' and 'fertility'.",
      "date": "1900-2000"
    }
  ]
}

