{
  "timeline": [
    {
      "headline": "Origins of Serfdom",
      "text": "Serfdom began to develop during late antiquity and the Early Middle Ages in Europe as a system of debt bondage and indentured servitude.",
      "date": "-0500"
    },
    {
      "headline": "Serfdom in the Carolingian Empire",
      "text": "During the 8th and 9th centuries, serfdom became more widespread in the Carolingian Empire, as the manorial system became the dominant economic structure.",
      "date": "0800"
    },
    {
      "headline": "Serfdom in Medieval Europe",
      "text": "By the 11th century, serfdom was a well-established institution in medieval Europe, particularly in France, England, and Germany.",
      "date": "1000"
    },
    {
      "headline": "Decline of Serfdom in Western Europe",
      "text": "Starting in the 14th century, serfdom began to decline in Western Europe due to economic changes, the Black Death, and peasant revolts.",
      "date": "1300"
    },
    {
      "headline": "Abolition of Serfdom in England",
      "text": "Serfdom effectively ended in England by the 16th century, as the system transitioned to wage labor and tenant farming.",
      "date": "1500"
    },
    {
      "headline": "Expansion of Serfdom in Eastern Europe",
      "text": "In the 16th and 17th centuries, serfdom expanded in Eastern Europe, particularly in Russia and Poland, as these regions sought to increase agricultural production.",
      "date": "1600"
    },
    {
      "headline": "Abolition of Serfdom in France",
      "text": "Serfdom was abolished in France during the French Revolution, with the formal decree issued in 1789.",
      "date": "1789"
    },
    {
      "headline": "Abolition of Serfdom in Austria",
      "text": "Serfdom was abolished in the Austrian Empire in 1848, following the revolutionary movements across Europe.",
      "date": "1848"
    },
    {
      "headline": "Abolition of Serfdom in Russia",
      "text": "Serfdom was abolished in Russia by the Emancipation Reform of 1861, which freed millions of serfs.",
      "date": "1861"
    }
  ]
}

