{
  "timeline": [
    {
      "headline": "Berlin Conference",
      "text": "The Berlin Conference on Africa took place from 1884 to 1885, where European powers recognized King Leopold II's claim to the Congo Basin, believing he was involved in humanitarian work.",
      "date": "1884-1885"
    },
    {
      "headline": "Establishment of the Congo Free State",
      "text": "On 29 May 1885, King Leopold II announced his plan to name his possessions 'the Congo Free State'. This name officially replaced 'International Association of the Congo' on 1 August 1885.",
      "date": "1885-08-01"
    },
    {
      "headline": "Leopold's Control",
      "text": "King Leopold II privately controlled the Congo Free State from Brussels. He never visited the region himself, ruling it as a personal possession.",
      "date": "1885"
    },
    {
      "headline": "Atrocities and Exploitation",
      "text": "Throughout the late 19th and early 20th centuries, the Congo Free State was the site of severe exploitation and atrocities, including forced labor and violence against the local population to extract resources like rubber.",
      "date": "1885-1908"
    },
    {
      "headline": "International Outcry and Reform",
      "text": "Reports of atrocities in the Congo Free State led to international outcry and pressure on King Leopold II to reform the administration of the region.",
      "date": "1900s"
    },
    {
      "headline": "Annexation by Belgium",
      "text": "In 1908, due to international pressure and condemnation of the abuses in the Congo Free State, the Belgian government annexed the territory, transforming it into the Belgian Congo.",
      "date": "1908"
    }
  ]
}

