{
  "timeline": [
    {
      "headline": "Establishment of the Independent State of Croatia",
      "text": "The Independent State of Croatia (NDH) was established on 10 April 1941, following the invasion of Yugoslavia by Axis powers. It was a puppet state of Nazi Germany and Fascist Italy.",
      "date": "1941-04-10"
    },
    {
      "headline": "Pact with Nazi Germany and Fascist Italy",
      "text": "On 15 June 1941, the NDH signed a pact with Nazi Germany and Fascist Italy, solidifying its status as a puppet state under their influence.",
      "date": "1941-06-15"
    },
    {
      "headline": "Genocide and Ethnic Cleansing",
      "text": "Throughout its existence, the NDH engaged in genocide and ethnic cleansing, targeting Serbs, Jews, and Roma populations. The Jasenovac concentration camp became infamous for its atrocities.",
      "date": "1941"
    },
    {
      "headline": "Resistance Movements",
      "text": "Resistance movements, including the Yugoslav Partisans led by Josip Broz Tito, began to form and gain strength against the NDH and Axis forces starting in 1941.",
      "date": "1941"
    },
    {
      "headline": "Italian Annexation of Dalmatia",
      "text": "In 1941, parts of Dalmatia were annexed by Italy, reducing the territory controlled by the NDH.",
      "date": "1941"
    },
    {
      "headline": "Battle of Neretva",
      "text": "In early 1943, the Battle of Neretva took place, where Yugoslav Partisans successfully evaded Axis forces, marking a significant victory for the resistance.",
      "date": "1943"
    },
    {
      "headline": "Capitulation of Italy",
      "text": "In September 1943, Italy capitulated, leading to changes in control over territories previously annexed by Italy, including parts of the NDH.",
      "date": "1943-09"
    },
    {
      "headline": "Collapse of the Independent State of Croatia",
      "text": "The NDH began to collapse in 1944 as the Yugoslav Partisans gained ground. By May 1945, the NDH was effectively dissolved following the defeat of Axis forces in Yugoslavia.",
      "date": "1945-05"
    },
    {
      "headline": "End of World War II in Europe",
      "text": "On 8 May 1945, World War II in Europe officially ended, marking the final dissolution of the Independent State of Croatia.",
      "date": "1945-05-08"
    }
  ]
}

