{
  "timeline": [
    {
      "headline": "Formation of the Sundarbans",
      "text": "The Sundarbans began forming as a deltaic region at the confluence of the Ganges, Brahmaputra, and Meghna Rivers in the Bay of Bengal. This process has been ongoing for thousands of years, with sediment deposition creating the largest mangrove forest in the world.",
      "date": "-10000"
    },
    {
      "headline": "Sundarbans as a Habitat",
      "text": "The Sundarbans developed into a rich habitat supporting diverse wildlife, including the Bengal tiger, spotted deer, crocodiles, and various bird species. The unique ecosystem is characterized by its mangrove forests and tidal waterways.",
      "date": "0000"
    },
    {
      "headline": "British Colonial Period",
      "text": "During the British colonial period, the Sundarbans were surveyed and mapped. The British administration recognized the economic potential of the forest resources, including timber and honey.",
      "date": "1757"
    },
    {
      "headline": "Establishment of Sundarbans Reserve Forest",
      "text": "In 1875, the British government declared the Sundarbans as a reserve forest, marking the beginning of formal conservation efforts in the region.",
      "date": "1875"
    },
    {
      "headline": "Sundarbans National Park Establishment",
      "text": "In 1984, the Indian government established the Sundarbans National Park, which later became a core area of the Sundarbans Tiger Reserve, to protect the unique biodiversity of the region.",
      "date": "1984"
    },
    {
      "headline": "UNESCO World Heritage Site Designation",
      "text": "In 1987, the Sundarbans in Bangladesh were designated as a UNESCO World Heritage Site, recognizing their global ecological significance and the need for conservation.",
      "date": "1987"
    },
    {
      "headline": "UNESCO World Heritage Site Designation for Sundarbans National Park",
      "text": "In 1987, the Sundarbans National Park in India was also designated as a UNESCO World Heritage Site, highlighting its importance as a protected area for biodiversity.",
      "date": "1987"
    },
    {
      "headline": "Cyclone Sidr Impact",
      "text": "In November 2007, Cyclone Sidr struck the Sundarbans, causing extensive damage to the mangrove forests and affecting the local wildlife and human populations.",
      "date": "2007-11"
    },
    {
      "headline": "Cyclone Aila Impact",
      "text": "In May 2009, Cyclone Aila hit the Sundarbans, leading to severe flooding and destruction of habitats, further challenging conservation efforts in the region.",
      "date": "2009-05"
    }
  ]
}

