      "date": "-0300"
    },
    {
      "headline": "Archimedes' Contributions",
      "text": "Around 250 BC, Archimedes made significant contributions to geometry, calculus, and the understanding of the concept of infinity.",
      "date": "-0250"
    },
    {
      "headline": "Diophantus and Algebra",
      "text": "Around 250 AD, Diophantus, known as the 'father of algebra', wrote 'Arithmetica', a series of books that laid the groundwork for algebraic notation and methods.",
      "date": "0250"
    },
    {
      "headline": "Development of Indian Mathematics",
      "text": "Around 500 AD, Indian mathematicians like Aryabhata and Brahmagupta made significant advances in algebra, trigonometry, and the concept of zero.",
      "date": "0500"
    },
    {
      "headline": "Islamic Golden Age of Mathematics",
      "text": "From the 8th to the 14th century, Islamic scholars preserved and expanded upon Greek and Indian mathematical knowledge, contributing to algebra, geometry, and trigonometry.",
      "date": "0800"
    },
    {
      "headline": "Fibonacci's Liber Abaci",
      "text": "In 1202, Leonardo of Pisa, known as Fibonacci, published 'Liber Abaci', introducing the Hindu-Arabic numeral system to Europe.",
      "date": "1202"
    },
    {
      "headline": "Renaissance and the Birth of Modern Mathematics",
      "text": "During the 16th and 17th centuries, European mathematicians like Descartes and Newton developed new mathematical concepts, including analytic geometry and calculus.",
      "date": "1600"
    }
  ]
}

