{
  "timeline": [
    {
      "headline": "Establishment of the Oracle of Delphi",
      "text": "The Oracle of Delphi, where the Pythia served, was established as a major religious site in ancient Greece. It became a central place for the worship of Apollo and a significant cultural and religious center.",
      "date": "-0800"
    },
    {
      "headline": "Role of the Pythia",
      "text": "The Pythia served as the high priestess of the Temple of Apollo at Delphi. She was considered the mouthpiece of Apollo and delivered prophecies to those who sought guidance.",
      "date": "-0800"
    },
    {
      "headline": "Peak of the Oracle's Influence",
      "text": "During the 6th century BCE, the Oracle of Delphi reached the height of its influence, attracting visitors from all over the Greek world and beyond, including leaders and common people seeking advice.",
      "date": "-0600"
    },
    {
      "headline": "Consultation Process",
      "text": "The Pythia would enter a trance-like state, often induced by vapors from a chasm in the earth, and deliver cryptic messages that were interpreted by priests.",
      "date": "-0600"
    },
    {
      "headline": "Decline of the Oracle",
      "text": "The influence of the Oracle of Delphi began to decline during the rise of the Roman Empire, as political and religious changes reduced its significance.",
      "date": "-00200"
    },
    {
      "headline": "Closure of the Temple",
      "text": "The Temple of Apollo at Delphi was closed by decree of the Roman Emperor Theodosius I, as part of his efforts to suppress pagan practices in favor of Christianity.",
      "date": "0385"
    }
  ]
}

