{
  "timeline": [
    {
      "headline": "Discovery of the Money Pit",
      "text": "In 1795, a teenager named Daniel McGinnis discovered a depression in the ground on Oak Island. This led to the first excavation attempts, which uncovered layers of logs and other materials, sparking the legend of the 'Money Pit'.",
      "date": "1795"
    },
    {
      "headline": "Formation of the Onslow Company",
      "text": "In 1804, the Onslow Company was formed to further excavate the Money Pit. They reached a depth of 90 feet and discovered layers of logs, charcoal, putty, and coconut fiber.",
      "date": "1804"
    },
    {
      "headline": "Discovery of the Inscribed Stone",
      "text": "In 1804, during the Onslow Company's excavation, a stone inscribed with mysterious symbols was reportedly found at a depth of 90 feet.",
      "date": "1804"
    },
    {
      "headline": "Truro Company Excavation",
      "text": "In 1849, the Truro Company was formed to continue the search. They drilled into the pit and reported striking wooden chests or platforms.",
      "date": "1849"
    },
    {
      "headline": "The Oak Island Association",
      "text": "In 1861, the Oak Island Association was formed and attempted to excavate the pit. A collapse and flooding halted their efforts, and one worker died during the excavation.",
      "date": "1861"
    },
    {
      "headline": "Formation of the Oak Island Treasure Company",
      "text": "In 1893, the Oak Island Treasure Company was formed. They attempted to excavate the pit but were thwarted by flooding.",
      "date": "1893"
    },
    {
      "headline": "The Restall Tragedy",
      "text": "On August 17, 1965, Robert Restall, his son, and two other workers died from gas exposure during an excavation attempt.",
      "date": "1965-08-17"
    },
    {
      "headline": "The Triton Alliance",
      "text": "In 1967, the Triton Alliance was formed by a group of investors, including Dan Blankenship and David Tobias, to continue the search for treasure.",
      "date": "1967"
    },
    {
      "headline": "Discovery of the Cross",
      "text": "In 1981, a cross-shaped formation of stones was discovered on the island, adding to the mystery and speculation about the island's history.",
      "date": "1981"
    },
    {
      "headline": "The Lagina Brothers' Involvement",
      "text": "In 2006, brothers Rick and Marty Lagina purchased a controlling interest in Oak Island Tours, Inc., and began their own search for the treasure.",
      "date": "2006"
    },
    {
      "headline": "The Curse of Oak Island TV Show",
      "text": "In 2014, the History Channel premiered 'The Curse of Oak Island', a reality TV series documenting the Lagina brothers' ongoing efforts to solve the mystery.",
      "date": "2014"
    }
  ]
}

