    {
      "headline": "Introduction of the 'Peelian Principles'",
      "text": "The Metropolitan Police was founded on the 'Peelian Principles', which emphasized the importance of crime prevention, public cooperation, and the ethical conduct of officers.",
      "date": "1829"
    },
    {
      "headline": "First Female Officers",
      "text": "The first women were appointed to the Metropolitan Police in 1919, marking a significant step towards gender equality within the force.",
      "date": "1919"
    },
    {
      "headline": "Move to New Scotland Yard",
      "text": "In 1967, the headquarters of the Metropolitan Police moved to a new building on Broadway, which was officially named New Scotland Yard.",
      "date": "1967"
    },
    {
      "headline": "Introduction of the Police National Computer",
      "text": "In 1974, the Metropolitan Police introduced the Police National Computer, a major technological advancement in law enforcement.",
      "date": "1974"
    },
    {
      "headline": "Counter-Terrorism Command Established",
      "text": "The Counter-Terrorism Command was established in 2006, combining the Anti-Terrorist Branch and Special Branch to enhance the Met's ability to combat terrorism.",
      "date": "2006"
    },
    {
      "headline": "Move to Victoria Embankment",
      "text": "In 2016, the Metropolitan Police headquarters moved to the Curtis Green Building on Victoria Embankment, retaining the name New Scotland Yard.",
      "date": "2016"
    }
  ]
}

