    {
      "headline": "Start of the Tigray War",
      "text": "The Tigray War began on 3 November 2020, when the Tigray People's Liberation Front (TPLF) attacked the Northern Command headquarters of the Ethiopian National Defense Force in the Tigray Region.",
      "date": "2020-11-03"
    },
    {
      "headline": "Ethiopian Government Declares State of Emergency",
      "text": "On 4 November 2020, the Ethiopian federal government declared a six-month state of emergency in the Tigray Region in response to the TPLF's attack.",
      "date": "2020-11-04"
    },
    {
      "headline": "Capture of Mekelle",
      "text": "On 28 November 2020, Ethiopian federal forces captured Mekelle, the capital of the Tigray Region, marking a significant point in the conflict.",
      "date": "2020-11-28"
    },
    {
      "headline": "TPLF Regains Control of Mekelle",
      "text": "On 28 June 2021, TPLF forces regained control of Mekelle after Ethiopian federal forces withdrew from the city.",
      "date": "2021-06-28"
    },
    {
      "headline": "Ceasefire Announcement",
      "text": "On 28 June 2021, the Ethiopian government announced a unilateral ceasefire, although fighting continued in various parts of the Tigray Region.",
      "date": "2021-06-28"
    },
    {
      "headline": "TPLF Advances into Amhara and Afar Regions",
      "text": "In July 2021, TPLF forces advanced into the neighboring Amhara and Afar regions, expanding the conflict beyond Tigray.",
      "date": "2021-07"
    },
    {
      "headline": "Ethiopian Government Recaptures Key Towns",
      "text": "In December 2021, Ethiopian federal forces recaptured key towns in the Amhara and Afar regions from TPLF forces.",
      "date": "2021-12"
    },
    {
      "headline": "Peace Talks Begin",
      "text": "In October 2022, peace talks began between the Ethiopian government and TPLF representatives in South Africa, mediated by the African Union.",
      "date": "2022-10"
    },
    {
      "headline": "Peace Agreement Signed",
      "text": "On 2 November 2022, a peace agreement was signed between the Ethiopian government and the TPLF, effectively ending the Tigray War.",
      "date": "2022-11-02"
    },
    {
      "headline": "End of the Tigray War",
      "text": "The Tigray War officially ended on 3 November 2022, following the peace agreement signed the previous day.",
      "date": "2022-11-03"
    }
  ]
}

