{
  "timeline": [
    {
      "headline": "Birth of Neoclassicism",
      "text": "Neoclassicism emerged as a Western cultural movement in the decorative and visual arts, literature, theatre, music, and architecture. It drew inspiration from the art and culture of classical antiquity and was born in Rome, largely due to the writings of Johann Joachim Winckelmann during the rediscovery of Pompeii and Herculaneum.",
      "date": "1750"
    },
    {
      "headline": "Rediscovery of Pompeii and Herculaneum",
      "text": "The rediscovery of the ancient cities of Pompeii and Herculaneum in the mid-18th century played a significant role in the birth of Neoclassicism. These archaeological finds sparked a renewed interest in classical antiquity.",
      "date": "1748"
    },
    {
      "headline": "Influence of Johann Joachim Winckelmann",
      "text": "Johann Joachim Winckelmann's writings, particularly his 'History of Ancient Art' published in 1764, were instrumental in shaping the Neoclassical movement. He advocated for the emulation of classical art, emphasizing its noble simplicity and calm grandeur.",
      "date": "1764"
    },
    {
      "headline": "Spread of Neoclassicism through the Grand Tour",
      "text": "The popularity of Neoclassicism expanded throughout Europe as a generation of European art students completed their Grand Tour, returning from Italy to their home countries with newly rediscovered Greco-Roman ideals.",
      "date": "1760"
    },
    {
      "headline": "Neoclassicism and the Age of Enlightenment",
      "text": "The main Neoclassical movement coincided with the 18th-century Age of Enlightenment, a period that emphasized reason, science, and intellectual interchange, which aligned with the ideals of Neoclassicism.",
      "date": "1750-1800"
    },
    {
      "headline": "Neoclassicism in Architecture",
      "text": "In architecture, Neoclassicism endured throughout the 19th, 20th, and into the 21st century. It was characterized by its use of classical orders, symmetry, and proportion.",
      "date": "1800-2000"
    },
    {
      "headline": "Competition with Romanticism",
      "text": "In the early 19th century, Neoclassicism began to compete with Romanticism, a movement that emphasized emotion and individualism, contrasting with the order and rationality of Neoclassicism.",
      "date": "1800"
    }
  ]
}

