{
  "timeline": [
    {
      "headline": "Beginning of the Warring States Period",
      "text": "The Warring States period began in 475 BCE, following the end of the Spring and Autumn period. This era was marked by the fragmentation of the Zhou dynasty's power and the rise of individual states.",
      "date": "-0475"
    },
    {
      "headline": "Battle of Guiling",
      "text": "In 354 BCE, the Battle of Guiling took place between the states of Qi and Wei. Qi emerged victorious, showcasing the strategic prowess of Sun Bin.",
      "date": "-0354"
    },
    {
      "headline": "Battle of Maling",
      "text": "In 342 BCE, the Battle of Maling was fought between the states of Qi and Wei. Qi, under the leadership of Sun Bin, defeated Wei using innovative military tactics.",
      "date": "-0342"
    },
    {
      "headline": "Reforms of Shang Yang",
      "text": "Around 356 BCE, Shang Yang implemented a series of reforms in the state of Qin, which strengthened its military and economic power, setting the stage for its eventual dominance.",
      "date": "-0356"
    },
    {
      "headline": "Battle of Changping",
      "text": "In 260 BCE, the Battle of Changping occurred between the states of Qin and Zhao. Qin's decisive victory significantly weakened Zhao and bolstered Qin's power.",
      "date": "-0260"
    },
    {
      "headline": "Qin's Conquest of Han",
      "text": "In 230 BCE, the state of Qin conquered the state of Han, marking the beginning of Qin's campaign to unify China.",
      "date": "-0230"
    },
    {
      "headline": "Qin's Conquest of Zhao",
      "text": "In 228 BCE, Qin conquered the state of Zhao, further consolidating its power in the region.",
      "date": "-0228"
    },
    {
      "headline": "Qin's Conquest of Wei",
      "text": "In 225 BCE, the state of Qin conquered Wei, continuing its expansion and unification efforts.",
      "date": "-0225"
    },
    {
      "headline": "Qin's Conquest of Chu",
      "text": "In 223 BCE, Qin defeated the state of Chu, one of its major rivals, bringing it closer to unifying China.",
      "date": "-0223"
    },
    {
      "headline": "Qin's Conquest of Yan",
      "text": "In 222 BCE, the state of Qin conquered Yan, furthering its dominance over the other warring states.",
      "date": "-0222"
    },
    {
      "headline": "Qin's Conquest of Qi",
      "text": "In 221 BCE, Qin conquered the state of Qi, completing its unification of China and marking the end of the Warring States period.",
      "date": "-0221"
    },
    {
      "headline": "Establishment of the Qin Dynasty",
      "text": "In 221 BCE, following the conquest of all rival states, the Qin dynasty was established, marking the beginning of imperial China.",
      "date": "-0221"
    }
  ]
}

