    },
    {
      "headline": "John C. Frémont's Expedition",
      "text": "In 1843, John C. Frémont led an expedition to map the Great Salt Lake and its surrounding areas, providing one of the first detailed descriptions of the lake.",
      "date": "1843"
    },
    {
      "headline": "Completion of the Transcontinental Railroad",
      "text": "In 1869, the completion of the Transcontinental Railroad brought increased attention and accessibility to the Great Salt Lake region.",
      "date": "1869"
    },
    {
      "headline": "Construction of the Lucin Cutoff",
      "text": "In 1904, the Southern Pacific Railroad completed the Lucin Cutoff, a railroad line that crossed the Great Salt Lake, significantly reducing travel time.",
      "date": "1904"
    },
    {
      "headline": "Establishment of Great Salt Lake State Park",
      "text": "In 1978, Great Salt Lake State Park was established to provide recreational opportunities and preserve the natural environment of the lake.",
      "date": "1978"
    },
    {
      "headline": "Record High Water Levels",
      "text": "In 1986, the Great Salt Lake reached record high water levels, causing significant flooding and damage to surrounding areas.",
      "date": "1986"
    },
    {
      "headline": "Record Low Water Levels",
      "text": "In 2021, the Great Salt Lake reached record low water levels due to prolonged drought and water diversion.",
      "date": "2021"
    }
