{
  "timeline": [
    {
      "headline": "Planning of the Kyūjō Incident",
      "text": "In early August 1945, as Japan faced imminent defeat in World War II, a group of Japanese military officers began planning a coup to prevent the surrender of Japan. The coup was intended to preserve the kokutai (national polity) and continue the war effort.",
      "date": "1945-08"
    },
    {
      "headline": "Emperor Hirohito's Decision to Surrender",
      "text": "On August 14, 1945, Emperor Hirohito decided to surrender to the Allies and recorded a speech to be broadcast to the Japanese people, announcing the surrender.",
      "date": "1945-08-14"
    },
    {
      "headline": "Attempted Coup Begins",
      "text": "On the night of August 14, 1945, the coup plotters, led by Major Kenji Hatanaka and other officers from the Ministry of War and the Imperial Guard, attempted to seize control of the Imperial Palace and prevent the broadcast of the Emperor's surrender speech.",
      "date": "1945-08-14"
    },
    {
      "headline": "Occupation of the Imperial Palace",
      "text": "The coup plotters occupied the Imperial Palace, seeking to find and destroy the recording of the Emperor's surrender speech. They also attempted to secure the support of senior military leaders.",
      "date": "1945-08-14"
    },
    {
      "headline": "Failure of the Coup",
      "text": "By the early hours of August 15, 1945, the coup had failed. Key military leaders refused to support the coup, and the plotters were unable to locate the recording of the Emperor's speech.",
      "date": "1945-08-15"
    },
    {
      "headline": "Broadcast of the Emperor's Speech",
      "text": "On August 15, 1945, Emperor Hirohito's recorded speech was broadcast to the Japanese public, announcing Japan's surrender and the end of World War II.",
      "date": "1945-08-15"
    },
    {
      "headline": "Aftermath and Consequences",
      "text": "Following the failure of the coup, Major Kenji Hatanaka and several other conspirators committed suicide. The incident highlighted the deep divisions within the Japanese military at the end of the war.",
      "date": "1945-08-15"
    }
  ]
}

