    },
    {
      "headline": "Co-National Anthem of Germany",
      "text": "From 1933, following the Nazi rise to power, the Horst-Wessel-Lied was made the co-national anthem of Germany, alongside the first stanza of the 'Deutschlandlied'.",
      "date": "1933"
    },
    {
      "headline": "End of Use as Co-National Anthem",
      "text": "The Horst-Wessel-Lied remained the co-national anthem of Germany until the end of World War II in 1945, when the Nazi regime was defeated.",
      "date": "1945"
    }
  ]
}

