{
  "timeline": [
    {
      "headline": "Foundation of Cynicism",
      "text": "Cynicism was founded by Antisthenes, a pupil of Socrates, in the late 5th century BCE. He emphasized living a life of virtue in agreement with nature.",
      "date": "-0400"
    },
    {
      "headline": "Diogenes of Sinope",
      "text": "Diogenes of Sinope, one of the most famous Cynics, lived from approximately 412 or 404 BCE to 323 BCE. He is known for his ascetic lifestyle and for carrying a lantern in daylight, claiming to be looking for an honest man.",
      "date": "-0404"
    },
    {
      "headline": "Diogenes' Death",
      "text": "Diogenes of Sinope died in 323 BCE. His life and teachings greatly influenced the development of Cynicism.",
      "date": "-0323"
    },
    {
      "headline": "Crates of Thebes",
      "text": "Crates of Thebes, a student of Diogenes, flourished around 328-325 BCE. He is known for giving away his wealth to live a Cynic life and for his marriage to Hipparchia, who also adopted Cynic philosophy.",
      "date": "-0328"
    },
    {
      "headline": "Zeno of Citium",
      "text": "Zeno of Citium, who founded Stoicism, was influenced by Cynicism after studying under Crates of Thebes around 300 BCE.",
      "date": "-0300"
    },
    {
      "headline": "Roman Cynicism",
      "text": "Cynicism continued into the Roman Imperial period, influencing Roman thinkers and being practiced by figures such as Demetrius the Cynic in the 1st century CE.",
      "date": "0100"
    },
    {
      "headline": "Decline of Cynicism",
      "text": "By the 4th century CE, Cynicism began to decline as a distinct philosophical movement, overshadowed by the rise of Christianity and other philosophical schools.",
      "date": "0400"
    }
  ]
}

{
  "timeline": [
