      "headline": "Foundation of Tangier",
      "text": "Tangier is believed to have been founded as a Phoenician colony as early as the 10th century BCE.",
      "date": "-1000"
    },
    {
      "headline": "Roman Rule",
      "text": "Tangier became part of the Roman Empire in the 1st century BCE, known as Tingis, and later became the capital of the Roman province of Mauretania Tingitana.",
      "date": "-0040"
    },
    {
      "headline": "Vandal and Byzantine Periods",
      "text": "After the fall of the Roman Empire, Tangier was occupied by the Vandals in the 5th century CE and later by the Byzantines in the 6th century.",
      "date": "0500"
    },
    {
      "headline": "Islamic Conquest",
      "text": "Tangier was conquered by the Umayyad Caliphate in 702 CE, marking the beginning of Islamic rule in the region.",
      "date": "0702"
    },
    {
      "headline": "Portuguese Occupation",
      "text": "The city was occupied by the Portuguese in 1471, becoming a strategic point for their expansion.",
      "date": "1471"
    },
    {
      "headline": "English Rule",
      "text": "Tangier was given to England as part of the dowry of Catherine of Braganza when she married King Charles II in 1661.",
      "date": "1661"
    },
    {
      "headline": "Return to Moroccan Control",
      "text": "Tangier was returned to Moroccan control in 1684 after being abandoned by the English.",
      "date": "1684"
    },
    {
      "headline": "International Zone",
      "text": "In 1923, Tangier was established as an international zone, governed by multiple European powers.",
      "date": "1923"
    },
    {
      "headline": "Reintegration into Morocco",
      "text": "Tangier was reintegrated into Morocco in 1956 following the country's independence from French and Spanish colonial rule.",
      "date": "1956"
    }
  ]
}

