    {
      "headline": "Introduction of Intrathecal Baclofen Therapy",
      "text": "In the 1980s, intrathecal baclofen therapy was introduced, allowing for direct delivery of the medication to the spinal cord via a pump, providing effective relief for severe spasticity.",
      "date": "1980"
    },
    {
      "headline": "Off-label Use for Alcohol Use Disorder",
      "text": "In the early 2000s, Baclofen began to be used off-label for the treatment of alcohol use disorder, following anecdotal reports and some clinical studies suggesting its effectiveness.",
      "date": "2000"
    },
    {
      "headline": "Research on Baclofen for Opioid Withdrawal",
      "text": "In the 2010s, research expanded into the use of Baclofen for managing opioid withdrawal symptoms, although it remains an off-label use.",
      "date": "2010"
    }
  ]
}

