{
  "timeline": [
    {
      "headline": "Birth of Maulana Azad",
      "text": "Abul Kalam Ghulam Muhiyuddin Ahmed bin Khairuddin Al-Hussaini Azad was born on 11 November 1888 in Mecca, which was then part of the Ottoman Empire.",
      "date": "1888-11-11"
    },
    {
      "headline": "Return to India",
      "text": "Azad's family returned to India in 1890, settling in Calcutta (now Kolkata).",
      "date": "1890"
    },
    {
      "headline": "Publication of Al-Hilal",
      "text": "In 1912, Maulana Azad started publishing a weekly journal in Urdu called Al-Hilal, which played a significant role in propagating revolutionary ideas against British rule.",
      "date": "1912"
    },
    {
      "headline": "Al-Hilal Banned",
      "text": "The British government banned Al-Hilal in 1914 due to its anti-colonial stance.",
      "date": "1914"
    },
    {
      "headline": "Publication of Al-Balagh",
      "text": "After the ban on Al-Hilal, Azad started another weekly journal, Al-Balagh, in 1915.",
      "date": "1915"
    },
    {
      "headline": "Detention by British Authorities",
      "text": "Maulana Azad was detained by the British authorities from 1916 to 1920 for his anti-colonial activities.",
      "date": "1916"
    },
    {
      "headline": "Release from Detention",
      "text": "Azad was released from detention in 1920 and became actively involved in the Khilafat Movement and the Non-Cooperation Movement.",
      "date": "1920"
    },
    {
      "headline": "President of Indian National Congress",
      "text": "Azad was elected as the President of the Indian National Congress in 1923, becoming the youngest person to hold the office.",
      "date": "1923"
    },
    {
      "headline": "Second Term as Congress President",
      "text": "He served a second term as the President of the Indian National Congress from 1940 to 1945 during the crucial years of the Quit India Movement.",
      "date": "1940"
    },
    {
      "headline": "India's Independence and First Minister of Education",
      "text": "Following India's independence in 1947, Maulana Azad became the first Minister of Education in the Indian government, serving until 1958.",
      "date": "1947"
    },
    {
      "headline": "Death of Maulana Azad",
      "text": "Maulana Azad passed away on 22 February 1958 in Delhi, India.",
      "date": "1958-02-22"
    }
  ]
}

