{
  "timeline": [
    {
      "headline": "Birth of Velupillai Prabhakaran",
      "text": "Velupillai Prabhakaran was born on November 26, 1954, in Valvettithurai, a town in the northern part of Sri Lanka.",
      "date": "1954-11-26"
    },
    {
      "headline": "Formation of the Tamil New Tigers",
      "text": "In 1972, Velupillai Prabhakaran founded the Tamil New Tigers, a precursor to the Liberation Tigers of Tamil Eelam (LTTE), marking the beginning of his militant activities.",
      "date": "1972"
    },
    {
      "headline": "Founding of the Liberation Tigers of Tamil Eelam (LTTE)",
      "text": "In May 1976, Velupillai Prabhakaran founded the Liberation Tigers of Tamil Eelam (LTTE), with the aim of creating an independent Tamil state in Sri Lanka.",
      "date": "1976-05"
    },
    {
      "headline": "Assassination of Jaffna Mayor Alfred Duraiappah",
      "text": "On July 27, 1975, Velupillai Prabhakaran was involved in the assassination of Jaffna Mayor Alfred Duraiappah, marking one of the first major acts of violence by the LTTE.",
      "date": "1975-07-27"
    },
    {
      "headline": "First Eelam War",
      "text": "The First Eelam War began in July 1983, following the ambush of a Sri Lankan army patrol by the LTTE, leading to widespread anti-Tamil riots and the escalation of the conflict.",
      "date": "1983-07"
    },
    {
      "headline": "Indian Peace Keeping Force (IPKF) Intervention",
      "text": "In 1987, the Indian Peace Keeping Force (IPKF) was deployed in Sri Lanka to enforce a peace accord, leading to clashes with the LTTE.",
      "date": "1987"
    },
    {
      "headline": "Assassination of Rajiv Gandhi",
      "text": "On May 21, 1991, former Indian Prime Minister Rajiv Gandhi was assassinated by an LTTE suicide bomber, an event that significantly impacted India's policy towards the LTTE.",
      "date": "1991-05-21"
    },
    {
      "headline": "Assassination of Sri Lankan President Ranasinghe Premadasa",
      "text": "On May 1, 1993, Sri Lankan President Ranasinghe Premadasa was assassinated by an LTTE suicide bomber.",
      "date": "1993-05-01"
    },
    {
      "headline": "Ceasefire Agreement",
      "text": "In February 2002, the LTTE and the Sri Lankan government signed a ceasefire agreement, temporarily halting hostilities.",
      "date": "2002-02"
    },
    {
      "headline": "Resumption of Hostilities",
      "text": "In 2006, hostilities resumed between the LTTE and the Sri Lankan government, leading to the eventual defeat of the LTTE.",
      "date": "2006"
    },
    {
      "headline": "Death of Velupillai Prabhakaran",
      "text": "Velupillai Prabhakaran was killed on May 18, 2009, during the final stages of the Sri Lankan Civil War, marking the end of the LTTE's military campaign.",
      "date": "2009-05-18"
    }
  ]
}

