{
  "timeline": [
    {
      "headline": "Birth of Joseph Augustus Zarelli",
      "text": "Joseph Augustus Zarelli was born on January 13, 1953.",
      "date": "1953-01-13"
    },
    {
      "headline": "Discovery of Joseph's Body",
      "text": "On February 25, 1957, the nude, malnourished, and beaten body of Joseph Augustus Zarelli was found on the side of Susquehanna Road in Philadelphia, Pennsylvania. He appeared to have been cleaned and freshly groomed, with a recent haircut and trimmed fingernails. Authorities determined that he had suffered extensive physical attacks prior to his death, with multiple bruises on his body, and was severely malnourished. His body was covered with scars, some of which were surgical. The cause of death was believed to be homicide by blunt force trauma.",
      "date": "1957-02-25"
    },
    {
      "headline": "Identification as 'Boy in the Box'",
      "text": "Following the discovery of his body, Joseph Augustus Zarelli became known as the 'Boy in the Box' or 'America's Unknown Child' due to the initial inability to identify him.",
      "date": "1957"
    },
