    {
      "headline": "Formulation of the Poincaré Conjecture",
      "text": "In 1904, the French mathematician Henri Poincaré formulated the Poincaré conjecture. It is a hypothesis about the characterization of the 3-sphere, which is the hypersphere that bounds the unit ball in four-dimensional space.",
      "date": "1904"
    },
    {
      "headline": "Initial Attempts and Developments",
      "text": "Throughout the 20th century, numerous mathematicians attempted to prove the Poincaré conjecture. These efforts led to significant developments in the field of topology, although the conjecture remained unproven for many decades.",
      "date": "1904-2000"
    },
    {
      "headline": "Grigori Perelman's Proof",
      "text": "In 2003, Russian mathematician Grigori Perelman published a series of papers on the arXiv preprint server, outlining a proof of the Poincaré conjecture. His work built on Richard S. Hamilton's theory of Ricci flow.",
      "date": "2003"
    },
    {
      "headline": "Verification of Perelman's Proof",
      "text": "By 2006, Perelman's proof was verified by several mathematicians, including teams led by Bruce Kleiner and John Lott, as well as by John Morgan and Gang Tian, confirming its correctness.",
      "date": "2006"
    },
    {
      "headline": "Award of the Fields Medal",
      "text": "In 2006, Grigori Perelman was awarded the Fields Medal for his proof of the Poincaré conjecture. However, he declined the award, stating that he was not interested in recognition or monetary rewards.",
      "date": "2006"
    },
    {
      "headline": "Clay Millennium Prize",
      "text": "In 2010, the Clay Mathematics Institute awarded Perelman the Millennium Prize for solving the Poincaré conjecture, one of the seven 'Millennium Prize Problems.' Perelman declined this prize as well.",
      "date": "2010"
    }
  ]
}

