    {
      "headline": "Beginning of the Devonian Period",
      "text": "The Devonian period began approximately 419.2 million years ago, following the end of the Silurian period. It marks the fourth period of both the Paleozoic and the Phanerozoic eons.",
      "date": "-419200000"
    },
    {
      "headline": "Early Devonian (Lochkovian Stage)",
      "text": "The Early Devonian, also known as the Lochkovian stage, spanned from about 419.2 to 410.8 million years ago. This stage saw the diversification of early land plants and the first appearance of ammonites.",
      "date": "-419200000"
    },
    {
      "headline": "Middle Devonian (Eifelian and Givetian Stages)",
      "text": "The Middle Devonian, comprising the Eifelian and Givetian stages, occurred from approximately 393.3 to 382.7 million years ago. This period was characterized by the development of extensive reef systems and the diversification of fish, including the first appearance of lobe-finned fish.",
      "date": "-393300000"
    },
    {
      "headline": "Late Devonian (Frasnian and Famennian Stages)",
      "text": "The Late Devonian, which includes the Frasnian and Famennian stages, spanned from about 382.7 to 358.9 million years ago. This period is known for the Late Devonian extinction events, which significantly affected marine life, particularly reef-building organisms and jawless fish.",
      "date": "-382700000"
    },
    {
      "headline": "End of the Devonian Period",
      "text": "The Devonian period ended approximately 358.9 million years ago, giving way to the Carboniferous period. This transition marked significant evolutionary changes, including the rise of early amphibians and the decline of many marine species.",
      "date": "-358900000"
    }
  ]
}

