      "headline": "Battle of Riachuelo",
      "text": "On June 11, 1865, the Battle of Riachuelo took place, resulting in a decisive naval victory for Brazil over Paraguay.",
      "date": "1865-06-11"
    },
    {
      "headline": "Battle of Tuyutí",
      "text": "On May 24, 1866, the Battle of Tuyutí occurred, which was the largest battle in South American history and resulted in a victory for the Triple Alliance.",
      "date": "1866-05-24"
    },
    {
      "headline": "Battle of Curupayty",
      "text": "On September 22, 1866, the Battle of Curupayty took place, where Paraguayan forces successfully repelled an attack by the Triple Alliance.",
      "date": "1866-09-22"
    },
    {
      "headline": "Fall of Humaitá",
      "text": "In July 1868, the strategic Paraguayan fortress of Humaitá fell to the forces of the Triple Alliance.",
      "date": "1868-07"
    },
    {
      "headline": "Assassination of Francisco Solano López",
      "text": "On March 1, 1870, Paraguayan President Francisco Solano López was killed in the Battle of Cerro Corá, effectively ending the war.",
      "date": "1870-03-01"
    },
    {
      "headline": "End of the Paraguayan War",
      "text": "The Paraguayan War officially ended in 1870 with Paraguay's defeat and the signing of peace treaties with the victorious allies.",
      "date": "1870"
