{
  "timeline": [
    {
      "headline": "Development of Tetanus Toxoid",
      "text": "The tetanus toxoid was developed in the early 1920s. It was created by inactivating the tetanus toxin with formaldehyde, which allowed it to be used as a vaccine to prevent tetanus.",
      "date": "1920"
    },
    {
      "headline": "First Use in Humans",
      "text": "The tetanus toxoid was first used in humans in 1924. It was initially used to immunize soldiers against tetanus during World War I.",
      "date": "1924"
    },
    {
      "headline": "Widespread Use in Military",
      "text": "During World War II, the tetanus vaccine was widely used to protect military personnel from tetanus, significantly reducing the incidence of the disease among soldiers.",
      "date": "1940"
    },
    {
      "headline": "Inclusion in Routine Childhood Immunization",
      "text": "The tetanus vaccine became part of the routine childhood immunization schedule in many countries during the 1940s and 1950s, often combined with diphtheria and pertussis vaccines (DTP).",
      "date": "1950"
    },
    {
      "headline": "Introduction of Tetanus-Diphtheria (Td) Vaccine",
      "text": "The Tetanus-Diphtheria (Td) vaccine, which includes a reduced dose of diphtheria toxoid, was introduced for booster doses in adolescents and adults.",
      "date": "1960"
    },
    {
      "headline": "Global Efforts to Eliminate Maternal and Neonatal Tetanus",
      "text": "In 1989, the World Health Organization launched a global initiative to eliminate maternal and neonatal tetanus, promoting the use of tetanus toxoid vaccination for women of childbearing age.",
      "date": "1989"
    },
    {
      "headline": "Introduction of Tetanus-Diphtheria-Pertussis (Tdap) Vaccine",
      "text": "The Tetanus-Diphtheria-Pertussis (Tdap) vaccine, which includes protection against pertussis, was introduced in 2005 for use in adolescents and adults.",
      "date": "2005"
    }
  ]
}

