{
  "timeline": [
    {
      "headline": "Introduction of Polish Notation",
      "text": "Polish notation, the precursor to Reverse Polish Notation (RPN), was introduced by the Polish mathematician Jan Łukasiewicz in the 1920s. This notation places operators before their operands.",
      "date": "1920"
    },
    {
      "headline": "Development of Reverse Polish Notation",
      "text": "Reverse Polish Notation (RPN) was developed as a variant of Polish notation. It places operators after their operands, eliminating the need for parentheses to denote operation order.",
      "date": "1950"
    },
    {
      "headline": "Adoption in Computer Science",
      "text": "RPN gained popularity in computer science and was adopted in various computing systems and calculators due to its efficiency in reducing the need for parentheses and simplifying the parsing process.",
      "date": "1960"
    },
    {
      "headline": "Introduction in Hewlett-Packard Calculators",
      "text": "Hewlett-Packard (HP) introduced calculators using RPN in the 1970s, starting with the HP-35, which helped popularize the notation among engineers and scientists.",
      "date": "1972"
    },
    {
      "headline": "Continued Use in Modern Calculators",
      "text": "RPN continues to be used in modern scientific and financial calculators, particularly those produced by HP, due to its efficiency and ease of use for complex calculations.",
      "date": "2000"
    }
  ]
}

