    {
      "headline": "Helium Production",
      "text": "In 1927, Amarillo became a major center for helium production, with the establishment of the Federal Helium Reserve.",
      "date": "1927"
    },
    {
      "headline": "World War II Impact",
      "text": "During World War II, Amarillo Army Air Field was established in 1942, significantly impacting the local economy and population.",
      "date": "1942"
    },
    {
      "headline": "Interstate 40 Construction",
      "text": "In the 1960s, the construction of Interstate 40 through Amarillo replaced the historic Route 66, further boosting the city's growth.",
      "date": "1960"
