{
  "timeline": [
    {
      "headline": "Emergence of Hindustani",
      "text": "Hindustani began to emerge as a distinct language during the Delhi Sultanate period, which lasted from 1206 to 1526. It developed as a lingua franca in the northern Indian subcontinent, influenced by Persian, Arabic, and Turkic languages due to the Muslim rule in the region.",
      "date": "1206"
    },
    {
      "headline": "Development under Mughal Empire",
      "text": "During the Mughal Empire (1526-1857), Hindustani further developed and was used as a court language. It was heavily influenced by Persian, which was the official language of the Mughal court.",
      "date": "1526"
    },
    {
      "headline": "Division into Hindi and Urdu",
      "text": "By the late 18th century, Hindustani began to diverge into two distinct registers: Hindi, written in the Devanagari script, and Urdu, written in the Persian script. This division was influenced by cultural and religious factors.",
      "date": "1770"
    },
    {
      "headline": "British Colonial Period",
      "text": "During British rule in India (1858-1947), Hindustani was promoted as a lingua franca to facilitate administration. The British recognized both Hindi and Urdu as important languages in the region.",
      "date": "1858"
    },
    {
      "headline": "Independence and Partition",
      "text": "In 1947, India gained independence from British rule, and the subcontinent was partitioned into India and Pakistan. Hindi was adopted as the official language of India, while Urdu became the national language of Pakistan.",
      "date": "1947"
    },
    {
      "headline": "Recognition of Hindi and Urdu",
      "text": "In 1950, the Constitution of India recognized Hindi in the Devanagari script as the official language of India. Urdu was recognized as one of the 22 scheduled languages of India.",
      "date": "1950"
    },
    {
      "headline": "Emergence of Hinglish and Urdish",
      "text": "In the late 20th and early 21st centuries, a new variety of Hindustani emerged, influenced by English. This variety, often called Hinglish or Urdish, is characterized by a mix of Hindi, Urdu, and English vocabulary and is widely used in urban areas and media.",
      "date": "2000"
    }
  ]
}

