    },
    {
      "headline": "Introduction of the Rashomon Effect",
      "text": "The term 'Rashomon effect' was coined to describe the phenomenon of contradictory interpretations of the same event by different people. This concept became widely recognized in various fields, including psychology, law, and media studies, following the release and international success of the film 'Rashomon'.",
      "date": "1950"
    },
    {
      "headline": "Rashomon Wins Golden Lion at Venice Film Festival",
      "text": "In 1951, 'Rashomon' won the Golden Lion at the Venice Film Festival, which helped introduce the film and its narrative technique to a global audience.",
      "date": "1951"
    },
    {
      "headline": "Academy Honorary Award for 'Rashomon'",
      "text": "In 1952, 'Rashomon' received an Academy Honorary Award for being the most outstanding foreign language film released in the United States during 1951. This recognition further popularized the Rashomon effect.",
      "date": "1952"
    }
  ]
}

