{
  "timeline": [
    {
      "headline": "First Cryonics Book Published",
      "text": "In 1962, Robert Ettinger published 'The Prospect of Immortality', which introduced the concept of cryonics to the public.",
      "date": "1962"
    },
    {
      "headline": "First Cryonics Organization Founded",
      "text": "In 1964, the Cryonics Society of New York was founded, becoming one of the first organizations dedicated to the promotion and practice of cryonics.",
      "date": "1964"
    },
    {
      "headline": "First Human Cryopreservation",
      "text": "On January 12, 1967, Dr. James Bedford became the first human to be cryopreserved after his legal death.",
      "date": "1967-01-12"
    },
    {
      "headline": "Alcor Life Extension Foundation Established",
      "text": "In 1972, the Alcor Life Extension Foundation was established, which would become one of the leading cryonics organizations.",
      "date": "1972"
    },
    {
      "headline": "Cryonics Institute Founded",
      "text": "In 1976, the Cryonics Institute was founded by Robert Ettinger, further advancing the cryonics movement.",
      "date": "1976"
    },
    {
      "headline": "First Successful Cryopreservation of a Mammalian Organ",
      "text": "In 1984, researchers successfully cryopreserved and revived a rabbit kidney, marking a significant scientific milestone for cryonics.",
      "date": "1984"
    },
    {
      "headline": "Cryonics Legal Case: Dora Kent",
      "text": "In 1988, the case of Dora Kent, whose head was cryopreserved, led to a legal battle over the definition of death and the legality of cryonics procedures.",
      "date": "1988"
    },
    {
      "headline": "First Cryonics Patient Stored in Europe",
      "text": "In 1994, the first cryonics patient was stored in Europe, marking the expansion of cryonics beyond the United States.",
      "date": "1994"
    },
    {
      "headline": "Cryonics Institute's 100th Patient",
      "text": "In 2011, the Cryonics Institute reached a milestone with its 100th patient being cryopreserved.",
      "date": "2011"
    },
    {
      "headline": "Teenager Wins Legal Battle for Cryopreservation",
      "text": "In 2016, a 14-year-old British girl won a legal battle to be cryopreserved after her death, bringing international attention to cryonics.",
      "date": "2016"
    }
  ]
}

