{
  "timeline": [
    {
      "headline": "Discovery of Pulsars",
      "text": "Pulsars were first discovered in 1967 by Jocelyn Bell Burnell and Antony Hewish. They observed a regular pulsing radio source, which they initially referred to as 'Little Green Men' due to its regularity.",
      "date": "1967"
    },
    {
      "headline": "Identification as Neutron Stars",
      "text": "In 1968, it was proposed that pulsars are rapidly rotating neutron stars. This hypothesis was confirmed by the observation of the Crab Pulsar in the Crab Nebula, which matched the predicted characteristics of a neutron star.",
      "date": "1968"
    },
    {
      "headline": "Nobel Prize in Physics",
      "text": "In 1974, Antony Hewish was awarded the Nobel Prize in Physics for his role in the discovery of pulsars. Jocelyn Bell Burnell, who made the initial discovery, was not included in the award.",
      "date": "1974"
    },
    {
      "headline": "Discovery of Millisecond Pulsars",
      "text": "The first millisecond pulsar, PSR B1937+21, was discovered in 1982. These pulsars have extremely short rotation periods, on the order of milliseconds.",
      "date": "1982"
    },
    {
      "headline": "Binary Pulsar and Gravitational Waves",
      "text": "The discovery of the binary pulsar PSR B1913+16 in 1974 provided indirect evidence for the existence of gravitational waves, as the system's orbital decay matched predictions from general relativity.",
      "date": "1974"
    },
    {
      "headline": "Pulsars as Cosmic Clocks",
      "text": "Pulsars have been used as cosmic clocks due to their incredibly regular rotation periods. This has applications in testing the general theory of relativity and in the search for gravitational waves.",
      "date": "Ongoing"
    },
    {
      "headline": "Pulsars and Ultra-High-Energy Cosmic Rays",
      "text": "Pulsars are considered one of the potential sources of ultra-high-energy cosmic rays, although this remains an area of active research.",
      "date": "Ongoing"
    }
  ]
}

