  "timeline": [
    {
      "headline": "Henry VIII's Marriage to Catherine of Aragon",
      "text": "Henry VIII married Catherine of Aragon in 1509. This marriage later became a central issue in the English Reformation.",
      "date": "1509"
    },
    {
      "headline": "Henry VIII's Request for Annulment",
      "text": "In 1527, Henry VIII sought an annulment of his marriage to Catherine of Aragon, which was initially denied by the Pope.",
      "date": "1527"
    },
    {
      "headline": "Act of Supremacy",
      "text": "In 1534, the Act of Supremacy was passed, declaring Henry VIII as the Supreme Head of the Church of England, marking a significant break from the Catholic Church.",
      "date": "1534"
    },
    {
      "headline": "Dissolution of the Monasteries",
      "text": "Between 1536 and 1541, Henry VIII ordered the Dissolution of the Monasteries, which involved the closure and destruction of monastic institutions across England.",
      "date": "1536"
    },
    {
      "headline": "Publication of the Great Bible",
      "text": "In 1539, the Great Bible, the first authorized edition of the Bible in English, was published under the orders of Henry VIII.",
      "date": "1539"
    },
    {
      "headline": "Edward VI's Protestant Reforms",
      "text": "During the reign of Edward VI (1547-1553), significant Protestant reforms were implemented, including the introduction of the Book of Common Prayer in 1549.",
      "date": "1549"
    },
    {
      "headline": "Mary I's Catholic Restoration",
      "text": "Mary I, who reigned from 1553 to 1558, attempted to restore Catholicism in England, reversing many of her father's reforms.",
      "date": "1553"
    },
    {
      "headline": "Elizabeth I's Religious Settlement",
      "text": "In 1559, Elizabeth I established the Elizabethan Religious Settlement, which sought a middle ground between Catholic and Protestant practices.",
      "date": "1559"
    },
    {
      "headline": "Thirty-Nine Articles",
      "text": "In 1563, the Thirty-Nine Articles were established, defining the doctrine of the Church of England and solidifying its Protestant identity.",
      "date": "1563"
    }
  ]
}

