}

{
  "timeline": [
    {
      "headline": "Sal Khan Creates Khan Academy",
      "text": "In 2006, Sal Khan, a former hedge fund analyst, founded Khan Academy. He started by creating educational videos to help tutor his cousins in mathematics.",
      "date": "2006"
    },
    {
      "headline": "Khan Academy Becomes a Non-Profit",
      "text": "In 2008, Khan Academy was formally established as a non-profit organization, with the mission to provide a free, world-class education for anyone, anywhere.",
