    {
      "headline": "Start of the Battle of Chosin Reservoir",
      "text": "The Battle of Chosin Reservoir began on November 27, 1950, when Chinese forces launched a surprise attack against United Nations forces, primarily composed of U.S. Marines and Army units, at the Chosin Reservoir in North Korea.",
      "date": "1950-11-27"
    },
    {
      "headline": "Chinese Forces Encircle UN Troops",
      "text": "By November 28, 1950, Chinese forces had successfully encircled the UN troops, cutting off their supply lines and forcing them into a defensive position.",
      "date": "1950-11-28"
    },
    {
      "headline": "UN Forces Begin Fighting Withdrawal",
      "text": "On December 1, 1950, UN forces began a fighting withdrawal from the Chosin Reservoir area, battling harsh winter conditions and continuous Chinese attacks.",
      "date": "1950-12-01"
    },
    {
      "headline": "Evacuation from Hagaru-ri",
      "text": "By December 6, 1950, UN forces had reached Hagaru-ri, where they regrouped and prepared for evacuation. The airstrip at Hagaru-ri was used to evacuate wounded soldiers and bring in supplies.",
      "date": "1950-12-06"
    },
    {
      "headline": "UN Forces Reach Hungnam",
      "text": "On December 11, 1950, the UN forces completed their withdrawal to Hungnam, where they were evacuated by sea. This marked the end of the Battle of Chosin Reservoir.",
      "date": "1950-12-11"
    }
  ]
}

