{
  "timeline": [
    {
      "headline": "Birth of Quantum Field Theory",
      "text": "Quantum field theory (QFT) emerged in the late 1920s and early 1930s as a theoretical framework that combines classical field theory, special relativity, and quantum mechanics.",
      "date": "1920"
    },
    {
      "headline": "Dirac's Quantum Electrodynamics",
      "text": "In 1927, Paul Dirac formulated the first quantum field theory, known as quantum electrodynamics (QED), which describes the electromagnetic force.",
      "date": "1927"
    },
    {
      "headline": "Development of Quantum Electrodynamics",
      "text": "During the 1940s, Richard Feynman, Julian Schwinger, and Sin-Itiro Tomonaga independently developed the modern formulation of quantum electrodynamics (QED), which was later proven to be a highly accurate theory.",
      "date": "1940"
    },
    {
      "headline": "Renormalization",
      "text": "In the late 1940s, the concept of renormalization was developed to address the infinities that arose in quantum field theories, allowing for meaningful physical predictions.",
      "date": "1940"
    },
    {
      "headline": "Quantum Chromodynamics",
      "text": "In the 1970s, quantum chromodynamics (QCD) was developed as the quantum field theory of the strong nuclear force, describing the interactions of quarks and gluons.",
      "date": "1970"
    },
    {
      "headline": "Standard Model of Particle Physics",
      "text": "By the mid-1970s, the Standard Model of particle physics was formulated, combining quantum electrodynamics, quantum chromodynamics, and the electroweak theory into a comprehensive framework.",
      "date": "1975"
    },
    {
      "headline": "Higgs Boson Discovery",
      "text": "In 2012, the discovery of the Higgs boson at CERN's Large Hadron Collider confirmed the existence of the Higgs field, a crucial component of the Standard Model of particle physics.",
      "date": "2012"
    }
  ]
}

