{
  "timeline": [
    {
      "headline": "Earliest Known Description",
      "text": "The earliest known written record of the camera obscura is by Mozi, a Chinese philosopher, who lived around 470 to 391 BCE. Mozi described the phenomenon of an inverted image formed through a pinhole.",
      "date": "-0470"
    },
    {
      "headline": "Aristotle's Observations",
      "text": "Around 350 BCE, Aristotle made observations of the camera obscura effect during a partial solar eclipse, noting how the light passing through leaves created crescent-shaped images.",
      "date": "-0350"
    },
    {
      "headline": "Alhazen's Detailed Study",
      "text": "In the 11th century, the Arab scientist Alhazen (Ibn al-Haytham) conducted detailed studies of optics and the camera obscura. He used the device to demonstrate how light travels in straight lines.",
      "date": "1000"
    },
    {
      "headline": "Leonardo da Vinci's Sketches",
      "text": "In the late 15th century, Leonardo da Vinci made sketches and notes on the camera obscura, recognizing its potential for artistic and scientific applications.",
      "date": "1490"
    },
    {
      "headline": "Giambattista della Porta's Publication",
      "text": "In 1558, Giambattista della Porta published 'Magia Naturalis', which included a detailed description of the camera obscura and its use in projecting images.",
      "date": "1558"
    },
    {
      "headline": "Kepler's Advancements",
      "text": "In the early 17th century, Johannes Kepler improved the camera obscura by adding a lens to enhance the clarity and brightness of the projected image.",
      "date": "1600"
    },
    {
      "headline": "Portable Camera Obscura",
      "text": "In the 17th century, the camera obscura was made portable, allowing artists to use it as a drawing aid for capturing landscapes and architectural scenes.",
      "date": "1600"
    },
    {
      "headline": "Development into Photographic Camera",
      "text": "By the 19th century, the principles of the camera obscura were foundational in the development of the photographic camera, leading to the invention of photography.",
      "date": "1800"
    }
  ]
}

