{
  "timeline": [
    {
      "headline": "Battle of the Granicus",
      "text": "In May 334 BC, Alexander the Great fought the Battle of the Granicus against the Persian satraps of Asia Minor. This was his first major battle against the Achaemenid Empire, resulting in a decisive victory for Alexander.",
      "date": "-0334-05"
    },
    {
      "headline": "Siege of Halicarnassus",
      "text": "In 334 BC, following the Battle of the Granicus, Alexander laid siege to the city of Halicarnassus. The siege ended with the capture of the city, further consolidating Alexander's control over Asia Minor.",
      "date": "-0334"
    },
    {
      "headline": "Battle of Issus",
      "text": "In November 333 BC, Alexander the Great defeated Darius III of Persia at the Battle of Issus. This battle was significant as it marked the first time Alexander faced Darius directly, leading to a major victory for the Macedonians.",
      "date": "-0333-11"
    },
    {
      "headline": "Siege of Tyre",
      "text": "In 332 BC, Alexander conducted the Siege of Tyre, a seven-month siege that ended with the capture of the city. This victory was crucial for securing the eastern Mediterranean coast.",
      "date": "-0332"
    },
    {
      "headline": "Conquest of Egypt",
      "text": "In 332 BC, after the Siege of Tyre, Alexander entered Egypt, where he was welcomed as a liberator. He founded the city of Alexandria and was declared a pharaoh.",
      "date": "-0332"
    },
    {
      "headline": "Battle of Gaugamela",
      "text": "On October 1, 331 BC, Alexander achieved a decisive victory over Darius III at the Battle of Gaugamela. This battle effectively marked the end of the Achaemenid Empire and established Alexander as the ruler of Persia.",
      "date": "-0331-10-01"
    },
    {
      "headline": "Capture of Babylon",
      "text": "In 331 BC, following his victory at Gaugamela, Alexander captured Babylon, one of the key cities of the Achaemenid Empire.",
      "date": "-0331"
    },
    {
      "headline": "Battle of the Hydaspes",
      "text": "In 326 BC, Alexander fought the Battle of the Hydaspes against King Porus in the Punjab region. Despite facing a formidable opponent and challenging conditions, Alexander emerged victorious.",
      "date": "-0326"
    },
    {
      "headline": "Mutiny at the Hyphasis",
      "text": "In 326 BC, Alexander's troops, exhausted and unwilling to continue further into India, mutinied at the Hyphasis River, forcing Alexander to turn back.",
      "date": "-0326"
    },
    {
      "headline": "Return to Babylon",
      "text": "In 323 BC, after years of campaigning, Alexander returned to Babylon, where he began planning further conquests.",
      "date": "-0323"
    },
    {
      "headline": "Death of Alexander the Great",
      "text": "On June 10, 323 BC, Alexander the Great died in the palace of Nebuchadnezzar II in Babylon at the age of 32. His death marked the end of his conquests and the beginning of the Hellenistic period.",
      "date": "-0323-06-10"
    }
  ]
}

