    {
      "headline": "Establishment of Forest Research Institute",
      "text": "The Forest Research Institute was established in Dehradun in 1906, becoming a premier institution in the field of forestry research in India.",
      "date": "1906"
    },
    {
      "headline": "Independence and Statehood",
      "text": "After India's independence in 1947, Dehradun became part of the newly formed state of Uttar Pradesh.",
      "date": "1947"
    },
    {
      "headline": "Formation of Uttarakhand",
      "text": "In 2000, Dehradun became part of the newly created state of Uttarakhand, which was carved out of Uttar Pradesh.",
      "date": "2000"
    },
