{
  "timeline": [
    {
      "headline": "Introduction of the Tariff Bill",
      "text": "The Smoot–Hawley Tariff Act was initially introduced in the United States Congress as a bill aimed at raising tariffs on imported goods to protect American industries.",
      "date": "1929"
    },
    {
      "headline": "Passage by the House of Representatives",
      "text": "The House of Representatives passed the tariff bill, which proposed significant increases in tariffs on imported goods, on May 28, 1929.",
      "date": "1929-05-28"
    },
    {
      "headline": "Passage by the Senate",
      "text": "The Senate passed its version of the tariff bill on March 24, 1930, after extensive debates and amendments.",
      "date": "1930-03-24"
    },
    {
      "headline": "Signing into Law",
      "text": "President Herbert Hoover signed the Smoot–Hawley Tariff Act into law on June 17, 1930, despite opposition from economists and international trading partners.",
      "date": "1930-06-17"
    },
    {
      "headline": "Retaliatory Tariffs",
      "text": "Following the enactment of the Smoot–Hawley Tariff, several countries imposed retaliatory tariffs on American goods, leading to a decline in international trade.",
      "date": "1930"
    },
    {
      "headline": "Impact on the Great Depression",
      "text": "The Smoot–Hawley Tariff is often cited as a factor that worsened the Great Depression by reducing international trade and causing economic strain.",
      "date": "1930s"
    },
    {
      "headline": "Repeal and Reduction of Tariffs",
      "text": "In subsequent years, the United States government moved to reduce tariffs and promote free trade, effectively reversing the policies of the Smoot–Hawley Tariff.",
      "date": "1934"
    }
  ]
}

{
