    {
      "headline": "Upanishadic Period",
      "text": "Around 800 BCE to 200 BCE, the Upanishads were composed, marking a shift towards philosophical and mystical interpretations of the Vedas. This period emphasized concepts like Brahman and Atman.",
      "date": "-0800"
    },
    {
      "headline": "Epic and Puranic Period",
      "text": "From around 500 BCE to 500 CE, the major epics, the Mahabharata and the Ramayana, as well as the Puranas, were composed. These texts played a crucial role in shaping Hindu mythology and religious practices.",
      "date": "-0500"
    },
    {
      "headline": "Classical Hinduism",
      "text": "Between 200 BCE and 1100 CE, Hinduism underwent significant development, with the establishment of major philosophical schools and the rise of devotional movements. This period saw the construction of many temples and the spread of Hindu culture.",
      "date": "-0200"
    },
    {
      "headline": "Medieval Period",
      "text": "From 1200 CE to 1750 CE, Hinduism faced challenges from Islamic invasions and rule in India. Despite this, it continued to evolve, with the Bhakti movement promoting personal devotion to deities.",
      "date": "1200"
    },
    {
      "headline": "Colonial Period",
      "text": "During the British colonial rule from the 18th to the mid-20th century, Hinduism underwent reform and revival movements, such as the Brahmo Samaj and Arya Samaj, which sought to modernize and purify Hindu practices.",
      "date": "1750"
    },
    {
      "headline": "Post-Independence",
      "text": "After India's independence in 1947, Hinduism continued to adapt and grow, with increased global presence and influence. The religion has become a significant cultural and spiritual force worldwide.",
      "date": "1947"
    }
  ]
}

