    },
    {
      "headline": "Ottoman Rule",
      "text": "In 1538, Bessarabia came under Ottoman control, becoming part of the larger Ottoman Empire.",
      "date": "1538"
    },
    {
      "headline": "Russian Annexation",
      "text": "In 1812, following the Russo-Turkish War (1806–1812), the eastern part of the Principality of Moldavia, including Bessarabia, was ceded to the Russian Empire under the Treaty of Bucharest.",
      "date": "1812"
    },
    {
      "headline": "Union with Romania",
      "text": "On March 27, 1918, Bessarabia declared union with the Kingdom of Romania following the Russian Revolution and the collapse of the Russian Empire.",
      "date": "1918-03-27"
    },
    {
      "headline": "Soviet Occupation",
      "text": "In June 1940, following the Molotov-Ribbentrop Pact, the Soviet Union occupied Bessarabia, integrating it into the Moldavian SSR.",
      "date": "1940-06"
    },
    {
      "headline": "Return to Romanian Control",
      "text": "During World War II, Bessarabia was retaken by Romanian and German forces in 1941.",
      "date": "1941"
    },
    {
      "headline": "Reoccupation by the Soviet Union",
      "text": "In 1944, the Soviet Union reoccupied Bessarabia, reestablishing the Moldavian SSR.",
      "date": "1944"
    },
    {
      "headline": "Dissolution of the Soviet Union",
      "text": "In 1991, following the dissolution of the Soviet Union, Bessarabia became part of the newly independent Republic of Moldova.",
      "date": "1991"
    }
  ]
}

