{
  "timeline": [
    {
      "headline": "Early Accounting Records",
      "text": "The earliest accounting records date back to ancient Mesopotamia over 7,000 years ago, where simple accounting systems were used to record the growth of crops and herds.",
      "date": "-5000"
    },
    {
      "headline": "Development of Double-Entry Bookkeeping",
      "text": "The double-entry bookkeeping system was developed in medieval Europe, with the earliest known description found in the work of the Italian mathematician Luca Pacioli in 1494.",
      "date": "1494"
    },
    {
      "headline": "Publication of 'Summa de Arithmetica'",
      "text": "In 1494, Luca Pacioli published 'Summa de Arithmetica, Geometria, Proportioni et Proportionalita', which included a section on double-entry bookkeeping, laying the foundation for modern accounting.",
      "date": "1494"
    },
    {
      "headline": "Establishment of the First Professional Accounting Body",
      "text": "The Institute of Accountants and Bookkeepers was established in 1854 in Edinburgh, Scotland, marking the beginning of professional accountancy organizations.",
      "date": "1854"
    },
    {
      "headline": "Formation of the American Institute of Certified Public Accountants (AICPA)",
      "text": "In 1887, the American Institute of Certified Public Accountants (AICPA) was formed, becoming a major professional organization for accountants in the United States.",
      "date": "1887"
    },
    {
      "headline": "Introduction of the Generally Accepted Accounting Principles (GAAP)",
      "text": "The Generally Accepted Accounting Principles (GAAP) were introduced in the United States in the 1930s to standardize accounting practices.",
      "date": "1930"
    },
    {
      "headline": "Establishment of the International Accounting Standards Committee (IASC)",
      "text": "In 1973, the International Accounting Standards Committee (IASC) was established to develop international accounting standards.",
      "date": "1973"
    },
    {
      "headline": "Formation of the Financial Accounting Standards Board (FASB)",
      "text": "The Financial Accounting Standards Board (FASB) was formed in 1973 to establish and improve financial accounting and reporting standards in the United States.",
      "date": "1973"
    },
    {
      "headline": "Creation of the International Financial Reporting Standards (IFRS)",
      "text": "The International Financial Reporting Standards (IFRS) were developed by the International Accounting Standards Board (IASB) in 2001 to provide a global framework for financial reporting.",
      "date": "2001"
    }
  ]
}

