{
  "timeline": [
    {
      "headline": "Foundation of the Maronite Church",
      "text": "The Maronite Church was founded by followers of Saint Maron, a 4th-century monk who lived in the region of modern-day Syria. The church was established around the teachings and monastic traditions of Saint Maron.",
      "date": "0400"
    },
    {
      "headline": "Council of Chalcedon",
      "text": "In 451, the Council of Chalcedon took place, which was a significant event for the Maronites as they supported the Chalcedonian definition of Christology, aligning them with the wider Christian community.",
      "date": "0451"
    },
    {
      "headline": "Migration to Mount Lebanon",
      "text": "During the 7th century, facing persecution and seeking refuge, the Maronites migrated to the mountains of Lebanon, where they established a strong community.",
      "date": "0650"
    },
    {
      "headline": "Establishment of the Maronite Patriarchate",
      "text": "In 685, John Maron was elected as the first Maronite Patriarch, marking the formal establishment of the Maronite Patriarchate.",
      "date": "0685"
    },
    {
      "headline": "Crusades and Maronite Alliance with the West",
      "text": "During the Crusades in the 11th and 12th centuries, the Maronites established alliances with the Crusaders and the Papacy, strengthening their ties with the Roman Catholic Church.",
      "date": "1095"
    },
    {
      "headline": "Formal Recognition by the Papacy",
      "text": "In 1182, the Maronite Church formally declared its communion with the Roman Catholic Church, a relationship that has continued to the present day.",
      "date": "1182"
    },
    {
      "headline": "Ottoman Rule and Maronite Autonomy",
      "text": "Under Ottoman rule, starting in the 16th century, the Maronites maintained a degree of autonomy and continued to flourish in the Mount Lebanon region.",
      "date": "1516"
    },
    {
      "headline": "Lebanese Civil War",
      "text": "From 1975 to 1990, the Lebanese Civil War had a significant impact on the Maronite community, leading to political and social changes in Lebanon.",
      "date": "1975"
    },
    {
      "headline": "Post-Civil War Era",
      "text": "After the end of the Lebanese Civil War in 1990, the Maronite community continued to play a vital role in Lebanon's political and cultural landscape.",
      "date": "1990"
    }
  ]
}

