{
  "timeline": [
    {
      "headline": "Beginning of New Hollywood",
      "text": "The New Hollywood era began in the mid-1960s, marked by a new generation of filmmakers who took on a key authorial role, influencing the types of films produced, their production and marketing, and the way major studios approached filmmaking.",
      "date": "1965"
    },
    {
      "headline": "Release of 'Bonnie and Clyde'",
      "text": "In 1967, 'Bonnie and Clyde', directed by Arthur Penn, was released. It became a landmark film of the New Hollywood era, known for its innovative editing, narrative style, and its portrayal of violence.",
      "date": "1967"
    },
    {
      "headline": "Release of 'The Graduate'",
      "text": "In 1967, 'The Graduate', directed by Mike Nichols, was released. The film was a critical and commercial success, and it became emblematic of the New Hollywood movement.",
      "date": "1967"
    },
    {
      "headline": "Release of 'Easy Rider'",
      "text": "In 1969, 'Easy Rider', directed by Dennis Hopper, was released. The film's success demonstrated the viability of low-budget films and the appeal of countercultural themes.",
      "date": "1969"
    },
    {
      "headline": "Release of 'Midnight Cowboy'",
      "text": "In 1969, 'Midnight Cowboy', directed by John Schlesinger, was released. It became the first and only X-rated film to win the Academy Award for Best Picture.",
      "date": "1969"
    },
    {
      "headline": "Release of 'The Godfather'",
      "text": "In 1972, 'The Godfather', directed by Francis Ford Coppola, was released. The film was a massive critical and commercial success and is considered one of the greatest films of all time.",
      "date": "1972"
    },
    {
      "headline": "Release of 'Jaws'",
      "text": "In 1975, 'Jaws', directed by Steven Spielberg, was released. It became the first blockbuster film, changing the way films were marketed and distributed.",
      "date": "1975"
    },
    {
      "headline": "Release of 'Star Wars'",
      "text": "In 1977, 'Star Wars', directed by George Lucas, was released. It became a cultural phenomenon and one of the highest-grossing films of all time, further cementing the blockbuster model.",
      "date": "1977"
    },
    {
      "headline": "End of New Hollywood Era",
      "text": "By the early 1980s, the New Hollywood era came to an end as the blockbuster model dominated the industry, and studios regained control over film production.",
      "date": "1980"
    }
  ]
}

