{
  "timeline": [
    {
      "headline": "Death of Emperor Charles VI",
      "text": "On October 20, 1740, Emperor Charles VI of the Holy Roman Empire died, leaving his daughter Maria Theresa as his heir. This event triggered the War of the Austrian Succession as various European powers challenged her right to succeed.",
      "date": "1740-10-20"
    },
    {
      "headline": "Frederick II Invades Silesia",
      "text": "In December 1740, Frederick II of Prussia invaded the Austrian province of Silesia, marking the beginning of the First Silesian War, a part of the larger War of the Austrian Succession.",
      "date": "1740-12"
    },
    {
      "headline": "Battle of Mollwitz",
      "text": "On April 10, 1741, the Battle of Mollwitz took place, where Prussian forces under Frederick II defeated the Austrian army, solidifying Prussian control over Silesia.",
      "date": "1741-04-10"
    },
    {
      "headline": "Treaty of Breslau",
      "text": "On June 11, 1742, the Treaty of Breslau was signed, ending the First Silesian War. Austria ceded most of Silesia to Prussia.",
      "date": "1742-06-11"
    },
    {
      "headline": "Second Silesian War Begins",
      "text": "In 1744, the Second Silesian War began as Frederick II of Prussia renewed hostilities against Austria to secure his earlier gains.",
      "date": "1744"
    },
    {
      "headline": "Battle of Fontenoy",
      "text": "On May 11, 1745, the Battle of Fontenoy occurred, where French forces defeated the British and their allies, marking a significant victory for France in the Austrian Netherlands.",
      "date": "1745-05-11"
    },
    {
      "headline": "Treaty of Dresden",
      "text": "On December 25, 1745, the Treaty of Dresden was signed, ending the Second Silesian War. Prussia retained control of Silesia.",
      "date": "1745-12-25"
    },
    {
      "headline": "Treaty of Aix-la-Chapelle",
      "text": "On October 18, 1748, the Treaty of Aix-la-Chapelle was signed, ending the War of the Austrian Succession. The treaty largely restored the status quo ante bellum, with territorial exchanges and the recognition of Maria Theresa's succession.",
      "date": "1748-10-18"
    }
  ]
}

