{
  "timeline": [
    {
      "headline": "Birth of Analytic Philosophy",
      "text": "Analytic philosophy emerged in the late 19th and early 20th centuries as a reaction against traditional philosophical approaches, emphasizing clarity and logical rigor.",
      "date": "1900"
    },
    {
      "headline": "Gottlob Frege's Contributions",
      "text": "Gottlob Frege, a German philosopher, and logician, laid the groundwork for analytic philosophy with his work on logic and the philosophy of language in the late 19th century.",
      "date": "1879"
    },
    {
      "headline": "Bertrand Russell and Alfred North Whitehead's 'Principia Mathematica'",
      "text": "In 1910-1913, Bertrand Russell and Alfred North Whitehead published 'Principia Mathematica', a landmark work in mathematical logic that influenced the development of analytic philosophy.",
      "date": "1910"
    },
    {
      "headline": "Ludwig Wittgenstein's 'Tractatus Logico-Philosophicus'",
      "text": "In 1921, Ludwig Wittgenstein published 'Tractatus Logico-Philosophicus', which became a foundational text for the analytic tradition, focusing on the relationship between language and reality.",
      "date": "1921"
    },
    {
      "headline": "Vienna Circle and Logical Positivism",
      "text": "In the 1920s and 1930s, the Vienna Circle, a group of philosophers and scientists, developed logical positivism, emphasizing empirical verification and the logical analysis of language.",
      "date": "1920"
    },
    {
      "headline": "Quine's Critique of the Analytic-Synthetic Distinction",
      "text": "In 1951, W.V.O. Quine published 'Two Dogmas of Empiricism', challenging the distinction between analytic and synthetic statements and influencing the direction of analytic philosophy.",
      "date": "1951"
    },
    {
      "headline": "Development of Ordinary Language Philosophy",
      "text": "In the mid-20th century, philosophers like J.L. Austin and later Wittgenstein shifted focus to ordinary language philosophy, analyzing the way language is used in everyday contexts.",
      "date": "1950"
    },
    {
      "headline": "Rise of Philosophy of Mind and Language",
      "text": "In the latter half of the 20th century, analytic philosophy expanded to include significant work in the philosophy of mind and language, with figures like Saul Kripke and Hilary Putnam.",
      "date": "1970"
    }
  ]
}

