  "timeline": [
    {
      "headline": "First European Settlement",
      "text": "In August 1559, Spanish explorer Tristán de Luna y Arellano established the first European settlement in what is now the United States at Pensacola Bay.",
      "date": "1559-08"
    },
    {
      "headline": "Hurricane Destroys Settlement",
      "text": "In September 1559, a hurricane devastated the settlement, sinking ships and causing the settlers to abandon the site.",
      "date": "1559-09"
    },
    {
      "headline": "Reestablishment by the Spanish",
      "text": "In 1698, the Spanish reestablished a settlement at Pensacola, building a fort and a village.",
      "date": "1698"
    },
    {
      "headline": "British Control",
      "text": "In 1763, following the Treaty of Paris, Pensacola came under British control.",
      "date": "1763"
    },
    {
      "headline": "Return to Spanish Control",
      "text": "In 1781, during the American Revolutionary War, Spanish forces captured Pensacola from the British.",
      "date": "1781"
    },
    {
      "headline": "Transfer to the United States",
      "text": "In 1821, Pensacola was transferred to the United States as part of the Adams-Onís Treaty.",
      "date": "1821"
    },
    {
      "headline": "Civil War Occupation",
      "text": "In 1861, during the American Civil War, Pensacola was occupied by Confederate forces until Union forces took control in 1862.",
      "date": "1861"
    },
    {
      "headline": "Union Control",
      "text": "In May 1862, Union forces took control of Pensacola, maintaining it for the remainder of the Civil War.",
      "date": "1862-05"
    },
    {
      "headline": "Establishment of Naval Air Station",
      "text": "In 1914, the Pensacola Naval Air Station was established, becoming the first naval air station in the United States.",
      "date": "1914"
    },
    {
      "headline": "Hurricane Ivan",
      "text": "In September 2004, Hurricane Ivan caused significant damage to Pensacola, impacting infrastructure and homes.",
      "date": "2004-09"
    }
  ]
}

