  "timeline": [
    {
      "headline": "Discovery of LSD",
      "text": "In 1938, Swiss chemist Albert Hofmann first synthesized lysergic acid diethylamide (LSD) at the Sandoz Laboratories in Basel, Switzerland.",
      "date": "1938"
    },
    {
      "headline": "First LSD Experience",
      "text": "On April 19, 1943, Albert Hofmann intentionally ingested LSD and experienced its psychedelic effects, marking the first recorded LSD trip.",
      "date": "1943-04-19"
    },
    {
      "headline": "Introduction of LSD to Psychiatry",
      "text": "In the 1950s, LSD began to be used in psychiatric research and therapy, with studies exploring its potential to treat mental health conditions.",
      "date": "1950"
    },
    {
      "headline": "Psilocybin Research",
      "text": "In 1958, Albert Hofmann isolated psilocybin and psilocin, the active compounds in psychedelic mushrooms, furthering research into naturally occurring psychedelics.",
      "date": "1958"
    },
    {
      "headline": "The Psychedelic Movement",
      "text": "During the 1960s, psychedelics became popular in the counterculture movement, with figures like Timothy Leary advocating for their use in expanding consciousness.",
      "date": "1960"
    },
    {
      "headline": "Controlled Substances Act",
      "text": "In 1970, the United States passed the Controlled Substances Act, classifying LSD and other psychedelics as Schedule I drugs, severely restricting their use.",
      "date": "1970"
    },
    {
      "headline": "Renewed Interest in Psychedelic Research",
      "text": "In the 1990s, interest in psychedelic research was renewed, with studies investigating their potential therapeutic benefits for conditions like PTSD and depression.",
      "date": "1990"
    },
    {
      "headline": "FDA Approves Psilocybin Trials",
      "text": "In 2018, the U.S. Food and Drug Administration (FDA) granted 'breakthrough therapy' designation to psilocybin for depression, facilitating further clinical trials.",
      "date": "2018"
    }
  ]
}

