    {
      "headline": "Removal by Thomas Bruce, 7th Earl of Elgin",
      "text": "Between 1801 and 1812, Thomas Bruce, 7th Earl of Elgin, removed a significant portion of the sculptures from the Parthenon and other structures on the Acropolis of Athens. This was done with the permission of the Ottoman Empire, which then ruled Greece.",
      "date": "1801"
    },
    {
      "headline": "Arrival in Britain",
      "text": "The Elgin Marbles were shipped to Britain and arrived between 1801 and 1812. They were initially displayed in Elgin's private residence.",
      "date": "1812"
    },
