    {
      "headline": "Official Start of the 2024 Pacific Hurricane Season",
      "text": "The 2024 Pacific hurricane season officially began on May 15 in the eastern Pacific basin and on June 1 in the central Pacific.",
      "date": "2024-05-15"
    },
    {
      "headline": "Slowest Start in Satellite Era",
      "text": "For the third consecutive year, there were no pre-season tropical cyclones in either basin, and the season got off to the slowest start of any Pacific hurricane season on record in the satellite era.",
      "date": "2024-06"
    },
    {
      "headline": "Formation of Tropical Storm Aletta",
      "text": "The first eastern Pacific tropical storm, Aletta, formed on July 4.",
      "date": "2024-07-04"
    },
    {
      "headline": "Formation of Tropical Storm Hone",
      "text": "The first, and only, central Pacific tropical storm, Hone, formed on August 22, becoming the first named storm to develop in the basin since 2019.",
      "date": "2024-08-22"
    },
    {
      "headline": "Dissipation of Tropical Depression Fourteen‑E",
      "text": "The final system of the season, Tropical Depression Fourteen‑E, dissipated on November 7.",
      "date": "2024-11-07"
    },
    {
      "headline": "Official End of the 2024 Pacific Hurricane Season",
      "text": "The 2024 Pacific hurricane season officially ended on November 30.",
      "date": "2024-11-30"
    }
  ]
}

{
