      "headline": "Founding of the Tijuana Cartel",
      "text": "The Tijuana Cartel, also known as the Arellano-Félix Cartel, was founded by the Arellano-Félix family in Tijuana, Baja California, Mexico. The cartel became known as one of the biggest and most violent criminal groups in Mexico.",
      "date": "1980s"
    },
    {
      "headline": "Peak of Power",
      "text": "During the 1990s, the Tijuana Cartel reached the peak of its power, controlling drug trafficking routes into the United States and engaging in violent confrontations with rival cartels.",
      "date": "1990s"
    },
    {
      "headline": "Sinaloa Cartel Incursion",
      "text": "In 2006, the Sinaloa Cartel began an incursion into Baja California, challenging the Tijuana Cartel's control over the region.",
      "date": "2006"
    },
    {
      "headline": "Fall of the Arellano-Félix Brothers",
      "text": "Following the Sinaloa Cartel's incursion, the Arellano-Félix brothers, leaders of the Tijuana Cartel, were captured or killed, leading to a significant reduction in the cartel's power.",
      "date": "2000s"
    },
    {
      "headline": "Rebranding as Cartel Tijuana Nueva Generación",
      "text": "In 2016, the organization rebranded itself as Cartel Tijuana Nueva Generación and aligned with the Jalisco New Generation Cartel and the Beltrán Leyva Organization to form an anti-Sinaloa alliance.",
      "date": "2016"
    },
    {
      "headline": "Current Conflicts",
      "text": "The alliance formed in 2016 has since dwindled, and the Tijuana, Jalisco New Generation, and Sinaloa cartels now battle each other for trafficking influence in Tijuana and Baja California.",
      "date": "2020s"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Crucifixion of Jesus",
      "text": "Jesus of Nazareth, the central figure of Christianity, was crucified by the Romans around the year 30-33 AD.",
      "date": "0030"
    },
    {
      "headline": "Pentecost",
      "text": "According to Christian tradition, the Holy Spirit descended upon the apostles and other followers of Jesus Christ, marking the beginning of the Christian Church. This event is celebrated as Pentecost, occurring 50 days after Easter.",
      "date": "0030"
    },
    {
      "headline": "Council of Jerusalem",
      "text": "Around 50 AD, the Council of Jerusalem was held to discuss the inclusion of Gentile converts into the Christian community, leading to the decision that they did not have to follow all Jewish laws.",
      "date": "0050"
    },
    {
      "headline": "Destruction of the Second Temple",
      "text": "In 70 AD, the Romans destroyed the Second Temple in Jerusalem, a pivotal event that led to the further separation of Christianity from Judaism.",
      "date": "0070"
    },
    {
      "headline": "Martyrdom of Peter and Paul",
      "text": "The apostles Peter and Paul were martyred in Rome around 64-68 AD during the reign of Emperor Nero.",
      "date": "0064"
    },
    {
      "headline": "Gospel of Mark Written",
      "text": "The Gospel of Mark, considered the earliest of the four canonical gospels, was likely written around 66-70 AD.",
      "date": "0066"
    },
    {
      "headline": "Gospel of Matthew Written",
      "text": "The Gospel of Matthew was likely composed between 70-100 AD, providing a Jewish perspective on the life and teachings of Jesus.",
      "date": "0070"
    },
    {
      "headline": "Gospel of Luke and Acts Written",
      "text": "The Gospel of Luke and the Acts of the Apostles, both attributed to Luke the Evangelist, were likely written around 80-90 AD.",
      "date": "0080"
    },
    {
      "headline": "Gospel of John Written",
      "text": "The Gospel of John, the last of the four canonical gospels, was likely written around 90-110 AD.",
      "date": "0090"
    },
    {
      "headline": "Persecution under Emperor Domitian",
      "text": "Christians faced persecution under Roman Emperor Domitian, who reigned from 81-96 AD.",
      "date": "0081"
    },
    {
      "headline": "Martyrdom of Ignatius of Antioch",
      "text": "Ignatius, the Bishop of Antioch, was martyred around 108-140 AD, known for his letters that provide insight into early Christian theology.",
      "date": "0108"
    },
    {
      "headline": "Martyrdom of Polycarp",
      "text": "Polycarp, the Bishop of Smyrna and a disciple of John the Apostle, was martyred around 155-160 AD.",
      "date": "0155"
    },
    {
      "headline": "Edict of Milan",
      "text": "In 313 AD, the Edict of Milan was issued by Emperor Constantine, granting religious tolerance for Christianity within the Roman Empire.",
      "date": "0313"
    },
    {
      "headline": "First Council of Nicaea",
      "text": "The First Council of Nicaea was convened in 325 AD by Emperor Constantine to address the Arian controversy and resulted in the Nicene Creed.",
      "date": "0325"
    }
  ]
}

