{
  "timeline": [
    {
      "headline": "Beginning of the Mesozoic Era",
      "text": "The Mesozoic Era began approximately 252 million years ago, following the Permian-Triassic extinction event, which was the most severe extinction event in Earth's history.",
      "date": "-0252"
    },
    {
      "headline": "Triassic Period",
      "text": "The Triassic Period lasted from about 252 to 201 million years ago. It was characterized by the recovery of life from the Permian extinction, the first appearance of dinosaurs, and the first mammals.",
      "date": "-0252"
    },
    {
      "headline": "Jurassic Period",
      "text": "The Jurassic Period spanned from approximately 201 to 145 million years ago. It saw the dominance of dinosaurs, the first birds, and the diversification of gymnosperms.",
      "date": "-0201"
    },
    {
      "headline": "Cretaceous Period",
      "text": "The Cretaceous Period lasted from about 145 to 66 million years ago. It was marked by the further diversification of dinosaurs, the appearance of flowering plants, and the breakup of the supercontinent Pangaea.",
      "date": "-0145"
    },
    {
      "headline": "End of the Mesozoic Era",
      "text": "The Mesozoic Era ended approximately 66 million years ago with the Cretaceous-Paleogene extinction event, which led to the extinction of the non-avian dinosaurs and many other species.",
      "date": "-0066"
    }
  ]
}

