    {
      "headline": "First Jewish–Roman War",
      "text": "During the First Jewish–Roman War, Masada was the site of the last stand of the Jewish rebels against the Roman Empire. The war began in 66 CE.",
      "date": "0066"
    },
    {
      "headline": "Siege of Masada",
      "text": "The Roman siege of Masada took place from 73 to 74 CE. The Roman governor Lucius Flavius Silva led the Roman legion X Fretensis in the siege against the Jewish rebels.",
      "date": "0073"
    },
    {
      "headline": "Fall of Masada",
      "text": "In 74 CE, after a lengthy siege, the Roman forces breached the walls of Masada. According to the historian Josephus, the Jewish defenders, led by Eleazar ben Yair, chose mass suicide over capture.",
      "date": "0074"
    },
    {
      "headline": "Rediscovery of Masada",
      "text": "Masada was rediscovered in the 19th century by explorers and archaeologists, with significant excavations conducted in the 1960s by Israeli archaeologist Yigael Yadin.",
      "date": "1960"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 2001, Masada was declared a UNESCO World Heritage Site, recognizing its historical and cultural significance.",
      "date": "2001"
    }
  ]
}

