      "headline": "Birth of Anna May Wong",
      "text": "Anna May Wong was born on January 3, 1905, in Los Angeles, California, USA.",
      "date": "1905-01-03"
    },
    {
      "headline": "Film Debut",
      "text": "In 1919, at the age of 14, Anna May Wong made her film debut as an extra in the film 'The Red Lantern'.",
      "date": "1919"
    },
    {
      "headline": "First Leading Role",
      "text": "In 1922, Wong received her first leading role in the film 'The Toll of the Sea', one of the first Technicolor films.",
      "date": "1922"
    },
    {
      "headline": "International Recognition",
      "text": "In 1924, Wong gained international recognition with her role in 'The Thief of Bagdad', starring opposite Douglas Fairbanks.",
      "date": "1924"
    },
    {
      "headline": "Move to Europe",
      "text": "Frustrated with stereotypical roles in Hollywood, Wong moved to Europe in 1928 to pursue a more diverse acting career.",
      "date": "1928"
    },
    {
      "headline": "Return to Hollywood",
      "text": "Anna May Wong returned to Hollywood in 1930 to star in the film 'Daughter of the Dragon'.",
      "date": "1930"
    },
    {
      "headline": "Star in 'Shanghai Express'",
      "text": "In 1932, Wong starred alongside Marlene Dietrich in the film 'Shanghai Express', which was a commercial success.",
      "date": "1932"
    },
    {
      "headline": "Broadway Debut",
      "text": "Wong made her Broadway debut in 1938 in the play 'On the Spot'.",
      "date": "1938"
    },
    {
      "headline": "World War II Efforts",
      "text": "During World War II, Wong devoted her time to helping the Chinese cause against Japan and worked with the United China Relief Fund.",
      "date": "1940s"
    },
    {
      "headline": "Television Career",
      "text": "In the 1950s, Wong became one of the first Asian Americans to star in a U.S. television series, 'The Gallery of Madame Liu-Tsong'.",
      "date": "1951"
    },
    {
      "headline": "Final Film Role",
      "text": "Wong's final film role was in 'Portrait in Black' in 1960.",
      "date": "1960"
    },
    {
      "headline": "Death of Anna May Wong",
      "text": "Anna May Wong passed away on February 3, 1961, in Santa Monica, California, USA, at the age of 56.",
      "date": "1961-02-03"
    }
  ]
}

