    {
      "headline": "Growth of the Tournament",
      "text": "By 2007, the Homeless World Cup had grown significantly, with the tournament in Copenhagen, Denmark, featuring 48 teams.",
      "date": "2007"
    },
    {
      "headline": "Expansion to Women's Teams",
      "text": "In 2008, the Homeless World Cup included women's teams for the first time, reflecting the organization's commitment to inclusivity.",
      "date": "2008"
    },
    {
      "headline": "10th Anniversary Tournament",
      "text": "The 10th anniversary of the Homeless World Cup was celebrated in 2012 with a tournament held in Mexico City, Mexico.",
      "date": "2012"
    },
    {
      "headline": "Edinburgh Tournament",
      "text": "In 2016, the Homeless World Cup was held in Edinburgh, Scotland, marking a return to the UK for the first time since 2005.",
      "date": "2016"
    },
    {
      "headline": "Impact and Reach",
      "text": "By 2019, the Homeless World Cup had grown to include 64 teams from around the world, with the tournament held in Cardiff, Wales.",
      "date": "2019"
    }
  ]
}

