    {
      "headline": "First Mention of Illyrians",
      "text": "The Illyrians were first mentioned in historical records by ancient Greek writers in the 6th century BCE.",
      "date": "-0600"
    },
    {
      "headline": "Illyrian Kingdoms Established",
      "text": "By the 4th century BCE, several Illyrian kingdoms had been established, including the Kingdom of the Taulantii and the Kingdom of the Dardani.",
      "date": "-0400"
    },
    {
      "headline": "Reign of King Bardylis",
      "text": "King Bardylis of the Dardani expanded his kingdom and became a significant power in the region during the 4th century BCE.",
      "date": "-0395"
    },
    {
      "headline": "Illyrian Wars with Macedonia",
      "text": "The Illyrians frequently clashed with the Macedonians, notably during the reign of King Philip II of Macedon in the 4th century BCE.",
      "date": "-0359"
    },
    {
      "headline": "Reign of Queen Teuta",
      "text": "Queen Teuta ruled the Ardiaei kingdom and engaged in piracy against Roman merchants, leading to the First Illyrian War with Rome in 229 BCE.",
      "date": "-0229"
    },
    {
      "headline": "First Illyrian War",
      "text": "The First Illyrian War between Rome and the Illyrians occurred from 229 to 228 BCE, resulting in Roman victory and the establishment of Roman influence in the region.",
      "date": "-0229"
    },
    {
      "headline": "Second Illyrian War",
      "text": "The Second Illyrian War took place from 220 to 219 BCE, further consolidating Roman control over the Illyrian territories.",
      "date": "-0220"
    },
    {
      "headline": "Third Illyrian War",
      "text": "The Third Illyrian War occurred in 168 BCE, leading to the defeat of King Gentius and the annexation of Illyria into the Roman Republic.",
      "date": "-0168"
    },
    {
      "headline": "Roman Province of Illyricum",
      "text": "Following the Third Illyrian War, the region was organized as the Roman province of Illyricum in 167 BCE.",
      "date": "-0167"
    },
    {
      "headline": "Illyrian Revolt",
      "text": "The Great Illyrian Revolt, also known as the Pannonian Revolt, occurred from 6 to 9 CE, as the Illyrians rebelled against Roman rule.",
      "date": "0006"
    }
  ]
}

