{
  "timeline": [
    {
      "headline": "Introduction of the Birth Control Pill",
      "text": "In 1960, the FDA approved the first oral contraceptive pill, which played a significant role in the sexual revolution by giving women more control over their reproductive rights.",
      "date": "1960"
    },
    {
      "headline": "Publication of 'The Feminine Mystique'",
      "text": "In 1963, Betty Friedan published 'The Feminine Mystique', which challenged the traditional roles of women and contributed to the feminist movement, a key component of the sexual revolution.",
      "date": "1963"
    },
    {
      "headline": "Griswold v. Connecticut",
      "text": "In 1965, the U.S. Supreme Court case Griswold v. Connecticut struck down a law prohibiting the use of contraceptives, establishing the right to privacy in marital relations.",
      "date": "1965"
    },
    {
      "headline": "Stonewall Riots",
      "text": "In June 1969, the Stonewall Riots occurred in New York City, marking a pivotal event in the fight for LGBTQ+ rights and a significant moment in the sexual revolution.",
      "date": "1969-06"
    },
    {
      "headline": "Legalization of Abortion in the U.S.",
      "text": "In 1973, the U.S. Supreme Court decision in Roe v. Wade legalized abortion nationwide, representing a major victory for reproductive rights advocates.",
      "date": "1973"
    },
    {
      "headline": "Publication of 'Our Bodies, Ourselves'",
      "text": "In 1971, the Boston Women's Health Book Collective published 'Our Bodies, Ourselves', a groundbreaking book on women's health and sexuality.",
      "date": "1971"
    },
    {
      "headline": "End of the Sexual Revolution",
      "text": "By the mid-1970s, the sexual revolution began to wane as societal attitudes shifted and the AIDS crisis emerged in the following decade.",
      "date": "1975"
    }
  ]
}

