{
  "timeline": [
    {
      "headline": "Construction of Babri Masjid",
      "text": "The Babri Masjid was constructed in the 16th century by Mir Baqi, a commander of the Mughal emperor Babur, in the city of Ayodhya, Uttar Pradesh, India.",
      "date": "1528"
    },
    {
      "headline": "First Recorded Communal Clashes",
      "text": "The first recorded communal clashes over the site occurred in 1853, during the reign of Nawab Wajid Ali Shah of Awadh.",
      "date": "1853"
    },
    {
      "headline": "British Administration Erects Fence",
      "text": "In 1859, the British colonial administration erected a fence to separate the places of worship, allowing the inner court to be used by Muslims and the outer court by Hindus.",
      "date": "1859"
    },
    {
      "headline": "Idols Placed Inside Mosque",
      "text": "In December 1949, idols of Rama were placed inside the mosque, leading to protests and the site being locked by the government.",
      "date": "1949-12"
    },
    {
      "headline": "Court Orders Site to Remain Locked",
      "text": "In 1950, a court ordered the site to remain locked, allowing only a Hindu priest to perform rituals.",
      "date": "1950"
    },
    {
      "headline": "Opening of Locks",
      "text": "In 1986, a district judge ordered the gates of the disputed site to be unlocked, allowing Hindus to worship there.",
      "date": "1986"
    },
    {
      "headline": "Rath Yatra by L.K. Advani",
      "text": "In September 1990, Bharatiya Janata Party leader L.K. Advani began a Rath Yatra (chariot journey) to garner support for the construction of a Ram temple at the site.",
      "date": "1990-09"
    },
    {
      "headline": "Demolition of Babri Masjid",
      "text": "On 6 December 1992, the Babri Masjid was demolished by a large group of activists of the Vishva Hindu Parishad and allied organisations after a political rally turned violent.",
      "date": "1992-12-06"
    },
    {
      "headline": "Riots Following Demolition",
      "text": "The demolition led to widespread riots across India, resulting in the deaths of over 2,000 people.",
      "date": "1992-12"
    },
    {
      "headline": "Liberhan Commission",
      "text": "In 1992, the Indian government set up the Liberhan Commission to investigate the demolition. The commission submitted its report in 2009.",
      "date": "1992"
    },
    {
      "headline": "Supreme Court Verdict",
      "text": "On 9 November 2019, the Supreme Court of India ruled that the land should be handed over to a trust to build a Hindu temple, and that an alternative site be provided to Muslims for a mosque.",
      "date": "2019-11-09"
    }
  ]
}

