{
  "timeline": [
    {
      "headline": "Birth of Yuan Shikai",
      "text": "Yuan Shikai was born on September 16, 1859, in the village of Zhangying, Xiangcheng County, Henan, China.",
      "date": "1859-09-16"
    },
    {
      "headline": "Military Career Begins",
      "text": "In 1881, Yuan Shikai began his military career by joining the Huai Army, which was a part of the Qing dynasty's military forces.",
      "date": "1881"
    },
    {
      "headline": "Appointed as Imperial Resident in Korea",
      "text": "In 1885, Yuan Shikai was appointed as the Imperial Resident in Korea, where he played a significant role in Chinese affairs on the Korean Peninsula.",
      "date": "1885"
    },
    {
      "headline": "Reforms in the Beiyang Army",
      "text": "In the late 1890s, Yuan Shikai implemented significant reforms in the Beiyang Army, modernizing its structure and training.",
      "date": "1890"
    },
    {
      "headline": "Role in the Boxer Rebellion",
      "text": "During the Boxer Rebellion in 1900, Yuan Shikai's forces were instrumental in maintaining order in northern China.",
      "date": "1900"
    },
    {
      "headline": "Appointed Viceroy of Zhili and Minister of Beiyang",
      "text": "In 1901, Yuan Shikai was appointed as the Viceroy of Zhili and Minister of Beiyang, giving him significant military and political power.",
      "date": "1901"
    },
    {
      "headline": "Dismissal from Office",
      "text": "In 1909, Yuan Shikai was dismissed from his official positions by the Qing court due to political rivalries.",
      "date": "1909"
    },
    {
      "headline": "Return to Power",
      "text": "In 1911, following the Wuchang Uprising and the start of the Xinhai Revolution, Yuan Shikai was recalled to lead the Beiyang Army to suppress the revolution.",
      "date": "1911"
    },
    {
      "headline": "Becomes Provisional President of the Republic of China",
      "text": "On March 10, 1912, Yuan Shikai became the provisional president of the Republic of China after the abdication of the last Qing emperor.",
      "date": "1912-03-10"
    },
    {
      "headline": "Inauguration as Official President",
      "text": "Yuan Shikai was inaugurated as the official President of the Republic of China on October 10, 1913.",
      "date": "1913-10-10"
    },
    {
      "headline": "Proclaims Himself Emperor",
      "text": "On December 12, 1915, Yuan Shikai declared himself Emperor of China, founding the short-lived Empire of China.",
      "date": "1915-12-12"
    },
    {
      "headline": "Abdication as Emperor",
      "text": "Facing widespread opposition and rebellion, Yuan Shikai abdicated as Emperor on March 22, 1916.",
      "date": "1916-03-22"
    },
    {
      "headline": "Death of Yuan Shikai",
      "text": "Yuan Shikai died on June 6, 1916, in Beijing, China, marking the end of his controversial rule.",
      "date": "1916-06-06"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Creation of Lascaux Cave Paintings",
      "text": "The Lascaux cave paintings were created during the Upper Paleolithic period, estimated to be around 17,000 to 22,000 years ago. These paintings primarily depict large animals and are believed to be the work of many generations.",
      "date": "-20000"
    },
    {
      "headline": "Discovery of Lascaux Caves",
      "text": "The Lascaux caves were discovered on September 12, 1940, by four teenagers: Marcel Ravidat, Jacques Marsal, Georges Agnel, and Simon Coencas, along with their dog, Robot.",
      "date": "1940-09-12"
    },
    {
      "headline": "Opening to the Public",
      "text": "The Lascaux caves were opened to the public in 1948, allowing visitors to view the prehistoric paintings.",
      "date": "1948"
    },
    {
      "headline": "Closure to the Public",
      "text": "In 1963, the Lascaux caves were closed to the public due to damage caused by carbon dioxide, heat, humidity, and other contaminants produced by visitors.",
      "date": "1963"
    },
    {
      "headline": "UNESCO World Heritage Site Designation",
      "text": "In 1979, the Lascaux caves were designated as a UNESCO World Heritage Site as part of the Prehistoric Sites and Decorated Caves of the Vézère Valley.",
      "date": "1979"
    },
    {
      "headline": "Opening of Lascaux II",
      "text": "Lascaux II, a replica of the Great Hall of the Bulls and the Painted Gallery, was opened in 1983 to allow visitors to experience the cave paintings without damaging the originals.",
      "date": "1983"
    }
  ]
}

