{
  "timeline": [
    {
      "headline": "Chernobyl Disaster Occurs",
      "text": "The Chernobyl disaster, considered the worst nuclear disaster in history, occurred on 26 April 1986 at the Chernobyl Nuclear Power Plant in the Ukrainian Soviet Socialist Republic, then part of the Soviet Union, now in Ukraine.",
      "date": "1986-04-26"
    },
    {
      "headline": "Immediate Deaths Due to Blast and Acute Radiation Syndrome",
      "text": "Approximately 30 people died from immediate blast trauma and acute radiation syndrome (ARS) in the seconds to months after the disaster.",
      "date": "1986"
    },
    {
      "headline": "Total Deaths in Decades Following the Disaster",
      "text": "A total of approximately 60 people have died in the decades since the disaster, inclusive of later radiation-induced cancer.",
      "date": "1986-2023"
    },
    {
      "headline": "Projected Long-term Death Estimates",
      "text": "Long-term death estimates range from up to 4,000 for the most exposed people of Ukraine, Belarus, and Russia, to 16,000 cases in total for all those exposed on the entire continent of Europe, with figures as high as 60,000 when including the relatively minor effects around the globe.",
      "date": "1986-2023"
    }
  ]
}

{
  "timeline": [
