{
  "timeline": [
    {
      "headline": "Creation of the Chief of Defence Staff Position",
      "text": "On December 24, 2019, the Government of India approved the creation of the Chief of Defence Staff (CDS) position. This role was established to enhance coordination and integration among the Indian Army, Navy, and Air Force.",
      "date": "2019-12-24"
    },
    {
      "headline": "Appointment of the First Chief of Defence Staff",
      "text": "General Bipin Rawat was appointed as the first Chief of Defence Staff of India on December 30, 2019. He assumed office on January 1, 2020.",
      "date": "2020-01-01"
    },
    {
      "headline": "General Bipin Rawat's Tenure as CDS",
      "text": "General Bipin Rawat served as the Chief of Defence Staff from January 1, 2020, until his untimely death in a helicopter crash on December 8, 2021.",
      "date": "2021-12-08"
    },
    {
      "headline": "Helicopter Crash and Death of General Bipin Rawat",
      "text": "On December 8, 2021, General Bipin Rawat, along with his wife and 11 others, died in a helicopter crash in Tamil Nadu, India.",
      "date": "2021-12-08"
    },
    {
