      "headline": "Founding of ETA",
      "text": "ETA was founded in 1959 during the era of Francoist Spain. It began as a pacifist group promoting traditional Basque culture.",
      "date": "1959"
    },
    {
      "headline": "First Violent Action",
      "text": "ETA's first known violent action took place in 1961 when they attempted to derail a train carrying Francoist veterans.",
      "date": "1961"
    },
    {
      "headline": "First Assassination",
      "text": "On June 7, 1968, ETA carried out its first assassination, killing Melitón Manzanas, a secret police chief in San Sebastián.",
      "date": "1968-06-07"
    },
    {
      "headline": "Burgos Trial",
      "text": "In December 1970, the Burgos Trial took place, where 16 ETA members were tried by a military court, leading to international attention and protests.",
      "date": "1970-12"
    },
    {
      "headline": "Assassination of Luis Carrero Blanco",
      "text": "On December 20, 1973, ETA assassinated Spanish Prime Minister Luis Carrero Blanco in a car bombing in Madrid.",
      "date": "1973-12-20"
    },
    {
      "headline": "Spanish Transition to Democracy",
      "text": "Following Franco's death in 1975, Spain transitioned to democracy, but ETA continued its violent campaign, rejecting the new democratic framework.",
      "date": "1975"
    },
    {
      "headline": "Creation of the Basque Autonomous Community",
      "text": "In 1979, the Statute of Autonomy of the Basque Country was approved, creating the Basque Autonomous Community, but ETA continued its activities.",
      "date": "1979"
    },
    {
      "headline": "ETA Declares Ceasefire",
      "text": "On September 16, 1998, ETA declared a unilateral ceasefire, which lasted until December 1999.",
      "date": "1998-09-16"
    },
    {
      "headline": "Madrid Barajas Airport Bombing",
      "text": "On December 30, 2006, ETA detonated a bomb at Madrid Barajas Airport, killing two people, ending a ceasefire declared in March 2006.",
      "date": "2006-12-30"
    },
    {
      "headline": "Permanent Ceasefire Announcement",
      "text": "On January 10, 2011, ETA announced a permanent, general, and verifiable ceasefire.",
      "date": "2011-01-10"
    },
    {
      "headline": "ETA Announces End of Armed Activity",
      "text": "On October 20, 2011, ETA announced the definitive cessation of its armed activities.",
      "date": "2011-10-20"
    },
    {
      "headline": "ETA Disbands",
      "text": "On May 3, 2018, ETA announced its dissolution and the end of its political initiative.",
      "date": "2018-05-03"
    }
  ]
}

