{
  "timeline": [
    {
      "headline": "Origin of Technocracy Concept",
      "text": "The concept of technocracy originated in the early 20th century, particularly during the Progressive Era in the United States, as a response to the perceived inefficiencies and corruption of traditional political systems.",
      "date": "1900"
    },
    {
      "headline": "Thorstein Veblen's Influence",
      "text": "Thorstein Veblen, an American economist and sociologist, was one of the early proponents of technocracy. His work in the early 20th century laid the groundwork for the idea that engineers and technical experts should be in charge of economic and political systems.",
      "date": "1920"
    },
    {
      "headline": "Technocracy Movement in the United States",
      "text": "The Technocracy movement gained momentum in the United States during the Great Depression in the 1930s. It proposed replacing politicians and businesspeople with scientists and engineers who had the technical expertise to manage the economy.",
      "date": "1930"
    },
    {
      "headline": "Howard Scott and the Technocracy Inc.",
      "text": "In 1933, Howard Scott founded Technocracy Inc., an organization that advocated for a technocratic society. The group gained significant attention during the 1930s, promoting the idea of a government run by technical experts.",
      "date": "1933"
    },
    {
      "headline": "Technocracy in Canada",
      "text": "Technocracy also found support in Canada during the 1930s, where it was seen as a potential solution to the economic challenges of the Great Depression.",
      "date": "1930"
    },
    {
      "headline": "Decline of the Technocracy Movement",
      "text": "By the late 1930s, the Technocracy movement began to decline in popularity. The New Deal policies in the United States and the onset of World War II shifted public attention away from technocratic ideas.",
      "date": "1939"
    },
    {
      "headline": "Technocracy in Modern Context",
      "text": "In the late 20th and early 21st centuries, technocracy has seen a resurgence in some regions, particularly in Europe and Asia, where technocrats have been appointed to governmental positions to address complex economic and technological challenges.",
      "date": "2000"
    }
  ]
}

