    {
      "headline": "Establishment of Southern Rhodesia",
      "text": "Southern Rhodesia was established as a self-governing British Crown colony on October 1, 1923, following a referendum in which the electorate chose responsible government over joining the Union of South Africa.",
      "date": "1923-10-01"
    },
    {
      "headline": "Federation of Rhodesia and Nyasaland",
      "text": "On August 1, 1953, Southern Rhodesia joined Northern Rhodesia and Nyasaland to form the Federation of Rhodesia and Nyasaland, also known as the Central African Federation.",
      "date": "1953-08-01"
    },
    {
      "headline": "Dissolution of the Federation",
      "text": "The Federation of Rhodesia and Nyasaland was dissolved on December 31, 1963, leading to the re-establishment of Southern Rhodesia as a separate colony.",
      "date": "1963-12-31"
    },
    {
      "headline": "Unilateral Declaration of Independence",
      "text": "On November 11, 1965, the government of Southern Rhodesia, led by Prime Minister Ian Smith, unilaterally declared independence from the United Kingdom, an act not recognized by the British government.",
      "date": "1965-11-11"
    },
    {
      "headline": "Republic of Rhodesia",
      "text": "Southern Rhodesia declared itself a republic on March 2, 1970, after a referendum, further entrenching its unrecognized independence.",
      "date": "1970-03-02"
    },
    {
      "headline": "Lancaster House Agreement",
      "text": "The Lancaster House Agreement was signed on December 21, 1979, leading to the end of the Rhodesian Bush War and setting the stage for recognized independence under majority rule.",
      "date": "1979-12-21"
    },
    {
      "headline": "Independence as Zimbabwe",
      "text": "Southern Rhodesia officially became the independent Republic of Zimbabwe on April 18, 1980, following elections and the implementation of the Lancaster House Agreement.",
      "date": "1980-04-18"
    }
  ]
}

