{
  "timeline": [
    {
      "headline": "First Description of Rubella",
      "text": "The disease now known as rubella was first described by German physicians in the mid-18th century. It was initially considered a variant of measles or scarlet fever.",
      "date": "1752"
    },
    {
      "headline": "Rubella Recognized as a Distinct Disease",
      "text": "In 1814, George de Maton recognized rubella as a distinct disease separate from measles and scarlet fever.",
      "date": "1814"
    },
    {
      "headline": "Naming of Rubella",
      "text": "The term 'rubella' was first used in 1866 by Henry Veale, derived from the Latin word meaning 'little red'.",
      "date": "1866"
    },
    {
      "headline": "Discovery of Congenital Rubella Syndrome",
      "text": "In 1941, Australian ophthalmologist Norman McAlister Gregg discovered the link between rubella infection in pregnant women and congenital defects in their babies, leading to the identification of congenital rubella syndrome (CRS).",
      "date": "1941"
    },
    {
      "headline": "Isolation of Rubella Virus",
      "text": "The rubella virus was first isolated in 1962 by two separate groups of researchers, Weller and Neva, and Parkman, Buescher, and Artenstein.",
      "date": "1962"
    },
    {
      "headline": "Development of Rubella Vaccine",
      "text": "The first rubella vaccine was licensed in 1969, significantly reducing the incidence of rubella and congenital rubella syndrome.",
      "date": "1969"
    },
    {
      "headline": "Introduction of MMR Vaccine",
      "text": "In 1971, the combined measles, mumps, and rubella (MMR) vaccine was introduced, further aiding in the control of rubella.",
      "date": "1971"
    },
    {
      "headline": "Rubella Elimination in the Americas",
      "text": "In 2015, the World Health Organization declared the Americas free of endemic rubella transmission, marking a significant public health achievement.",
      "date": "2015"
    }
  ]
}

