{
  "timeline": [
    {
      "headline": "Establishment of the French Army",
      "text": "The French Army, as a formal institution, traces its origins back to the early Middle Ages, but it was officially established as a standing army in the 15th century under King Charles VII.",
      "date": "1445"
    },
    {
      "headline": "Reforms of Louis XIV",
      "text": "Under King Louis XIV, the French Army underwent significant reforms, including the establishment of a professional standing army and the development of a more centralized command structure. These reforms were part of Louis XIV's efforts to strengthen royal power and expand French influence in Europe.",
      "date": "1660"
    },
    {
      "headline": "Napoleonic Wars",
      "text": "The French Army played a central role in the Napoleonic Wars (1803-1815), where it was led by Napoleon Bonaparte. The army achieved numerous victories across Europe, significantly impacting European political boundaries.",
      "date": "1803"
    },
    {
      "headline": "Franco-Prussian War",
      "text": "The French Army was involved in the Franco-Prussian War (1870-1871), which resulted in a decisive defeat for France and led to the fall of the Second French Empire.",
      "date": "1870"
    },
    {
      "headline": "World War I",
      "text": "During World War I (1914-1918), the French Army was a major Allied force, enduring significant battles such as the Battle of the Marne and the Battle of Verdun.",
      "date": "1914"
    },
    {
      "headline": "World War II",
      "text": "In World War II (1939-1945), the French Army initially faced defeat during the German invasion in 1940, leading to the occupation of France. However, Free French Forces continued to fight alongside the Allies until the liberation of France in 1944.",
      "date": "1939"
    },
    {
      "headline": "Algerian War",
      "text": "The French Army was heavily involved in the Algerian War (1954-1962), a conflict that ultimately led to Algeria gaining independence from France.",
      "date": "1954"
    },
    {
      "headline": "Professionalization of the French Army",
      "text": "In 1996, the French government decided to transition the French Army into a fully professional force, ending conscription and focusing on modernization and rapid deployment capabilities.",
      "date": "1996"
    }
  ]
}

