{
  "timeline": [
    {
      "headline": "Introduction of Public-key Cryptography",
      "text": "The concept of public-key cryptography was introduced in 1976 by Whitfield Diffie and Martin Hellman in their paper 'New Directions in Cryptography'.",
      "date": "1976"
    },
    {
      "headline": "Diffie-Hellman Key Exchange",
      "text": "The Diffie-Hellman key exchange method was the first practical method for establishing a shared secret over an unprotected communications channel. It was introduced in 1976.",
      "date": "1976"
    },
    {
      "headline": "RSA Algorithm Developed",
      "text": "In 1977, Ron Rivest, Adi Shamir, and Leonard Adleman developed the RSA algorithm, one of the first public-key cryptosystems, which is widely used for secure data transmission.",
      "date": "1977"
    },
    {
      "headline": "First Public Description of RSA",
      "text": "The RSA algorithm was publicly described in 1978 in the paper 'A Method for Obtaining Digital Signatures and Public-Key Cryptosystems' by Rivest, Shamir, and Adleman.",
      "date": "1978"
    },
    {
      "headline": "Introduction of ElGamal Encryption",
      "text": "In 1985, Taher ElGamal introduced the ElGamal encryption system, which is based on the Diffie-Hellman key exchange.",
      "date": "1985"
    },
    {
      "headline": "Development of Elliptic Curve Cryptography",
      "text": "Elliptic Curve Cryptography (ECC) was independently proposed by Neal Koblitz and Victor S. Miller in 1985 as an alternative to traditional public-key cryptosystems.",
      "date": "1985"
    },
    {
      "headline": "Introduction of Digital Signature Algorithm (DSA)",
      "text": "In 1991, the National Institute of Standards and Technology (NIST) proposed the Digital Signature Algorithm (DSA) for digital signatures, which was adopted as a Federal Information Processing Standard.",
      "date": "1991"
    },
    {
      "headline": "Adoption of Public-key Cryptography Standards",
      "text": "In the 1990s, various standards for public-key cryptography were developed, including PKCS (Public-Key Cryptography Standards) by RSA Laboratories.",
      "date": "1990s"
    },
    {
      "headline": "Introduction of Quantum-resistant Algorithms",
      "text": "In the 2010s, research into quantum-resistant algorithms began to address the potential future threat of quantum computers to public-key cryptography.",
      "date": "2010s"
    }
  ]
}

