  "timeline": [
    {
      "headline": "Birth of William Tyndale",
      "text": "William Tyndale was born around 1494 in Gloucestershire, England.",
      "date": "1494"
    },
    {
      "headline": "Education at Oxford",
      "text": "Tyndale attended Magdalen Hall, Oxford, where he received a Bachelor of Arts degree in 1512 and a Master of Arts degree in 1515.",
      "date": "1515"
    },
    {
      "headline": "Studies at Cambridge",
      "text": "After Oxford, Tyndale went to the University of Cambridge, where he furthered his studies and was influenced by the ideas of the Reformation.",
      "date": "1520"
    },
    {
      "headline": "Begins Translation of the New Testament",
      "text": "In 1523, Tyndale sought permission and funds to translate the Bible into English, but was denied by the Bishop of London.",
      "date": "1523"
    },
    {
      "headline": "Flees to Germany",
      "text": "In 1524, Tyndale left England for Germany to pursue his translation work without interference.",
      "date": "1524"
    },
    {
      "headline": "First English New Testament",
      "text": "In 1526, Tyndale's English translation of the New Testament was printed in Worms, Germany, and smuggled into England.",
      "date": "1526"
    },
    {
      "headline": "Continued Translation Work",
      "text": "Tyndale continued his translation work, including parts of the Old Testament, while living in Antwerp, Belgium.",
      "date": "1529"
    },
    {
      "headline": "Publication of The Pentateuch",
      "text": "In 1530, Tyndale published his translation of the Pentateuch, the first five books of the Old Testament.",
      "date": "1530"
    },
    {
      "headline": "Arrest and Imprisonment",
      "text": "Tyndale was arrested in 1535 in Antwerp and imprisoned in the castle of Vilvoorde near Brussels.",
      "date": "1535"
    },
    {
      "headline": "Execution",
      "text": "On October 6, 1536, William Tyndale was executed by strangulation and then burned at the stake for heresy.",
      "date": "1536-10-06"
    }
  ]
}

