      "headline": "Founding of Bacardi",
      "text": "Bacardi was founded on February 4, 1862, by Facundo Bacardí Massó in Santiago de Cuba. The company began as a small distillery producing rum.",
      "date": "1862-02-04"
    },
    {
      "headline": "Creation of Bacardi White Rum",
      "text": "Facundo Bacardí Massó developed a unique method of rum production that resulted in a smooth, light-bodied rum, which became known as Bacardi White Rum.",
      "date": "1862"
    },
    {
      "headline": "Introduction of the Bat Logo",
      "text": "In 1862, Bacardi adopted the bat as its logo, inspired by the fruit bats that lived in the rafters of the original distillery.",
      "date": "1862"
    },
    {
      "headline": "Expansion to the United States",
      "text": "In 1910, Bacardi expanded its operations to the United States, establishing a bottling plant in New York City.",
      "date": "1910"
    },
    {
      "headline": "Prohibition Era",
      "text": "During the Prohibition era in the United States (1920-1933), Bacardi's rum became popular among Americans who traveled to Cuba to enjoy legal drinking.",
      "date": "1920"
    },
    {
      "headline": "Relocation to Puerto Rico",
      "text": "In 1936, Bacardi opened a distillery in Puerto Rico to ensure continued access to the U.S. market, taking advantage of Puerto Rico's status as a U.S. territory.",
      "date": "1936"
    },
    {
      "headline": "Cuban Revolution and Exile",
      "text": "After the Cuban Revolution in 1959, Bacardi faced nationalization of its assets in Cuba and subsequently relocated its headquarters to Bermuda in 1965.",
      "date": "1965"
    },
    {
      "headline": "Introduction of Bacardi 151",
      "text": "In 1963, Bacardi introduced Bacardi 151, a highly alcoholic rum with 75.5% alcohol by volume.",
      "date": "1963"
    },
    {
      "headline": "Acquisition of Martini & Rossi",
      "text": "In 1993, Bacardi acquired Martini & Rossi, an Italian company known for its vermouth and sparkling wines, significantly expanding its product portfolio.",
      "date": "1993"
    },
    {
      "headline": "Acquisition of Grey Goose",
      "text": "In 2004, Bacardi acquired Grey Goose, a premium vodka brand, further diversifying its offerings in the spirits market.",
      "date": "2004"
    },
    {
      "headline": "150th Anniversary",
      "text": "In 2012, Bacardi celebrated its 150th anniversary, marking a century and a half since its founding in Cuba.",
      "date": "2012"
    }
  ]
}

