{
  "timeline": [
    {
      "headline": "Ancient Understanding of Hysteria",
      "text": "The concept of hysteria dates back to ancient Egypt and Greece, where it was believed that a woman's uterus could wander through her body, causing various symptoms. This belief persisted for centuries.",
      "date": "-1900"
    },
    {
      "headline": "Hysteria in the Middle Ages",
      "text": "During the Middle Ages, hysteria was often associated with witchcraft or demonic possession. Women exhibiting symptoms were sometimes subjected to exorcisms or other religious rituals.",
      "date": "1200"
    },
    {
      "headline": "Hysteria as a Medical Diagnosis",
      "text": "In the 19th century, hysteria became a common medical diagnosis for women. It was thought to be caused by disturbances in the uterus and was treated with a variety of methods, including rest cures and, in some cases, hysterectomies.",
      "date": "1800"
    },
    {
      "headline": "Jean-Martin Charcot's Research",
      "text": "In the late 19th century, neurologist Jean-Martin Charcot conducted research on hysteria at the Salpêtrière Hospital in Paris. He used hypnosis to study and treat patients, influencing future research on the condition.",
      "date": "1870"
    },
    {
      "headline": "Sigmund Freud's Studies",
      "text": "Sigmund Freud, influenced by Charcot, began studying hysteria and developed the theory of psychoanalysis. He proposed that hysteria was linked to repressed emotions and unresolved psychological conflicts.",
      "date": "1895"
    },
    {
      "headline": "Decline of Hysteria Diagnosis",
      "text": "By the early 20th century, the diagnosis of hysteria began to decline as understanding of mental health improved. It was gradually replaced by more specific diagnoses such as anxiety disorders and depression.",
      "date": "1900"
    },
    {
      "headline": "Hysteria in Modern Context",
      "text": "Today, hysteria is no longer recognized as a medical diagnosis. The term is used more broadly to describe extreme emotional reactions, and historical cases are often re-evaluated under modern psychological understanding.",
      "date": "2000"
    }
  ]
}

