{
  "timeline": [
    {
      "headline": "Development of Nuclear Weapons",
      "text": "The development of nuclear weapons began during World War II, with the United States' Manhattan Project, which led to the creation of the first atomic bombs in 1945.",
      "date": "1945"
    },
    {
      "headline": "Use of Atomic Bombs in World War II",
      "text": "The United States dropped atomic bombs on the Japanese cities of Hiroshima and Nagasaki in August 1945, leading to Japan's surrender and the end of World War II.",
      "date": "1945-08"
    },
    {
      "headline": "Start of the Cold War",
      "text": "The Cold War began shortly after World War II, characterized by political and military tension between the United States and the Soviet Union, both of which possessed nuclear weapons.",
      "date": "1947"
    },
    {
      "headline": "Introduction of the MAD Doctrine",
      "text": "The concept of Mutual Assured Destruction (MAD) emerged during the Cold War as both the United States and the Soviet Union developed second-strike capabilities, ensuring that any nuclear attack would result in the total destruction of both the attacker and the defender.",
      "date": "1960s"
    },
    {
      "headline": "Cuban Missile Crisis",
      "text": "The Cuban Missile Crisis in October 1962 was a pivotal moment in the Cold War, bringing the world to the brink of nuclear war. The crisis highlighted the principles of MAD, as both superpowers recognized the catastrophic consequences of a nuclear conflict.",
      "date": "1962-10"
    },
    {
      "headline": "Strategic Arms Limitation Talks (SALT)",
      "text": "The Strategic Arms Limitation Talks (SALT) began in 1969 between the United States and the Soviet Union, aiming to limit the number of nuclear weapons and reduce the risk of nuclear war, reflecting the influence of MAD on international relations.",
      "date": "1969"
    },
    {
      "headline": "End of the Cold War",
      "text": "The Cold War ended in 1991 with the dissolution of the Soviet Union, reducing the immediate threat of nuclear conflict and the relevance of the MAD doctrine.",
      "date": "1991"
    }
  ]
}

