{
  "timeline": [
    {
      "headline": "Formation of the Sanhedrin",
      "text": "The Sanhedrin was established as a legislative and judicial assembly in ancient Israel. It was composed of either 23 or 70 elders, serving at both local and central levels. The exact date of its formation is not clearly defined, but it is believed to have been established during the Second Temple period.",
      "date": "-0500"
    },
    {
      "headline": "Role during the Hasmonean Dynasty",
      "text": "During the Hasmonean Dynasty (140–37 BCE), the Sanhedrin played a significant role in the governance of Judea, acting as both a legislative and judicial body.",
      "date": "-0140"
    },
    {
      "headline": "Sanhedrin under Roman Rule",
      "text": "With the Roman conquest of Judea in 63 BCE, the Sanhedrin continued to function but under the oversight of Roman authorities. It retained some judicial authority but was subject to Roman political influence.",
      "date": "-0063"
    },
    {
      "headline": "Trial of Jesus",
      "text": "According to the New Testament, the Sanhedrin played a role in the trial of Jesus, which is traditionally dated to around 30 CE. The Sanhedrin's involvement in this event is a significant aspect of its historical narrative.",
      "date": "0030"
    },
    {
      "headline": "Dissolution after the First Jewish-Roman War",
      "text": "Following the destruction of the Second Temple in 70 CE during the First Jewish-Roman War, the Sanhedrin was disbanded. It marked the end of its role as a central judicial and legislative body in Jewish society.",
      "date": "0070"
    },
    {
      "headline": "Reestablishment Attempts",
      "text": "There were several attempts to reestablish the Sanhedrin in later centuries, including during the 4th and 5th centuries CE, but none were permanently successful.",
      "date": "0400"
    }
  ]
}

