    {
      "headline": "Introduction of the Missouri Compromise",
      "text": "The Missouri Compromise was introduced to address the balance between slave and free states in the United States.",
      "date": "1820"
    },
    {
      "headline": "Passage by the 16th United States Congress",
      "text": "The 16th United States Congress passed the Missouri Compromise legislation on March 3, 1820.",
      "date": "1820-03-03"
    },
    {
      "headline": "Signing by President James Monroe",
      "text": "President James Monroe signed the Missouri Compromise into law on March 6, 1820.",
      "date": "1820-03-06"
    },
    {
      "headline": "Admission of Missouri as a Slave State",
      "text": "Under the Missouri Compromise, Missouri was admitted to the Union as a slave state.",
      "date": "1821"
    },
    {
      "headline": "Admission of Maine as a Free State",
      "text": "Maine was admitted to the Union as a free state as part of the Missouri Compromise.",
      "date": "1820"
    },
    {
      "headline": "Prohibition of Slavery North of 36°30′ Parallel",
      "text": "The Missouri Compromise declared a policy of prohibiting slavery in the remaining Louisiana Purchase lands north of the 36°30′ parallel.",
      "date": "1820"
    },
    {
      "headline": "Repeal by the Kansas-Nebraska Act",
      "text": "The Missouri Compromise was effectively repealed by the Kansas-Nebraska Act in 1854, which allowed territories to decide the issue of slavery by popular sovereignty.",
      "date": "1854"
    },
    {
      "headline": "Dred Scott Decision",
      "text": "In 1857, the Dred Scott v. Sandford decision by the Supreme Court declared the Missouri Compromise unconstitutional, stating that Congress had no authority to prohibit slavery in the territories.",
      "date": "1857"
    }
  ]
}

