{
  "timeline": [
    {
      "headline": "Cambridge Analytica Founded",
      "text": "Cambridge Analytica was founded in 2013 as a subsidiary of the SCL Group, focusing on data mining and analysis for political campaigns.",
      "date": "2013"
    },
    {
      "headline": "Aleksandr Kogan Develops 'This Is Your Digital Life'",
      "text": "In 2014, Aleksandr Kogan, a researcher at Cambridge University, developed an app called 'This Is Your Digital Life' which collected data from Facebook users and their friends.",
      "date": "2014"
    },
    {
      "headline": "Data Harvesting Begins",
      "text": "In 2014, the app 'This Is Your Digital Life' began collecting data from Facebook users, eventually gathering information from millions of profiles without explicit consent.",
      "date": "2014"
    },
    {
      "headline": "Data Used for Political Campaigns",
      "text": "In 2015, it was revealed that the data collected by Cambridge Analytica was used to support political campaigns, including the 2016 U.S. presidential election.",
      "date": "2015"
    },
    {
      "headline": "The Guardian Reports on Data Breach",
      "text": "On December 11, 2015, The Guardian reported that Ted Cruz's presidential campaign was using psychological data harvested from Facebook.",
      "date": "2015-12-11"
    },
    {
      "headline": "Facebook Changes Platform Policy",
      "text": "In 2015, Facebook changed its platform policy to limit the data third-party apps could access, but the data collected by Cambridge Analytica was not deleted.",
      "date": "2015"
    },
    {
      "headline": "The New York Times and The Observer Expose Scandal",
      "text": "On March 17, 2018, The New York Times and The Observer published reports detailing how Cambridge Analytica harvested data from millions of Facebook profiles.",
      "date": "2018-03-17"
    },
    {
      "headline": "Facebook Suspends Cambridge Analytica",
      "text": "On March 16, 2018, Facebook announced it had suspended Cambridge Analytica from its platform for violating its data privacy policies.",
      "date": "2018-03-16"
    },
    {
      "headline": "Mark Zuckerberg Testifies Before Congress",
      "text": "On April 10-11, 2018, Facebook CEO Mark Zuckerberg testified before the U.S. Congress regarding the Cambridge Analytica data scandal.",
      "date": "2018-04-10"
    },
    {
      "headline": "Cambridge Analytica Files for Bankruptcy",
      "text": "On May 2, 2018, Cambridge Analytica filed for bankruptcy and ceased operations following the data scandal.",
      "date": "2018-05-02"
    },
    {
      "headline": "Facebook Fined by FTC",
      "text": "On July 24, 2019, Facebook was fined $5 billion by the Federal Trade Commission for privacy violations related to the Cambridge Analytica scandal.",
      "date": "2019-07-24"
    }
  ]
}

{
  "timeline": [
