      "headline": "Establishment of Los Alamos National Laboratory",
      "text": "Los Alamos National Laboratory was established in 1943 as part of the Manhattan Project, a top-secret project aimed at developing the first atomic bomb during World War II.",
      "date": "1943"
    },
    {
      "headline": "Trinity Test",
      "text": "On July 16, 1945, the first atomic bomb, developed at Los Alamos, was successfully detonated in the Trinity Test in the New Mexico desert.",
      "date": "1945-07-16"
    },
    {
      "headline": "End of World War II",
      "text": "In August 1945, atomic bombs developed at Los Alamos were dropped on Hiroshima and Nagasaki, Japan, contributing to the end of World War II.",
      "date": "1945-08"
    },
    {
      "headline": "Transition to peacetime research",
      "text": "After World War II, Los Alamos National Laboratory transitioned to peacetime research, focusing on nuclear energy and other scientific advancements.",
      "date": "1946"
    },
    {
      "headline": "Becomes part of the Atomic Energy Commission",
      "text": "In 1947, Los Alamos National Laboratory became part of the newly formed United States Atomic Energy Commission.",
      "date": "1947"
    },
    {
      "headline": "Development of the hydrogen bomb",
      "text": "In the early 1950s, scientists at Los Alamos played a key role in the development of the hydrogen bomb, a more powerful nuclear weapon.",
      "date": "1952"
    },
    {
      "headline": "Expansion of research areas",
      "text": "Throughout the 1960s and 1970s, Los Alamos expanded its research areas to include space exploration, supercomputing, and other scientific fields.",
      "date": "1960"
    },
    {
      "headline": "Involvement in the Strategic Defense Initiative",
      "text": "In the 1980s, Los Alamos National Laboratory was involved in research for the Strategic Defense Initiative, also known as 'Star Wars,' a missile defense system proposed by President Ronald Reagan.",
      "date": "1983"
    },
    {
      "headline": "Focus on non-proliferation and environmental science",
      "text": "In the 1990s, Los Alamos shifted focus towards nuclear non-proliferation, environmental science, and renewable energy research.",
      "date": "1990"
    },
    {
      "headline": "Part of the Department of Energy",
      "text": "Los Alamos National Laboratory is currently operated by Triad National Security, LLC, for the Department of Energy's National Nuclear Security Administration.",
      "date": "2006"
    }
  ]
}

