{
  "timeline": [
    {
      "headline": "Founding of the Institute for Social Research",
      "text": "The Institute for Social Research, which would become the home of the Frankfurt School, was founded at Goethe University Frankfurt in 1923.",
      "date": "1923"
    },
    {
      "headline": "Max Horkheimer Becomes Director",
      "text": "Max Horkheimer became the director of the Institute for Social Research in 1930, marking the beginning of the Frankfurt School's development of critical theory.",
      "date": "1930"
    },
    {
      "headline": "Publication of 'Traditional and Critical Theory'",
      "text": "In 1937, Max Horkheimer published 'Traditional and Critical Theory', which laid the foundation for the Frankfurt School's approach to critical theory.",
      "date": "1937"
    },
    {
      "headline": "Relocation to the United States",
      "text": "With the rise of the Nazi regime, the Institute for Social Research relocated to the United States in 1934, eventually settling at Columbia University in New York City.",
      "date": "1934"
    },
    {
      "headline": "Publication of 'Dialectic of Enlightenment'",
      "text": "In 1944, Max Horkheimer and Theodor Adorno published 'Dialectic of Enlightenment', a seminal work that critiqued the Enlightenment and modernity.",
      "date": "1944"
    },
    {
      "headline": "Return to Frankfurt",
      "text": "After World War II, the Institute for Social Research returned to Frankfurt in 1953, re-establishing itself in Germany.",
      "date": "1953"
    },
    {
      "headline": "Jürgen Habermas Joins the Institute",
      "text": "Jürgen Habermas joined the Institute for Social Research in 1956, becoming one of the leading figures of the second generation of the Frankfurt School.",
      "date": "1956"
    },
    {
      "headline": "Publication of 'The Structural Transformation of the Public Sphere'",
      "text": "In 1962, Jürgen Habermas published 'The Structural Transformation of the Public Sphere', which became a key text in critical theory and sociology.",
      "date": "1962"
    }
  ]
}

